def normalize_external_text(value):
    """还原 Google 表格/HTML 剪贴板的实体，同时完整保留 Unicode 文本。

    Google Sheets 的 HTML 剪贴板有时会把单引号作为 ``&#39;`` 写进纯文本，
    甚至可能二次编码成 ``&amp;#39;``。导入前最多重复解码三次；不会删除
    越南语、中文、换行、引号或表情符号。
    """
    text = str(value or '').replace('\ufeff', '')
    for _ in range(3):
        decoded = html.unescape(text)
        if decoded == text:
            break
        text = decoded
    return text.replace('\xa0', ' ')


def flow_spoken_text(value):
    """生成给外部视频口播使用的纯朗读文本，不改动原始文案。"""
    text = normalize_external_text(value)
    # 移除 Emoji、变体选择符和 ZWJ 组合符；保留正常文字、数字、引号、
    # 逗号、句号等自然停顿标点，避免 Flow 把图标当成要朗读的内容。
    text = re.sub(r'[\U0001F000-\U0001FAFF\U0001FC00-\U0001FFFD\u2600-\u27FF\u2300-\u23FF\u2B00-\u2BFF\uFE0E\uFE0F\u200D]+', ' ', text)
    return re.sub(r'[ \t]+', ' ', text).strip()


def _relaunch_with_project_venv():
    """让资源管理器双击 main.py 时也使用项目 .venv，而非系统 Python。"""
    if __name__ != "__main__" or getattr(sys, "frozen", False):
        return
    if os.environ.get("WT_PROJECT_VENV_LAUNCHED", "") == "1":
        return
    try:
        project_dir = os.path.dirname(os.path.abspath(__file__))
        project_venv = os.path.normcase(os.path.abspath(os.path.join(project_dir, ".venv")))
        # Windows 的 venv 启动器有时会在进程信息中显示基础 Python，
        # 但 sys.prefix 仍准确指向项目虚拟环境。以它为准可避免重复拉起主程序。
        active_prefix = os.path.normcase(os.path.abspath(getattr(sys, "prefix", "") or ""))
        if active_prefix == project_venv:
            return
        venv_scripts = os.path.join(project_dir, ".venv", "Scripts")
        venv_python = os.path.join(venv_scripts, "pythonw.exe" if os.name == "nt" else "python")
        if not os.path.isfile(venv_python):
            return
        current = os.path.normcase(os.path.abspath(sys.executable))
        target = os.path.normcase(os.path.abspath(venv_python))
        # 从项目虚拟环境启动时无需再拉起一次。
        if current == target or current == os.path.normcase(os.path.abspath(os.path.join(venv_scripts, "python.exe"))):
            return
        env = os.environ.copy()
        env["WT_PROJECT_VENV_LAUNCHED"] = "1"
        import subprocess as _bootstrap_subprocess
        kwargs = {"cwd": project_dir, "env": env}
        if os.name == "nt":
            kwargs["creationflags"] = getattr(_bootstrap_subprocess, "CREATE_NO_WINDOW", 0)
        _bootstrap_subprocess.Popen([venv_python, os.path.abspath(__file__), *sys.argv[1:]], **kwargs)
        raise SystemExit(0)
    except SystemExit:
        raise
    except Exception:
        # 启动桥接绝不能阻断普通 python main.py 的原有行为。
        return


_relaunch_with_project_venv()


# 在导入 PyQt 前先启动轻量预启动页，再由正式 Qt 启动页接替。它让用户在
# 大型依赖加载期间也能立即得到启动反馈。仅当明确设置
# WT_ENABLE_EARLY_BOOT_SPLASH=0 时才关闭该体验。
_EARLY_BOOT_SPLASH_SIGNAL = ""
_EARLY_BOOT_SPLASH_POSITION = ""
_EARLY_BOOT_SPLASH_PROCESS = None


def _read_early_boot_splash_position():
    """读取预启动页的坐标和显示器标识，失败时不影响正常启动。"""
    position_path = str(_EARLY_BOOT_SPLASH_POSITION or "")
    if not position_path:
        return None
    try:
        import json
        with open(position_path, "r", encoding="utf-8") as position_file:
            position = json.load(position_file)
        position = {
            "x": int(position["x"]),
            "y": int(position["y"]),
            "monitor_device": str(position.get("monitor_device", "") or ""),
            "monitor_work": position.get("monitor_work", []),
        }
        # Tk reports a Windows device id (DISPLAY1/2), while Qt normally
        # reports a monitor model name.  Preserve both identities so the Qt
        # splash can still select the same physical monitor after DPI scaling.
        saved = _read_saved_main_window_startup_handoff()
        if isinstance(saved, dict):
            position["screen_name"] = str(saved.get("screen_name", "") or "")
        return position
    except Exception:
        return None


def _startup_config_path():
    """Resolve config before the normal CONFIG_FILE constant exists."""
    data_dir = os.environ.get("VIDEO_TASK_HUB_DATA_DIR", "").strip()
    if not data_dir:
        data_dir = os.path.join(
            os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or os.path.dirname(os.path.abspath(__file__)),
            "VideoTaskHub",
        )
    return os.path.join(data_dir, "config.json")


def _read_saved_main_window_startup_handoff():
    """Read the last main-window screen before the Qt splash is constructed.

    The early Tk splash is optional, so the regular Qt splash cannot depend on
    it for monitor information.  This small read keeps every startup surface on
    the same screen as the main window was last closed.
    """
    try:
        # This runs before imports/configuration finish, so CONFIG_FILE has not
        # been assigned yet.  Reading the stable user-data location directly is
        # what keeps both startup windows off screen 1.
        config_path = globals().get('CONFIG_FILE', '') or _startup_config_path()
        if not config_path or not os.path.isfile(config_path):
            return None
        with open(config_path, 'r', encoding='utf-8') as config_file:
            config = json.load(config_file)
        config = config or {}
        screen_name = str(config.get('main_window_screen_name') or '').strip()
        monitor_device = str(config.get('main_window_monitor_device') or '').strip()
        monitor_work = list(config.get('main_window_monitor_work') or [])
        if not screen_name and not monitor_device:
            return None
        return {
            'screen_name': screen_name,
            'monitor_device': monitor_device,
            'monitor_work': monitor_work,
            'center': True,
        }
    except Exception:
        return None


def _launch_early_boot_splash():
    global _EARLY_BOOT_SPLASH_SIGNAL, _EARLY_BOOT_SPLASH_POSITION, _EARLY_BOOT_SPLASH_PROCESS
    if (
        __name__ != "__main__"
        or
        getattr(sys, "frozen", False)
        or os.environ.get("WT_ENABLE_EARLY_BOOT_SPLASH", "").strip() == "0"
        or os.environ.get("WT_DISABLE_BOOT_SPLASH", "") == "1"
        or os.environ.get("QT_QPA_PLATFORM", "").strip().lower() == "offscreen"
        or os.environ.get("WT_PACKAGING_SMOKE_TEST", "") == "1"
    ):
        return
    try:
        project_dir = os.path.dirname(os.path.abspath(__file__))
        splash_script = os.path.join(project_dir, "startup_splash.pyw")
        if not os.path.isfile(splash_script):
            return
        temp_dir = os.environ.get("TEMP") or os.environ.get("TMP") or project_dir
        signal_path = os.path.join(temp_dir, f"worktool_boot_ready_{os.getpid()}_{int(time.time() * 1000)}.flag")
        position_path = f"{signal_path}.position.json"
        if os.path.exists(signal_path):
            os.remove(signal_path)
        if os.path.exists(position_path):
            os.remove(position_path)
        import subprocess as _early_boot_subprocess
        flags = getattr(_early_boot_subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0
        _EARLY_BOOT_SPLASH_PROCESS = _early_boot_subprocess.Popen(
            [sys.executable, splash_script, signal_path, position_path],
            cwd=project_dir,
            creationflags=flags,
            close_fds=(os.name != "nt"),
        )
        _EARLY_BOOT_SPLASH_SIGNAL = signal_path
        _EARLY_BOOT_SPLASH_POSITION = position_path
    except Exception:
        # 预启动页只是体验增强，绝不能影响正常启动。
        _EARLY_BOOT_SPLASH_SIGNAL = ""
        _EARLY_BOOT_SPLASH_POSITION = ""
        _EARLY_BOOT_SPLASH_PROCESS = None


def _dismiss_early_boot_splash():
    global _EARLY_BOOT_SPLASH_PROCESS
    signal_path = str(_EARLY_BOOT_SPLASH_SIGNAL or "")
    if not signal_path:
        return
    try:
        with open(signal_path, "w", encoding="utf-8") as signal_file:
            signal_file.write("ready")
    except Exception:
        pass
    # 正常情况下预启动页会在下一次 45ms 轮询中自行退出。额外保留一个
    # 受控兜底：某些 Windows/Tk 组合会漏掉文件轮询，此时不能遗留会闪烁的
    # 小窗口，更不能靠 35 秒超时才消失。
    process = _EARLY_BOOT_SPLASH_PROCESS
    _EARLY_BOOT_SPLASH_PROCESS = None
    position_path = str(_EARLY_BOOT_SPLASH_POSITION or "")

    def _ensure_early_splash_closed():
        try:
            if process is not None and process.poll() is None:
                process.terminate()
        except Exception:
            pass
        try:
            if position_path and os.path.isfile(position_path):
                os.remove(position_path)
        except Exception:
            pass

    try:
        import threading
        cleanup_timer = threading.Timer(1.2, _ensure_early_splash_closed)
        cleanup_timer.daemon = True
        cleanup_timer.start()
    except Exception:
        _ensure_early_splash_closed()


_launch_early_boot_splash()

# === 紧急诊断：捕获所有启动阶段的崩溃 ===
def _startup_diagnostic_path(filename):
    """返回稳定的启动诊断位置，避免封包版写入启动快捷方式的当前目录。"""
    try:
        root = os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else os.path.dirname(os.path.abspath(__file__))
        if root:
            return os.path.join(root, filename)
    except Exception:
        pass
    return filename


def emergency_log(msg):
    with open(_startup_diagnostic_path("STARTUP_ERROR.txt"), "a", encoding="utf-8") as f:
        f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {msg}\n")
    # --windowed 封包中 stdout 可能不存在，不能让诊断输出反过来导致启动失败。
    if getattr(sys, "stdout", None) is not None:
        print(f"!!! [DIAGNOSTIC] {msg}")

try:
    emergency_log("程序启动：正在初始化基础模块...")
except Exception as e:
    with open(_startup_diagnostic_path("CRITICAL_BOOT_FAILURE.txt"), "w", encoding="utf-8") as f:
        f.write(str(e))
