def _stable_user_data_file(filename):
    try:
        os.makedirs(USER_DATA_DIR, exist_ok=True)
        destination = os.path.join(USER_DATA_DIR, filename)
        # 开发源码版本位于项目根目录的子文件夹；优先迁移项目根目录的真实用户
        # 配置，而不是误取新版本文件夹刚生成的空配置。
        candidates = []
        version_folder = os.path.basename(base_dir).startswith("AI视频任务工作站-dev源码v")
        if version_folder:
            candidates.append(os.path.join(os.path.dirname(base_dir), filename))
        candidates.append(os.path.join(base_dir, filename))
        if os.path.isfile(destination):
            # v1.0.132 首次迁移时可能已存在一份较早共享配置，而项目根目录中的
            # 正在使用配置随后仍被旧实例写入。只在“开发版本目录 + 根配置更新更
            # 晚 + JSON 合法”时合并：根配置覆盖同名字段，保留共享配置独有字段。
            # 合并前先保存不可覆盖的时间戳备份，绝不直接丢弃任何用户数据。
            if filename == "config.json" and version_folder and candidates:
                source = candidates[0]
                try:
                    if os.path.isfile(source) and os.path.getmtime(source) > os.path.getmtime(destination):
                        with open(source, "r", encoding="utf-8") as source_file:
                            newer_config = json.load(source_file)
                        with open(destination, "r", encoding="utf-8") as destination_file:
                            existing_config = json.load(destination_file)
                        if isinstance(newer_config, dict) and isinstance(existing_config, dict):
                            backup = f"{destination}.before-legacy-merge-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
                            shutil.copy2(destination, backup)
                            merged_config = dict(existing_config)
                            merged_config.update(newer_config)
                            staging = f"{destination}.merging.{os.getpid()}"
                            with open(staging, "w", encoding="utf-8") as staging_file:
                                json.dump(merged_config, staging_file, ensure_ascii=False, indent=2)
                            os.replace(staging, destination)
                except Exception:
                    # 共享配置可直接使用；迁移合并失败绝不能阻断启动或破坏原文件。
                    pass
            return destination
        for source in candidates:
            if not os.path.isfile(source) or os.path.abspath(source) == os.path.abspath(destination):
                continue
            staging = f"{destination}.migrating.{os.getpid()}"
            try:
                shutil.copy2(source, staging)
                os.replace(staging, destination)
                break
            except Exception:
                try:
                    if os.path.exists(staging):
                        os.remove(staging)
                except Exception:
                    pass
        return destination
    except Exception:
        # 受限环境无法写入用户数据目录时保留原有目录行为，不阻断软件启动。
        return os.path.join(base_dir, filename)


