def _read_subtitle_presets_file(fallback=None):
    """用户独立预设优先于旧版主配置；更新程序目录不会覆盖它。"""
    presets = dict(fallback or {})
    if not os.path.isfile(SUBTITLE_PRESETS_FILE):
        return {str(k): dict(v) for k, v in presets.items() if isinstance(v, dict)}
    with open(SUBTITLE_PRESETS_FILE, 'r', encoding='utf-8-sig') as file:
        payload = json.load(file)
    stored = payload.get('presets', {}) if isinstance(payload, dict) else {}
    if not isinstance(stored, dict):
        raise ValueError('字幕预设配置格式无效')
    presets.update({str(k): dict(v) for k, v in stored.items() if isinstance(v, dict)})
    return {str(k): dict(v) for k, v in presets.items() if isinstance(v, dict)}


def _write_subtitle_presets_file(presets):
    """同目录临时文件 + 原子替换，避免崩溃留下半个 JSON。"""
    payload = {'format': 'VideoTaskHub_subtitle_presets_v1',
               'presets': {str(k): dict(v) for k, v in dict(presets or {}).items() if isinstance(v, dict)}}
    os.makedirs(os.path.dirname(SUBTITLE_PRESETS_FILE), exist_ok=True)
    staging = SUBTITLE_PRESETS_FILE + f'.{os.getpid()}.tmp'
    try:
        with open(staging, 'w', encoding='utf-8') as file:
            json.dump(payload, file, ensure_ascii=False, indent=2)
            file.flush(); os.fsync(file.fileno())
        os.replace(staging, SUBTITLE_PRESETS_FILE)
    finally:
        if os.path.exists(staging):
            os.remove(staging)


def _enable_native_crash_log():
    """将 Python/原生扩展的致命崩溃栈追加到独立日志，供人工对位故障排查。"""
    global _native_crash_log_handle
    try:
        _native_crash_log_handle = open(MANUAL_ALIGNMENT_CRASH_LOG, "a", encoding="utf-8", buffering=1)
        _native_crash_log_handle.write(f"\n{'=' * 18} process start {datetime.now().isoformat(timespec='seconds')} {'=' * 18}\n")
        _native_crash_log_handle.flush()
        faulthandler.enable(file=_native_crash_log_handle, all_threads=True)
    except Exception:
        _native_crash_log_handle = None


