def _configure_packaged_media_runtime():
    """让所有视频功能都能找到随封包附带的 FFmpeg/VLC 动态库。

    部分旧线程直接执行 ``ffmpeg`` / ``ffprobe``，不会经过各自的路径解析。
    因此在进程启动时将程序目录下的 bin、tools、VLC 统一加入 PATH，
    同时保留用户显式设置的工具路径优先级。
    """
    roots = []
    for root in (
        base_dir,
        getattr(sys, "_MEIPASS", ""),
        os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else "",
    ):
        if root and os.path.isdir(root):
            normalized = os.path.abspath(root)
            if normalized not in roots:
                roots.append(normalized)

    runtime_dirs = []
    for root in roots:
        for name in ("bin", "tools", "VLC", "vlc"):
            candidate = os.path.join(root, name)
            if os.path.isdir(candidate) and candidate not in runtime_dirs:
                runtime_dirs.append(candidate)

    if not runtime_dirs:
        return

    try:
        old_parts = [p for p in os.environ.get("PATH", "").split(os.pathsep) if p]
        prepend = [p for p in runtime_dirs if p not in old_parts]
        if prepend:
            os.environ["PATH"] = os.pathsep.join(prepend + old_parts)
        if os.name == "nt" and hasattr(os, "add_dll_directory"):
            for directory in runtime_dirs:
                try:
                    _RUNTIME_DLL_DIR_HANDLES.append(os.add_dll_directory(directory))
                except Exception:
                    pass
    except Exception:
        pass

    # 仅在用户没有指定路径时，自动采用随程序发布的 FFmpeg/FFprobe。
    for executable, env_name in (("ffmpeg.exe", "WT_FFMPEG_PATH"), ("ffprobe.exe", "WT_FFPROBE_PATH")):
        if os.environ.get(env_name, "").strip():
            continue
        for directory in runtime_dirs:
            candidate = os.path.join(directory, executable)
            if os.path.isfile(candidate):
                os.environ[env_name] = candidate
                break


_configure_packaged_media_runtime()

_API_THROTTLE_LOCK = Lock()
_API_NEXT_ALLOWED_TS = {}

# ─────────────────────────────────────────────
# 路径模板（变量）解析
# 目标：把所有“输出路径/存放位置”入口统一到同一套解析逻辑
# - 支持环境变量：${HOME} / %USERPROFILE% 等（os.path.expandvars）
# - 支持 ~：用户目录（os.path.expanduser）
# - 支持内置变量：
#   {date}/{yyyy-MM-dd}、{yyyyMMdd}、{yyyyMM}、{time}/{hhmmss}、{cwd}、{home}
# - 支持上下文变量：通过 variables 传入，例如 {project}、{src_dir} 等
# 注意：该函数只在“真正执行写入/导出”时做解析；配置里仍保存用户输入的模板原文。
# ─────────────────────────────────────────────
def render_path_template(path_template, variables=None, project_name=""):
    raw = str(path_template or "").strip().strip('"').strip("'")
    if not raw:
        return ""

    # 1) 先展开环境变量与 ~
    try:
        raw = os.path.expandvars(os.path.expanduser(raw))
    except Exception:
        pass

    # 2) 内置变量
    try:
        now = datetime.now()
    except Exception:
        now = None

    mapping = {}
    if now is not None:
        mapping.update({
            "{date}": now.strftime("%Y-%m-%d"),
            "{yyyy-MM-dd}": now.strftime("%Y-%m-%d"),
            "{yyyyMMdd}": now.strftime("%Y%m%d"),
            "{yyyyMM}": now.strftime("%Y%m"),
            "{time}": now.strftime("%H-%M-%S"),
            "{hhmmss}": now.strftime("%H%M%S"),
        })

    # 常用系统变量
    try:
        mapping["{cwd}"] = os.getcwd()
    except Exception:
        mapping["{cwd}"] = ""
    try:
        mapping["{home}"] = os.path.expanduser("~")
    except Exception:
        mapping["{home}"] = ""

    # project_name 快捷注入（仅在相关模块传入时生效）
    if project_name:
        try:
            safe_project = clean_long_filename(str(project_name or ""), 120)
        except Exception:
            safe_project = str(project_name or "")
        mapping["{project}"] = safe_project

    # 3) 自定义上下文变量（允许传入 "project" 或 "{project}" 两种写法）
    if isinstance(variables, dict):
        for k, v in variables.items():
            key = str(k or "")
            if not key:
                continue
            token = key if key.startswith("{") and key.endswith("}") else ("{" + key + "}")
            mapping[token] = "" if v is None else str(v)

    # 4) 替换（仅做简单替换，保持兼容现有 {yyyy-MM-dd} 这种带符号 token）
    for token, value in mapping.items():
        if token and token in raw:
            raw = raw.replace(token, value)

    # 5) 规范化路径
    try:
        return normalize_user_path(raw, make_absolute=False)
    except Exception:
        return raw


def normalize_user_path(path, make_absolute=True):
    """统一处理本地、映射盘和 Windows UNC 网络路径。

    支持 ``\\\\服务器\\共享名\\目录``、``//服务器/共享名/目录``、
    ``file://服务器/共享名/目录`` 与 ``smb://服务器/共享名/目录``。UNC 不会再被
    ``abspath`` 误拼到当前工作目录；额外输入的开头反斜杠也会收敛为标准双反斜杠。
    """
    raw = str(path or "").strip().strip('"').strip("'")
    if not raw:
        return ""
    try:
        raw = os.path.expandvars(os.path.expanduser(raw))
    except Exception:
        pass
    lower = raw.lower()
    if lower.startswith(("file://", "smb://")):
        try:
            parsed = urllib.parse.urlsplit(raw)
            host = str(parsed.netloc or "").strip()
            remote_path = urllib.parse.unquote(parsed.path or "").lstrip("/\\")
            if host:
                raw = "\\\\" + host + ("\\" + remote_path if remote_path else "")
            elif lower.startswith("file:///"):
                raw = remote_path
        except Exception:
            pass
    if os.name == "nt":
        raw = raw.replace("/", "\\")
        if raw.startswith("\\\\"):
            # ``\\\server``、``///server`` 等输入全部统一为合法 UNC 前缀 ``\\server``。
            raw = "\\\\" + raw.lstrip("\\/")
            return os.path.normpath(raw)
    try:
        return os.path.abspath(raw) if make_absolute else os.path.normpath(raw)
    except Exception:
        return raw


def is_network_share_path(path):
    normalized = normalize_user_path(path, make_absolute=False)
    return bool(normalized.startswith("\\\\") or normalized.startswith("//"))

def normalize_api_base(api_base, default=""):
    return (api_base or default or "").strip().rstrip("/")

def is_google_native_api(api_base):
    base = normalize_api_base(api_base).lower()
    return "generativelanguage.googleapis.com" in base or "googleapis.com" in base

def pick_google_model(model_name, default_model="gemini-1.5-flash"):
    name = (model_name or "").strip()
    return name if "gemini" in name.lower() else default_model

def get_effective_api_interval(api_base, ai_config=None, fallback=0):
    interval = max(0, int(fallback or 0))
    if isinstance(ai_config, dict):
        try:
            interval = max(interval, int(ai_config.get("api_interval", fallback) or 0))
        except Exception:
            pass
    return max(0, interval)

def get_api_pool_strategy(ai_config=None, default="ordered"):
    strategy = default
    if isinstance(ai_config, dict):
        if ai_config.get("api_random_enabled"):
            return "random"
        strategy = ai_config.get("api_pool_strategy", default)
    strategy = str(strategy or default).strip().lower()
    if strategy in {"random", "shuffle", "rand", "随机"}:
        return "random"
    return "ordered"

def order_api_keys(api_keys, ai_config=None, strategy=None):
    keys = [str(k).strip() for k in (api_keys or []) if str(k).strip()]
    if len(keys) <= 1:
        return keys
    resolved = get_api_pool_strategy({"api_pool_strategy": strategy} if strategy is not None else ai_config)
    ordered = list(keys)
    if resolved == "random":
        random.shuffle(ordered)
    return ordered

def fix_mojibake_text(text):
    raw = str(text or "")
    if not raw:
        return raw
    suspicious = ("Ã", "Â", "â", "æ", "å", "ä", "ç", "é")
    if any(token in raw for token in suspicious):
        try:
            repaired = raw.encode("latin-1").decode("utf-8")
            if repaired:
                return repaired
        except Exception:
            pass
    return raw

def sanitize_api_keys(api_keys):
    seen = set()
    cleaned = []
    for key in api_keys or []:
        k = str(key or "").strip()
        if not k or k in seen:
            continue
        seen.add(k)
        cleaned.append(k)
    return cleaned

def normalize_api_base_for_profile(api_base, default="https://api.openai.com/v1"):
    base = normalize_api_base(api_base, default)
    if "/chat/completions" in base:
        base = base.replace("/chat/completions", "")
    lower = base.lower()
    if "googleapis.com" in lower:
        return "https://generativelanguage.googleapis.com"
    if any(x in lower for x in ["openrouter.ai", "openai.com", "groq.com"]) and not base.endswith("/v1"):
        if "openrouter.ai" in lower and not base.endswith("/api/v1"):
            return base.rstrip("/") + "/api/v1"
        return base.rstrip("/") + "/v1"
    return base

def normalize_api_pool_entry(entry, idx=0):
    if not isinstance(entry, dict):
        entry = {}
    keys = sanitize_api_keys(entry.get("api_keys", []))
    if not keys:
        raw_text = str(entry.get("api_keys_text", "") or "")
        keys = sanitize_api_keys(raw_text.splitlines())
    profile = {
        "name": str(entry.get("name") or f"API-{idx + 1}").strip() or f"API-{idx + 1}",
        "api_base": normalize_api_base_for_profile(entry.get("api_base") or entry.get("base") or ""),
        "api_model": str(entry.get("api_model") or entry.get("model") or "gpt-4o-mini").strip() or "gpt-4o-mini",
        "api_keys": keys,
        "enabled": bool(entry.get("enabled", True)),
    }
    return profile

def build_legacy_api_profile(ai_config=None):
    ai_config = ai_config or {}
    api_keys = ai_config.get("api_keys", [])
    if not api_keys and ai_config.get("api_key"):
        api_keys = [ai_config.get("api_key", "")]
    api_keys = sanitize_api_keys(api_keys)
    return {
        "name": "传统单接口",
        "api_base": normalize_api_base_for_profile(ai_config.get("api_base", "")),
        "api_model": str(ai_config.get("api_model", "gpt-4o-mini") or "gpt-4o-mini").strip(),
        "api_keys": order_api_keys(api_keys, ai_config),
        "enabled": True,
        "source": "legacy",
    }

def normalize_api_pool(ai_config=None):
    ai_config = ai_config or {}
    raw_pool = ai_config.get("api_pool", [])
    pool = []
    seen_names = set()
    for idx, item in enumerate(raw_pool or []):
        profile = normalize_api_pool_entry(item, idx)
        base_name = profile["name"]
        name = base_name
        seq = 2
        while name in seen_names:
            name = f"{base_name}_{seq}"
            seq += 1
        profile["name"] = name
        profile["source"] = "pool"
        pool.append(profile)
        seen_names.add(name)
    if pool:
        return pool

    legacy = build_legacy_api_profile(ai_config)
    legacy_keys = sanitize_api_keys(legacy.get("api_keys", []))
    if not legacy_keys:
        fallback_key = str(ai_config.get("api_key", "") or os.environ.get("OPENAI_API_KEY", "") or "").strip()
        if fallback_key:
            legacy_keys = [fallback_key]
    if not legacy_keys:
        return []
    return [{
        "name": str(legacy.get("name") or "默认节点").strip() or "默认节点",
        "api_base": normalize_api_base_for_profile(legacy.get("api_base") or ai_config.get("api_base") or ""),
        "api_model": str(legacy.get("api_model") or ai_config.get("api_model") or "gpt-4o-mini").strip() or "gpt-4o-mini",
        "api_keys": order_api_keys(legacy_keys, ai_config),
        "enabled": True,
        "source": "pool_migrated",
    }]

def get_api_source_mode(ai_config=None, default="pool"):
    ai_config = ai_config or {}
    mode = str(ai_config.get("api_source_mode", default) or default).strip().lower()
    if mode == "legacy":
        return "pool"
    if mode in {"single", "pool"}:
        return mode
    return default

def get_api_provider_strategy(ai_config=None, default="ordered"):
    ai_config = ai_config or {}
    if ai_config.get("api_random_enabled"):
        return "random"
    strategy = str(ai_config.get("api_provider_strategy", default) or default).strip().lower()
    if strategy in {"random", "shuffle", "rand", "随机"}:
        return "random"
    return "ordered"

def resolve_api_profiles(ai_config=None):
    ai_config = ai_config or {}
    pool = normalize_api_pool(ai_config)
    mode = get_api_source_mode(ai_config, "pool")
    active_name = str(ai_config.get("active_api_name", "") or "").strip()
    if not pool:
        return []

    enabled_pool = [dict(p) for p in pool if p.get("enabled", True)]
    candidate_pool = enabled_pool or [dict(p) for p in pool]
    if not candidate_pool:
        return []

    if mode == "single":
        selected = next((dict(p) for p in candidate_pool if p.get("name") == active_name), None)
        if not selected:
            selected = dict(candidate_pool[0])
        selected["api_keys"] = order_api_keys(selected.get("api_keys", []), ai_config)
        return [selected]

    strategy = get_api_provider_strategy(ai_config, "ordered")
    ordered_pool = [dict(p) for p in candidate_pool]
    if strategy == "random":
        random.shuffle(ordered_pool)
    elif active_name:
        for idx, item in enumerate(ordered_pool):
            if item.get("name") == active_name:
                ordered_pool = ordered_pool[idx:] + ordered_pool[:idx]
                break
    for item in ordered_pool:
        item["api_keys"] = order_api_keys(item.get("api_keys", []), ai_config)
    return ordered_pool

def get_runtime_api_profiles(ai_config=None, fallback_env=True):
    ai_config = ai_config or {}
    profiles = []
    for idx, profile in enumerate(resolve_api_profiles(ai_config)):
        item = dict(profile)
        keys = sanitize_api_keys(item.get("api_keys", []))
        if not keys and idx == 0 and fallback_env:
            fallback_key = str(ai_config.get("api_key", "") or os.environ.get("OPENAI_API_KEY", "") or "").strip()
            if fallback_key:
                keys = [fallback_key]
        if not keys:
            continue
        item["api_keys"] = order_api_keys(keys, ai_config)
        profiles.append(item)
    return profiles


def get_primary_api_profile(ai_config=None):
    profiles = get_runtime_api_profiles(ai_config)
    if profiles:
        return profiles[0]
    pool = normalize_api_pool(ai_config)
    if pool:
        return dict(pool[0])
    return build_legacy_api_profile(ai_config)

REVIEW_STATE_PENDING = "⚪ 待审核"
REVIEW_STATE_PASS = "✅ 已通过"
REVIEW_STATE_COPY_MISMATCH = "🟣 文案不贴切"
REVIEW_STATE_VISUAL_ISSUE = "🟠 视觉违规"
REVIEW_STATE_MANUAL = "🟡 需人工复核"

def get_review_json_schema_text():
    return (
        "{\"violation\": true/false, "
        "\"category\": \"pass|copy_mismatch|visual_violation|manual_review\", "
        "\"hit_rules\": [\"触发的视觉规则关键词，可为空数组\"], "
        "\"reason\": \"一句话说明结论\", "
        "\"analysis\": \"用 2-4 句说明判定依据，重点写主题、意境、情绪、氛围、主体动作、镜头感是否匹配\", "
        "\"suggestion\": \"若有优化建议请给出，可为空\", "
        "\"confidence\": 0~1}"
    )

def get_default_review_prompt_template():
    return (
        "你是一名专业、谨慎的图片审核员，负责判断图片是否适合当前中文文案与视觉规则。\n\n"
        "请不要只做机械的“元素对元素”比对，而要综合判断图片与中文文案在以下维度是否贴切：\n"
        "1. 主题与主体是否一致\n"
        "2. 场景、动作、叙事方向是否一致\n"
        "3. 情绪、氛围、意境、审美气质是否一致\n"
        "4. 镜头语言、构图感觉、风格调性是否和文案想表达的感觉相符\n"
        "5. 画面本身是否存在明显视觉问题，或违反了给定视觉规则\n\n"
        "请优先以中文文案为主进行判断；若同时给了英文文案，英文只作为辅助参考。\n"
        "如果图片虽然出现了相似元素，但整体气质、意境、情绪、故事感与中文文案不符，也应判定为 `copy_mismatch`。\n"
        "如果主要问题是画面质量、违规元素、构图缺陷、文字水印、模糊、遮挡、低质感或不符合视觉规则，应判定为 `visual_violation`。\n"
        "如果你无法稳定判断，或图文之间存在边界情况、歧义、信息不足，请判定为 `manual_review`，不要勉强给通过。\n\n"
        "{{审核重点}}\n\n"
        "{{视觉规则}}\n\n"
        "{{文案信息}}\n\n"
        "请只返回 JSON，不要返回额外解释。JSON 格式如下：\n"
        "{{JSON格式}}"
    )

def build_review_focus_text():
    return (
        "审核重点：\n"
        "- 重点判断“中文文案是否贴切”，不要只按图片里出现了哪些物体来机械匹配。\n"
        "- 要特别关注文案的意境、氛围、情绪、气质、审美风格、故事感、镜头感。\n"
        "- 若图片与文案只是表面元素相关，但深层表达不一致，也属于不贴切。"
    )

def build_effective_review_system_prompt(ai_config=None, rules_str="", combined_copy=""):
    ai_config = ai_config or {}
    template = str(ai_config.get("review_prompt_template", "") or "").strip() or get_default_review_prompt_template()
    visual_text = f"视觉规则：\n{rules_str.strip()}" if str(rules_str or "").strip() else "视觉规则：\n未设置视觉规则。"
    copy_text = f"文案信息：\n{combined_copy.strip()}" if str(combined_copy or "").strip() else "文案信息：\n未提供中文/英文文案。"
    rendered = template
    replacements = {
        "{{审核重点}}": build_review_focus_text(),
        "{{视觉规则}}": visual_text,
        "{{文案信息}}": copy_text,
        "{{JSON格式}}": get_review_json_schema_text(),
    }
    for token, value in replacements.items():
        rendered = rendered.replace(token, value)
    # 关键加固：强制模型“逐条执行”视觉规则，而不是只参考。
    # 说明：不改变既有字段解析逻辑；即使模型额外返回 hit_rules，也不会影响解析。
    extra = (
        "\n\n【规则执行要求】\n"
        "1) 你必须逐条检查上面的每一条“视觉规则”，不要遗漏。\n"
        "2) 若命中任意视觉规则：必须设置 violation=true 且 category=\"visual_violation\"。\n"
        "3) 若未命中任何视觉规则：hit_rules 设为空数组 []。\n"
        "4) 发现命中的规则时：请在 hit_rules 中列出命中的规则关键词（例如：\"黑色十字架\"）。\n"
    )
    return (rendered.strip() + extra).strip()

def normalize_review_category(value):
    raw = str(value or "").strip().lower()
    if raw in {"pass", "ok", "passed", "通过", "已通过"}:
        return "pass"
    if raw in {"copy_mismatch", "copy", "text_mismatch", "semantic_mismatch", "文案不贴切", "图文不符", "图文不贴切"}:
        return "copy_mismatch"
    if raw in {"visual_violation", "visual", "image_issue", "视觉违规", "画面违规", "画面问题"}:
        return "visual_violation"
    if raw in {"manual_review", "manual", "review", "uncertain", "需人工复核", "人工复核", "不确定"}:
        return "manual_review"
    return ""

def infer_review_category(data):
    data = data or {}
    explicit = normalize_review_category(data.get("category") or data.get("status") or data.get("result"))
    if explicit:
        return explicit
    reason = str(data.get("reason", "") or "")
    analysis = str(data.get("analysis", "") or "")
    suggestion = str(data.get("suggestion", "") or "")
    text = f"{reason}\n{analysis}\n{suggestion}".lower()
    conf = data.get("confidence", "")
    try:
        if conf != "" and conf is not None and float(conf) < 0.55:
            return "manual_review"
    except Exception:
        pass
    manual_keys = ["人工复核", "需复核", "不确定", "难以判断", "无法判断", "边界", "歧义", "信息不足", "uncertain", "manual"]
    copy_keys = ["文案不贴切", "图文不符", "图文不贴切", "不匹配", "不一致", "意境不符", "氛围不符", "情绪不符", "语义不符", "主题不符", "气质不符"]
    visual_keys = ["视觉违规", "画面问题", "模糊", "糊", "水印", "logo", "文字", "遮挡", "低质", "噪点", "曝光", "过曝", "欠曝", "拉伸", "变形", "裁切", "黑边", "规则不符"]
    if any(k.lower() in text for k in manual_keys):
        return "manual_review"
    visual_hit = any(k.lower() in text for k in visual_keys)
    copy_hit = any(k.lower() in text for k in copy_keys)
    if visual_hit and copy_hit:
        return "manual_review"
    if copy_hit:
        return "copy_mismatch"
    if visual_hit:
        return "visual_violation"
    if data.get("violation"):
        return "manual_review"
    return "pass"

def parse_json_loose(text):
    """
    宽松 JSON 解析器：尽最大可能从模型输出中提取一个 dict。
    支持：
    - ```json 代码块
    - JSON 前后夹杂自然语言
    - JSON 数组（取第一个 dict）
    - 类 Python dict（单引号/True/False/None）兜底
    """
    import json as _json
    import re as _re
    import ast as _ast

    t = str(text or "").strip()
    if not t:
        return None

    # 去掉 ``` / ```json 包裹
    if t.startswith("```"):
        lines = t.splitlines()
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].startswith("```"):
            lines = lines[:-1]
        t = "\n".join(lines).strip()

    # 1) 直接 JSON
    try:
        obj = _json.loads(t)
        if isinstance(obj, list) and obj and isinstance(obj[0], dict):
            return obj[0]
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass

    # 2) JSONDecoder.raw_decode：允许前后夹杂文本（例如“结果如下：{...}”）
    try:
        decoder = _json.JSONDecoder()
        for m in _re.finditer(r"[\{\[]", t):
            start = m.start()
            try:
                obj, _end = decoder.raw_decode(t[start:])
                if isinstance(obj, list) and obj and isinstance(obj[0], dict):
                    return obj[0]
                if isinstance(obj, dict):
                    return obj
            except Exception:
                continue
    except Exception:
        pass

    # 3) 兜底：抽取一个 {...}，尝试按 Python dict 解析（兼容单引号 / True / None）
    m = _re.search(r"\{[\s\S]*\}", t)
    if not m:
        return None
    s = m.group(0).strip()
    # 清理常见尾逗号
    s = _re.sub(r",\s*}", "}", s)
    s = _re.sub(r",\s*]", "]", s)
    try:
        obj = _ast.literal_eval(s)
        return obj if isinstance(obj, dict) else None
    except Exception:
        return None

def review_state_label_from_category(category):
    category = normalize_review_category(category) or infer_review_category({"category": category})
    if category == "copy_mismatch":
        return REVIEW_STATE_COPY_MISMATCH
    if category == "visual_violation":
        return REVIEW_STATE_VISUAL_ISSUE
    if category == "manual_review":
        return REVIEW_STATE_MANUAL
    return REVIEW_STATE_PASS

def normalize_review_state_label(state):
    state = str(state or "").strip()
    if state in {REVIEW_STATE_PENDING, REVIEW_STATE_PASS, REVIEW_STATE_COPY_MISMATCH, REVIEW_STATE_VISUAL_ISSUE, REVIEW_STATE_MANUAL}:
        return state
    if state == "🟡 待审核":
        return REVIEW_STATE_PENDING
    if state == "⚠️ 有问题":
        return REVIEW_STATE_MANUAL
    return REVIEW_STATE_PENDING

def build_review_note(category, reason="", ai_note=""):
    category = normalize_review_category(category) or "pass"
    reason = str(reason or "").strip()
    ai_note = str(ai_note or "").strip()
    brief = reason or ai_note or "未说明原因"
    if category == "copy_mismatch":
        return f"文案不贴切：{brief}"
    if category == "visual_violation":
        return f"视觉违规：{brief}"
    if category == "manual_review":
        return f"需人工复核：{brief}"
    return f"AI审核通过：{ai_note[:80]}" if ai_note else "AI审核通过"

def _api_throttle_token(api_base, api_key):
    # Google 原生接口的配额/限流往往是“项目/账号级”而不是“Key 级”，
    # 多 Key 并发反而更容易整体触发 429/503。
    # 因此对 Google 原生接口：忽略 api_key，让所有请求共用同一个节流桶。
    if is_google_native_api(api_base):
        raw = f"{normalize_api_base(api_base)}"
    else:
        raw = f"{normalize_api_base(api_base)}|{api_key or ''}"
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()

def wait_for_api_slot(api_base, api_key, min_interval=0, stop_check=None, log_fn=None, prefix=""):
    token = _api_throttle_token(api_base, api_key)
    while True:
        with _API_THROTTLE_LOCK:
            now = time.time()
            next_allowed = _API_NEXT_ALLOWED_TS.get(token, 0.0)
            wait_seconds = max(0.0, next_allowed - now)
            if wait_seconds <= 0:
                return
        if log_fn and wait_seconds >= 0.5:
            log_fn(f"{prefix}检测到限流冷却，等待 {wait_seconds:.1f}s 后重试...", "gray")
        steps = max(1, int(wait_seconds * 10))
        for _ in range(steps):
            if stop_check and stop_check():
                return
            time.sleep(0.1)

def apply_api_cooldown(api_base, api_key, cooldown_seconds):
    cooldown_seconds = max(0.0, float(cooldown_seconds or 0))
    if cooldown_seconds <= 0:
        return
    token = _api_throttle_token(api_base, api_key)
    with _API_THROTTLE_LOCK:
        _API_NEXT_ALLOWED_TS[token] = max(_API_NEXT_ALLOWED_TS.get(token, 0.0), time.time() + cooldown_seconds)

def parse_retry_after_seconds(response, default_seconds):
    try:
        retry_after = response.headers.get("Retry-After", "")
        if retry_after:
            return max(float(retry_after), float(default_seconds or 0))
    except Exception:
        pass
    return float(default_seconds or 0)

def extract_api_error_message(response):
    try:
        data = response.json()
        if isinstance(data, dict):
            err = data.get("error")
            if isinstance(err, dict):
                msg = err.get("message") or err.get("status") or ""
                details = err.get("details")
                if isinstance(details, list) and details:
                    detail_text = []
                    for item in details[:2]:
                        if isinstance(item, dict):
                            part = item.get("reason") or item.get("detail") or item.get("@type") or ""
                            if part:
                                detail_text.append(str(part))
                    if detail_text:
                        msg = f"{msg} ({'; '.join(detail_text)})".strip()
                if msg:
                    return str(msg)
        text = response.text.strip()
        if text:
            return text[:200]
    except Exception:
        try:
            text = response.text.strip()
            if text:
                return text[:200]
        except Exception:
            pass
    return f"HTTP {getattr(response, 'status_code', 'ERROR')}"


_in_debug = False
_runtime_debug_backlog = []
_runtime_debug_lock = threading.RLock()


def _publish_runtime_debug(msg, color="black"):
    """把终端诊断同步给 GUI；GUI 尚未创建时先保存在本次会话缓冲中。"""
    text = str(msg or "").rstrip()
    if not text:
        return
    with _runtime_debug_lock:
        _runtime_debug_backlog.append((text, str(color or "black")))
        # GUI 未就绪前的启动诊断足够保留；完整内容仍在 debug_log.txt 中。
        if len(_runtime_debug_backlog) > 1200:
            del _runtime_debug_backlog[:200]
    emitter = globals().get("GLOBAL_LOG")
    if emitter is not None:
        try:
            emitter.log_signal.emit(text, str(color or "black"))
        except Exception:
            pass


def _redact_sensitive_log_data(value):
    """Remove credentials from diagnostic output before it reaches disk or the UI."""
    text = str(value or "")
    # Cover the formats this application sends to OpenAI-compatible and Google
    # APIs, plus common accidental key dumps in exception text.
    text = re.sub(r"(?i)(authorization\s*[:=]\s*bearer\s+)[^\s'\"\\]+", r"\1***", text)
    text = re.sub(r"(?i)(\bbearer\s+)[A-Za-z0-9._~+\-/=]{12,}", r"\1***", text)
    text = re.sub(r"(?i)([?&](?:key|api[_-]?key|access[_-]?token|token)=)[^&#\s'\"]+", r"\1***", text)
    text = re.sub(r"(?i)([\"'](?:api[_-]?key|access[_-]?token|token|password)[\"']\s*[:=]\s*[\"'])[^\"']+", r"\1***", text)
    text = re.sub(r"\bsk-[A-Za-z0-9_-]{12,}", "sk-***", text)
    return text


def write_debug(msg, color="black"):
    global _in_debug
    if _in_debug: return
    _in_debug = True
    try:
        msg = _redact_sensitive_log_data(msg)
        ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(DEBUG_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {msg}\n")
        # 不用 print：安装了终端镜像后 print 会再次回流到日志，造成重复/递归。
        console = getattr(sys, "__stdout__", None)
        if console is not None:
            try:
                console.write(f"[DEBUG] {msg}\n"); console.flush()
            except Exception:
                pass
        _publish_runtime_debug(str(msg), color)
    except: pass
    finally: _in_debug = False

if os.path.exists(DEBUG_LOG):
    try: os.remove(DEBUG_LOG)
    except: pass

write_debug(">>> 阶段 1: 基础环境初始化")

_VLC_RUNTIME_INFO = {"root": "", "libvlc_dll": "", "plugins_dir": ""}
_VLC_DLL_DIR_HANDLES = []

def _get_python_bitness():
    try:
        import struct
        return struct.calcsize("P") * 8
    except Exception:
        return 64 if "64" in platform.architecture()[0] else 32

def _get_windows_pe_bitness(pe_path):
    try:
        with open(pe_path, "rb") as f:
            if f.read(2) != b"MZ":
                return 0
            f.seek(0x3C)
            pe_offset = int.from_bytes(f.read(4), "little", signed=False)
            f.seek(pe_offset)
            if f.read(4) != b"PE\x00\x00":
                return 0
            machine = int.from_bytes(f.read(2), "little", signed=False)
        if machine == 0x8664:
            return 64
        if machine == 0x014C:
            return 32
        if machine == 0xAA64:
            return 64
    except Exception:
        pass
    return 0

def _iter_vlc_runtime_candidates():
    seen = set()

    def _push(path):
        p = os.path.abspath(str(path or "").strip().strip('"'))
        if not p or p in seen:
            return
        seen.add(p)
        yield p

    env_candidates = [
        os.environ.get("VLC_ROOT", ""),
        os.environ.get("VLC_HOME", ""),
        os.environ.get("VLC_INSTALL_DIR", ""),
        os.environ.get("VLC_DIR", ""),
    ]
    for item in env_candidates:
        for out in _push(item):
            yield out

    plugin_env = os.environ.get("VLC_PLUGIN_PATH", "")
    if plugin_env:
        for out in _push(os.path.dirname(plugin_env)):
            yield out

    if sys.platform == "win32":
        for item in [
            os.environ.get("ProgramFiles", ""),
            os.environ.get("ProgramFiles(x86)", ""),
            os.environ.get("LOCALAPPDATA", ""),
        ]:
            if not item:
                continue
            for out in _push(os.path.join(item, "VideoLAN", "VLC")):
                yield out
            for out in _push(os.path.join(item, "Programs", "VideoLAN", "VLC")):
                yield out
        try:
            import winreg
            reg_keys = [
                (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\VideoLAN\VLC"),
                (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\VideoLAN\VLC"),
                (winreg.HKEY_CURRENT_USER, r"SOFTWARE\VideoLAN\VLC"),
            ]
            for hive, subkey in reg_keys:
                try:
                    with winreg.OpenKey(hive, subkey) as key:
                        for value_name in ["InstallDir", "InstallPath", ""]:
                            try:
                                val, _ = winreg.QueryValueEx(key, value_name)
                                for out in _push(val):
                                    yield out
                            except Exception:
                                continue
                except Exception:
                    continue
            if state['karaoke_words']:
                karaoke_generate_button.setText('↻ 重新生成同步字幕（SRT + ASS）')
                karaoke_label.setText('已读取有效的同步字幕缓存：播放时会逐词高亮；可按需重新生成。')
        except Exception:
            pass

    local_candidates = [
        os.path.join(base_dir, "VLC"),
        os.path.join(base_dir, "vlc"),
        base_dir,
        os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else "",
    ]
    for item in local_candidates:
        for out in _push(item):
            yield out

def _probe_vlc_runtime():
    global _VLC_RUNTIME_INFO
    fallback = None
    preferred = None
    py_bits = _get_python_bitness() if sys.platform == "win32" else 0
    for root in _iter_vlc_runtime_candidates():
        libvlc_dll = os.path.join(root, "libvlc.dll") if sys.platform == "win32" else os.path.join(root, "libvlc.so")
        if sys.platform == "darwin":
            libvlc_dll = os.path.join(root, "libvlc.dylib")
        plugins_dir = os.path.join(root, "plugins")
        if os.path.isfile(libvlc_dll):
            dll_bits = _get_windows_pe_bitness(libvlc_dll) if sys.platform == "win32" else 0
            candidate = {
                "root": root,
                "libvlc_dll": libvlc_dll,
                "plugins_dir": plugins_dir if os.path.isdir(plugins_dir) else "",
                "dll_bitness": dll_bits,
                "python_bitness": py_bits,
            }
            if sys.platform == "win32" and py_bits and dll_bits and py_bits != dll_bits:
                if fallback is None:
                    fallback = candidate
                continue
            if candidate["plugins_dir"]:
                preferred = candidate
                break
            if fallback is None:
                fallback = candidate
    if preferred:
        _VLC_RUNTIME_INFO = preferred
        return dict(_VLC_RUNTIME_INFO)
    if fallback:
        _VLC_RUNTIME_INFO = fallback
        return dict(_VLC_RUNTIME_INFO)
    _VLC_RUNTIME_INFO = {"root": "", "libvlc_dll": "", "plugins_dir": "", "dll_bitness": 0, "python_bitness": py_bits}
    return dict(_VLC_RUNTIME_INFO)

def _prepare_vlc_runtime(log_if_missing=True):
    info = _probe_vlc_runtime()
    root = info.get("root", "")
    libvlc_dll = info.get("libvlc_dll", "")
    plugins_dir = info.get("plugins_dir", "")
    dll_bits = int(info.get("dll_bitness", 0) or 0)
    py_bits = int(info.get("python_bitness", 0) or 0)
    if not root or not libvlc_dll:
        if log_if_missing:
            write_debug("[VLC] 未找到 VLC Runtime（libvlc.dll / libvlc.so / libvlc.dylib）")
        return False, info
    if sys.platform == "win32" and py_bits and dll_bits and py_bits != dll_bits:
        if log_if_missing:
            write_debug(f"[VLC] 已找到 VLC Runtime，但位数不匹配：Python={py_bits} 位，libvlc.dll={dll_bits} 位，路径={root}")
        return False, info

    try:
        if sys.platform == "win32":
            path_parts = [p for p in os.environ.get("PATH", "").split(os.pathsep) if p]
            if root not in path_parts:
                os.environ["PATH"] = root + os.pathsep + os.environ.get("PATH", "")
            if hasattr(os, "add_dll_directory"):
                try:
                    _VLC_DLL_DIR_HANDLES.append(os.add_dll_directory(root))
                except Exception:
                    pass
        if plugins_dir:
            os.environ["VLC_PLUGIN_PATH"] = plugins_dir
        return True, info
    except Exception as e:
        write_debug(f"[VLC] 注入 VLC Runtime 路径失败: {e}")
        return False, info

