class InstructionAlbumGalleryView(QListView):
    """Qt Model/View-based instruction album gallery.

    This deliberately uses Qt's mature item-view engine rather than a
    QListWidget full of manually-owned widgets.  The model keeps only metadata
    and stable asset IDs; the view paints only visible cells in batched mode.
    It is consequently safe to refresh a large album without losing the
    selected asset or blocking the workbench on one oversized image.
    """
    asset_open_requested = pyqtSignal(str)
    set_cover_requested = pyqtSignal(str)
    remove_requested = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._asset_model = QStandardItemModel(self)
        self.setModel(self._asset_model)
        self.setViewMode(QListView.ViewMode.IconMode if PYQT_VERSION == 6 else QListView.IconMode)
        self.setResizeMode(QListView.ResizeMode.Adjust if PYQT_VERSION == 6 else QListView.Adjust)
        self.setMovement(QListView.Movement.Static if PYQT_VERSION == 6 else QListView.Static)
        self.setSelectionMode(_ExtendedSelection)
        self.setUniformItemSizes(True)
        try:
            self.setLayoutMode(QListView.LayoutMode.Batched if PYQT_VERSION == 6 else QListView.Batched)
            self.setBatchSize(48)
        except Exception:
            pass
        self.setIconSize(QSize(118, 88)); self.setGridSize(QSize(138, 122)); self.setWordWrap(True)
        self.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers if PYQT_VERSION == 6 else QAbstractItemView.NoEditTriggers)
        self.setContextMenuPolicy(_CustomContextMenu)
        self.customContextMenuRequested.connect(self._open_context_menu)
        self.activated.connect(self._activate_index)

    def selected_asset_id(self):
        index = self.currentIndex()
        return str(index.data(_UserRole) or '') if index.isValid() else ''

    def set_album_entries(self, entries, selected_asset_id=''):
        wanted = str(selected_asset_id or self.selected_asset_id() or '')
        self.setUpdatesEnabled(False)
        try:
            self._asset_model.clear()
            selected_index = None
            for entry in entries or []:
                if not isinstance(entry, dict):
                    continue
                asset_id = str(entry.get('id') or '')
                item = QStandardItem(str(entry.get('original_name') or entry.get('file_name') or '图片'))
                item.setData(asset_id, _UserRole)
                path = str(entry.get('path') or '')
                item.setToolTip(path if path and os.path.isfile(path) else '图片文件已不存在')
                item.setEditable(False)
                item.setSizeHint(QSize(138, 122))
                if path and os.path.isfile(path):
                    # QIcon retains only the file reference until Qt needs to
                    # paint that viewport cell; it does not create a QLabel /
                    # QPixmap widget for every image in the album.
                    item.setIcon(QIcon(path))
                self._asset_model.appendRow(item)
                if asset_id and asset_id == wanted:
                    selected_index = item.index()
            if selected_index is not None:
                self.setCurrentIndex(selected_index)
        finally:
            self.setUpdatesEnabled(True)

    def _activate_index(self, index):
        asset_id = str(index.data(_UserRole) or '') if index.isValid() else ''
        if asset_id:
            self.asset_open_requested.emit(asset_id)

    def _open_context_menu(self, point):
        index = self.indexAt(point)
        if not index.isValid():
            return
        self.setCurrentIndex(index)
        asset_id = str(index.data(_UserRole) or '')
        if not asset_id:
            return
        menu = QMenu(self)
        open_action = menu.addAction('打开原图')
        cover_action = menu.addAction('设为封面')
        remove_action = menu.addAction('从相册移除')
        chosen = menu.exec(self.viewport().mapToGlobal(point)) if PYQT_VERSION == 6 else menu.exec_(self.viewport().mapToGlobal(point))
        if chosen == open_action:
            self.asset_open_requested.emit(asset_id)
        elif chosen == cover_action:
            self.set_cover_requested.emit(asset_id)
        elif chosen == remove_action:
            self.remove_requested.emit(asset_id)

    def keyPressEvent(self, event):
        if event.key() == _Key_Delete:
            asset_id = self.selected_asset_id()
            if asset_id:
                self.remove_requested.emit(asset_id)
                event.accept()
                return
        super().keyPressEvent(event)


def register_bundled_open_fonts():
    """注册随软件发布的 OFL 字体；只在进程内可见，不写入 Windows 系统字体库。"""
    font_dir = os.path.join(base_dir, 'assets', 'fonts')
    if not os.path.isdir(font_dir):
        return []
    families = []
    for filename in sorted(os.listdir(font_dir)):
        if not filename.lower().endswith(('.ttf', '.otf')):
            continue
        try:
            font_id = QFontDatabase.addApplicationFont(os.path.join(font_dir, filename))
            if font_id >= 0:
                families.extend(QFontDatabase.applicationFontFamilies(font_id))
        except Exception:
            continue
    return list(dict.fromkeys(families))


def apply_consistent_light_theme(app):
    """使用独立亮色调色板，避免系统深色主题导致未显式着色的文字不可见。"""
    try:
        # setStyle("Fusion") 会把整棵控件树先卸载、再重新抛光。皮肤切换只需
        # 改调色板和 QSS；Fusion 已经启用时绝不能重复设定，否则一次取色也会造成
        # 数秒钟的界面假死。
        current_style = app.style()
        if current_style is None or str(current_style.objectName() or "").lower() != "fusion":
            app.setStyle("Fusion")
    except Exception:
        pass

    try:
        roles = QPalette.ColorRole if PYQT_VERSION == 6 else QPalette
        palette = QPalette()
        colors = {
            "Window": "#f8fafc", "WindowText": "#111827", "Base": "#ffffff",
            "AlternateBase": "#f1f5f9", "ToolTipBase": "#ffffff", "ToolTipText": "#111827",
            "Text": "#111827", "Button": "#f8fafc", "ButtonText": "#111827",
            "BrightText": "#ffffff", "Highlight": "#2563eb", "HighlightedText": "#ffffff",
            "Link": "#1d4ed8",
        }
        for role_name, color in colors.items():
            palette.setColor(getattr(roles, role_name), QColor(color))
        app.setPalette(palette)
    except Exception as exc:
        try:
            write_debug(f"亮色主题调色板应用失败: {exc}")
        except Exception:
            pass

    # 明确设置常用控件的前景色；局部样式若未声明颜色，也会继承此处的高对比度设置。
    app.setStyleSheet("""
        QWidget { color: #111827; }
        QMainWindow, QDialog { background-color: #f8fafc; }
        QLabel { color: #111827; background-color: transparent; }
        QLineEdit, QTextEdit, QTextBrowser, QPlainTextEdit, QSpinBox, QDoubleSpinBox,
        QComboBox, QListWidget, QTableWidget, QTreeWidget {
            color: #111827; background-color: #ffffff; border: 1px solid #cbd5e1;
        }
        QLineEdit:disabled, QTextEdit:disabled, QComboBox:disabled, QPushButton:disabled,
        QCheckBox:disabled, QRadioButton:disabled, QLabel:disabled { color: #6b7280; }
        QComboBox QAbstractItemView, QMenu {
            color: #111827; background-color: #ffffff; selection-background-color: #dbeafe;
            selection-color: #111827;
        }
        QTableWidget::item { color: #111827; }
        QHeaderView::section {
            color: #1f2937; background-color: #e2e8f0; border: 1px solid #cbd5e1;
        }
        QPushButton, QToolButton {
            color: #111827; background-color: #f8fafc; border: 1px solid #94a3b8;
            padding: 4px 8px; border-radius: 4px;
        }
        QPushButton:hover, QToolButton:hover { background-color: #e2e8f0; }
        QTabBar::tab { color: #111827; background-color: #e2e8f0; padding: 7px 12px; }
        QTabBar::tab:selected { background-color: #ffffff; color: #0f172a; }
        QToolTip { color: #111827; background-color: #ffffff; border: 1px solid #64748b; }
    """)


