def _fit_top_level_window_to_screen(window, available, width, height, x=None, y=None, center=False,
                                    minimum_size=(480, 340), margin=10):
    """把顶层窗口完整限制在屏幕工作区内，始终保留标题栏和系统按钮可操作。"""
    # QWidget 的 geometry 不包含 Windows 的标题栏和阴影；预留这些像素，避免视觉上
    # "窗口已在屏幕内"、实际关闭按钮却落在屏幕外的情况。
    try:
        frame = window.frameGeometry()
        extra_w = max(0, frame.width() - window.width())
        extra_h = max(0, frame.height() - window.height())
    except Exception:
        extra_w, extra_h = 16, 40

    max_width = max(1, available.width() - extra_w - margin * 2)
    max_height = max(1, available.height() - extra_h - margin * 2)
    min_width = min(max_width, max(1, int(minimum_size[0])))
    min_height = min(max_height, max(1, int(minimum_size[1])))
    target_width = max(min_width, min(int(width), max_width))
    target_height = max(min_height, min(int(height), max_height))

    # 不让布局的旧最小值在小屏幕上反向把窗口撑出屏幕。内容区由滚动容器承载。
    try:
        window.setMinimumSize(min_width, min_height)
        window.resize(target_width, target_height)
    except Exception:
        return False

    try:
        # resize 后再取一次真实边框尺寸，作为最终位置约束依据。
        frame = window.frameGeometry()
        frame_width, frame_height = frame.width(), frame.height()
    except Exception:
        frame_width, frame_height = target_width + extra_w, target_height + extra_h

    left = available.left() + margin
    top = available.top() + margin
    right = max(left, available.right() - frame_width - margin + 1)
    bottom = max(top, available.bottom() - frame_height - margin + 1)
    if center or x is None or y is None:
        target_x = left + max(0, (right - left) // 2)
        target_y = top + max(0, (bottom - top) // 2)
    else:
        target_x = max(left, min(int(x), right))
        target_y = max(top, min(int(y), bottom))
    try:
        window.move(target_x, target_y)
        return True
    except Exception:
        return False


def restore_window_geometry_safely(window, geometry, default_size=(1280, 820), min_visible_width=240, min_visible_height=160,
                                   preferred_screen_name=''):
    """恢复窗口位置；旧屏幕的坐标或过大尺寸会自动缩小、居中或校正。"""
    if not isinstance(geometry, (list, tuple)) or len(geometry) != 4:
        return False
    try:
        x, y, width, height = [int(value) for value in geometry]
    except (TypeError, ValueError):
        return False
    if width <= 0 or height <= 0:
        return False

    try:
        screens = QApplication.screens()
        primary_screen = QApplication.primaryScreen()
    except Exception:
        return False
    if not screens or primary_screen is None:
        return False

    saved_rect = QRect(x, y, max(1, width), max(1, height))
    target_screen = None
    largest_area = 0
    for screen in screens:
        available = screen.availableGeometry()
        overlap = saved_rect.intersected(available)
        overlap_area = max(0, overlap.width()) * max(0, overlap.height())
        if (overlap.width() >= min_visible_width and overlap.height() >= min_visible_height
                and overlap_area > largest_area):
            target_screen = screen
            largest_area = overlap_area

    # Windows 可能在接线、休眠或远程桌面后重排显示器坐标。若保存的
    # 屏幕名称仍存在，优先回到同一块物理屏幕，而不因为旧坐标失效就跳回屏幕 1。
    if target_screen is None:
        target_screen = next((screen for screen in screens if str(screen.name() or '') == str(preferred_screen_name or '')), primary_screen)
        center_on_screen = True
    else:
        center_on_screen = False

    available = target_screen.availableGeometry()
    # 已保存窗口不能占满可用区：留下边缘可拖动区域，也能避免标题栏被系统缩放裁掉。
    comfortable_width = max(1, round(available.width() * 0.94))
    comfortable_height = max(1, round(available.height() * 0.92))
    width = min(width, comfortable_width)
    height = min(height, comfortable_height)
    return _fit_top_level_window_to_screen(
        window, available, width, height, x=x, y=y, center=center_on_screen,
        minimum_size=(min(default_size[0] // 2, 640), min(default_size[1] // 2, 440)),
    )


def get_window_monitor_handoff(window):
    """Capture both Qt's screen name and the real Windows monitor device id."""
    handoff = {'screen_name': '', 'monitor_device': '', 'monitor_work': []}
    try:
        point = window.frameGeometry().center()
        screen = QApplication.screenAt(point) or window.screen() or QApplication.primaryScreen()
        handoff['screen_name'] = str(screen.name() or '') if screen is not None else ''
    except Exception:
        pass
    if os.name != 'nt':
        return handoff
    try:
        import ctypes
        from ctypes import wintypes

        class MonitorInfo(ctypes.Structure):
            _fields_ = [
                ('cbSize', wintypes.DWORD), ('rcMonitor', wintypes.RECT),
                ('rcWork', wintypes.RECT), ('dwFlags', wintypes.DWORD),
                ('szDevice', wintypes.WCHAR * 32),
            ]

        monitor = ctypes.windll.user32.MonitorFromWindow(int(window.winId()), 2)  # nearest monitor
        info = MonitorInfo(); info.cbSize = ctypes.sizeof(MonitorInfo)
        if monitor and ctypes.windll.user32.GetMonitorInfoW(monitor, ctypes.byref(info)):
            handoff['monitor_device'] = str(info.szDevice or '')
            handoff['monitor_work'] = [info.rcWork.left, info.rcWork.top, info.rcWork.right, info.rcWork.bottom]
    except Exception:
        pass
    return handoff


