class PathDropTextEdit(QTextEdit):
    """支持把多个文件夹/文件直接拖入的多行文本框。"""
    def __init__(self, parent=None, accept_dirs=True, accept_files=False):
        super().__init__(parent)
        self.accept_dirs = accept_dirs
        self.accept_files = accept_files
        # 多次拖入是否保留此前路径。默认维持旧页面“本次拖入即替换”的行为；
        # 需要累计素材的页面可显式打开，避免第二次拖入看似丢失第一批视频。
        self.append_dropped_paths = False
        self.setAcceptDrops(True)
        self.setFixedHeight(60) # 默认高度，显示约2-3行

    def _extract_local_path(self, url):
        path = url.toLocalFile()
        if not path:
            raw = url.toString()
            if raw.startswith("file:///"):
                path = urllib.parse.unquote(raw[8:])
                if sys.platform == 'win32' and path.startswith('/'):
                    path = path[1:]
        return normalize_user_path(path) if path else ""

    def _is_acceptable_path(self, path):
        if not path: return False
        return (self.accept_dirs and os.path.isdir(path)) or (self.accept_files and os.path.isfile(path))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if self._is_acceptable_path(self._extract_local_path(url)):
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dragMoveEvent(self, event):
        self.dragEnterEvent(event)

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore(); return
        paths = []
        for url in event.mimeData().urls():
            path = self._extract_local_path(url)
            if self._is_acceptable_path(path):
                paths.append(path)
        if paths:
            if self.append_dropped_paths:
                merged, seen = [], set()
                for value in list(self.toPlainText().splitlines()) + paths:
                    value = str(value or '').strip()
                    if not value:
                        continue
                    key = os.path.normcase(os.path.abspath(value))
                    if key not in seen:
                        merged.append(value); seen.add(key)
                self.setPlainText("\n".join(merged))
            else:
                self.setPlainText("\n".join(paths))
            event.acceptProposedAction()
        else:
            event.ignore()

    # 兼容 QLineEdit 的常用方法
    def text(self): return self.toPlainText()
    def setText(self, t): self.setPlainText(t)


class SpreadsheetFileDropHandler(QObject):
    """把资源管理器中的可读取表格拖入指定页面后交给原有加载流程。"""
    spreadsheet_dropped = pyqtSignal(str)
    SUPPORTED_SUFFIXES = {".xlsx", ".csv", ".tsv"}

    def _spreadsheet_path_from_event(self, event):
        if not event.mimeData() or not event.mimeData().hasUrls():
            return ""
        for url in event.mimeData().urls():
            try:
                path = normalize_user_path(url.toLocalFile())
            except Exception:
                path = ""
            if path and os.path.isfile(path) and os.path.splitext(path)[1].lower() in self.SUPPORTED_SUFFIXES:
                return path
        return ""

    def eventFilter(self, watched, event):
        drag_enter = QEvent.Type.DragEnter if PYQT_VERSION == 6 else QEvent.DragEnter
        drag_move = QEvent.Type.DragMove if PYQT_VERSION == 6 else QEvent.DragMove
        drop = QEvent.Type.Drop if PYQT_VERSION == 6 else QEvent.Drop
        if event.type() in (drag_enter, drag_move):
            if self._spreadsheet_path_from_event(event):
                event.acceptProposedAction()
                return True
            event.ignore()
            return False
        if event.type() == drop:
            path = self._spreadsheet_path_from_event(event)
            if not path:
                event.ignore()
                return False
            event.acceptProposedAction()
            self.spreadsheet_dropped.emit(path)
            return True
        return super().eventFilter(watched, event)


def open_folder_from_path_widget(input_widget, parent=None):
    """打开路径输入框的首条有效路径；文件自动定位到其所在目录。

    配置中允许保存日期等路径模板；打开前必须展开，不能把
    ``{yyyy-MM-dd}`` 当作真实文件夹名称。
    """
    try:
        raw_paths = [line.strip().strip('"') for line in input_widget.text().splitlines() if line.strip()]
    except Exception:
        raw_paths = []
    if not raw_paths:
        QMessageBox.information(parent, "打开文件夹", "请先填写或选择一个有效路径。")
        return
    selected = normalize_user_path(render_path_template(raw_paths[0]))
    folder = selected if os.path.isdir(selected) else os.path.dirname(selected)
    # UNC 服务器根目录（例如 \\192.168.1.3）可以由资源管理器继续浏览，
    # 但 ``os.path.isdir`` 在未连接共享名时可能返回 False，不能提前拦截。
    if not folder or (not os.path.isdir(folder) and not is_network_share_path(selected)):
        QMessageBox.warning(parent, "打开文件夹", f"找不到可打开的文件夹：\n{folder or selected}")
        return
    try:
        QDesktopServices.openUrl(QUrl.fromLocalFile(folder))
    except Exception as exc:
        QMessageBox.warning(parent, "打开文件夹", f"无法打开文件夹：\n{exc}")

class PathDropLineEdit(QLineEdit):
    """支持把文件夹/文件拖入的单行输入框（用于路径）。"""
    def __init__(self, parent=None, accept_dirs=True, accept_files=False):
        super().__init__(parent)
        self.accept_dirs = accept_dirs
        self.accept_files = accept_files
        self.setAcceptDrops(True)

    def _extract_local_path(self, url):
        path = ""
        try:
            path = url.toLocalFile()
        except Exception:
            path = ""
        if not path:
            raw = ""
            try:
                raw = url.toString()
            except Exception:
                raw = ""
            if raw.startswith("file:///"):
                path = urllib.parse.unquote(raw[8:])
                if sys.platform == 'win32' and path.startswith('/'):
                    path = path[1:]
        return normalize_user_path(path) if path else ""

    def _is_acceptable_path(self, path):
        if not path:
            return False
        return (self.accept_dirs and os.path.isdir(path)) or (self.accept_files and os.path.isfile(path))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if self._is_acceptable_path(self._extract_local_path(url)):
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dragMoveEvent(self, event):
        self.dragEnterEvent(event)

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore()
            return
        for url in event.mimeData().urls():
            path = self._extract_local_path(url)
            if self._is_acceptable_path(path):
                self.setText(path)
                event.acceptProposedAction()
                return
        event.ignore()

class ChatInputTextEdit(QTextEdit):
    """聊天输入框：支持拖入文件/文件夹作为附件。"""
    attachments_dropped = pyqtSignal(list)
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragEnterEvent(event)
    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
        else:
            super().dragMoveEvent(event)
    def dropEvent(self, event):
        urls = event.mimeData().urls() if event.mimeData() and event.mimeData().hasUrls() else []
        paths = []
        for url in urls:
            try:
                p = url.toLocalFile()
            except Exception:
                p = ""
            if p:
                p = normalize_user_path(p)
                if os.path.exists(p):
                    paths.append(p)
        if paths:
            self.attachments_dropped.emit(paths)
            event.acceptProposedAction()
            return
        super().dropEvent(event)

# 所有素材图片入口共用同一份格式表，不能让扫描、拖入与预览各自漏格式。
# 多页/动态图只使用第一帧；原文件整理导出时不做格式转换。
MATERIAL_IMAGE_EXTS = (
    '.jpg', '.jpeg', '.jpe', '.jfif', '.png', '.apng', '.webp', '.bmp',
    '.dib', '.gif', '.tif', '.tiff', '.ico', '.icns', '.pcx', '.tga',
    '.ppm', '.pgm', '.pbm', '.pnm', '.pam', '.jp2', '.j2k', '.jpf',
    '.jpx', '.jpc', '.jpm', '.psd', '.dds', '.qoi', '.avif', '.avifs',
    '.heic', '.heif', '.hif', '.heics', '.heifs', '.svg', '.svgz',
    '.eps', '.ps', '.wmf', '.emf', '.xbm', '.xpm', '.cur', '.sgi', '.rgb', '.rgba',
    '.bw', '.fits', '.fit', '.fts', '.fli', '.flc', '.pcd', '.im', '.msp', '.wal',
    '.dng', '.cr2', '.cr3', '.nef', '.nrw', '.arw', '.raf', '.orf', '.rw2', '.pef', '.srw',
)
MATERIAL_IMAGE_FILTER = '图片文件 (' + ' '.join('*' + ext for ext in MATERIAL_IMAGE_EXTS) + ');;所有文件 (*.*)'


def load_material_image(path):
    """统一解码为独立 RGB 图像；不修改原文件，不把解码失败当成不存在。"""
    from PIL import Image, ImageOps
    ext = os.path.splitext(str(path))[1].lower()
    try:
        if ext in ('.heic', '.heif', '.hif', '.heics', '.heifs'):
            try:
                from pillow_heif import register_heif_opener
            except ImportError as exc:
                raise RuntimeError('HEIC/HEIF 解码组件未安装：需要 pillow-heif') from exc
            register_heif_opener()
        if ext in ('.dng', '.cr2', '.cr3', '.nef', '.nrw', '.arw', '.raf', '.orf', '.rw2', '.pef', '.srw'):
            try:
                import rawpy
            except ImportError as exc:
                raise RuntimeError('相机 RAW 解码组件未安装：需要 rawpy') from exc
            with rawpy.imread(str(path)) as raw:
                return Image.fromarray(raw.postprocess(use_camera_wb=True, output_bps=8))
        if ext in ('.svg', '.svgz'):
            if PYQT_VERSION == 6:
                from PyQt6.QtSvg import QSvgRenderer
            else:
                from PyQt5.QtSvg import QSvgRenderer
            renderer = QSvgRenderer(str(path))
            if not renderer.isValid():
                raise ValueError('SVG 文件无法解析')
            size = renderer.defaultSize()
            if size.isEmpty():
                raise ValueError('SVG 没有有效画布尺寸')
            size.scale(2048, 2048, Qt.AspectRatioMode.KeepAspectRatio if PYQT_VERSION == 6 else Qt.KeepAspectRatio)
            canvas = QImage(size, QImage.Format.Format_ARGB32 if PYQT_VERSION == 6 else QImage.Format_ARGB32)
            canvas.fill(QColor('white'))
            painter = QPainter(canvas)
            try:
                renderer.render(painter)
            finally:
                painter.end()
            canvas = canvas.convertToFormat(QImage.Format.Format_RGBA8888 if PYQT_VERSION == 6 else QImage.Format_RGBA8888)
            bits = canvas.bits()
            bits.setsize(canvas.sizeInBytes() if PYQT_VERSION == 6 else canvas.byteCount())
            return Image.frombytes('RGBA', (canvas.width(), canvas.height()), bytes(bits)).convert('RGB')
        with Image.open(path) as source:
            source.seek(0)
            oriented = ImageOps.exif_transpose(source)
            rgba = oriented.convert('RGBA')
            background = Image.new('RGBA', rgba.size, 'white')
            return Image.alpha_composite(background, rgba).convert('RGB')
    except Exception as exc:
        raise RuntimeError(f'无法解码图片 {os.path.basename(str(path))}：{exc}；原文件已保留') from exc


def material_image_pixmap(path):
    """Qt 没有对应格式插件时，仍用与匹配相同的解码器预览。"""
    pixmap = QPixmap(path)
    if not pixmap.isNull():
        return pixmap
    try:
        with load_material_image(path) as source:
            source.thumbnail((2048, 2048))
            buf = io.BytesIO()
            source.save(buf, format='PNG')
            pixmap.loadFromData(buf.getvalue(), 'PNG')
    except Exception:
        pass
    return pixmap


def is_image_path(path):
    ext = os.path.splitext(str(path or ""))[1].lower()
    return ext in MATERIAL_IMAGE_EXTS

def safe_read_text_file(path, max_chars=5000):
    encodings = ["utf-8", "utf-8-sig", "gbk", "gb18030", "latin-1"]
    for enc in encodings:
        try:
            with open(path, "r", encoding=enc) as f:
                return f.read(max_chars)
        except Exception:
            continue
    return ""

def summarize_folder_for_ai(folder_path, max_items=40):
    try:
        folders = 0
        files = 0
        samples = []
        for root, dirnames, filenames in os.walk(folder_path):
            folders += len(dirnames)
            files += len(filenames)
            for name in filenames[:max(0, max_items - len(samples))]:
                rel = os.path.relpath(os.path.join(root, name), folder_path)
                samples.append(rel)
            if len(samples) >= max_items:
                break
        lines = [
            f"文件夹路径: {folder_path}",
            f"共发现 {folders} 个子文件夹，{files} 个文件。"
        ]
        if samples:
            lines.append("样例文件:")
            lines.extend([f"- {item}" for item in samples[:max_items]])
        return "\n".join(lines)
    except Exception as e:
        return f"文件夹路径: {folder_path}\n读取失败: {e}"

def summarize_attachment_for_ai(att):
    path = str(att.get("path", "") or "").strip()
    if not path:
        return ""
    name = att.get("name") or os.path.basename(path) or path
    kind = att.get("kind") or ("folder" if os.path.isdir(path) else "file")
    if not os.path.exists(path):
        return f"[附件] {name}\n路径: {path}\n状态: 文件不存在"
    if kind == "folder" or os.path.isdir(path):
        return f"[文件夹附件] {name}\n{summarize_folder_for_ai(path)}"
    mime, _ = mimetypes.guess_type(path)
    if is_image_path(path):
        return f"[图片附件] {name}\n路径: {path}\n说明: 这是用户附带的图片，可结合路径和文件名理解上下文。"
    text_exts = {".txt", ".md", ".markdown", ".csv", ".json", ".py", ".log", ".ini", ".yaml", ".yml", ".toml"}
    ext = os.path.splitext(path)[1].lower()
    if ext in text_exts or (mime and mime.startswith("text/")):
        content = safe_read_text_file(path, 5000)
        if content:
            return f"[文本附件] {name}\n路径: {path}\n内容摘录:\n{content}"
    try:
        size_kb = os.path.getsize(path) / 1024.0
    except Exception:
        size_kb = 0
    return f"[文件附件] {name}\n路径: {path}\n大小: {size_kb:.1f} KB"

def render_markdown_html(text):
    # Markdown's default renderer passes raw HTML through unchanged.  Chat
    # messages can originate from a remote API, so treat all HTML tags as
    # text before rendering the Markdown syntax itself.
    raw = html.escape(str(text or ""), quote=False)
    try:
        import markdown as _markdown
        html_body = _markdown.markdown(
            raw,
            extensions=["fenced_code", "tables", "sane_lists", "nl2br"]
        )
    except Exception:
        html_body = html.escape(raw).replace("\n", "<br>")
    return html_body

def parse_plan_items_from_text(text, fallback_source="AI"):
    lines = str(text or "").splitlines()
    items = []
    priority_keywords = [
        ("高", ["p0", "p1", "高优先级", "紧急", "重要", "urgent", "high"]),
        ("中", ["p2", "中优先级", "一般", "normal", "medium"]),
        ("低", ["p3", "低优先级", "稍后", "low", "later"])
    ]
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        line = re.sub(r"^\s*(?:[-*•]|\d+[.)]|`)\s*", "", line).strip()
        if not line or len(line) < 2:
            continue
        if len(items) >= 50:
            break
        priority = "中"
        lower = line.lower()
        for label, keys in priority_keywords:
            if any(k in lower for k in keys):
                priority = label
                line = re.sub("|".join(re.escape(k) for k in keys[:3]), "", line, flags=re.I).strip(" :：-")
                break
        items.append({
            "done": False,
            "priority": priority,
            "content": line[:200],
            "deadline": "",
            "source": fallback_source
        })
    return items

