# ─────────────────────────────────────────────
#  整合修复后的 UniversalEngine 类
# ─────────────────────────────────────────────
class GPUMonitor(QThread):
    update_signal = pyqtSignal(dict)
    def __init__(self, parent=None):
        super().__init__(parent)
        self._running = True

    def stop(self):
        self._running = False

    @staticmethod
    def _nvml_name(pynvml, handle):
        try:
            name = pynvml.nvmlDeviceGetName(handle)
            return name.decode('utf-8', errors='replace') if isinstance(name, bytes) else str(name)
        except Exception:
            return 'NVIDIA 独立显卡'

    def _select_nvml_discrete_gpu(self, pynvml):
        """优先选择可读取利用率且显存最大的 NVIDIA 独显。"""
        devices = []
        try:
            count = int(pynvml.nvmlDeviceGetCount())
        except Exception:
            count = 0
        for index in range(max(0, count)):
            try:
                handle = pynvml.nvmlDeviceGetHandleByIndex(index)
                memory = pynvml.nvmlDeviceGetMemoryInfo(handle)
                utilization = pynvml.nvmlDeviceGetUtilizationRates(handle)
                devices.append((int(memory.total or 0), handle, self._nvml_name(pynvml, handle), utilization))
            except Exception:
                continue
        if not devices:
            return None
        devices.sort(key=lambda row: row[0], reverse=True)
        return devices[0][1], devices[0][2]

    @staticmethod
    def _nvml_task_manager_like_utilization(pynvml, handle):
        """取独显最繁忙引擎，避免视频编解码时 NVML 核心占用偏低。"""
        readings = []
        try:
            readings.append(float(pynvml.nvmlDeviceGetUtilizationRates(handle).gpu))
        except Exception:
            pass
        # Windows 任务管理器的 GPU 百分比按最繁忙的图形、计算或媒体引擎显示。
        # NVML 的 gpu 字段未必包含视频解码/编码，所以同时读取可用媒体引擎。
        for method_name in (
            'nvmlDeviceGetEncoderUtilization',
            'nvmlDeviceGetDecoderUtilization',
            'nvmlDeviceGetJpgUtilization',
            'nvmlDeviceGetOfaUtilization',
        ):
            try:
                result = getattr(pynvml, method_name)(handle)
                value = result[0] if isinstance(result, (tuple, list)) else result
                readings.append(float(value))
            except Exception:
                continue
        return max(0.0, min(100.0, max(readings))) if readings else None

    @staticmethod
    def _open_windows_gpu_fallback_counter():
        """无独显数据时读取 Windows GPU Engine 计数器；优先原生计数器。"""
        try:
            import win32pdh
            query = win32pdh.OpenQuery()
            _items, instances = win32pdh.EnumObjectItems(None, None, 'GPU Engine', win32pdh.PERF_DETAIL_WIZARD)
            counters = []
            for instance in instances:
                # 使用最繁忙引擎而非累加，因此保留 3D、编解码等所有引擎，
                # 与 Windows 任务管理器的 GPU 总使用率口径一致。
                path = rf'\GPU Engine({instance})\Utilization Percentage'
                try:
                    counters.append((str(instance), win32pdh.AddCounter(query, path)))
                except Exception:
                    continue
            if not counters:
                win32pdh.CloseQuery(query)
                return ('cim',)
            win32pdh.CollectQueryData(query)  # 首次采样用于建立基线
            return ('pdh', win32pdh, query, counters)
        except Exception:
            # 很多只带集显的机器并未安装 pywin32。CIM 是 Windows 自带的
            # GPU 性能类，不需要额外安装监控软件，作为兼容回退。
            return ('cim',)

    @staticmethod
    def _read_windows_gpu_fallback(counter_state):
        if not counter_state:
            return None
        if counter_state[0] == 'cim':
            try:
                startupinfo = None
                creationflags = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
                command = (
                    "$ErrorActionPreference='Stop'; "
                    "$rows=@(); "
                    "try {$rows=Get-CimInstance -ClassName Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine "
                    "| ForEach-Object {[pscustomobject]@{Name=$_.Name;Value=$_.UtilizationPercentage}}} catch {}; "
                    "if (!$rows) {try {$rows=(Get-Counter -Counter '\\GPU Engine(*)\\Utilization Percentage' "
                    "-ErrorAction Stop).CounterSamples | ForEach-Object {[pscustomobject]@{Name=$_.InstanceName;Value=$_.CookedValue}}} catch {}}; "
                    "$rows | ConvertTo-Json -Compress"
                )
                completed = subprocess.run(
                    ['powershell', '-NoProfile', '-NonInteractive', '-Command', command],
                    capture_output=True, text=True, encoding='utf-8', errors='replace',
                    timeout=3, startupinfo=startupinfo, creationflags=creationflags,
                )
                if completed.returncode != 0 or not completed.stdout.strip():
                    return None
                rows = json.loads(completed.stdout)
                if isinstance(rows, dict):
                    rows = [rows]
                grouped = {}
                for row in rows or []:
                    name = str((row or {}).get('Name', ''))
                    value = float((row or {}).get('Value', 0) or 0)
                    # 同一块 GPU 的各个引擎按 LUID 聚合，采用最繁忙引擎值，
                    # 与 Windows 任务管理器的总使用率展示方式一致。
                    match = re.search(r'luid_0x[0-9a-fA-F_]+', name, re.I)
                    key = match.group(0).lower() if match else name
                    grouped[key] = max(value, grouped.get(key, 0.0))
                if grouped:
                    return max(0.0, min(100.0, max(grouped.values())))
            except Exception:
                return None
            return None
        try:
            _mode, win32pdh, query, counters = counter_state
            win32pdh.CollectQueryData(query)
            grouped = {}
            for instance, counter in counters:
                _kind, value = win32pdh.GetFormattedCounterValue(counter, win32pdh.PDH_FMT_DOUBLE)
                # 同一 LUID 是同一块显卡的多个进程/引擎；保留使用率最高的 3D 引擎。
                key_match = re.search(r'luid_0x[0-9a-fA-F_]+', instance)
                key = key_match.group(0) if key_match else instance
                grouped[key] = max(float(value or 0.0), grouped.get(key, 0.0))
            if grouped:
                return max(0.0, min(100.0, max(grouped.values())))
        except Exception:
            return None
        return None

    def run(self):
        pynvml = None
        fallback_counter = None
        try:
            import pynvml
            pynvml.nvmlInit()
            selected = self._select_nvml_discrete_gpu(pynvml)
            if selected is None:
                raise RuntimeError('没有可读取利用率的 NVIDIA 独显')
            handle, gpu_name = selected
            while self._running:
                info = pynvml.nvmlDeviceGetMemoryInfo(handle)
                temp = pynvml.nvmlDeviceGetTemperature(handle, 0) # 0 = NVML_TEMPERATURE_GPU
                utilization = self._nvml_task_manager_like_utilization(pynvml, handle)
                self.update_signal.emit({
                    "used": info.used // 1024**2, 
                    "total": info.total // 1024**2, 
                    "temp": temp,
                    "gpu_util": utilization,
                    "gpu_name": gpu_name,
                    "gpu_kind": "独立显卡",
                })
                self.msleep(1000)
        except Exception:
            # NVIDIA 独显不存在或不可读取时，才回退到 Windows 图形引擎（常见为集显）。
            fallback_counter = self._open_windows_gpu_fallback_counter()
            unavailable_reported = False
            while self._running and fallback_counter is not None:
                utilization = self._read_windows_gpu_fallback(fallback_counter)
                if utilization is None and not unavailable_reported:
                    write_debug("GPU 监测不可用：Windows 未提供可读取的 GPU 使用率计数器。")
                    unavailable_reported = True
                self.update_signal.emit({
                    # 集显显存通常是系统共享内存，Windows 没有可靠的显存/温度值。
                    # 以 None 传给界面，绝不能伪装成 0°C 或令进度条进入忙碌动画。
                    "used": 0, "total": 0, "temp": None, "gpu_util": utilization,
                    "gpu_name": "Windows 图形引擎" if utilization is not None else "系统未提供 GPU 使用率计数器",
                    "gpu_kind": "集成/通用显卡" if utilization is not None else "不可用",
                })
                # CIM/PowerShell 是备用方案：低频采集以避免只有集显的机器
                # 持续创建系统查询进程，造成卡顿或长期运行不稳定。
                self.msleep(3000 if fallback_counter[0] == 'cim' else 1000)
        finally:
            try:
                if fallback_counter is not None:
                    if fallback_counter[0] == 'pdh':
                        fallback_counter[1].CloseQuery(fallback_counter[2])
            except Exception:
                pass
            try:
                if pynvml is not None:
                    pynvml.nvmlShutdown()
            except Exception:
                pass

class UniversalEngine:
    def __init__(self, log_callback):
        self.log_callback = log_callback
        self.vision_cache = {} # 视觉特征缓存
        self.model = None
        self.processor = None
        self.tokenizer = None
        self.current_model_path = ""
        self.is_vision_model = False
        self.supports_text = False
        self.supports_vision = False
        self.model_family = "unknown"
        self.is_gguf = False
        self.last_error = ""
        self.last_error_detail = ""
        # 引入停止标志位，支持推理中断
        self.stop_criteria = StopOnFlag()
        
    def log(self, msg, color=None):
        if self.log_callback:
            # 兼容 pyqtSignal 和普通函数回调
            # 注意：如果 log_callback 是 pyqtSignal，它可能不支持颜色参数，这里做兼容处理
            if hasattr(self.log_callback, "emit"):
                self.log_callback.emit(str(msg))
            else:
                try: self.log_callback(msg, color)
                except: self.log_callback(msg)
        try:
            write_debug(f"[{color if color else 'LOG'}] {msg}")
        except Exception:
            pass

    def _gpu_report(self):
        """返回适合展示给用户的 CUDA/显卡状态说明。"""
        try:
            if not torch.cuda.is_available():
                return "未检测到 PyTorch CUDA。请确认已安装 NVIDIA 驱动、CUDA 版 PyTorch，并且程序不是在 CPU-only 环境中运行。"
            idx = torch.cuda.current_device()
            props = torch.cuda.get_device_properties(idx)
            total_gb = props.total_memory / 1024**3
            try:
                free_b, total_b = torch.cuda.mem_get_info(idx)
                free_gb = free_b / 1024**3
                return f"CUDA 可用：{props.name}，总显存 {total_gb:.1f}GB，当前空闲 {free_gb:.1f}GB。"
            except Exception:
                return f"CUDA 可用：{props.name}，总显存 {total_gb:.1f}GB。"
        except Exception as e:
            return f"CUDA 状态检测失败：{e}"

    def _llama_cpp_gpu_status(self):
        """检测 llama-cpp-python 是否具备 GPU offload 能力。"""
        try:
            import llama_cpp
            ver = getattr(llama_cpp, "__version__", "未知版本")
            supports_gpu = None
            if hasattr(llama_cpp, "llama_supports_gpu_offload"):
                try:
                    supports_gpu = bool(llama_cpp.llama_supports_gpu_offload())
                except Exception:
                    supports_gpu = None
            if supports_gpu is True:
                return f"llama-cpp-python {ver}：检测到支持 GPU/CUDA offload。"
            if supports_gpu is False:
                return f"llama-cpp-python {ver}：当前是 CPU 版或未启用 GPU offload。"
            return f"llama-cpp-python {ver}：无法自动确认是否支持 GPU offload。"
        except ImportError:
            return "未安装 llama-cpp-python，因此无法加载 .gguf 模型。"
        except Exception as e:
            return f"llama-cpp-python 状态检测失败：{e}"

    def _is_chinese(self, string):
        """判断字符串是否包含中文"""
        for char in string:
            if '\u4e00' <= char <= '\u9fa5':
                return True
        return False

    def _format_gguf_error(self, err, model_path):
        raw = str(err).strip() or repr(err)
        lower = raw.lower()
        hints = []
        if isinstance(err, ImportError) or "no module named 'llama_cpp'" in lower or "no module named llama_cpp" in lower:
            hints.append("缺少 GGUF 依赖：请安装 llama-cpp-python。")
        if "cuda" in lower or "cublas" in lower or "ggml_cuda" in lower or "gpu" in lower:
            hints.append("CUDA/GPU 加载失败：请确认安装的是支持 CUDA 的 llama-cpp-python，而不是 CPU 版。")
        if "out of memory" in lower or "cuda error 2" in lower or "memory" in lower or "failed to allocate" in lower:
            hints.append("显存不足：GTX 2080Ti 11GB 建议优先使用 7B/8B 的 Q4_K_M、Q5_K_M 量化模型，或减少 GPU 层数/上下文长度。")
        if "unknown model architecture" in lower or "unsupported" in lower or "invalid model" in lower:
            hints.append("模型格式或架构不被当前 llama-cpp-python 支持：请升级 llama-cpp-python，或换用新版/兼容的 GGUF 文件。")
        if "mmproj" in lower or "clip" in lower:
            hints.append("视觉 GGUF 需要匹配的 mmproj/clip 文件；纯文本模型请不要选择视觉组件。")
        if not os.path.exists(model_path):
            hints.append("模型路径不存在，请确认 .gguf 文件位于程序根目录的 models 文件夹中。")
        if self._is_chinese(model_path):
            hints.append("检测到路径包含中文！这是加载失败的最常见原因。建议将程序和模型移动到纯英文路径（例如 D:\\AI\\models）下再试。")
        if "Failed to load model from file" in raw:
            hints.append("底层加载失败：可能是模型文件损坏、路径不支持中文、或者该 GGUF 架构需要更高版本的 llama-cpp-python。")
        if not hints:
            hints.append("常见原因包括：依赖缺失、llama-cpp-python 为 CPU 版、显存不足、GGUF 模型损坏或模型架构过新。")

        install_tip = (
            "安装/重装 CUDA 版 llama-cpp-python 的常用命令（Windows PowerShell）：\n"
            "pip uninstall -y llama-cpp-python\n"
            "$env:CMAKE_ARGS='-DGGML_CUDA=on'\n"
            "$env:FORCE_CMAKE='1'\n"
            "pip install --no-cache-dir --force-reinstall llama-cpp-python\n\n"
            "如果你使用的是预编译 CUDA wheel，也可以按 llama-cpp-python 官方说明安装与你 CUDA 版本匹配的 cuBLAS/CUDA wheel。"
        )
        return (
            f"GGUF 模型加载失败：{raw}\n\n"
            f"环境检测：\n- {self._gpu_report()}\n- {self._llama_cpp_gpu_status()}\n\n"
            "可能原因/处理建议：\n- " + "\n- ".join(hints) + "\n\n" + install_tip
        )

    def force_clean(self):
        self.log("🧹 清理显存/内存...")
        try:
            if self.model:
                if hasattr(self.model, "to"): self.model.to("cpu")
                del self.model
            if self.processor: del self.processor
            if self.tokenizer: del self.tokenizer
        except: pass
        self.model = None
        self.processor = None
        self.tokenizer = None
        self.current_model_path = ""
        self.is_vision_model = False
        self.supports_text = False
        self.supports_vision = False
        self.model_family = "unknown"
        self.is_gguf = False
        gc.collect()
        if torch is not None and torch.cuda.is_available(): torch.cuda.empty_cache()
        self.log("✓ 已重置引擎")

    def _flatten_message_content(self, obj):
        if isinstance(obj, str):
            return obj
        if isinstance(obj, list):
            parts = []
            for item in obj:
                if isinstance(item, dict):
                    if item.get("type") == "text":
                        parts.append(str(item.get("text", "") or ""))
                    elif "text" in item:
                        parts.append(str(item.get("text", "") or ""))
                elif item is not None:
                    parts.append(str(item))
            return " ".join(p for p in parts if p).strip()
        if isinstance(obj, dict):
            return self._flatten_message_content(obj.get("text", ""))
        return str(obj) if obj is not None else ""

    def _detect_transformers_capabilities(self, config, model_path):
        model_type = str(getattr(config, "model_type", "") or "").lower()
        arch_text = " ".join(getattr(config, "architectures", []) or []).lower()
        auto_map = getattr(config, "auto_map", {}) or {}
        try:
            auto_map_text = json.dumps(auto_map, ensure_ascii=False).lower()
        except Exception:
            auto_map_text = str(auto_map).lower()
        probe_text = " | ".join([model_type, arch_text, auto_map_text, str(model_path).lower()])
        vision_markers = [
            "qwen2_vl", "qwen2_5_vl", "vl", "vision", "image",
            "llava", "moondream", "internvl", "idefics", "cogvlm",
            "fuyu", "paligemma", "phi3_v", "minicpmv", "mplug", "ovis"
        ]
        has_vision_config = any([
            getattr(config, "vision_config", None) is not None,
            getattr(config, "image_token_id", None) is not None,
            getattr(config, "image_token_index", None) is not None,
            getattr(config, "mm_vision_tower", None) is not None,
            getattr(config, "vision_tower", None) is not None,
        ])
        supports_vision = has_vision_config or any(marker in probe_text for marker in vision_markers)
        return {
            "model_type": model_type,
            "supports_text": True,
            "supports_vision": bool(supports_vision)
        }

    def _load_tokenizer_with_fallback(self, model_path):
        tokenizer_errors = []
        for use_fast in (True, False):
            try:
                tokenizer = AutoTokenizer.from_pretrained(
                    model_path,
                    trust_remote_code=False,
                    local_files_only=True,
                    use_fast=use_fast
                )
                if getattr(tokenizer, "pad_token", None) is None and getattr(tokenizer, "eos_token", None):
                    tokenizer.pad_token = tokenizer.eos_token
                return tokenizer
            except Exception as e:
                tokenizer_errors.append(f"use_fast={use_fast}: {e}")
        try:
            fallback_processor = AutoProcessor.from_pretrained(
                model_path, trust_remote_code=False, local_files_only=True
            )
            tokenizer = getattr(fallback_processor, "tokenizer", None)
            if tokenizer:
                if getattr(tokenizer, "pad_token", None) is None and getattr(tokenizer, "eos_token", None):
                    tokenizer.pad_token = tokenizer.eos_token
                if not self.processor:
                    self.processor = fallback_processor
                return tokenizer
        except Exception as e:
            tokenizer_errors.append(f"processor fallback: {e}")
        raise RuntimeError("Tokenizer 加载失败：\n- " + "\n- ".join(tokenizer_errors))

    def _build_text_prompt(self, history):
        if self.tokenizer and hasattr(self.tokenizer, "apply_chat_template"):
            return self.tokenizer.apply_chat_template(history, tokenize=False, add_generation_prompt=True)
        if self.processor and hasattr(self.processor, "apply_chat_template"):
            return self.processor.apply_chat_template(history, tokenize=False, add_generation_prompt=True)
        prompt = ""
        for msg in history:
            role = str(msg.get("role", "user")).capitalize()
            content = self._flatten_message_content(msg.get("content", ""))
            prompt += f"{role}: {content}\n"
        return prompt + "Assistant:"

    def _get_model_device(self):
        device = getattr(self.model, "device", None)
        if device is not None and str(device) != "meta":
            return device
        try:
            return next(self.model.parameters()).device
        except Exception:
            return torch.device("cuda" if torch and torch.cuda.is_available() else "cpu")

    def _clear_inference_tensors(self):
        try:
            gc.collect()
            if torch.cuda.is_available():
                torch.cuda.empty_cache()
        except Exception:
            pass

    def _sync_generation_special_tokens(self):
        """同步 tokenizer / processor 的 special token 到 model.config 和 generation_config，避免生成阶段配置不一致。"""
        try:
            tok = self.tokenizer or getattr(self.processor, "tokenizer", None)
            if not tok or not self.model:
                return

            pad_id = getattr(tok, "pad_token_id", None)
            eos_id = getattr(tok, "eos_token_id", None)
            bos_id = getattr(tok, "bos_token_id", None)

            if pad_id is None and eos_id is not None:
                try:
                    tok.pad_token = tok.eos_token
                    pad_id = getattr(tok, "pad_token_id", None)
                except Exception:
                    pass

            for cfg in [getattr(self.model, "config", None), getattr(self.model, "generation_config", None)]:
                if cfg is None:
                    continue
                if pad_id is not None:
                    cfg.pad_token_id = pad_id
                if eos_id is not None:
                    cfg.eos_token_id = eos_id
                if bos_id is not None:
                    cfg.bos_token_id = bos_id
        except Exception as e:
            self.log(f"⚠️ 同步生成 special tokens 失败：{e}", "orange")

    def _move_inputs_to_model_device(self, inputs):
        try:
            target_device = self._get_model_device()
            if hasattr(inputs, "to"):
                return inputs.to(target_device)
        except Exception as e:
            self.log(f"⚠️ 输入搬运到模型设备时失败，继续使用默认设备：{e}", "orange")
        return inputs

    def _decode_generated_text(self, outputs, inputs):
        input_ids = getattr(inputs, "input_ids", None)
        if input_ids is not None:
            generated_trimmed = [
                out_ids[len(in_ids):] for in_ids, out_ids in zip(input_ids, outputs)
            ]
        else:
            generated_trimmed = outputs

        # Qwen2.5-VL / 多模态 processor 优先走官方推荐的 batch_decode 路径
        if self.supports_vision and self.processor and hasattr(self.processor, "batch_decode"):
            try:
                decoded = self.processor.batch_decode(
                    generated_trimmed,
                    skip_special_tokens=True,
                    clean_up_tokenization_spaces=False
                )
                if decoded:
                    return str(decoded[0]).strip()
            except Exception as e:
                self.log(f"⚠️ processor.batch_decode 失败，回退通用解码：{e}", "orange")

        generated = generated_trimmed[0] if isinstance(generated_trimmed, (list, tuple)) and generated_trimmed else generated_trimmed
        decoder = self.tokenizer or getattr(self.processor, "tokenizer", None) or self.processor
        if hasattr(decoder, "decode"):
            return decoder.decode(generated, skip_special_tokens=True).strip()
        if hasattr(decoder, "batch_decode"):
            return decoder.batch_decode([generated], skip_special_tokens=True)[0].strip()
        return str(generated)

    def load_model(self, model_path, mmproj_path=None):
        try:
            return self._load_model_impl(model_path, mmproj_path)
        except Exception as e:
            self.last_error = str(e)
            self.last_error_detail = f"致命加载错误：{e}"
            self.log(f"❌ 崩溃防护已触发: {e}")
            return False

    def _has_python_module(self, module_name):
        try:
            import importlib.util
            return importlib.util.find_spec(module_name) is not None
        except Exception:
            return False

    def _build_transformers_load_kwargs(self, quantization_config=None, prefer_auto_device=True, local_files_only=True):
        kwargs = {
            # 本地模型目录也属于不可信输入：Transformers 的自定义代码会以
            # 当前 Windows 用户权限执行。所有通用加载路径与 tokenizer /
            # processor 保持一致，只接受库内置架构，不执行模型附带 Python。
            "trust_remote_code": False,
            "torch_dtype": torch.float16 if torch.cuda.is_available() else torch.float32
        }
        if local_files_only:
            kwargs["local_files_only"] = True
        if quantization_config is not None:
            kwargs["quantization_config"] = quantization_config
        if prefer_auto_device and self._has_python_module("accelerate"):
            kwargs["device_map"] = "auto"
        elif prefer_auto_device:
            self.log("⚠️ 未检测到 accelerate，已关闭 device_map=auto，改为普通加载模式。", "orange")
        return kwargs

    def _post_adjust_transformers_device(self, model_obj):
        if not model_obj:
            return model_obj
        if self._has_python_module("accelerate"):
            return model_obj
        try:
            if getattr(model_obj, "is_loaded_in_4bit", False) or getattr(model_obj, "is_loaded_in_8bit", False):
                return model_obj
            target_device = "cuda" if torch.cuda.is_available() else "cpu"
            if hasattr(model_obj, "to"):
                model_obj.to(target_device)
                self.log(f"🧩 已将模型放到 {target_device.upper()}。", "gray")
        except Exception as move_e:
            self.log(f"⚠️ 模型加载成功，但切换设备时失败：{move_e}", "orange")
        return model_obj

    def _load_transformers_model_with_fallback(self, loader_cls, model_path, quantization_config=None, loader_name="模型"):
        last_error = None
        attempts = [
            ("量化加载", self._build_transformers_load_kwargs(quantization_config=quantization_config, prefer_auto_device=True, local_files_only=True)),
            ("普通加载", self._build_transformers_load_kwargs(quantization_config=None, prefer_auto_device=False, local_files_only=True)),
        ]
        for attempt_name, kwargs in attempts:
            try:
                self.log(f"🔄 尝试 {loader_name}{attempt_name}...", "gray")
                model_obj = loader_cls.from_pretrained(model_path, **kwargs)
                return self._post_adjust_transformers_device(model_obj)
            except Exception as e:
                last_error = e
                self.log(f"⚠️ {loader_name}{attempt_name}失败: {str(e)[:220]}", "orange")
        raise last_error if last_error else RuntimeError(f"{loader_name}加载失败")

    def _auto_fix_hf_cache(self, error_msg, model_path):
        """自愈逻辑：全量同步本地 Python 脚本到报错的缓存位置"""
        try:
            # 兼容 Windows 路径中的双反斜杠和单反斜杠
            error_msg = error_msg.replace("\\\\", os.sep).replace("\\", os.sep)
            # 从报错信息中提取目标路径的特征
            match = re.search(r"No such file or directory: '([^']+)'", error_msg)
            if not match: 
                # 尝试匹配 Transformers 特有的模块导入错误路径
                match = re.search(r"module '([^']+)' has no attribute", error_msg)
                if not match: return False
            
            target_file = match.group(1)
            # 找到 transformers_modules 下的模型根目录 (例如 .../moondream2/51c44c1e9bfb08b2/)
            # 针对 Windows 路径做深度兼容
            target_file = target_file.replace("/", os.sep).replace("\\", os.sep)
            parts = target_file.split(os.sep)
            try:
                # 查找 transformers_modules 的索引
                idx = -1
                for i, p in enumerate(parts):
                    if "transformers_modules" in p:
                        idx = i; break
                
                if idx != -1:
                    # 模块根目录通常是 transformers_modules/模型名/哈希值/
                    # 我们取到哈希值这一层
                    module_root = os.sep.join(parts[:idx+3])
                else:
                    module_root = os.path.dirname(target_file)
            except:
                module_root = os.path.dirname(target_file)

            self.log(f"🛠️ 正在执行全量自愈同步到: {module_root}", "orange")
            
            # 本地源目录
            source_dir = os.path.abspath(model_path)
            
            # 同步所有 .py 文件
            count = 0
            if not os.path.exists(module_root):
                os.makedirs(module_root, exist_ok=True)
                
            for root, dirs, files in os.walk(source_dir):
                for f in files:
                    if f.endswith(".py"):
                        rel_path = os.path.relpath(os.path.join(root, f), source_dir)
                        dest_path = os.path.join(module_root, rel_path)
                        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
                        shutil.copy2(os.path.join(root, f), dest_path)
                        count += 1
            
            self.log(f"✅ 自愈完成：已强行同步 {count} 个脚本文件到缓存。", "green")
            return True
        except Exception as e:
            self.log(f"⚠️ 自愈尝试失败: {e}")
        return False

    def _load_model_impl(self, model_path, mmproj_path=None):
        if self.model and model_path == self.current_model_path: 
            if torch.cuda.is_available(): torch.cuda.empty_cache()
            return True
        self.force_clean()
        self.log(f"🚀 正在加载: {os.path.basename(model_path)}")
        try:
            # 1. GGUF 模式处理
            if model_path.endswith(".gguf"):
                self.is_gguf = True
                try:
                    from llama_cpp import Llama
                except ImportError:
                    self.log("📦 检测到 GGUF 依赖缺失，正在自动安装 llama-cpp-python...", "blue")
                    if not _silent_install_libs(["llama_cpp"], timeout=1800, log_prefix="[GGUF]"):
                        raise ImportError("缺少 GGUF 依赖，且 llama-cpp-python 自动安装失败。")
                    import importlib
                    importlib.invalidate_caches()
                    from llama_cpp import Llama
                chat_handler = None
                if mmproj_path and os.path.exists(mmproj_path):
                    self.log(f"📷 加载视觉组件: {os.path.basename(mmproj_path)}")
                    try:
                        from llama_cpp.llama_chat_format import NanoLlavaChatHandler
                    except ImportError:
                        self.log("📦 检测到 GGUF 视觉依赖缺失，正在尝试自动补装 llama-cpp-python...", "blue")
                        if not _silent_install_libs(["llama_cpp"], timeout=1800, log_prefix="[GGUF-VISION]"):
                            raise ImportError("缺少 GGUF 视觉依赖，且 llama-cpp-python 自动安装失败。")
                        import importlib
                        importlib.invalidate_caches()
                        from llama_cpp.llama_chat_format import NanoLlavaChatHandler
                    chat_handler = NanoLlavaChatHandler(clip_model_path=mmproj_path, verbose=False)
                    self.is_vision_model = True
                    self.supports_vision = True
                    self.model_family = "gguf_vision"
                else:
                    self.supports_vision = False
                    self.model_family = "gguf_text"
                self.supports_text = True
                
                self.log(f"🧩 {self._gpu_report()}")
                self.log(f"🧩 {self._llama_cpp_gpu_status()}")

                # 路径兼容性处理：如果路径包含中文，llama.cpp 底层可能会失败
                final_model_path = model_path
                if self._is_chinese(model_path) and os.name == 'nt':
                    self.log("⚠️ 检测到路径包含中文，尝试使用系统短路径名以提高兼容性...")
                    try:
                        import ctypes
                        buf = ctypes.create_unicode_buffer(512)
                        ctypes.windll.kernel32.GetShortPathNameW(model_path, buf, 512)
                        if buf.value:
                            final_model_path = buf.value
                            self.log(f"🔗 已转换路径: {final_model_path}")
                    except:
                        pass

                # GTX 2080Ti 11GB：优先尝试全 GPU offload；如果显存或 CUDA 版依赖不合适，自动降级到部分 GPU 层，最后再尝试 CPU。
                common_kwargs = dict(
                    model_path=final_model_path,
                    n_ctx=1024,
                    chat_handler=chat_handler,
                    verbose=True # 开启底层日志以捕获具体失败原因
                )
                load_attempts = [
                    ("全量 GPU offload", -1),
                    ("保守 GPU offload（约 35 层，适合 7B/8B 量化）", 35),
                    ("最低 GPU offload（约 20 层，适合显存紧张时）", 20),
                    ("CPU 模式（能跑但会明显变慢）", 0),
                ]
                last_exc = None
                for attempt_name, gpu_layers in load_attempts:
                    try:
                        self.log(f"🔄 尝试 {attempt_name}，n_gpu_layers={gpu_layers}...")
                        self.model = Llama(n_gpu_layers=gpu_layers, **common_kwargs)
                        self.current_model_path = model_path
                        if gpu_layers == 0:
                            self.log("⚠️ 已用 CPU 模式加载成功；如需 CUDA 加速，请安装 CUDA 版 llama-cpp-python。")
                        else:
                            self.log(f"✓ 成功 (🧊 GGUF {'视觉' if chat_handler else '文本'}模式，{attempt_name})")
                        return True
                    except Exception as sub_e:
                        last_exc = sub_e
                        self.log(f"⚠️ {attempt_name}失败: {str(sub_e)[:180]}")
                        try:
                            if self.model:
                                del self.model
                        except Exception:
                            pass
                        self.model = None
                        gc.collect()
                        if torch.cuda.is_available():
                            torch.cuda.empty_cache()
                raise last_exc if last_exc else RuntimeError("未知 GGUF 加载错误")
            # 2. Transformers 模式处理 (安全加固版)
            self.is_gguf = False
            try:
                from transformers import BitsAndBytesConfig, AutoConfig, AutoModelForCausalLM, AutoModel
            except ImportError:
                self.log("📦 检测到本地模型依赖缺失，正在自动安装 transformers / accelerate / safetensors ...", "blue")
                if not _silent_install_libs(["transformers", "accelerate", "safetensors"], timeout=1800, log_prefix="[TRANSFORMERS]"):
                    raise ImportError("缺少必要的 Transformers 依赖，且自动安装失败。")
                import importlib
                importlib.invalidate_caches()
                from transformers import BitsAndBytesConfig, AutoConfig, AutoModelForCausalLM, AutoModel

            q_cfg = BitsAndBytesConfig(
                load_in_4bit=True, 
                bnb_4bit_compute_dtype=torch.float32, 
                bnb_4bit_quant_type="nf4", 
                bnb_4bit_use_double_quant=True
            )
            
            # 尝试获取模型配置，如果失败则直接回退到基础加载
            try:
                config = AutoConfig.from_pretrained(model_path, trust_remote_code=False, local_files_only=True)
                caps = self._detect_transformers_capabilities(config, model_path)
                model_type = caps.get("model_type", "")
            except Exception as e:
                self.log(f"⚠️ 无法读取模型配置({e})，将尝试通用加载方式...")
                model_type = "unknown"
                caps = {"supports_text": True, "supports_vision": False, "model_type": model_type}

            self.supports_text = bool(caps.get("supports_text", True))
            self.supports_vision = bool(caps.get("supports_vision", False))
            self.is_vision_model = self.supports_vision
            self.model_family = "transformers_vision" if self.supports_vision else "transformers_text"

            # 终极修复：针对 Moondream2 采用“强力缓存注入”模式
            if "moondream" in model_path.lower() or "moondream" in model_type:
                self.log("🚀 正在启动 Moondream2 专用加载程序...", "cyan")
                model_abs_path = os.path.abspath(model_path)
                
                # --- 预检逻辑 ---
                required = ["configuration_moondream.py", "layers.py", "moondream.py", "vision_encoder.py"]
                missing = [f for f in required if not os.path.exists(os.path.join(model_abs_path, f))]
                if missing:
                    self.log(f"❌ 预检失败！您的文件夹缺少关键脚本: {', '.join(missing)}", "red")
                    return False

                # 强行预同步：在加载前直接尝试寻找缓存位置并注入，不再等待报错触发
                self.log("🛠️ 正在预同步本地脚本到 Transformers 缓存...", "orange")
                # 我们先制造一个假报错来获取缓存路径，或者通过 AutoConfig 探测
                try:
                    # 禁止模型目录内的自定义 Python 代码；仅加载 Transformers 内置架构。
                    temp_config = AutoConfig.from_pretrained(model_path, trust_remote_code=False, local_files_only=True)
                    # 如果能走到这，说明路径已经解析过，我们尝试通过其模块路径反推
                    if hasattr(temp_config, "__module__"):
                        mod_file = sys.modules[temp_config.__module__].__file__
                        self._auto_fix_hf_cache(f"No such file or directory: '{mod_file}'", model_path)
                except Exception as e:
                    self._auto_fix_hf_cache(str(e), model_path)

                try:
                    self.model = AutoModelForCausalLM.from_pretrained(
                        model_path, 
                        quantization_config=q_cfg, 
                        device_map="auto", 
                        trust_remote_code=False, 
                        torch_dtype=torch.float16,
                        local_files_only=True
                    )
                except Exception as e:
                    # 二次重试：如果 4bit 加载失败，尝试不带量化加载（防止 bitsandbytes 环境问题）
                    self.log(f"⚠️ 4bit 加载失败 ({e})，尝试不带量化加载...", "orange")
                    self.model = AutoModelForCausalLM.from_pretrained(
                        model_path, 
                        device_map="auto", 
                        trust_remote_code=False, 
                        torch_dtype=torch.float16,
                        local_files_only=True
                    )
                self.is_vision_model = True
                self.supports_vision = True
                self.supports_text = True
                self.model_family = "transformers_vision"
                self.processor = AutoProcessor.from_pretrained(model_path, trust_remote_code=False, local_files_only=True)
                self.tokenizer = getattr(self.processor, "tokenizer", None)
                self.log("✨ Moondream2 加载成功！", "green")
            elif self.supports_vision and ("qwen" in model_type or "qwen" in model_path.lower()):
                self.log(f"ℹ️ 正在加载 Qwen 系列视觉模型 ({model_type})...")
                try:
                    from transformers import AutoProcessor, AutoModelForCausalLM
                    candidate_loaders = []
                    try:
                        from transformers import Qwen2_5_VLForConditionalGeneration
                        candidate_loaders.append(("Qwen2_5_VLForConditionalGeneration", Qwen2_5_VLForConditionalGeneration))
                    except Exception:
                        pass
                    try:
                        from transformers import Qwen2VLForConditionalGeneration
                        candidate_loaders.append(("Qwen2VLForConditionalGeneration", Qwen2VLForConditionalGeneration))
                    except Exception:
                        pass
                    try:
                        from transformers import AutoModelForImageTextToText
                        candidate_loaders.append(("AutoModelForImageTextToText", AutoModelForImageTextToText))
                    except Exception:
                        pass
                    try:
                        from transformers import AutoModelForVision2Seq
                        candidate_loaders.append(("AutoModelForVision2Seq", AutoModelForVision2Seq))
                    except Exception:
                        pass
                    candidate_loaders.append(("AutoModelForCausalLM", AutoModelForCausalLM))

                    last_loader_error = None
                    self.model = None
                    for loader_name, loader_cls in candidate_loaders:
                        try:
                            self.model = self._load_transformers_model_with_fallback(
                                loader_cls, model_path, quantization_config=q_cfg, loader_name=loader_name
                            )
                            if self.model:
                                self.log(f"✅ Qwen 已通过 {loader_name} 加载成功。", "green")
                                break
                        except Exception as loader_e:
                            last_loader_error = loader_e
                            self.log(f"⚠️ {loader_name} 不兼容或加载失败，继续尝试下一种方式...", "orange")
                    if not self.model:
                        raise last_loader_error if last_loader_error else RuntimeError("Qwen 模型没有可用的加载方式")
                    self.processor = AutoProcessor.from_pretrained(model_path, trust_remote_code=False, local_files_only=True)
                    self.tokenizer = getattr(self.processor, "tokenizer", None)
                    self.supports_text = True
                    self.supports_vision = True
                    self.is_vision_model = True
                except Exception as q_e:
                    self.log(f"❌ Qwen 加载失败: {q_e}")
                    raise q_e
            else:
                self.log(f"ℹ️ 正在使用通用接口加载模型 ({model_type})...")
                self.model = self._load_transformers_model_with_fallback(
                    AutoModelForCausalLM, model_path, quantization_config=q_cfg, loader_name="AutoModelForCausalLM"
                )
                self.tokenizer = self._load_tokenizer_with_fallback(model_path)
                self.is_vision_model = False
                self.supports_vision = False
                self.supports_text = True
                self.model_family = "transformers_text"
            
            self.current_model_path = model_path
            self._sync_generation_special_tokens()
            mode_desc = "图文模型" if self.supports_vision else "纯文字模型"
            self.log(f"✓ 成功 (🔥 Transformers 模式 / {mode_desc})")
            return True
        except Exception as e:
            if model_path.endswith(".gguf"):
                self.last_error_detail = self._format_gguf_error(e, model_path)
            else:
                error_msg = str(e)
            diag_hints = []
            if "FileNotFoundError" in traceback.format_exc() and ".cache\\huggingface" in traceback.format_exc():
                diag_hints.append("💡 诊断建议：检测到 Hugging Face 本地缓存损坏。")
                diag_hints.append("请尝试手动删除此文件夹后重试：")
                cache_match = re.search(r'([A-Z]:\\Users\\[^\\]+\\.cache\\huggingface\\modules\\transformers_modules\\[^\\]+)', traceback.format_exc())
                if cache_match:
                    diag_hints.append(f"👉 {cache_match.group(1)}")
                else:
                    diag_hints.append("👉 C:\\Users\\您的用户名\\.cache\\huggingface\\modules\\transformers_modules")
            
            hint_str = "\n".join(diag_hints) + "\n\n" if diag_hints else ""
            self.last_error_detail = f"{hint_str}模型加载失败：{e}\n\n详细堆栈：\n{traceback.format_exc()}"
            self.last_error = str(e)
            self.log("❌ 失败: " + self.last_error_detail)
            return False

    def chat(self, history, system_prompt, image_paths=None, max_new_tokens=1024, temperature=0.0, do_sample=False, prefer_low_memory=False, cleanup_cache=False):
        try:
            image_paths = [p for p in (image_paths or []) if p]
            if image_paths and not self.supports_vision:
                raise ValueError("当前本地模型是纯文字模型，不支持图片输入或图文任务。请切换到视觉模型后再试。")
            if not self.supports_text:
                raise ValueError("当前本地模型未启用文本对话能力。")
            if self.is_gguf:
                # GGUF 视觉/文本推理逻辑
                if self.supports_vision and image_paths:
                    messages = [{"role": "system", "content": system_prompt}]
                    for msg in history:
                        if msg["role"] == "user":
                            # 修复：content 可能已是 list，提取纯文本
                            _raw = msg["content"]
                            _txt = self._flatten_message_content(_raw)
                            content = [{"type": "text", "text": _txt}]
                            for img_p in image_paths:
                                # 修复：使用压缩后的 Base64，避免大图占满显存
                                try:
                                    b64_url = AiImageMatchThread._encode_image(img_p)
                                    content.append({"type": "image_url", "image_url": {"url": b64_url}})
                                except Exception:
                                    with open(img_p, "rb") as f:
                                        b64 = base64.b64encode(f.read()).decode("utf-8")
                                        content.append({"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{b64}"}})
                            messages.append({"role": "user", "content": content})
                        else: messages.append(msg)
                    output = self.model.create_chat_completion(messages=messages, max_tokens=1024)
                    return output["choices"][0]["message"]["content"].strip()
                else:
                    prompt = f"System: {system_prompt}\n"
                    for msg in history:
                        role = str(msg.get('role', 'user')).capitalize()
                        content = self._flatten_message_content(msg.get('content', ''))
                        prompt = f"{prompt}{role}: {content}\n"
                    prompt = f"{prompt}Assistant:"
                    output = self.model(prompt, max_tokens=1024, stop=["\n"], echo=False)
                    return output["choices"][0]["text"].strip()
            
            # Transformers 推理逻辑 (整合 Qwen2.5-VL 格式)
            full_history = [{"role": "system", "content": system_prompt}] + history
            
            if self.supports_vision and image_paths:
                # 仅在有图片时启用多模态包装
                formatted_history = []
                for i, msg in enumerate(full_history):
                    role = str(msg.get("role", "user"))
                    raw_text = self._flatten_message_content(msg.get("content", ""))
                    # 只在最后一条用户消息中加入图片
                    if i == len(full_history) - 1 and role == "user":
                        content = []
                        for img_p in image_paths:
                            content.append({"type": "image", "image": f"file://{img_p}"})
                        content.append({"type": "text", "text": raw_text or ""})
                        formatted_history.append({"role": "user", "content": content})
                    else:
                        # 关键修复：system / assistant / 普通 user 按官方推荐保持纯文本字符串，
                        # 不再统一包装成 [{type:text}]，避免 Qwen2.5-VL chat template 偏离官方格式。
                        formatted_history.append({"role": role, "content": raw_text or ""})
                prompt_builder = self.processor if self.processor and hasattr(self.processor, "apply_chat_template") else self.tokenizer
                prompt = prompt_builder.apply_chat_template(formatted_history, tokenize=False, add_generation_prompt=True)
                
                if not prefer_low_memory:
                    try:
                        from qwen_vl_utils import process_vision_info
                        image_inputs, video_inputs = process_vision_info(formatted_history)
                        inputs = self._move_inputs_to_model_device(self.processor(
                            text=[prompt],
                            images=image_inputs,
                            videos=video_inputs,
                            padding=True,
                            return_tensors="pt"
                        ))
                    except Exception as vision_e:
                        self.log(f"⚠️ 多模态快速装载失败，自动切换低显存模式：{str(vision_e)[:160]}", "orange")
                        prefer_low_memory = True
                if prefer_low_memory:
                    # 低显存兜底：主动缩图，避免一次把多张原图送入视觉编码器
                    images = []
                    for p in (image_paths or []):
                        img = load_material_image(p)
                        # 11GB 显存下兼顾速度与细节：比 384 更保留细节（例如小水印/小符号），又显著低于原图成本。
                        img.thumbnail((512, 512), Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.ANTIALIAS)
                        images.append(img)
                    inputs = self._move_inputs_to_model_device(
                        self.processor(text=[prompt], images=images if images else None, padding=True, return_tensors="pt")
                    )
            else:
                safe_history = []
                for m in full_history:
                    role = str(m.get("role", "user"))
                    text = self._flatten_message_content(m.get("content", ""))
                    # 改回官方更常见的纯文本消息格式，避免视觉模型文本轮也被错误包装
                    safe_history.append({"role": role, "content": text})
                prompt = self._build_text_prompt(safe_history)
                if self.supports_vision and self.processor:
                    inputs = self._move_inputs_to_model_device(self.processor(text=[prompt], return_tensors="pt"))
                elif self.tokenizer:
                    inputs = self._move_inputs_to_model_device(self.tokenizer(prompt, return_tensors="pt"))
                else:
                    raise RuntimeError("当前模型缺少可用的 tokenizer/processor，无法进行文本推理。")
            
            tok = self.tokenizer or getattr(self.processor, "tokenizer", None)

            pad_token_id = (
                getattr(tok, "pad_token_id", None)
                if tok is not None else None
            )
            eos_token_id = (
                getattr(tok, "eos_token_id", None)
                if tok is not None else None
            )

            if pad_token_id is None:
                pad_token_id = getattr(getattr(self.model, "config", None), "pad_token_id", None)
            if eos_token_id is None:
                eos_token_id = getattr(getattr(self.model, "config", None), "eos_token_id", None)

            temp = float(temperature or 0.0)

            generate_kwargs = {
                "max_new_tokens": max(1, int(max_new_tokens or 1)),
                "stopping_criteria": StoppingCriteriaList([self.stop_criteria]),
                "use_cache": True,
                "renormalize_logits": True,
                "remove_invalid_values": True,
            }

            if pad_token_id is not None:
                generate_kwargs["pad_token_id"] = int(pad_token_id)
            if eos_token_id is not None:
                generate_kwargs["eos_token_id"] = int(eos_token_id)

            if bool(do_sample) and temp > 1e-5:
                generate_kwargs.update({
                    "do_sample": True,
                    "temperature": max(temp, 1e-5),
                    "top_p": 0.9,
                    "top_k": 50,
                })
            else:
                generate_kwargs["do_sample"] = False

            try:
                with torch.inference_mode():
                    outputs = self.model.generate(**inputs, **generate_kwargs)
            except RuntimeError as gen_e:
                err_text = str(gen_e)
                if "device-side assert triggered" in err_text:
                    self.log("❌ CUDA device-side assert 已触发，当前 CUDA 上下文可能已损坏。请重启程序后重新加载模型。", "red")
                raise
            return self._decode_generated_text(outputs, inputs)
        except Exception as e: 
            # 增强：本地引擎推理层抛出异常，让上层线程捕获完整堆栈
            err_detail = f"本地引擎推理出错: {e}\n{traceback.format_exc()}"
            write_debug(err_detail)
            raise e
        finally:
            if cleanup_cache or image_paths:
                self._clear_inference_tensors()

class StopOnFlag(StoppingCriteria):
    def __init__(self): self.should_stop = False
    def __call__(self, input_ids, scores, **kwargs): return self.should_stop

# ─────────────────────────────────────────────
#  ClipFastMatchThread：CLIP 极速图文匹配后台线程
# ─────────────────────────────────────────────
class ClipFastMatchThread(QThread):
    """
    CLIP 极速图文匹配线程。
    不依赖大型视觉语言模型，直接利用 CLIP 模型计算图文余弦相似度。
    显存占用仅约 300MB，匹配速度比大模型快 10-50 倍。
    支持图片特征向量缓存，重复运行时无需重新编码图片。
    """
    progress = pyqtSignal(int)
    log      = pyqtSignal(str, str)
    result   = pyqtSignal(dict)
    error    = pyqtSignal(str)

    # 类级共享缓存：{img_path: numpy_feature_vector}
    _img_feature_cache = {}
    # 缓存向量只能和生成它的同一模型配对。不同模型维度可能是 512、768 等。
    _img_feature_cache_model_name = ""
    _clip_model = None
    _clip_model_name = ""

    def __init__(self, image_paths, scripts, clip_model_name="OFA-Sys/chinese-clip-vit-large-patch14", top_k=3, use_gpu=True):
        super().__init__()
        self.image_paths    = image_paths
        self.scripts        = scripts
        self.clip_model_name = clip_model_name
        self.top_k          = top_k  # 候选图片数（取相似度最高的 top_k 张送入大模型进行精选）
        self.use_gpu        = use_gpu
        self._stop          = False

    def stop(self):
        self._stop = True

    @staticmethod
    def _normalize_match_text(text):
        text = str(text or "").strip().lower()
        return re.sub(r"[\s_\-\\/|,，、;；:：·]+", "", text)

    @classmethod
    def _build_remark_keywords(cls, remark):
        """从备注/特殊要求中提取用于路径匹配的关键词。"""
        remark = str(remark or "").strip()
        if not remark:
            return []

        parts = re.split(r"[\n\r,，、;；|/]+", remark)
        keywords = []
        for part in parts:
            part = str(part or "").strip()
            if not part:
                continue
            keywords.append(part.lower())
            compact = cls._normalize_match_text(part)
            if compact and compact not in keywords:
                keywords.append(compact)

        full_compact = cls._normalize_match_text(remark)
        if full_compact and full_compact not in keywords:
            keywords.append(full_compact)

        # 去重并让长关键词优先
        keywords = sorted(set([k for k in keywords if k]), key=len, reverse=True)
        return keywords

    @classmethod
    def _parse_remark_image_directives(cls, remark, image_paths):
        """解析备注里明确点名的素材图，和真正需要由视觉模型判断的要求分开。

        例：使用“小明XE_1.jpeg”、“小明XE_2.jpeg”，必须侧面镜头。
        前两项构成候选白名单；“必须侧面镜头”才是选择白名单内图片的唯一评分依据。
        """
        remark = str(remark or '').strip()
        all_paths = list(image_paths or [])
        empty = {'include': set(), 'exclude': set(), 'visual_remark': remark, 'has_directive': False}
        if not remark or not all_paths:
            return empty
        extension = r'(?:jpe?g|png|webp|bmp|gif|tiff?|heic|avif)'
        # 支持中英文引号和未加引号的完整文件名；文件名允许中文、空格、下划线与连字符。
        tokens = re.findall(rf'[“"\']?([^“”"\'\n\r,，、;；]+?\.{extension})[”"\']?', remark, flags=re.I)
        tokens = [str(token or '').strip().strip('“”"\' ') for token in tokens if str(token or '').strip()]
        if not tokens:
            return empty

        def name_key(value):
            return cls._normalize_match_text(os.path.basename(str(value or '')))

        includes, excludes = set(), set()
        for token in tokens:
            token_key = name_key(token)
            if not token_key:
                continue
            pos = remark.casefold().find(token.casefold())
            context = remark[max(0, pos - 18):min(len(remark), pos + len(token) + 8)] if pos >= 0 else remark
            is_exclude = bool(re.search(r'(?:不使用|不用|排除|忽略|不要|不选)', context, flags=re.I))
            matched = {
                index for index, path in enumerate(all_paths)
                if name_key(path) == token_key
            }
            if is_exclude:
                excludes.update(matched)
            else:
                includes.update(matched)

        # “使用 A、B”是白名单；“不使用 A”只是本行黑名单。若同一张图同时出现，排除优先。
        includes.difference_update(excludes)
        visual = remark
        for token in tokens:
            visual = re.sub(re.escape(token), ' ', visual, flags=re.I)
        visual = re.sub(r'(?:使用|选用|指定|仅使用|仅用|从中选择|从中选|包含|图片名称|原素材目录|素材目录|图片|照片)', ' ', visual, flags=re.I)
        visual = re.sub(r'[“”"\'\[\]()（）,，、;；|/]+', ' ', visual)
        visual = re.sub(r'\s+', ' ', visual).strip(' ：:，,、;；。.')
        return {
            'include': includes, 'exclude': excludes, 'visual_remark': visual,
            'has_directive': bool(includes or excludes),
        }

    @classmethod
    def _build_path_priority_bonus(cls, remark, image_paths):
        """
        根据备注中的关键词，对命中文件夹/路径名的图片给予强优先级加分。
        返回: bonus(np.ndarray), hit_count(int)
        """
        import numpy as np

        keywords = cls._build_remark_keywords(remark)
        if not keywords:
            return np.zeros(len(image_paths), dtype=np.float32), 0

        bonus = np.zeros(len(image_paths), dtype=np.float32)
        hit_count = 0

        for idx, p in enumerate(image_paths):
            path_str = str(p or "")
            path_lower = path_str.lower()
            norm_path = cls._normalize_match_text(path_lower)
            dir_parts = [x for x in re.split(r"[\\/]+", os.path.dirname(path_lower)) if x]
            base_name = os.path.splitext(os.path.basename(path_lower))[0]
            norm_base = cls._normalize_match_text(base_name)

            best = 0.0
            for kw in keywords:
                kw_lower = kw.lower()
                kw_norm = cls._normalize_match_text(kw_lower)
                if not kw_norm:
                    continue

                # 1) 文件夹完全匹配：最高优先级
                if any((d == kw_lower) or (cls._normalize_match_text(d) == kw_norm) for d in dir_parts):
                    best = max(best, 0.60)
                # 2) 文件夹包含关键词：高优先级
                elif any((kw_lower in d) or (kw_norm in cls._normalize_match_text(d)) for d in dir_parts):
                    best = max(best, 0.42)
                # 3) 文件名命中：中优先级
                elif (kw_lower in base_name) or (kw_norm in norm_base):
                    best = max(best, 0.28)
                # 4) 整个路径命中：轻度优先
                elif (kw_lower in path_lower) or (kw_norm in norm_path):
                    best = max(best, 0.18)

            bonus[idx] = best
            if best > 0:
                hit_count += 1

        return bonus, hit_count

    @staticmethod
    def _build_requirement_prompt(content, remark):
        """把用户自由填写的备注与文案合成一个完整画面意图，不预设词表或规则。"""
        return (
            "请寻找一张能够同时表达以下完整画面意图的图片。\n"
            f"文案场景：{str(content or '').strip()}\n"
            f"补充要求：{str(remark or '').strip()}"
        )

    @staticmethod
    def _build_strict_requirement_prompts(remark):
        """为备注生成视觉核验查询；不依赖固定词表，任何自由描述均可参与。"""
        remark = str(remark or '').strip()
        if not remark:
            return []
        clauses = [part.strip() for part in re.split(r"[\n\r,，、;；|/]+", remark) if part.strip()]
        prompts = [remark, f"画面中必须清楚可见：{remark}", f"photo with clearly visible visual requirement: {remark}"]
        for clause in clauses[:8]:
            prompts.extend((clause, f"画面中清楚可见：{clause}", f"photo showing: {clause}"))
        return list(dict.fromkeys(prompts))

    @classmethod
    def _load_clip_model(cls, model_name, use_gpu, log_fn):
        """CLIP 模型延迟加载（类级单例，避免重复加载）。

        默认使用中文增强版 CLIP 模型，如果用户未指定或指定了不支持的名称。
        """
        default_chinese_clip = "OFA-Sys/chinese-clip-vit-large-patch14"
        normalized_name = (model_name or default_chinese_clip).strip()
        if not normalized_name:
            normalized_name = default_chinese_clip

        # 特征缓存还必须区分加载架构。此前同一模型名曾被错误地以普通
        # CLIP 架构加载；升级为原生 Chinese-CLIP 后不能继续复用旧向量。
        runtime_cache_key = f"{normalized_name}::native-architecture-v3"

        previous_cache_model = str(getattr(cls, "_img_feature_cache_model_name", "") or "")
        if cls._img_feature_cache and previous_cache_model != runtime_cache_key:
            old_label = previous_cache_model or "旧版未知模型"
            cls._img_feature_cache.clear()
            log_fn(
                f"🔄 检测到 CLIP 模型已从 {old_label} 切换为 {normalized_name}；"
                "已自动清除不兼容的图片特征缓存，并将重新编码图片。",
                "orange",
            )
        cls._img_feature_cache_model_name = runtime_cache_key

        if cls._clip_model is not None and cls._clip_model_name == runtime_cache_key:
            return cls._clip_model

        # Hugging Face 缓存与 Seed-VC 的模型缓存彻底分开。首次任务前主动提示，
        # 不让用户只看到界面“没反应”而误以为软件故障。
        cache_root = os.environ.get("HF_HOME", "")
        cache_key = "models--" + normalized_name.replace("/", "--")
        cache_dir = os.path.join(cache_root, "hub", cache_key)

        def _clip_cache_status():
            """区分“有残留目录”和“可完全离线加载的模型”，避免半包伪装成本地缓存。"""
            try:
                snapshots = os.path.join(cache_dir, "snapshots")
                if not os.path.isdir(snapshots):
                    return False, False
                entries = [entry.path for entry in os.scandir(snapshots) if entry.is_dir()]
                if not entries:
                    return False, False
                for snapshot in entries:
                    names = set()
                    for root, _, files in os.walk(snapshot):
                        for filename in files:
                            names.add(filename.lower())
                    has_config = "config.json" in names
                    has_weight = any(name.endswith(".safetensors") or name in {"pytorch_model.bin", "model.bin"} for name in names)
                    has_processor = any(name in names for name in ("preprocessor_config.json", "processor_config.json", "tokenizer_config.json", "vocab.txt", "merges.txt"))
                    if has_config and has_weight and has_processor:
                        return True, True
                return True, False
            except OSError:
                return False, False

        cache_exists, has_cached_model = _clip_cache_status()
        if has_cached_model:
            log_fn(f"📦 已验证完整本地 CLIP 缓存：{normalized_name}；本次将离线加载，不再联网下载或校验。", "green")
        elif cache_exists:
            log_fn(f"⚠️ 检测到不完整的 CLIP 缓存：{normalized_name}。将联网补齐缺失文件；若网络不可用，会在超时后明确报错。", "orange")
        else:
            log_fn(
                f"📥 首次模型下载提醒：CLIP 模型 {normalized_name} 尚未在本机缓存中找到，正在下载并加载。"
                "首次可能需要数分钟，请勿关闭软件；完成后将直接使用缓存。",
                "orange",
            )
            log_fn("💾 本机使用兼容缓存：不影响模型下载或匹配；首次缓存可能比支持开发者模式的 Windows 多占少量空间。", "gray")

        # Hugging Face 的进度条主要写入终端的回车行，图形程序捕获后常常只剩
        # “Downloading …”这一行。这里直接监测其 .incomplete 缓存文件，稳定地
        # 向运行日志报告容量、百分比与速率，不依赖终端是否可用。
        download_monitor_stop = Event()
        # 无论缓存是否完整都持续报告状态。此前完整缓存分支没有心跳，加载大权重时
        # 用户只能看到“正在加载”而误认为卡死；残缺缓存还会报告下载锁和补齐进度。
        if True:
            expected_sizes = {
                "OFA-Sys/chinese-clip-vit-large-patch14": 1.63 * 1024 ** 3,
                "OFA-Sys/chinese-clip-vit-base-patch16": 0.753 * 1024 ** 3,
                "clip-ViT-L-14": 1.71 * 1024 ** 3,
                "clip-ViT-B-16": 0.599 * 1024 ** 3,
                "clip-ViT-B-32": 0.605 * 1024 ** 3,
            }
            expected_bytes = expected_sizes.get(normalized_name, 1.0 * 1024 ** 3)

            def _watch_clip_download():
                last_bytes = -1
                last_time = time.monotonic()
                last_notice = 0.0
                started = last_time
                while not download_monitor_stop.wait(1.0):
                    downloaded = 0
                    lock_count = 0
                    try:
                        for root, _, files in os.walk(cache_dir):
                            for filename in files:
                                if filename.endswith(".incomplete"):
                                    try:
                                        downloaded += os.path.getsize(os.path.join(root, filename))
                                    except OSError:
                                        pass
                                elif filename.endswith(".lock"):
                                    lock_count += 1
                    except OSError:
                        pass
                    now = time.monotonic()
                    if downloaded > 0 and downloaded != last_bytes:
                        delta = max(0, downloaded - max(0, last_bytes))
                        speed = delta / max(0.1, now - last_time) / 1024 ** 2
                        percent = min(99, int(downloaded * 100 / expected_bytes))
                        log_fn(f"📥 CLIP 下载进度：{downloaded / 1024 ** 2:.1f} MB / {expected_bytes / 1024 ** 3:.2f} GB（{percent}%，{speed:.1f} MB/s）", "blue")
                        last_bytes, last_time, last_notice = downloaded, now, now
                    elif now - last_notice >= 12:
                        elapsed = int(now - started)
                        if has_cached_model:
                            log_fn(f"⏳ 正在离线校验并载入 CLIP 权重（已等待 {elapsed} 秒，首次载入大模型会占用磁盘和内存）…", "gray")
                        elif lock_count:
                            log_fn(f"⏳ CLIP 正在等待下载锁（{lock_count} 个）。请勿同时启动另一份软件；若所有软件都已关闭仍持续不动，请清理该模型缓存后重试。", "orange")
                        else:
                            log_fn("🌐 CLIP 正在连接、下载或校验缺失文件；网络不可用时将在超时后给出明确错误…", "gray")
                        last_notice = now

            threading.Thread(target=_watch_clip_download, name="clip-model-progress", daemon=True).start()

        device = "cpu"
        if use_gpu:
            try:
                import torch
                if torch.cuda.is_available():
                    device = "cuda"
                    log_fn("✅ 检测到 CUDA，CLIP 将使用 GPU 加速", "green")
                else:
                    log_fn("⚠️ 未检测到 CUDA (Torch版本不匹配或无NVIDIA显卡)，将使用 CPU 运行。", "orange")
                    log_fn("💡 提示：若您有NVIDIA显卡，请在终端运行：pip install torch torchvision --index-url https://download.pytorch.org/whl/cu121", "gray")
            except Exception:
                pass

        st_load_error = None
        tf_load_error = None
        try:
            # SentenceTransformer 可成功装载 Chinese-CLIP，但在当前环境的
            # encode(text) 中仍会进入损坏的 get_text_features()/pooler_output
            # 路径。模型加载成功不等于可编码，Chinese-CLIP 必须走下方原生适配。
            if "chinese-clip" in normalized_name.lower():
                raise RuntimeError("Chinese-CLIP 使用原生架构适配器，跳过不兼容的 SentenceTransformer 包装层")
            # 优先尝试使用 sentence-transformers 加载 Hugging Face 模型
            from sentence_transformers import SentenceTransformer
            log_fn(f"⏳ 正在加载 CLIP 模型: {normalized_name}…", "blue")
            cls._clip_model = SentenceTransformer(normalized_name, device=device)
            cls._clip_model_name = runtime_cache_key
            download_monitor_stop.set()
            log_fn(f"✅ CLIP 模型加载完成 (device={device})", "green")
            return cls._clip_model
        except Exception as e:
            st_load_error = e
            msg = str(e)
            if ("upgrade torch to at least v2.6" in msg) or ("CVE-2025-32434" in msg):
                log_fn(f"⚠️ sentence-transformers 因 PyTorch 版本安全限制拒绝加载（{e}）", "orange")
                log_fn("💡 解决思路：升级 torch>=2.6，或改用 Transformers(优先 safetensors) / cn_clip 加载。", "gray")
            else:
                log_fn(f"⚠️ sentence-transformers 加载失败 ({e})", "orange")

        # 备选：直接使用 Transformers 加载 CLIP（优先 safetensors，绕开 sentence-transformers 的版本限制）
        try:
            import torch
            log_fn("🔄 尝试使用 Transformers 直接加载 CLIP（优先 safetensors）...", "gray")
            # Windows + pythonw 场景下，sys.stdout/sys.stderr 可能为 None，
            # HuggingFace/Transformers 内部会调用 isatty() 导致报错：
            #   'NoneType' object has no attribute 'isatty'
            # 这里做一次兜底，保证加载过程不崩。
            import sys
            if getattr(sys, "stdout", None) is None:
                sys.stdout = open(os.devnull, "w", encoding="utf-8")
            if getattr(sys, "stderr", None) is None:
                sys.stderr = open(os.devnull, "w", encoding="utf-8")
            # 不依赖 Hub 终端进度条；上方缓存监测器会以 GUI 日志形式展示进度。
            os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
            from transformers import AutoConfig, CLIPModel, CLIPProcessor

            # 不同 CLIP 权重不能强行套用同一个 Python 类。尤其
            # OFA-Sys/chinese-clip-* 的 config.model_type 是 chinese_clip；
            # 以前用 CLIPModel 加载会产生大量“缺失/意外权重”，看似完成加载，
            # 实际文本池化输出为 None，随后所有文案匹配都会失败。
            # 完整缓存必须彻底离线：否则 Hugging Face 仍会进行远端 ETag 校验，
            # 在受限网络或旧下载锁机器上表现为“加载模型一直卡住”。
            load_kwargs = {"local_files_only": bool(has_cached_model)}
            clip_config = AutoConfig.from_pretrained(normalized_name, **load_kwargs)
            is_chinese_clip = str(getattr(clip_config, "model_type", "") or "").strip().lower() == "chinese_clip"
            if is_chinese_clip:
                from transformers import ChineseCLIPModel, ChineseCLIPProcessor
                model_class, processor_class = ChineseCLIPModel, ChineseCLIPProcessor
                log_fn("✅ 已识别 Chinese-CLIP 权重，使用对应原生架构加载", "green")
            else:
                model_class, processor_class = CLIPModel, CLIPProcessor

            # device 字符串 -> torch.device
            torch_device = torch.device(device)
            # 优先使用 safetensors；如果仓库没有 safetensors，则自动回退到 .bin 权重
            try:
                clip_model = model_class.from_pretrained(normalized_name, use_safetensors=True, **load_kwargs)
            except Exception:
                clip_model = model_class.from_pretrained(normalized_name, use_safetensors=False, **load_kwargs)
            clip_processor = processor_class.from_pretrained(normalized_name, **load_kwargs)
            clip_model.eval().to(torch_device)

            class TransformersClipAdapter:
                def __init__(self, model, processor, device):
                    self.model = model
                    self.processor = processor
                    self.device = device

                def _batched(self, items, batch_size):
                    for i in range(0, len(items), max(1, int(batch_size))):
                        yield items[i:i + max(1, int(batch_size))]

                def encode(self, sentences, batch_size=32, show_progress_bar=False, convert_to_numpy=True):
                    # 兼容 SentenceTransformer.encode 的调用方式：
                    # - sentences: List[str] 或 List[PIL.Image.Image]
                    from PIL import Image
                    import numpy as np
                    import torch

                    if not sentences:
                        return np.zeros((0, 512), dtype=np.float32)

                    is_image = isinstance(sentences[0], Image.Image)
                    feats_all = []

                    def _extract_2d_embedding(model_out, want: str):
                        """
                        将各种 Transformers 输出统一抽取成 (B, D) 的 embedding 张量。
                        want: "image" 或 "text"
                        """
                        # 1) 最理想：CLIP/ChineseCLIP 输出
                        if want == "image" and hasattr(model_out, "image_embeds") and model_out.image_embeds is not None:
                            return model_out.image_embeds
                        if want == "text" and hasattr(model_out, "text_embeds") and model_out.text_embeds is not None:
                            return model_out.text_embeds

                        # 2) 直接就是 tensor
                        if torch.is_tensor(model_out):
                            return model_out

                        # 3) BERT 类：pooler_output
                        if hasattr(model_out, "pooler_output") and model_out.pooler_output is not None:
                            return model_out.pooler_output

                        # 4) last_hidden_state：取 CLS 向量
                        if hasattr(model_out, "last_hidden_state") and model_out.last_hidden_state is not None:
                            lhs = model_out.last_hidden_state
                            if torch.is_tensor(lhs):
                                if lhs.dim() == 3:
                                    return lhs[:, 0, :]
                                if lhs.dim() == 2:
                                    return lhs

                        # 5) tuple/list 输出：找一个像 embedding 的 2D tensor
                        if isinstance(model_out, (tuple, list)):
                            for x in model_out:
                                if torch.is_tensor(x) and x.dim() == 2:
                                    return x
                            if len(model_out) >= 2 and torch.is_tensor(model_out[1]):
                                return model_out[1]

                        raise TypeError(f"无法从 Transformers 输出中提取 embedding: {type(model_out)}")

                    with torch.no_grad():
                        if is_image:
                            for batch in self._batched(sentences, batch_size):
                                inputs = self.processor(images=batch, return_tensors="pt")
                                inputs = inputs.to(self.device)
                                # 兼容某些模型 forward 强制要求 input_ids 的情况：
                                # 优先走 vision_model 分支，仅依赖 pixel_values
                                if "pixel_values" in inputs and hasattr(self.model, "vision_model"):
                                    vout = self.model.vision_model(pixel_values=inputs["pixel_values"])
                                    feats = _extract_2d_embedding(vout, "image")
                                    if hasattr(self.model, "visual_projection"):
                                        feats = self.model.visual_projection(feats)
                                else:
                                    out = self.model(**inputs)
                                    feats = _extract_2d_embedding(out, "image")
                                feats = feats / (feats.norm(dim=-1, keepdim=True) + 1e-8)
                                feats_all.append(feats.detach().cpu())
                        else:
                            for batch in self._batched(sentences, batch_size):
                                inputs = self.processor(text=batch, padding=True, truncation=True, return_tensors="pt")
                                inputs = inputs.to(self.device)
                                # 这个 Chinese-CLIP 在当前 Transformers 组合中，
                                # get_text_features() 会在内部把空 pooler_output 送进
                                # text_projection，报 linear(input=None)。直接使用文本
                                # 编码器的 CLS 隐藏向量，再做可用投影，完全绕过该缺陷。
                                feats = None
                                if "input_ids" in inputs and hasattr(self.model, "text_model"):
                                    text_kwargs = {
                                        "input_ids": inputs.get("input_ids"),
                                        "attention_mask": inputs.get("attention_mask", None),
                                    }
                                    # Chinese-CLIP 是 BERT 文本塔，token_type_ids 需要随
                                    # 处理器一起传入；普通 CLIP 不接受该参数，故仅在存在时
                                    # 尝试并在旧模型拒绝时无损回退。
                                    if "token_type_ids" in inputs:
                                        text_kwargs["token_type_ids"] = inputs.get("token_type_ids")
                                    try:
                                        tout = self.model.text_model(**text_kwargs)
                                    except TypeError:
                                        text_kwargs.pop("token_type_ids", None)
                                        tout = self.model.text_model(**text_kwargs)
                                    hidden = getattr(tout, "last_hidden_state", None)
                                    if torch.is_tensor(hidden):
                                        feats = hidden[:, 0, :] if hidden.dim() == 3 else hidden
                                    else:
                                        feats = _extract_2d_embedding(tout, "text")
                                    projection = getattr(self.model, "text_projection", None)
                                    if callable(projection):
                                        feats = projection(feats)
                                else:
                                    out = self.model(**inputs)
                                    feats = _extract_2d_embedding(out, "text")
                                if feats is None or not torch.is_tensor(feats):
                                    raise TypeError("CLIP 未返回可用的文本特征向量")
                                feats = feats / (feats.norm(dim=-1, keepdim=True) + 1e-8)
                                feats_all.append(feats.detach().cpu())

                    feats_all = torch.cat(feats_all, dim=0) if feats_all else torch.zeros((0, 512))
                    return feats_all.numpy() if convert_to_numpy else feats_all

            cls._clip_model = TransformersClipAdapter(clip_model, clip_processor, torch_device)
            cls._clip_model_name = runtime_cache_key
            download_monitor_stop.set()
            log_fn(f"✅ Transformers CLIP 加载完成 (device={device})", "green")
            return cls._clip_model
        except Exception as e:
            tf_load_error = e
            log_fn(f"⚠️ Transformers 加载失败 ({e})，尝试使用 cn_clip 官方库加载...", "orange")

        # 如果 sentence-transformers 加载失败，尝试 cn_clip 官方库
        try:
            import torch
            try:
                import cn_clip.clip as clip
                from cn_clip.clip import load_from_name
            except ImportError:
                log_fn("📦 检测到 cn_clip 缺失，正在自动安装 cn-clip...", "blue")
                if not _silent_install_libs(["cn_clip"], timeout=1800, log_prefix="[CN-CLIP]"):
                    raise ImportError("缺失 cn_clip 库，且自动安装失败。")
                import importlib
                importlib.invalidate_caches()
                import cn_clip.clip as clip
                from cn_clip.clip import load_from_name

            model_short_name = normalized_name.split("/")[-1].replace("chinese-clip-", "").upper()
            # 适配 cn_clip 官方库的模型名称
            if model_short_name == "VIT-L-14": model_short_name = "ViT-L-14"
            elif model_short_name == "VIT-H-14": model_short_name = "ViT-H-14"
            elif model_short_name == "VIT-B-16": model_short_name = "ViT-B-16"
            elif model_short_name == "RN50": model_short_name = "RN50"
            else: model_short_name = "ViT-L-14" # 默认一个，确保能加载

            # 尝试从 ModelScope 自动下载
            log_fn(f"⏳ 正在加载 CN-CLIP 模型: {model_short_name}…", "blue")
            # 使用 download_root 和 use_modelscope=True 确保自动下载
            model, preprocess = load_from_name(model_short_name, device=device, download_root=os.environ["HF_HOME"], use_modelscope=True)

            class CnClipAdapter:
                def __init__(self, model, preprocess, device):
                    self.model = model.eval().to(device)
                    self.preprocess = preprocess
                    self.device = device

                def encode(self, sentences, batch_size=32, show_progress_bar=False, convert_to_numpy=True):
                    from PIL import Image
                    import numpy as np
                    import torch

                    if isinstance(sentences[0], Image.Image):
                        processed_images = torch.stack([self.preprocess(img) for img in sentences]).to(self.device)
                        with torch.no_grad():
                            features = self.model.encode_image(processed_images)
                    else:
                        tokenized_texts = clip.tokenize(sentences).to(self.device)
                        with torch.no_grad():
                            features = self.model.encode_text(tokenized_texts)
                    features /= features.norm(dim=-1, keepdim=True)
                    return features.cpu().numpy() if convert_to_numpy else features

            cls._clip_model = CnClipAdapter(model, preprocess, device)
            cls._clip_model_name = runtime_cache_key
            download_monitor_stop.set()
            log_fn(f"✅ CN-CLIP 模型加载完成 (device={device})", "green")
            return cls._clip_model
        except Exception as cn_e:
            download_monitor_stop.set()
            final_error_msg = (
                "CLIP 模型加载失败：\n"
                f"  - sentence-transformers 尝试失败: {st_load_error}\n"
                f"  - transformers 尝试失败: {tf_load_error}\n"
                f"  - cn_clip 尝试失败: {cn_e}\n"
                "建议按优先级排查：\n"
                "  1) 安装/更新 safetensors + transformers（优先使用 safetensors 权重）\n"
                "  2) 或安装 cn_clip 作为兜底（pip install cn_clip）\n"
                "  3) 最后再考虑升级 torch>=2.6\n"
                "并确认模型名称正确。"
            )
            raise RuntimeError(final_error_msg)

    @classmethod
    def clear_cache(cls):
        """  清除图片特征缓存。"""
        cls._img_feature_cache.clear()
        cls._img_feature_cache_model_name = ""

    def run(self):
        try:
            total_images  = len(self.image_paths)
            total_scripts = len(self.scripts)
            if total_images == 0:
                self.error.emit("没有可处理的图片池")
                return
            if total_scripts == 0:
                self.error.emit("表格中没有文案内容")
                return

            self.log.emit(f"⚡ [CLIP 极速模式] 开始：{total_images} 张图片 × {total_scripts} 条文案", "blue")

            # 1. 加载 CLIP 模型
            self.progress.emit(2)
            model = self._load_clip_model(self.clip_model_name, self.use_gpu, self.log.emit)

            # 2. 批量编码图片（利用缓存避免重复计算）
            self.log.emit("🖼️ 正在提取图片特征向量（已缓存的图片直接跳过）...", "blue")
            uncached = [p for p in self.image_paths if p not in self.__class__._img_feature_cache]
            if uncached:
                try:
                    from PIL import Image as _PILImage
                    pil_images = []
                    valid_paths = []
                    for p in uncached:
                        try:
                            img = load_material_image(p)
                            img.thumbnail((336, 336))
                            pil_images.append(img)
                            valid_paths.append(p)
                        except Exception as img_e:
                            self.log.emit(f"⚠️ 图片读取失败，跳过: {os.path.basename(p)} ({img_e})", "orange")
                    if pil_images:
                        # 某些 SentenceTransformer / CUDA 组合在长批次中会罕见地
                        # 返回少于输入图片数的特征，却不抛出异常。旧代码直接 zip，
                        # 会静默吞掉尾部图片，最后表现为“图片和文案数量相同却漏两张”。
                        # 此处先保存确实返回的部分，再对缺失项单张重试；仍失败才把
                        # 文件名和原因明确写入日志，绝不把半批结果伪装成完整结果。
                        feats = model.encode(pil_images, batch_size=16, show_progress_bar=False, convert_to_numpy=True)
                        try:
                            returned_count = len(feats)
                        except TypeError:
                            returned_count = 0
                        usable_count = min(len(valid_paths), returned_count)
                        for path, feat in zip(valid_paths[:usable_count], feats[:usable_count]):
                            self.__class__._img_feature_cache[path] = feat
                        if returned_count != len(valid_paths):
                            self.log.emit(
                                f"⚠️ 图片批量特征返回数量异常：送入 {len(valid_paths)} 张、返回 {returned_count} 条；"
                                f"正在逐张补试 {len(valid_paths) - usable_count} 张，避免漏匹配。",
                                "orange"
                            )
                        for path, image in zip(valid_paths[usable_count:], pil_images[usable_count:]):
                            try:
                                single_feat = model.encode([image], batch_size=1, show_progress_bar=False, convert_to_numpy=True)
                                if len(single_feat) < 1:
                                    raise RuntimeError("模型未返回图片特征")
                                self.__class__._img_feature_cache[path] = single_feat[0]
                                self.log.emit(f"↻ 已逐张补回图片特征：{os.path.basename(path)}", "blue")
                            except Exception as retry_error:
                                self.log.emit(
                                    f"⚠️ 图片特征提取失败，无法参与匹配：{os.path.basename(path)} ({retry_error})",
                                    "orange"
                                )
                except Exception as enc_e:
                    self.error.emit(f"CLIP 图片编码失败: {enc_e}")
                    return
            cached_count = total_images - len(uncached)
            encoded_count = sum(p in self.__class__._img_feature_cache for p in uncached)
            failed_count = len(uncached) - encoded_count
            self.log.emit(f"图片特征：新编码 {encoded_count} 张，命中缓存 {cached_count} 张，失败 {failed_count} 张（失败文件及原因见上方日志）", "orange" if failed_count else "green")
            self.progress.emit(30)

            # 3. 收集所有有效图片特征
            import numpy as np
            img_feat_list = []
            valid_img_paths = []
            for p in self.image_paths:
                if p in self.__class__._img_feature_cache:
                    img_feat_list.append(self.__class__._img_feature_cache[p])
                    valid_img_paths.append(p)
            if not img_feat_list:
                self.error.emit("所有图片特征提取失败")
                return
            img_matrix = np.array(img_feat_list)  # shape: (N, D)
            # 归一化图片特征
            norms = np.linalg.norm(img_matrix, axis=1, keepdims=True)
            norms = np.where(norms == 0, 1e-8, norms)
            img_matrix_norm = img_matrix / norms

            # 4. 全局最优一对一匹配（最大化总体相似度）
            # 说明：
            # - 先为每条文案计算它对所有图片的相似度向量，组成 (M, N) 的相似度矩阵
            # - 再用匈牙利算法求解一对一全局最优分配（最大化 sum(sim)）
            match_result = {}

            # 收集有效文案（无内容且无备注的行直接跳过）
            valid_scripts = []   # [{script, row_idx, content, en, remark}]
            sims_rows = []       # 每行对应一条文案对所有图片的相似度
            path_bonus_rows = [] # 每行对应备注命中的路径优先级加分
            requirement_fused_rows = []
            strict_requirement_rows = []
            # 备注行先按备注筛出候选，再用文案在这些候选中择优。该数组仅用于
            # “备注行优先占图”的全局一对一求解，避免拿展示得分误作分配得分。
            requirement_selection_rows = []
            score_component_rows = []
            allowed_image_rows = []

            for s_idx, script in enumerate(self.scripts):
                if self._stop:
                    self.log.emit("⚠️ 已手动停止", "orange")
                    break
                row_idx = script["row"]
                content = (script.get("cn", "") or script.get("en", "")).strip()
                remark  = script.get("remark", "").strip()
                if not content and not remark:
                    continue

                directive = self.__class__._parse_remark_image_directives(remark, valid_img_paths)
                visual_remark = str(directive.get('visual_remark', '') or '').strip()
                include_indices = set(directive.get('include', set()) or set())
                exclude_indices = set(directive.get('exclude', set()) or set())
                allowed_scope_dirs = [os.path.normcase(os.path.abspath(path)) for path in script.get('allowed_image_dirs', []) or [] if os.path.isdir(path)]
                if allowed_scope_dirs:
                    scope_indices = set()
                    for img_index, image_path in enumerate(valid_img_paths):
                        image_absolute = os.path.normcase(os.path.abspath(image_path))
                        for directory in allowed_scope_dirs:
                            try:
                                if os.path.commonpath([image_absolute, directory]) == directory:
                                    scope_indices.add(img_index)
                                    break
                            except ValueError:
                                continue
                    if not scope_indices:
                        self.log.emit(f"⚠️ 第 {row_idx + 1} 行指定的图片目录中没有可用图片，已保留为空。", "orange")
                        continue
                else:
                    scope_indices = set(range(len(valid_img_paths)))
                allowed_indices = (include_indices if include_indices else scope_indices) & scope_indices
                allowed_indices -= exclude_indices
                include_fallback = bool(include_indices) and not allowed_indices
                if include_fallback:
                    # 备注点名的文件若不在当前素材池，不能让整行被永久卡死；
                    # 按用户规则回退到文案匹配，但仍保持备注行先于普通行处理。
                    allowed_indices = scope_indices - exclude_indices
                    self.log.emit(
                        f"⚠️ 第 {row_idx + 1} 行备注点名图片不在当前素材池，已改为按文案视觉回退。",
                        "orange"
                    )
                if directive.get('has_directive'):
                    self.log.emit(f"🖼️ 第 {row_idx + 1} 行备注图片规则：可用 {len(allowed_indices)} 张；视觉要求：{visual_remark or '无（直接按指定图片）'}", "blue")
                if not allowed_indices:
                    self.log.emit(f"⚠️ 第 {row_idx + 1} 行备注指定/排除后没有可用图片，已跳过该行。", "orange")
                    continue

                # 逐条生成该文案对所有图片的相似度向量
                try:
                    content_feat = model.encode([content], convert_to_numpy=True)[0] if content else None
                    content_norm = content_feat / (np.linalg.norm(content_feat) + 1e-8) if content_feat is not None else None

                    # 备注既保留完整语义，也会拆成视觉查询；不依赖固定关键词表。
                    remark_feat = None
                    requirement_feat = None
                    strict_requirement_sims = np.zeros(len(valid_img_paths))
                    if visual_remark:
                        raw_remark_feat = model.encode([visual_remark], convert_to_numpy=True)[0]
                        requirement_feat = model.encode(
                            [self.__class__._build_requirement_prompt('', visual_remark)], convert_to_numpy=True
                        )[0]
                        remark_feat = raw_remark_feat
                    remark_norm = remark_feat / (np.linalg.norm(remark_feat) + 1e-8) if remark_feat is not None else None
                    requirement_norm = requirement_feat / (np.linalg.norm(requirement_feat) + 1e-8) if requirement_feat is not None else None

                    content_sims = img_matrix_norm @ content_norm if content_norm is not None else np.zeros(len(valid_img_paths))
                    remark_sims  = img_matrix_norm @ remark_norm  if remark_norm is not None  else np.zeros(len(valid_img_paths))
                    requirement_sims = img_matrix_norm @ requirement_norm if requirement_norm is not None else np.zeros(len(valid_img_paths))
                    if visual_remark:
                        # 备注中的每一项都是“画面必须能看见”的要求。多种自然语言
                        # 表述分别召回，先得到备注满足度；文案只在满足度相近的
                        # 候选中择优，不允许反过来压过备注条件。
                        strict_queries = self.__class__._build_strict_requirement_prompts(visual_remark)
                        strict_vectors = model.encode(strict_queries, convert_to_numpy=True)
                        strict_vectors = strict_vectors / (np.linalg.norm(strict_vectors, axis=1, keepdims=True) + 1e-8)
                        strict_requirement_sims = np.maximum(
                            remark_sims,
                            np.max(img_matrix_norm @ strict_vectors.T, axis=1)
                        )
                        # 表格展示仍以备注满足度为主；专用的 selection_sims 会在
                        # 备注候选内部用极小权重引入文案语义，避免“侧面/闭眼都
                        # 符合但完全不贴台词”的情况。
                        combined_sims = strict_requirement_sims
                        selection_sims = strict_requirement_sims * 8.0 + content_sims * 0.10
                        self.log.emit(f"🧠 第 {row_idx + 1} 行启用备注优先：先满足备注，再以文案择优：{visual_remark[:64]}", "blue")
                    elif include_indices:
                        combined_sims = np.ones(len(valid_img_paths), dtype=np.float32)
                        selection_sims = content_sims if content else combined_sims
                    else:
                        combined_sims = content_sims
                        selection_sims = content_sims

                    # 关键增强：备注命中的文件夹/路径优先
                    path_bonus, hit_count = self.__class__._build_path_priority_bonus(visual_remark, valid_img_paths)
                    if hit_count > 0:
                        self.log.emit(
                            f"📁 第 {row_idx+1} 行备注命中 {hit_count} 张路径/文件夹，优先从这些图片中选择",
                            "gray"
                        )
                        combined_sims = combined_sims + path_bonus
                        if visual_remark:
                            strict_requirement_sims = strict_requirement_sims + path_bonus
                            selection_sims = selection_sims + path_bonus * 8.0
                        else:
                            selection_sims = selection_sims + path_bonus

                    disallowed = set(range(len(valid_img_paths))) - allowed_indices
                    if disallowed:
                        combined_sims = combined_sims.copy()
                        strict_requirement_sims = strict_requirement_sims.copy()
                        selection_sims = selection_sims.copy()
                        combined_sims[list(disallowed)] = -1e9
                        strict_requirement_sims[list(disallowed)] = -1e9
                        selection_sims[list(disallowed)] = -1e9

                    valid_scripts.append({
                        "script": script,
                        "row": row_idx,
                        "cn": content,
                        "en": script.get("en", ""),
                        "remark": remark,
                    })
                    sims_rows.append(combined_sims.astype(np.float32))
                    path_bonus_rows.append(path_bonus.astype(np.float32))
                    requirement_fused_rows.append(bool(visual_remark) or bool(include_indices))
                    strict_requirement_rows.append(strict_requirement_sims.astype(np.float32))
                    requirement_selection_rows.append(selection_sims.astype(np.float32))
                    score_component_rows.append((remark_sims, requirement_sims, content_sims))
                    allowed_image_rows.append(allowed_indices)
                except Exception as e:
                    self.log.emit(f"❌ 第 {row_idx+1} 行特征提取失败，已跳过: {e}", "red")

                self.progress.emit(30 + int((s_idx + 1) / max(1, total_scripts) * 35))

            if not valid_scripts:
                self.error.emit("没有可用于匹配的文案内容（全部为空或特征提取失败）")
                return

            sims_matrix = np.vstack(sims_rows)  # shape: (M, N)
            M, N = sims_matrix.shape
            def _hungarian_min_cost(cost_matrix):
                """
                匈牙利算法（最小化成本），支持行数<=列数的矩形矩阵。
                cost_matrix: List[List[float]]，shape=(rows, cols)
                return: assignment 列索引列表，长度=rows，每个元素为 0..cols-1
                """
                rows = len(cost_matrix)
                cols = len(cost_matrix[0]) if rows else 0
                # 1-indexed 实现：rows<=cols
                u = [0.0] * (rows + 1)
                v = [0.0] * (cols + 1)
                p = [0] * (cols + 1)
                way = [0] * (cols + 1)

                INF = 1e30
                for i in range(1, rows + 1):
                    p[0] = i
                    j0 = 0
                    minv = [INF] * (cols + 1)
                    used = [False] * (cols + 1)
                    while True:
                        used[j0] = True
                        i0 = p[j0]
                        delta = INF
                        j1 = 0
                        for j in range(1, cols + 1):
                            if not used[j]:
                                cur = cost_matrix[i0 - 1][j - 1] - u[i0] - v[j]
                                if cur < minv[j]:
                                    minv[j] = cur
                                    way[j] = j0
                                if minv[j] < delta:
                                    delta = minv[j]
                                    j1 = j
                        for j in range(0, cols + 1):
                            if used[j]:
                                u[p[j]] += delta
                                v[j] -= delta
                            else:
                                minv[j] -= delta
                        j0 = j1
                        if p[j0] == 0:
                            break
                    while True:
                        j1 = way[j0]
                        p[j0] = p[j1]
                        j0 = j1
                        if j0 == 0:
                            break

                assignment = [-1] * rows
                for j in range(1, cols + 1):
                    if p[j] != 0:
                        assignment[p[j] - 1] = j - 1
                return assignment

            def _solve_one_to_one(score_matrix):
                """最大化分数的一对一分配；图片不足时返回 -1，不伪造结果。"""
                rows, actual_cols = score_matrix.shape
                if not rows or not actual_cols:
                    return [-1] * rows
                stable_scores = score_matrix.astype(np.float64) - (np.arange(actual_cols, dtype=np.float64)[None, :] * 1e-12)
                padded_cols = max(actual_cols, rows)
                if padded_cols != actual_cols:
                    stable_scores = np.hstack((stable_scores, np.full((rows, padded_cols - actual_cols), -1e9, dtype=np.float64)))
                assigned = _hungarian_min_cost((-stable_scores).tolist())
                return [column if 0 <= column < actual_cols else -1 for column in assigned]

            # 备注是硬性画面条件：先在完整图片池中为所有备注行做全局一对一分配，
            # 再让普通文案从剩余图片中分配。这样“侧面/闭眼/祷告”等目标不会被
            # 其它无备注文案以更高的故事语义分数抢走。
            assign_cols = [-1] * M
            requirement_indices = [i for i, item in enumerate(requirement_fused_rows) if item]
            plain_indices = [i for i, item in enumerate(requirement_fused_rows) if not item]
            used_columns = set()
            if requirement_indices:
                strict_matrix = np.vstack([requirement_selection_rows[i] for i in requirement_indices])
                for local_row, column in enumerate(_solve_one_to_one(strict_matrix)):
                    if column >= 0:
                        assign_cols[requirement_indices[local_row]] = column
                        used_columns.add(column)
                self.log.emit(f"🔒 已优先为 {len(requirement_indices)} 条备注要求保留图片；普通文案仅在剩余图片中匹配。", "blue")
            remaining_columns = [column for column in range(N) if column not in used_columns]
            if plain_indices and remaining_columns:
                plain_matrix = sims_matrix[np.ix_(plain_indices, remaining_columns)]
                for local_row, local_column in enumerate(_solve_one_to_one(plain_matrix)):
                    if local_column >= 0:
                        assign_cols[plain_indices[local_row]] = remaining_columns[local_column]

            matched = 0
            for i, j in enumerate(assign_cols):
                meta = valid_scripts[i]
                row_idx = meta["row"]
                if j is None or j < 0 or j >= N:
                    self.log.emit(f"❓ 第 {row_idx+1} 行：图片不足或未分配到有效图片", "orange")
                    continue
                if j not in allowed_image_rows[i] or float(sims_matrix[i, j]) < -1e8:
                    self.log.emit(f"❓ 第 {row_idx+1} 行：备注的图片使用/排除规则下未分配到有效图片", "orange")
                    continue

                sel_path = valid_img_paths[j]
                sim = float(sims_matrix[i, j])
                path_bonus_val = float(path_bonus_rows[i][j]) if i < len(path_bonus_rows) and j < len(path_bonus_rows[i]) else 0.0
                remark_part, intent_part, content_part = (float(x[j]) for x in score_component_rows[i])
                final_score = round(sim * 100, 1)
                match_result[sel_path] = {
                    "row": row_idx,
                    "score": final_score,
                    "reason": (f"CLIP相似度:{sim:.3f} (全局最优"
                               f"{' / 备注:{remark_part:.3f}、完整意图:{intent_part:.3f}、备注优先后由文案择优' if requirement_fused_rows[i] else ''}"
                               f"{' / 备注路径优先' if path_bonus_val > 0 else ''})"),
                    "cn": meta["cn"],
                    "en": meta["en"],
                }
                matched += 1
                self.log.emit(
                    f"✅ 第 {row_idx+1} 行 → {os.path.basename(sel_path)} (得分: {final_score})",
                    "green"
                )

                self.progress.emit(65 + int((i + 1) / max(1, M) * 35))

            self.log.emit(f"⚡ CLIP 匹配完成！共 {matched} 组结果（全局最优一对一）。", "green")
            expected_rows = {s['row'] for s in self.scripts if str(s.get('cn') or s.get('en') or '').strip() or str(s.get('remark') or '').strip()}
            missing_rows = sorted(expected_rows - {info['row'] for info in match_result.values()})
            if missing_rows:
                self.log.emit('⚠️ 匹配未完整：以下文案行没有图片：' + ', '.join(str(r + 1) for r in missing_rows)
                              + '。请检查图片数量、解码失败与文案特征错误；不会伪造匹配结果。', 'orange')
            self.result.emit(match_result)

        except Exception as e:
            err_msg = traceback.format_exc()
            self.log.emit(f"❌ CLIP 匹配线程异常：{e}", "red")
            self.error.emit(f"CLIP 匹配线程异常: {e}\n{err_msg}")
            # 后台线程禁止直接创建 QMessageBox；错误已通过 signal 回到界面线程处理。


# ─────────────────────────────────────────────
#  AiImageReviewThread：AI 图片智能审核后台线程
# ─────────────────────────────────────────────
class AiImageReviewThread(QThread):
    """
    后台线程：调用 AI（视觉模型），根据用户设定的规则对图片进行审核。
    """
    progress  = pyqtSignal(int)          # 0-100
    log       = pyqtSignal(str, str)     # (消息, 颜色)
    result    = pyqtSignal(dict)         # {(proj_name, row_idx): {"state": str, "note": str}}
    error     = pyqtSignal(str)          # 错误信息

    def __init__(self, tasks, rules, ai_config, local_engine=None):
        super().__init__()
        self.tasks = tasks; self.rules = rules; self.ai_config = ai_config; self.local_engine = local_engine; self._stop = False

    def stop(self): self._stop = True

    def run(self):
        try:
            if not self.tasks: return
            rules_str = "\n".join([f"- {r['keyword']}: {r.get('desc', '无详细说明')}" for r in self.rules if r.get("keyword")])
            review_results = {}; total = len(self.tasks)
            for i, task in enumerate(self.tasks):
                if self._stop: break
                
                proj = task["proj"]; row_idx = task["row"]; img_path = task["img"]; code = task["code"]
                cn_text = str(task.get("cn", "") or "").strip()
                en_text = str(task.get("en", "") or "").strip()
                combined_copy = "\n".join([t for t in [f"中文文案：{cn_text}" if cn_text else "", f"英文文案：{en_text}" if en_text else ""] if t]).strip()
                has_visual_rules = bool(rules_str.strip())
                has_copy_review = bool(cn_text or en_text)
                if not img_path or not os.path.exists(img_path): continue
                self.log.emit(f"🔍 正在审核 [{proj}] {code} ...", "blue")
                try:
                    response_text = ""
                    detail_text = ""
                    if self.ai_config.get("mode") == "local" and self.local_engine:
                        if not getattr(self.local_engine, "supports_vision", False):
                            self.log.emit(
                                f"⚠️ {code} 跳过: 当前本地模型是纯文字模型，不支持图片审核。请切换视觉模型或改用远程 API。",
                                "orange"
                            )
                            continue
                        system_prompt = build_effective_review_system_prompt(self.ai_config, rules_str, combined_copy)
                        user_text = "请审核这张图片，并按约定 JSON 返回结果。"
                        if combined_copy:
                            user_text += f"\n\n需要匹配的文案如下：\n{combined_copy}"
                        # 11GB 显存 + 追求速度：强制低显存/缩图推理 + 限制输出长度
                        # 说明：prefer_low_memory=True 会在引擎内部将图片缩到约 384px，显著降低显存与耗时。
                        response_text = self.local_engine.chat(
                            history=[{"role": "user", "content": user_text}],
                            system_prompt=system_prompt,
                            image_paths=[img_path],
                            max_new_tokens=256,
                            temperature=0.0,
                            do_sample=False,
                            prefer_low_memory=True,
                            cleanup_cache=True
                        )
                        detail_text = response_text or ""
                    elif self.ai_config.get("mode") == "clip":
                        # CLIP 模式不支持视觉审核逻辑（它只能算相似度，不能理解规则），给出明确提示
                        self.log.emit(f"⚠️ {code} 跳过: CLIP 模式不支持图片内容审核，请在配置中切换为『远程 API』或『本地大模型』。", "orange")
                        continue
                    else:
                        # 远程 API 模式
                        runtime_profiles = get_runtime_api_profiles(self.ai_config)
                        primary_profile = runtime_profiles[0] if runtime_profiles else build_legacy_api_profile(self.ai_config)
                        api_keys = list(primary_profile.get("api_keys", []))
                        if not api_keys:
                            fallback_key = os.environ.get("OPENAI_API_KEY", "")
                            api_keys = [fallback_key] if fallback_key else []
                        api_base = primary_profile.get("api_base", "https://api.openai.com/v1")
                        model = primary_profile.get("api_model", "gpt-4o-mini")
                        
                        if not api_keys:
                            self.log.emit(f"❌ {code} 失败: 未配置 API Key，请点击『AI 配置』填写。", "red")
                            continue

                        # 核心改进：审核台专用极致压缩 (224px, 50 quality)，大幅降低 Token 消耗，防止 429
                        try:
                            from PIL import Image
                            with load_material_image(img_path) as img:
                                if img.mode in ("RGBA", "P", "LA"): img = img.convert("RGB")
                                img.thumbnail((224, 224), Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.ANTIALIAS)
                                buf = io.BytesIO()
                                img.save(buf, format="JPEG", quality=50, optimize=True)
                                b64_raw_data = base64.b64encode(buf.getvalue()).decode("utf-8")
                                b64_url = f"data:image/jpeg;base64,{b64_raw_data}"
                        except:
                            b64_url = AiImageMatchThread._encode_image(img_path)
                        system_prompt = build_effective_review_system_prompt(self.ai_config, rules_str, combined_copy)

                        review_user_text = "请根据系统规则审核这张图片，并返回 JSON 格式结果。"
                        if combined_copy:
                            review_user_text += f"\n\n需要匹配的文案如下：\n{combined_copy}"

                        # 优化 Payload 兼容性：部分模型不支持 system 消息为列表格式，改为纯文本
                        messages = [
                            {"role": "system", "content": system_prompt},
                            {"role": "user", "content": [
                                {"type": "text", "text": review_user_text}, 
                                {"type": "image_url", "image_url": {"url": b64_url}}
                            ]}
                        ]
                        import urllib.request; import json as _json
                        # 核心修复：移除 "response_format": {"type": "json_object"}
                        # 因为很多兼容接口（如 Gemini, Claude, Ollama, Qwen）在视觉模式下开启此项会报 400 错误
                        payload = {
                            "model": model, 
                            "messages": messages, 
                            "max_tokens": 500,
                            "temperature": 0.1
                        }
                        
                        # 调试模式日志
                        if self.ai_config.get("debug_mode"):
                            debug_target = f"{api_base}/chat/completions"
                            if is_google_native_api(api_base):
                                debug_target = f"{api_base}/v1beta/models/{pick_google_model(model, 'gemini-1.5-flash')}:generateContent"
                            self.log.emit(f"🛠️ [DEBUG] 发送请求到: {debug_target}", "gray")
                            self.log.emit(f"🛠️ [DEBUG] 模型: {model}", "gray")
                            # 仅打印部分 payload 避免刷屏，不打印 base64 图片数据
                            self.log.emit(f"🛠️ [DEBUG] 系统提示词: {system_prompt[:160]}...", "gray")

                        try:
                            # requests 已在文件顶部导入
                            def _make_request(current_model, current_key):
                                wait_for_api_slot(
                                    api_base, current_key,
                                    get_effective_api_interval(api_base, self.ai_config, 0),
                                    stop_check=lambda: self._stop,
                                    log_fn=self.log.emit,
                                    prefix=f"⏳ {code}: "
                                )
                                if is_google_native_api(api_base):
                                    # Google 原生适配：忠实使用用户选择的模型
                                    g_mdl = pick_google_model(current_model, "gemini-1.5-flash")
                                    h = {"Content-Type": "application/json"}
                                    b64_raw = b64_url.split(",")[-1]
                                    p = {
                                        "contents": [{
                                            "parts": [
                                                {"text": f"System: {system_prompt}\nUser: {review_user_text}"},
                                                {"inline_data": {"mime_type": "image/jpeg", "data": b64_raw}}
                                            ]
                                        }],
                                        "generationConfig": {"temperature": 0.1, "maxOutputTokens": 500},
                                        "safetySettings": [
                                            {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                                            {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                                            {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                                            {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
                                        ]
                                    }

                                    tried_models = []
                                    google_candidates = [g_mdl]
                                    if g_mdl == "gemini-2.5-flash":
                                        google_candidates.extend(["gemini-2.0-flash", "gemini-1.5-flash"])

                                    res = None
                                    for candidate_model in google_candidates:
                                        if candidate_model in tried_models:
                                            continue
                                        tried_models.append(candidate_model)
                                        url = f"{api_base}/v1beta/models/{candidate_model}:generateContent?key={current_key}"
                                        self.log.emit(f"🔍 {code}: 正在向 Google 发送图片数据 (模型: {candidate_model})...", "gray")
                                        r = requests.post(url, json=p, headers=h, timeout=60, verify=HTTP_VERIFY)
                                        self.log.emit(f"📡 {code}: Google 已响应，状态码: {r.status_code}", "gray")

                                        if r.status_code == 403:
                                            err_detail = extract_api_error_message(r)
                                            self.log.emit(f"⚠️ {code}: Google 403 - {err_detail[:160]}", "orange")
                                            low_detail = err_detail.lower()
                                            quota_like = any(x in low_detail for x in ["quota", "resource_exhausted", "rate limit", "billing", "daily limit"])
                                            model_like = any(x in low_detail for x in ["permission", "forbidden", "not found", "unsupported", "not available", "denied", "model"])
                                            if quota_like:
                                                raise RuntimeError(f"Google 403 配额/项目限制: {err_detail}")
                                            if model_like and candidate_model != google_candidates[-1]:
                                                self.log.emit(f"🔄 {code}: 当前模型疑似不可用，自动尝试备选模型...", "orange")
                                                continue
                                            raise RuntimeError(f"Google 403 权限限制: {err_detail}")

                                        r.raise_for_status()
                                        res = r.json()
                                        break

                                    if res is None:
                                        raise RuntimeError("Google 未返回有效结果")
                                    # 健壮解析：处理被安全过滤的情况
                                    candidates = res.get("candidates", [])
                                    if not candidates:
                                        feedback = res.get("promptFeedback", {})
                                        reason = feedback.get("blockReason", "未知原因")
                                        raise RuntimeError(f"Google 安全策略拦截: {reason}")
                                    
                                    content_obj = candidates[0].get("content", {})
                                    parts = content_obj.get("parts", [])
                                    if not parts:
                                        finish_reason = candidates[0].get("finishReason", "Unknown")
                                        raise RuntimeError(f"Google 未返回内容, 原因: {finish_reason}")
                                    
                                    text = parts[0].get("text", "").strip()
                                    return _json.dumps({"choices": [{"message": {"content": text}}]})
                                else:
                                    payload["model"] = current_model
                                    headers = {
                                        "Authorization": f"Bearer {current_key}", 
                                        "Content-Type": "application/json",
                                        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
                                    }
                                    self.log.emit(f"🔍 {code}: 正在向服务器发送图片数据 (模型: {current_model})...", "gray")
                                    r = requests.post(f"{api_base}/chat/completions", json=payload, headers=headers, timeout=60, verify=HTTP_VERIFY)
                                    self.log.emit(f"📡 {code}: 服务器已响应，状态码: {r.status_code}", "gray")
                                    r.raise_for_status()
                                    return r.text

                            raw_res = None
                            max_retries = max(1, int(self.ai_config.get("api_max_retries", 3)))
                            if not hasattr(self, "_current_key_idx"): self._current_key_idx = 0

                            success_flag = False
                            last_exception = None
                            available_keys = [k for k in api_keys if k.strip()]
                            rate_limited_keys = set()
                            is_google_direct = is_google_native_api(api_base)

                            for attempt_round in range(max_retries):
                                if self._stop or success_flag:
                                    break

                                attempted_this_round = 0
                                for offset in range(len(available_keys)):
                                    if self._stop or success_flag:
                                        break

                                    key_pos = (self._current_key_idx + offset) % len(available_keys)
                                    active_key = available_keys[key_pos]
                                    if active_key in rate_limited_keys and len(rate_limited_keys) < len(available_keys):
                                        continue

                                    attempted_this_round += 1
                                    self._current_key_idx = (key_pos + 1) % len(available_keys)

                                    try:
                                        raw_res = _make_request(model, active_key)
                                        success_flag = True
                                        break
                                    except Exception as re:
                                        last_exception = re
                                        err_msg = str(re)
                                        if "429" in err_msg:
                                            cooldown = (2 ** attempt_round) * (20 if is_google_direct else 3)
                                            apply_api_cooldown(api_base, active_key, cooldown)
                                            rate_limited_keys.add(active_key)
                                            remaining = len([k for k in available_keys if k not in rate_limited_keys])
                                            if len(available_keys) == 1:
                                                self.log.emit(f"⚠️ {code}: 当前 Key 触发 429，进入 {cooldown}s 冷却后重试...", "orange")
                                            else:
                                                self.log.emit(f"⚠️ {code}: 当前 Key 触发 429，冷却 {cooldown}s；剩余可切换 Key: {remaining} 个。", "orange")
                                            continue

                                        if "安全策略拦截" in err_msg:
                                            self.log.emit(f"🚫 {code}: {err_msg}", "orange")
                                            break

                                        if "400" in err_msg and model == "gpt-4o-mini":
                                            try:
                                                raw_res = _make_request("gpt-4o", active_key)
                                                success_flag = True
                                                break
                                            except Exception as upgrade_err:
                                                last_exception = upgrade_err

                                        raise re

                                if success_flag:
                                    break

                                if attempted_this_round == 0 and rate_limited_keys and attempt_round < max_retries - 1:
                                    rate_limited_keys.clear()

                            if not success_flag:
                                if available_keys and len(rate_limited_keys) == len(available_keys):
                                    raise RuntimeError(f"{code}: 所有 Key 都因 429 进入冷却，请稍后重试或把请求间隔调高。")
                                if last_exception:
                                    raise last_exception

                            if raw_res:
                                if self.ai_config.get("debug_mode"):
                                    self.log.emit(f"🛠️ [DEBUG] 收到原始返回: {raw_res[:500]}...", "gray")
                                res_json = _json.loads(raw_res)
                                response_text = res_json["choices"][0]["message"]["content"].strip()
                                detail_text = response_text or ""
                        except Exception as e:
                            err_msg = str(e)
                            if "401" in err_msg:
                                self.log.emit(f"❌ {code} 审核失败: 401 Unauthorized (API Key 无效)。", "red")
                            elif "403" in err_msg:
                                self.log.emit(f"❌ {code} 审核失败: 403 Forbidden ({err_msg[:180]})", "red")
                            elif "404" in err_msg:
                                self.log.emit(f"❌ {code} 审核失败: 404 Not Found (模型或地址错误)。", "red")
                            elif "400" in err_msg:
                                self.log.emit(f"❌ {code} 审核失败: 400 Bad Request (模型不支持或参数错误)。", "red")
                            else:
                                self.log.emit(f"❌ {code} 审核失败: {err_msg[:120]}", "red")
                            continue
                    if response_text:
                        rt = str(response_text).strip()
                        if rt.startswith("```"):
                            lines = rt.splitlines()
                            if lines and lines[0].startswith("```"): lines = lines[1:]
                            if lines and lines[-1].startswith("```"): lines = lines[:-1]
                            rt = "\n".join(lines).strip()
                        # 宽松解析：兼容自然语言/代码块/类 Python dict 输出
                        data = parse_json_loose(rt)
                        if isinstance(data, dict):
                            analysis_txt = str(data.get("analysis", "") or "").strip()
                            suggestion_txt = str(data.get("suggestion", "") or "").strip()
                            conf_txt = data.get("confidence", "")
                            if conf_txt != "" and conf_txt is not None:
                                try:
                                    analysis_txt = (analysis_txt + f"（置信度: {float(conf_txt):.2f}）").strip()
                                except Exception:
                                    analysis_txt = (analysis_txt + f"（置信度: {conf_txt}）").strip()
                            ai_note = analysis_txt or str(data.get("reason", "") or "").strip()
                            category = infer_review_category(data)
                            state_label = review_state_label_from_category(category)
                            note = build_review_note(category, data.get("reason", ""), ai_note)
                            review_results[(proj, row_idx)] = {
                                "state": state_label,
                                "note": note,
                                "detail": detail_text,
                                "analysis": ai_note,
                                "suggestion": suggestion_txt,
                                "category": category,
                            }
                            if state_label == REVIEW_STATE_PASS:
                                self.log.emit(f"✅ {code}: 审核通过", "green")
                            elif state_label == REVIEW_STATE_COPY_MISMATCH:
                                self.log.emit(f"🟣 {code}: {note}", "#7c3aed")
                            elif state_label == REVIEW_STATE_VISUAL_ISSUE:
                                self.log.emit(f"🟠 {code}: {note}", "orange")
                            else:
                                self.log.emit(f"🟡 {code}: {note}", "#ca8a04")
                        else:
                            # 解析失败也要把原文留给用户核对
                            review_results[(proj, row_idx)] = {"state": REVIEW_STATE_MANUAL, "note": "需人工复核：AI 返回无法解析", "detail": detail_text or rt, "analysis": "", "suggestion": "", "category": "manual_review"}
                            if self.ai_config.get("debug_mode"):
                                self.log.emit(f"🛠️ [DEBUG] 无法解析的原始输出: {rt[:400]}...", "gray")
                            self.log.emit(f"❌ {code} 审核结果解析失败: 模型未返回可解析的 JSON 结果", "red")
                except Exception as e: self.log.emit(f"❌ {code} 审核出错: {str(e)}", "red")
                self.progress.emit(int((i + 1) / total * 100))
            self.result.emit(review_results)
        except Exception as e:
            err_msg = traceback.format_exc()
            self.error.emit(f"图片审核线程异常: {e}\n{err_msg}")
# ─────────────────────────────────────────────
#  ParallelImageReviewThread：多 Key 并行 AI 图片审核线程
# ─────────────────────────────────────────────
class ParallelImageReviewThread(QThread):
    """
    后台线程：将图片审核任务均匀分配到多个 API Key，并行执行。
    """
    progress  = pyqtSignal(int)
    log       = pyqtSignal(str, str)
    result    = pyqtSignal(dict)
    error     = pyqtSignal(str)

    def __init__(self, tasks, rules, ai_config):
        super().__init__()
        self.tasks = tasks
        self.rules = rules
        self.ai_config = ai_config
        self._stop = False

    def stop(self): self._stop = True

    def _build_task_context(self, task, rules_str):
        proj = task["proj"]
        row_idx = task["row"]
        img_path = task["img"]
        code = task["code"]
        cn_text = str(task.get("cn", "") or "").strip()
        en_text = str(task.get("en", "") or "").strip()
        combined_copy = "\n".join([
            t for t in [
                f"中文文案：{cn_text}" if cn_text else "",
                f"英文文案：{en_text}" if en_text else ""
            ] if t
        ]).strip()
        system_prompt = build_effective_review_system_prompt(self.ai_config, rules_str, combined_copy)
        review_user_text = "请根据系统规则审核这张图片，并返回 JSON 格式结果。"
        if combined_copy:
            review_user_text += f"\n\n需要匹配的文案如下：\n{combined_copy}"

        return {
            "proj": proj,
            "row_idx": row_idx,
            "img_path": img_path,
            "code": code,
            "system_prompt": system_prompt,
            "review_user_text": review_user_text
        }

    def _encode_review_image(self, img_path):
        try:
            from PIL import Image
            with load_material_image(img_path) as img:
                if img.mode in ("RGBA", "P", "LA"):
                    img = img.convert("RGB")
                img.thumbnail((224, 224), Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.ANTIALIAS)
                buf = io.BytesIO()
                img.save(buf, format="JPEG", quality=50, optimize=True)
                b64_raw_data = base64.b64encode(buf.getvalue()).decode("utf-8")
                return f"data:image/jpeg;base64,{b64_raw_data}"
        except:
            return AiImageMatchThread._encode_image(img_path)

    def _review_one_task(self, task, rules_str, ordered_keys, slot_no, slot_total):
        import json as _json
        import re as _re

        if self._stop:
            return None

        ctx = self._build_task_context(task, rules_str)
        proj = ctx["proj"]
        row_idx = ctx["row_idx"]
        img_path = ctx["img_path"]
        code = ctx["code"]

        if not img_path or not os.path.exists(img_path):
            return None

        self.log.emit(f"🔍 [槽位 {slot_no}/{slot_total}] 正在审核 [{proj}] {code} ...", "blue")

        runtime_profiles = get_runtime_api_profiles(self.ai_config)
        primary_profile = runtime_profiles[0] if runtime_profiles else build_legacy_api_profile(self.ai_config)
        api_base = primary_profile.get("api_base", "https://api.openai.com/v1")
        model = primary_profile.get("api_model", "gpt-4o-mini")
        max_retries = max(1, int(self.ai_config.get("api_max_retries", 3)))
        b64_url = self._encode_review_image(img_path)

        def _make_request(current_model, current_key):
            wait_for_api_slot(
                api_base, current_key,
                get_effective_api_interval(api_base, self.ai_config, 0),
                stop_check=lambda: self._stop,
                log_fn=self.log.emit,
                prefix=f"⏳ {code}: "
            )
            if is_google_native_api(api_base):
                g_mdl = pick_google_model(current_model, "gemini-1.5-flash")
                h = {"Content-Type": "application/json"}
                b64_raw = b64_url.split(",")[-1]
                p = {
                    "contents": [{
                        "parts": [
                            {"text": f"System: {ctx['system_prompt']}\nUser: {ctx['review_user_text']}"},
                            {"inline_data": {"mime_type": "image/jpeg", "data": b64_raw}}
                        ]
                    }],
                    "generationConfig": {"temperature": 0.1, "maxOutputTokens": 500},
                    "safetySettings": [
                        {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                        {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                        {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                        {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
                    ]
                }

                tried_models = []
                google_candidates = [g_mdl]
                if g_mdl == "gemini-2.5-flash":
                    google_candidates.extend(["gemini-2.0-flash", "gemini-1.5-flash"])

                res = None
                for candidate_model in google_candidates:
                    if candidate_model in tried_models:
                        continue
                    tried_models.append(candidate_model)
                    url = f"{api_base}/v1beta/models/{candidate_model}:generateContent?key={current_key}"
                    self.log.emit(f"🔍 {code}: 正在向 Google 发送图片数据 (模型: {candidate_model})...", "gray")
                    r = requests.post(url, json=p, headers=h, timeout=60, verify=HTTP_VERIFY)
                    self.log.emit(f"📡 {code}: Google 已响应，状态码: {r.status_code}", "gray")

                    if r.status_code == 403:
                        err_detail = extract_api_error_message(r)
                        self.log.emit(f"⚠️ {code}: Google 403 - {err_detail[:160]}", "orange")
                        low_detail = err_detail.lower()
                        # 这类 403 通常与“项目/账号权限”有关，换模型无效，直接判定该 Key 不可用
                        perm_denied_like = any(x in low_detail for x in [
                            "denied access", "permission_denied", "api not enabled",
                            "has not been used", "not have permission", "project has been denied"
                        ])
                        if perm_denied_like:
                            raise RuntimeError(f"GOOGLE_KEY_DENIED: {err_detail}")
                        quota_like = any(x in low_detail for x in ["quota", "resource_exhausted", "rate limit", "billing", "daily limit"])
                        model_like = any(x in low_detail for x in ["permission", "forbidden", "not found", "unsupported", "not available", "denied", "model"])
                        if quota_like:
                            raise RuntimeError(f"Google 403 配额/项目限制: {err_detail}")
                        if model_like and candidate_model != google_candidates[-1]:
                            self.log.emit(f"🔄 {code}: 当前模型疑似不可用，自动尝试备选模型...", "orange")
                            continue
                        raise RuntimeError(f"Google 403 权限限制: {err_detail}")

                    r.raise_for_status()
                    res = r.json()
                    break

                if res is None:
                    raise RuntimeError("Google 未返回有效结果")

                candidates = res.get("candidates", [])
                if not candidates:
                    feedback = res.get("promptFeedback", {})
                    reason = feedback.get("blockReason", "未知原因")
                    raise RuntimeError(f"Google 安全策略拦截: {reason}")

                content_obj = candidates[0].get("content", {})
                parts = content_obj.get("parts", [])
                if not parts:
                    finish_reason = candidates[0].get("finishReason", "Unknown")
                    raise RuntimeError(f"Google 未返回内容, 原因: {finish_reason}")

                text = parts[0].get("text", "").strip()
                return _json.dumps({"choices": [{"message": {"content": text}}]})

            payload = {
                "model": current_model,
                "messages": [
                    {"role": "system", "content": ctx["system_prompt"]},
                    {"role": "user", "content": [
                        {"type": "text", "text": ctx["review_user_text"]},
                        {"type": "image_url", "image_url": {"url": b64_url}}
                    ]}
                ],
                "max_tokens": 500,
                "temperature": 0.1
            }
            headers = {
                "Authorization": f"Bearer {current_key}",
                "Content-Type": "application/json",
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            }
            self.log.emit(f"🔍 {code}: 正在向服务器发送图片数据 (模型: {current_model})...", "gray")
            r = requests.post(f"{api_base}/chat/completions", json=payload, headers=headers, timeout=60, verify=HTTP_VERIFY)
            self.log.emit(f"📡 {code}: 服务器已响应，状态码: {r.status_code}", "gray")
            r.raise_for_status()
            return r.text

        def _extract_json_obj(text):
            """
            尽量从模型返回文本中提取 JSON 对象（兼容代码块/包裹引号/额外解释文字）。
            """
            # 统一走宽松解析，兼容更多模型输出（含自然语言、类 Python dict 等）
            if text is None:
                return None
            t = str(text).strip()
            if not t:
                return None
            # 有些模型会把 JSON 当成字符串再包一层引号
            if (t.startswith('"') and t.endswith('"')) or (t.startswith("'") and t.endswith("'")):
                try:
                    t = _json.loads(t)
                except Exception:
                    t = t.strip('"').strip("'").strip()
            return parse_json_loose(t)

        raw_res = None
        success_flag = False
        last_exception = None
        rate_limited_keys = set()
        blocked_keys = set()

        for attempt_round in range(max_retries):
            if self._stop or success_flag:
                break

            attempted_this_round = 0
            for active_key in ordered_keys:
                if self._stop or success_flag:
                    break
                if active_key in blocked_keys:
                    continue
                if active_key in rate_limited_keys and len(rate_limited_keys) < len(ordered_keys):
                    continue

                attempted_this_round += 1
                try:
                    raw_res = _make_request(model, active_key)
                    success_flag = True
                    break
                except Exception as re:
                    last_exception = re
                    err_msg = str(re)
                    if "GOOGLE_KEY_DENIED" in err_msg:
                        blocked_keys.add(active_key)
                        self.log.emit(f"⛔ {code}: 当前 Key 无权限（已跳过该 Key）", "orange")
                        continue
                    if "429" in err_msg:
                        cooldown = (2 ** attempt_round) * (20 if is_google_native_api(api_base) else 3)
                        apply_api_cooldown(api_base, active_key, cooldown)
                        rate_limited_keys.add(active_key)
                        remaining = len([k for k in ordered_keys if k not in rate_limited_keys])
                        self.log.emit(f"⚠️ {code}: 当前 Key 触发 429，冷却 {cooldown}s；剩余可切换 Key: {remaining} 个。", "orange")
                        continue
                    if "503" in err_msg:
                        cooldown = (2 ** attempt_round) * 3
                        apply_api_cooldown(api_base, active_key, cooldown)
                        self.log.emit(f"⚠️ {code}: 503 服务繁忙，冷却 {cooldown}s 后重试...", "orange")
                        continue

                    if "安全策略拦截" in err_msg:
                        self.log.emit(f"🚫 {code}: {err_msg}", "orange")
                        return None

                    if "400" in err_msg and model == "gpt-4o-mini":
                        try:
                            raw_res = _make_request("gpt-4o", active_key)
                            success_flag = True
                            break
                        except Exception as upgrade_err:
                            last_exception = upgrade_err
                    continue

            if success_flag:
                break

            if attempted_this_round == 0 and rate_limited_keys and attempt_round < max_retries - 1:
                rate_limited_keys.clear()

        if not success_flag:
            err_msg = str(last_exception) if last_exception else "未知错误"
            if "401" in err_msg:
                self.log.emit(f"❌ {code} 审核失败: 401 Unauthorized (API Key 无效)。", "red")
            elif "403" in err_msg:
                self.log.emit(f"❌ {code} 审核失败: 403 Forbidden ({err_msg[:180]})", "red")
            elif "404" in err_msg:
                self.log.emit(f"❌ {code} 审核失败: 404 Not Found (模型或地址错误)。", "red")
            elif "400" in err_msg:
                self.log.emit(f"❌ {code} 审核失败: 400 Bad Request (模型不支持或参数错误)。", "red")
            else:
                self.log.emit(f"❌ {code} 审核失败: {err_msg[:120]}", "red")
            return None

        if not raw_res:
            return None

        try:
            if self.ai_config.get("debug_mode"):
                self.log.emit(f"🛠️ [DEBUG] 收到原始返回: {raw_res[:500]}...", "gray")
            res_json = _json.loads(raw_res)
            response_text = res_json["choices"][0]["message"]["content"].strip()
            data = _extract_json_obj(response_text)
            if not isinstance(data, dict):
                raise RuntimeError("模型未返回可解析的 JSON 结果")
            analysis_txt = str(data.get("analysis", "") or "").strip()
            suggestion_txt = str(data.get("suggestion", "") or "").strip()
            conf_txt = data.get("confidence", "")
            if conf_txt != "" and conf_txt is not None:
                try:
                    analysis_txt = (analysis_txt + f"（置信度: {float(conf_txt):.2f}）").strip()
                except Exception:
                    analysis_txt = (analysis_txt + f"（置信度: {conf_txt}）").strip()
            ai_note = analysis_txt or str(data.get("reason", "") or "").strip()
            category = infer_review_category(data)
            state_label = review_state_label_from_category(category)
            note = build_review_note(category, data.get("reason", ""), ai_note)
            if state_label == REVIEW_STATE_PASS:
                self.log.emit(f"✅ {code}: 审核通过", "green")
            elif state_label == REVIEW_STATE_COPY_MISMATCH:
                self.log.emit(f"🟣 {code}: {note}", "#7c3aed")
            elif state_label == REVIEW_STATE_VISUAL_ISSUE:
                self.log.emit(f"🟠 {code}: {note}", "orange")
            else:
                self.log.emit(f"🟡 {code}: {note}", "#ca8a04")
            return {
                "key": (proj, row_idx),
                "value": {"state": state_label, "note": note, "detail": response_text, "analysis": ai_note, "suggestion": suggestion_txt, "category": category}
            }
        except Exception as parse_err:
            self.log.emit(f"❌ {code} 审核结果解析失败: {str(parse_err)[:120]}", "red")
            # 解析失败也给用户看原始输出，便于你判断模型到底在说什么
            return {
                "key": (proj, row_idx),
                "value": {"state": REVIEW_STATE_MANUAL, "note": "需人工复核：AI 返回无法解析", "detail": response_text if 'response_text' in locals() else "", "analysis": "", "suggestion": "", "category": "manual_review"}
            }

    def run(self):
        from concurrent.futures import ThreadPoolExecutor, as_completed

        try:
            if not self.tasks:
                return

            rules_str = "\n".join([f"- {r['keyword']}: {r.get('desc', '无详细说明')}" for r in self.rules if r.get("keyword")])

            runtime_profiles = get_runtime_api_profiles(self.ai_config)
            primary_profile = runtime_profiles[0] if runtime_profiles else build_legacy_api_profile(self.ai_config)
            api_keys = list(primary_profile.get("api_keys", []))
            if not api_keys:
                fallback_key = os.environ.get("OPENAI_API_KEY", "")
                api_keys = [fallback_key] if fallback_key else []

            if not api_keys:
                self.error.emit("图片审核中断：未配置任何 API Key")
                return

            valid_tasks = [t for t in self.tasks if t.get("img") and os.path.exists(t.get("img"))]
            if not valid_tasks:
                return

            total = len(valid_tasks)
            api_base = primary_profile.get("api_base", "https://api.openai.com/v1")
            is_google_direct = is_google_native_api(api_base)
            configured_max = int(self.ai_config.get("api_max_concurrency", 0) or 0)
            # Google 原生接口对并发非常敏感（通常是项目级限流），这里强制串行更稳定。
            if is_google_direct:
                max_workers = 1
                self.log.emit("🚦 检测到 Google 原生接口：为避免 429/503，图片审核将强制串行执行（多 Key 仅用于失败切换）。", "gray")
            else:
                if configured_max > 0:
                    max_workers = max(1, min(total, len(api_keys), configured_max))
                else:
                    max_workers = min(total, len(api_keys))
                self.log.emit(f"🚀 AI 图片审核已切换为并行模式：{max_workers} 个并发槽，任务会均匀分配到不同 API Key。", "blue")

            review_results = {}
            completed_count = 0
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_to_task = {}
                for idx, task in enumerate(valid_tasks):
                    slot_no = (idx % max_workers) + 1
                    ordered_keys = api_keys[idx % len(api_keys):] + api_keys[:idx % len(api_keys)]
                    future = executor.submit(self._review_one_task, task, rules_str, ordered_keys, slot_no, max_workers)
                    future_to_task[future] = task

                for future in as_completed(future_to_task):
                    if self._stop:
                        break
                    try:
                        res = future.result()
                        if res and res.get("key"):
                            review_results[res["key"]] = res["value"]
                    except Exception as worker_err:
                        self.log.emit(f"❌ 并行审核子任务异常: {str(worker_err)[:120]}", "red")
                    finally:
                        completed_count += 1
                        self.progress.emit(int(completed_count / total * 100))

            self.result.emit(review_results)
        except Exception as e:
            err_msg = traceback.format_exc()
            self.error.emit(f"并行图片审核线程异常: {e}\n{err_msg}")
# ─────────────────────────────────────────────
#  ParallelAiAuditThread：多 Key 并行 AI 语义审核引擎
# ─────────────────────────────────────────────
class ParallelAiAuditThread(QThread):
    progress = pyqtSignal(int)
    log      = pyqtSignal(str, str)
    result   = pyqtSignal(dict)  # {(proj, row): {"state": str, "note": str}}
    finished = pyqtSignal()

    def __init__(self, match_results, project_name, ai_config):
        super().__init__()
        self.match_results = match_results # {img_path: {row, cn, en, ...}}
        self.project_name = project_name
        self.ai_config = ai_config
        self._stop = False

    def stop(self): self._stop = True

    def run(self):
        from concurrent.futures import ThreadPoolExecutor, as_completed
        import json as _json
        
        try:
            items = []
            for img_path, info in self.match_results.items():
                items.append({
                    "img": img_path,
                    "row": info.get("row"),
                    "cn": info.get("cn", ""),
                    "en": info.get("en", "")
                })
            
            if not items:
                self.finished.emit()
                return

            runtime_profiles = get_runtime_api_profiles(self.ai_config)
            primary_profile = runtime_profiles[0] if runtime_profiles else build_legacy_api_profile(self.ai_config)
            api_keys = list(primary_profile.get("api_keys", []))
            
            if not api_keys:
                self.log.emit("❌ 审核中断：未配置任何 API Key", "red")
                self.finished.emit()
                return

            api_base = primary_profile.get("api_base", "https://api.openai.com/v1")
            is_google_direct = is_google_native_api(api_base)
            # Google 原生接口在免费配额下非常容易被并发打爆，这里强制串行。
            configured_max = int(self.ai_config.get("api_max_concurrency", 0) or 0)
            if is_google_direct:
                max_workers = 1
            elif configured_max > 0:
                max_workers = max(1, min(len(api_keys), configured_max))
            else:
                max_workers = len(api_keys)
            self.log.emit(f"🚀 启动语义审核：使用 {max_workers} 个并发线程", "blue")
            if is_google_direct and len(items) > 1:
                self.log.emit("🚦 已为 Google 原生接口启用串行审核，避免并发触发 429。", "gray")
            
            final_audit_results = {}
            completed_count = 0
            total = len(items)

            def audit_task(item, key):
                if self._stop: return None
                img_path = item["img"]
                cn_text = item["cn"]
                
                # 构造语义校验 Prompt
                system_prompt = (
                    "你是一个资深的视觉导演。请判断给出的图片与文案在【语义、情绪、氛围】上是否匹配。\n"
                    "特别注意：如果文案是悲伤/沉重的，而图片是欢快/明亮的，则属于不匹配。\n"
                    "请严格按 JSON 返回：{\"match\": true/false, \"reason\": \"如果不匹配，请说明原因；如果匹配，留空\"}"
                )
                user_prompt = f"文案内容：{cn_text}\n请审核图片是否符合该文案的情绪和语义。"
                
                try:
                    # 借用 AiImageMatchThread 的编码逻辑
                    b64_url = AiImageMatchThread._encode_image(img_path)
                    b64_raw = b64_url.split(",")[-1]
                    
                    api_base = primary_profile.get("api_base", "https://api.openai.com/v1")
                    model = primary_profile.get("api_model", "gemini-2.5-flash")
                    max_retries = max(1, int(self.ai_config.get("api_max_retries", 3)))
                    
                    if is_google_native_api(api_base):
                        # Google 协议
                        g_mdl = pick_google_model(model, "gemini-2.5-flash")
                        p = {
                            "contents": [{"parts": [
                                {"text": f"System: {system_prompt}\nUser: {user_prompt}"},
                                {"inline_data": {"mime_type": "image/jpeg", "data": b64_raw}}
                            ]}],
                            "generationConfig": {"temperature": 0, "maxOutputTokens": 200}
                        }
                        res_text = ""
                        last_error = None
                        for attempt in range(max_retries):
                            wait_for_api_slot(
                                api_base, key,
                                get_effective_api_interval(api_base, self.ai_config, 0),
                                stop_check=lambda: self._stop,
                                log_fn=self.log.emit,
                                prefix="⏳ "
                            )
                            url = f"{api_base}/v1beta/models/{g_mdl}:generateContent?key={key}"
                            r = requests.post(url, json=p, timeout=45, verify=HTTP_VERIFY)
                            if r.status_code == 429:
                                cooldown = parse_retry_after_seconds(r, (2 ** attempt) * 8)
                                apply_api_cooldown(api_base, key, cooldown)
                                last_error = RuntimeError(f"Google 审核触发 429，冷却 {cooldown:.0f}s")
                                continue
                            r.raise_for_status()
                            res_json = r.json()
                            candidates = res_json.get("candidates", [])
                            if candidates and "content" in candidates[0] and "parts" in candidates[0]["content"]:
                                res_text = candidates[0]["content"]["parts"][0].get("text", "").strip()
                                break
                            finish_reason = candidates[0].get("finishReason", "Unknown") if candidates else "No candidates"
                            last_error = RuntimeError(f"Google 审核未返回内容: {finish_reason}")
                        if not res_text and last_error:
                            raise last_error
                    else:
                        # OpenAI 协议
                        headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
                        p = {
                            "model": model,
                            "messages": [
                                {"role": "system", "content": system_prompt},
                                {"role": "user", "content": [
                                    {"type": "text", "text": user_prompt},
                                    {"type": "image_url", "image_url": {"url": b64_url}}
                                ]}
                            ],
                            "temperature": 0
                        }
                        r = requests.post(f"{api_base}/chat/completions", json=p, headers=headers, timeout=45, verify=HTTP_VERIFY)
                        r.raise_for_status()
                        res_text = r.json()["choices"][0]["message"]["content"].strip()
                    
                    # 解析 JSON
                    import re as _re
                    m = _re.search(r'\{.*\}', res_text, _re.DOTALL)
                    if m:
                        data = _json.loads(m.group())
                        return {"row": item["row"], "match": data.get("match"), "reason": data.get("reason")}
                except Exception as e:
                    return {"row": item["row"], "error": str(e)}
                return None

            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                future_to_item = {}
                for i, item in enumerate(items):
                    # 轮询分配 Key
                    assigned_key = api_keys[i % len(api_keys)]
                    future = executor.submit(audit_task, item, assigned_key)
                    future_to_item[future] = item
                
                for future in as_completed(future_to_item):
                    if self._stop: break
                    res = future.result()
                    if res:
                        row = res["row"]
                        if "error" in res:
                            self.log.emit(f"⚠️ 第 {row+1} 行审核出错: {res['error'][:50]}", "orange")
                        else:
                            if res["match"] is False:
                                note = f"语义不匹配: {res.get('reason', '原因未说明')}"
                                final_audit_results[row] = {"state": "⚠️ 语义不符", "note": note}
                                self.log.emit(f"❌ 第 {row+1} 行: {note}", "red")
                            else:
                                final_audit_results[row] = {"state": "✅ 语义匹配", "note": "AI语义审核通过"}
                                self.log.emit(f"✅ 第 {row+1} 行: 语义匹配通过", "green")
                    
                    completed_count += 1
                    self.progress.emit(int(completed_count / total * 100))
            
            self.result.emit(final_audit_results)
        except Exception as e:
            self.log.emit(f"❌ 并行审核引擎异常: {e}", "red")
        finally:
            self.finished.emit()

            # 错误由已发出的信号交给界面线程处理，不能在工作线程创建弹窗。

# ─────────────────────────────────────────────
#  AiImageMatchThread：AI 智能图文匹配后台线程
# ─────────────────────────────────────────────
class AiChatThread(QThread):
    """通用 AI 对话线程，支持多 Key 轮询与 429 绕过"""
    log_signal = pyqtSignal(str, str)
    answer_signal = pyqtSignal(str)
    partial_signal = pyqtSignal(str)
    finished_signal = pyqtSignal(bool, str)

    def __init__(self, history, ai_config, system_prompt="你是一个专业、可靠、简洁的 AI 助手。", local_engine=None, image_paths=None):
        super().__init__()
        self.history = history or []
        self.ai_config = ai_config
        self.system_prompt = system_prompt or "你是一个专业、可靠、简洁的 AI 助手。"
        self.local_engine = local_engine
        # 本地 VL 模型需要显式传入图片路径，否则“看不到图”，会表现得像每轮都在开新话题
        self.image_paths = [p for p in (image_paths or []) if p and os.path.exists(p)]
        self._stop = False

    def stop(self):
        self._stop = True

    def _extract_google_stream_text(self, payload):
        text_parts = []
        if isinstance(payload, list):
            for item in payload:
                text = self._extract_google_stream_text(item)
                if text:
                    text_parts.append(text)
            return "".join(text_parts)
        if not isinstance(payload, dict):
            return ""
        for cand in payload.get("candidates", []) or []:
            content = cand.get("content", {})
            for part in content.get("parts", []) or []:
                txt = part.get("text")
                if txt:
                    text_parts.append(str(txt))
        return "".join(text_parts)

    def _stream_openai_response(self, url, headers, payload):
        payload = dict(payload or {})
        payload["stream"] = True
        with requests.post(url, json=payload, headers=headers, timeout=180, verify=HTTP_VERIFY, stream=True) as r:
            if r.status_code == 429:
                raise RuntimeError(f"429: {extract_api_error_message(r)}")
            r.raise_for_status()
            r.encoding = "utf-8"
            full_answer = ""
            for raw_line in r.iter_lines(decode_unicode=True):
                if self._stop:
                    return full_answer, True
                if not raw_line:
                    continue
                line = fix_mojibake_text(raw_line).strip()
                if not line.startswith("data:"):
                    continue
                data_str = line[5:].strip()
                if data_str == "[DONE]":
                    break
                try:
                    data = json.loads(data_str)
                except Exception:
                    continue
                delta = ""
                choices = data.get("choices") or []
                if choices:
                    delta_obj = choices[0].get("delta") or {}
                    delta = delta_obj.get("content", "")
                    if isinstance(delta, list):
                        delta = "".join(
                            str(item.get("text", "")) if isinstance(item, dict) else str(item)
                            for item in delta
                        )
                if delta:
                    delta = fix_mojibake_text(delta)
                    full_answer += delta
                    self.partial_signal.emit(full_answer)
            return full_answer, False

    def _stream_google_response(self, api_base, model, key, payload):
        g_mdl = pick_google_model(model, "gemini-1.5-flash")
        url = f"{api_base}/v1beta/models/{g_mdl}:streamGenerateContent?alt=sse&key={key}"
        with requests.post(url, json=payload, timeout=180, verify=HTTP_VERIFY, stream=True) as r:
            if r.status_code == 404:
                raise RuntimeError(f"404: 模型 {g_mdl} 不支持流式输出")
            if r.status_code == 429:
                raise RuntimeError(f"429: {extract_api_error_message(r)}")
            r.raise_for_status()
            r.encoding = "utf-8"
            full_answer = ""
            for raw_line in r.iter_lines(decode_unicode=True):
                if self._stop:
                    return full_answer, True
                if not raw_line:
                    continue
                line = fix_mojibake_text(raw_line).strip()
                if not line.startswith("data:"):
                    continue
                data_str = line[5:].strip()
                if data_str == "[DONE]":
                    break
                try:
                    payload_obj = json.loads(data_str)
                except Exception:
                    continue
                chunk = self._extract_google_stream_text(payload_obj)
                if chunk:
                    chunk = fix_mojibake_text(chunk)
                    full_answer += chunk
                    self.partial_signal.emit(full_answer)
            return full_answer, False

    def run(self):
        import requests, json, time
        mode = str(self.ai_config.get("mode", "api") or "api").lower()
        if mode == "local":
            if not self.local_engine:
                self.finished_signal.emit(False, "错误：当前已切换到本地模型，但本地模型还没有加载完成。")
                return
            try:
                answer = self.local_engine.chat(self.history, self.system_prompt, image_paths=self.image_paths)
                if self._stop:
                    if answer:
                        self.answer_signal.emit(answer)
                    self.finished_signal.emit(False, "__STOPPED__")
                    return
                answer = str(answer or "").strip()
                if not answer:
                    raise RuntimeError("本地模型返回内容为空")
                self.partial_signal.emit(answer)
                self.answer_signal.emit(answer)
                self.finished_signal.emit(True, "对话完成")
                return
            except Exception as e:
                self.finished_signal.emit(False, f"本地模型调用失败: {e}")
                return
        profiles = get_runtime_api_profiles(self.ai_config)
        if not profiles:
            self.finished_signal.emit(False, "错误：当前使用来源没有可用的 API Key")
            return

        max_retries = max(1, int(self.ai_config.get("api_max_retries", 3)))
        
        last_error = "未知错误"
        success = False
        final_answer = ""
        api_messages = [{"role": "system", "content": self.system_prompt}]
        google_contents = []
        if self.system_prompt:
            google_contents.extend([
                {"role": "user", "parts": [{"text": f"系统要求：{self.system_prompt}"}]},
                {"role": "model", "parts": [{"text": "好的，我会严格遵守这些要求。"}]}
            ])
        for msg in self.history:
            role = msg.get("role", "user")
            text = msg.get("content", "")
            if isinstance(text, list):
                text = " ".join(
                    part.get("text", "") if isinstance(part, dict) else str(part)
                    for part in text
                )
            elif isinstance(text, dict):
                text = text.get("text", "")
            else:
                text = str(text)
            text = text.strip()
            if not text:
                continue
            api_messages.append({"role": role, "content": text})
            google_contents.append({
                "role": "model" if role == "assistant" else "user",
                "parts": [{"text": text}]
            })

        for p_idx, profile in enumerate(profiles):
            if self._stop or success:
                break
            api_base = profile.get("api_base", "") or "https://api.openai.com/v1"
            model = profile.get("api_model", "gpt-4o-mini")
            api_keys = profile.get("api_keys", [])
            provider_name = profile.get("name", f"API-{p_idx+1}")
            self.log_signal.emit(f"🌐 正在尝试 API 节点 [{provider_name}] ...", "blue")
            for k_idx, key in enumerate(api_keys):
                if self._stop or success:
                    break
                strategy_label = "随机" if get_api_pool_strategy(self.ai_config) == "random" else "顺序"
                self.log_signal.emit(f"🤖 节点 [{provider_name}] 正在按{strategy_label}策略尝试第 {k_idx+1} 个 Key ...", "blue")
                for attempt in range(max_retries):
                    if self._stop:
                        break
                    try:
                        wait_for_api_slot(
                            api_base, key,
                            get_effective_api_interval(api_base, self.ai_config, 5),
                            stop_check=lambda: self._stop,
                            log_fn=self.log_signal.emit,
                            prefix="⏳ "
                        )
                        if is_google_native_api(api_base):
                            g_mdl = pick_google_model(model, "gemini-1.5-flash")
                            url = f"{api_base}/v1beta/models/{g_mdl}:generateContent?key={key}"
                            payload = {
                                "contents": google_contents or [{"role": "user", "parts": [{"text": "你好"}]}],
                                "generationConfig": {"maxOutputTokens": 2048},
                                "safetySettings": [
                                    {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                                    {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"}
                                ]
                            }
                        else:
                            url = f"{api_base}/chat/completions"
                            headers = {"Authorization": f"Bearer {key}", "Content-Type": "application/json"}
                            payload = {"model": model, "messages": api_messages}

                        answer = ""
                        stopped = False
                        if is_google_native_api(api_base):
                            try:
                                answer, stopped = self._stream_google_response(api_base, model, key, payload)
                            except Exception as stream_e:
                                self.log_signal.emit(f"⚠️ 流式输出不可用，自动回退普通回复: {stream_e}", "orange")
                                g_mdl = pick_google_model(model, "gemini-1.5-flash")
                                url = f"{api_base}/v1beta/models/{g_mdl}:generateContent?key={key}"
                                r = requests.post(url, json=payload, timeout=60, verify=HTTP_VERIFY)
                                if r.status_code == 429:
                                    cooldown = parse_retry_after_seconds(r, (2 ** attempt) * 20)
                                    apply_api_cooldown(api_base, key, cooldown)
                                    err_detail = extract_api_error_message(r)
                                    last_error = f"节点 [{provider_name}] Key-{k_idx+1} 触发 429，冷却 {cooldown:.0f}s，原因: {err_detail[:120]}"
                                    if attempt < max_retries - 1:
                                        self.log_signal.emit(f"⚠️ {last_error}，正在重试...", "orange")
                                        continue
                                    self.log_signal.emit(f"⚠️ {last_error}，切换下一个 Key...", "orange")
                                    break
                                if r.status_code == 404:
                                    fallbacks = ["gemini-2.0-flash", "gemini-pro"]
                                    for f_mdl in fallbacks:
                                        if f_mdl == g_mdl:
                                            continue
                                        self.log_signal.emit(f"🔄 模型 {g_mdl} 不可用，尝试备选 {f_mdl}...", "orange")
                                        f_url = f"{api_base}/v1beta/models/{f_mdl}:generateContent?key={key}"
                                        r = requests.post(f_url, json=payload, timeout=60, verify=HTTP_VERIFY)
                                        if r.status_code == 200:
                                            break
                                r.raise_for_status()
                                res_data = r.json()
                                if "candidates" in res_data and res_data["candidates"]:
                                    answer = fix_mojibake_text(res_data["candidates"][0]["content"]["parts"][0]["text"])
                                    self.partial_signal.emit(answer)
                        else:
                            try:
                                answer, stopped = self._stream_openai_response(url, headers, payload)
                            except Exception as stream_e:
                                self.log_signal.emit(f"⚠️ 流式输出不可用，自动回退普通回复: {stream_e}", "orange")
                                r = requests.post(url, json=payload, headers=headers, timeout=60, verify=HTTP_VERIFY)
                                if r.status_code == 429:
                                    cooldown = parse_retry_after_seconds(r, (2 ** attempt) * 3)
                                    apply_api_cooldown(api_base, key, cooldown)
                                    err_detail = extract_api_error_message(r)
                                    last_error = f"节点 [{provider_name}] Key-{k_idx+1} 触发 429，冷却 {cooldown:.0f}s，原因: {err_detail[:120]}"
                                    if attempt < max_retries - 1:
                                        self.log_signal.emit(f"⚠️ {last_error}，正在重试...", "orange")
                                        continue
                                    self.log_signal.emit(f"⚠️ {last_error}，切换下一个 Key...", "orange")
                                    break
                                r.raise_for_status()
                                res_data = r.json()
                                answer = fix_mojibake_text(res_data["choices"][0]["message"]["content"])
                                self.partial_signal.emit(answer)

                        if stopped or self._stop:
                            if answer:
                                self.answer_signal.emit(answer)
                                self.finished_signal.emit(False, "__STOPPED__")
                            else:
                                self.finished_signal.emit(False, "__STOPPED_EMPTY__")
                            return

                        if answer:
                            final_answer = answer
                            self.answer_signal.emit(answer)
                            success = True
                            break
                        raise RuntimeError("API 返回内容为空")
                    except Exception as e:
                        last_error = str(e)
                        if attempt < max_retries - 1:
                            self.log_signal.emit(f"⚠️ 节点 [{provider_name}] Key-{k_idx+1} 调用失败，立即重试: {e}", "orange")
                            continue
                        self.log_signal.emit(f"❌ 节点 [{provider_name}] Key-{k_idx+1} 调用失败: {e}", "red")

        if self._stop and not success:
            self.finished_signal.emit(False, "__STOPPED__")
        elif success:
            self.finished_signal.emit(True, "对话完成")
        else:
            self.finished_signal.emit(False, f"所有 API 节点均调用失败: {last_error}")

class AiImageMatchThread(QThread):
    """
    后台线程：调用 AI（远程 API 或 本地引擎），分析一批图片与一批文案的最佳匹配关系。
    """
    progress  = pyqtSignal(int)          # 0-100
    log       = pyqtSignal(str, str)     # (消息, 颜色)
    result    = pyqtSignal(dict)         # {img_path: {"row": row_index, "score": float, "reason": str}}
    error     = pyqtSignal(str)          # 错误信息

    def __init__(self, image_paths, scripts, api_key, api_base, model="gpt-4.1-mini", engine_mode="api", local_engine=None, api_interval=5, max_retries=3, api_keys=None,
                 clip_model_name="OFA-Sys/chinese-clip-vit-large-patch14", clip_use_gpu=True):
        super().__init__()
        self.image_paths  = image_paths
        self.scripts      = scripts
        self.api_key      = api_key
        self.api_base     = api_base.rstrip("/") if api_base else ""
        self.model        = model
        self.engine_mode  = engine_mode
        self.local_engine = local_engine
        self.api_interval = api_interval   # 兼容保留：仅在真实 429 冷却链路中参考
        self.max_retries  = max_retries    # 遇到 429 时的最大重试次数
        self._stop        = False
        self.api_keys     = api_keys or ([api_key] if api_key else [])
        # 视觉模型不应直接从目录顺序抽图。先由 CLIP 在完整素材池中初筛，
        # 再把少量最相关候选交给视觉模型逐图核验。
        self.clip_model_name = str(clip_model_name or "OFA-Sys/chinese-clip-vit-large-patch14")
        self.clip_use_gpu = bool(clip_use_gpu)

    def stop(self):
        self._stop = True

    def _suggest_local_candidate_limit(self):
        limit = 5
        model_name = str(self.model or "").lower()
        try:
            import torch
            if torch.cuda.is_available():
                total_gb = torch.cuda.get_device_properties(torch.cuda.current_device()).total_memory / 1024**3
                if total_gb <= 12.5:
                    limit = 2
                elif total_gb <= 16.5:
                    limit = 3
        except Exception:
            pass
        if "qwen2.5-vl-3b" in model_name or "qwen2_5_vl" in model_name:
            limit = min(limit, 2)
        return max(1, int(limit))

    @staticmethod
    def _encode_image(path):
        """将图片压缩为轻量 JPEG data URL，避免一次传入大图造成卡顿和内存飙升。"""
        try:
            from PIL import Image
            with load_material_image(path) as img:
                if img.mode in ("RGBA", "P", "LA"):
                    img = img.convert("RGB")
                # 极致优化：将图片缩小到 384px，质量降至 60，大幅减少传输体积
                img.thumbnail((384, 384), Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.ANTIALIAS)
                buf = io.BytesIO()
                img.save(buf, format="JPEG", quality=60, optimize=True)
                data = base64.b64encode(buf.getvalue()).decode("utf-8")
                return f"data:image/jpeg;base64,{data}"
        except Exception as exc:
            # 不能把 HEIC/RAW 等原始字节伪装为 JPEG 发给视觉接口。
            raise RuntimeError(f'视觉匹配图片转换失败：{exc}') from exc

    def _rank_visual_candidates(self, available_images, content, remark, limit):
        """CLIP 只负责召回候选；不以文件排序决定哪些图片有资格被视觉模型检查。"""
        try:
            import numpy as np
            from PIL import Image as PILImage

            directive = ClipFastMatchThread._parse_remark_image_directives(remark, available_images)
            include = set(directive.get('include', set()) or set())
            exclude = set(directive.get('exclude', set()) or set())
            source_indices = include if include else set(range(len(available_images)))
            allowed = [path for index, path in enumerate(available_images) if index in source_indices and index not in exclude]
            if not allowed:
                return []
            # 点名文件名不是视觉语义；视觉模型只用“必须侧面”等剩余要求判定。
            visual_remark = str(directive.get('visual_remark', '') or '').strip()
            if include and not visual_remark:
                return allowed[:max(1, int(limit))]

            model = ClipFastMatchThread._load_clip_model(
                self.clip_model_name, self.clip_use_gpu,
                lambda message, color="black": self.log.emit(message, color)
            )
            missing = [path for path in allowed if path not in ClipFastMatchThread._img_feature_cache]
            if missing:
                self.log.emit(f"   🔎 CLIP 初筛：正在编码 {len(missing)} 张新图片…", "gray")
                valid_paths, images = [], []
                for path in missing:
                    try:
                        with load_material_image(path) as source:
                            image = source.convert("RGB")
                            image.thumbnail((336, 336))
                            images.append(image.copy())
                            valid_paths.append(path)
                    except Exception as exc:
                        self.log.emit(f"   ⚠️ 初筛跳过无法读取的图片：{os.path.basename(path)} ({exc})", "orange")
                if images:
                    vectors = model.encode(images, batch_size=16, show_progress_bar=False, convert_to_numpy=True)
                    for path, vector in zip(valid_paths, vectors):
                        ClipFastMatchThread._img_feature_cache[path] = vector

            valid_paths = [path for path in allowed if path in ClipFastMatchThread._img_feature_cache]
            if not valid_paths:
                return list(allowed[:limit])
            vectors = np.asarray([ClipFastMatchThread._img_feature_cache[path] for path in valid_paths], dtype=np.float32)
            vectors /= (np.linalg.norm(vectors, axis=1, keepdims=True) + 1e-8)
            candidate_limit = max(1, int(limit))
            if visual_remark:
                # 备注先决定“哪些图有资格入选”，文案只在这些优先候选中决定
                # 最终画面。与此同时保留少量纯文案候选，供视觉模型在备注根本
                # 无法满足时回退，避免因此整行空白。
                requirement = ClipFastMatchThread._build_requirement_prompt('', visual_remark)
                remark_vector = model.encode([visual_remark], convert_to_numpy=True)[0]
                intent_vector = model.encode([requirement], convert_to_numpy=True)[0]
                content_vector = model.encode([content], convert_to_numpy=True)[0] if content else None
                def _norm(item): return item / (np.linalg.norm(item) + 1e-8)
                requirement_scores = np.maximum(vectors @ _norm(remark_vector), vectors @ _norm(intent_vector))
                content_scores = vectors @ _norm(content_vector) if content_vector is not None else requirement_scores
                requirement_count = min(candidate_limit, max(1, (candidate_limit + 1) // 2))
                requirement_order = np.argsort(-requirement_scores, kind="mergesort")[:requirement_count]
                # 文案回退候选与备注候选去重；顺序保留“备注在前、文案回退在后”。
                ranked_indices = [int(index) for index in requirement_order]
                for index in np.argsort(-content_scores, kind="mergesort"):
                    index = int(index)
                    if index not in ranked_indices:
                        ranked_indices.append(index)
                    if len(ranked_indices) >= candidate_limit:
                        break
                ranked = [valid_paths[index] for index in ranked_indices]
                self.log.emit(
                    f"   🔎 备注优先召回 {min(requirement_count, len(ranked))} 张，另保留 {max(0, len(ranked) - requirement_count)} 张文案回退候选，交由视觉模型核验。",
                    "gray"
                )
                return ranked
            else:
                query = model.encode([content], convert_to_numpy=True)[0]
                scores = vectors @ (query / (np.linalg.norm(query) + 1e-8))
            # mergesort 保持输入路径的稳定顺序，用于同分情况下的可复现结果。
            order = np.argsort(-scores, kind="mergesort")[:candidate_limit]
            ranked = [valid_paths[int(index)] for index in order]
            self.log.emit(f"   🔎 已从完整图片池召回 {len(ranked)} 张候选，交由视觉模型复核。", "gray")
            return ranked
        except Exception as exc:
            self.log.emit(f"   ⚠️ CLIP 初筛不可用，临时改用目录候选：{exc}", "orange")
            return list(available_images[:max(1, int(limit))])

    @staticmethod
    def _parse_visual_choice(response_text, candidate_count, has_requirement):
        """兼容 JSON 与旧视觉模型仅返回数字的格式。"""
        text = str(response_text or "").strip()
        choice = None
        meets_requirement = True
        try:
            json_match = re.search(r"\{.*?\}", text, re.S)
            payload = json.loads(json_match.group(0) if json_match else text)
            choice = int(payload.get("choice", payload.get("index", -1)))
            if has_requirement and "meets_requirement" in payload:
                meets_requirement = bool(payload.get("meets_requirement"))
        except Exception:
            number = re.search(r"(?<!\d)(\d+)(?!\d)", text)
            choice = int(number.group(1)) if number else None
            # 兼容旧模型，但明确的“未满足/none”仍应否决本次分配。
            if has_requirement and re.search(r"(?:false|no|none|不满足|未满足|没有符合)", text, re.I):
                meets_requirement = False
        if choice is None or choice < 0 or choice >= candidate_count:
            return None, False if has_requirement else True
        return choice, meets_requirement

    def run(self):
        try:
            total_scripts = len(self.scripts)
            total_images = len(self.image_paths)
            if total_images == 0:
                self.error.emit("没有可处理的图片池")
                return
            if total_scripts == 0:
                self.error.emit("表格中没有文案内容，请先填写中文或英文文案")
                return

            match_result = {}  # {img_path: row_index}
            used_images = set() # 已被选中的图片，避免重复使用
            
            self.log.emit(f"🚀 启动智能池化筛选：从 {total_images} 张图片中为 {total_scripts} 条文案挑选最佳匹配", "blue")

            # 统一优先级：手工锁定已在启动线程前从图片池排除；这里必须先完成
            # 所有填写了备注的行，才允许普通文案消耗剩余图片。这样 API、本地
            # 视觉和 CLIP 三种引擎不会再因表格行顺序而抢走备注目标图。
            remark_scripts = [script for script in self.scripts if str(script.get('remark', '') or '').strip()]
            plain_scripts = [script for script in self.scripts if not str(script.get('remark', '') or '').strip()]
            ordered_scripts = remark_scripts + plain_scripts
            if remark_scripts:
                self.log.emit(
                    f"🔒 已按优先级安排：先处理 {len(remark_scripts)} 条备注要求，再处理 {len(plain_scripts)} 条普通文案。",
                    "blue"
                )

            # 策略：备注行先占用符合要求的图片；再为普通文案挑选剩余图片。
            for idx, script in enumerate(ordered_scripts):
                if self._stop:
                    self.log.emit("⚠️ 已手动停止", "orange")
                    break

                row_idx = script["row"]
                cn_content = script.get("cn", "").strip()
                en_content = script.get("en", "").strip()
                content = (cn_content or en_content)
                remark = script.get("remark", "").strip()
                
                log_msg = f"正在为第 {row_idx+1} 行挑选图片: {content[:20]}..."
                if remark: log_msg += f" (备注: {remark[:15]})"
                self.log.emit(log_msg, "blue")

                try:
                    available_images = [p for p in self.image_paths if p not in used_images]
                    allowed_scope_dirs = [os.path.normcase(os.path.abspath(path)) for path in script.get('allowed_image_dirs', []) or [] if os.path.isdir(path)]
                    if allowed_scope_dirs:
                        scoped_images = []
                        for image_path in available_images:
                            image_absolute = os.path.normcase(os.path.abspath(image_path))
                            try:
                                in_scope = any(os.path.commonpath([image_absolute, directory]) == directory for directory in allowed_scope_dirs)
                            except ValueError:
                                in_scope = False
                            if in_scope:
                                scoped_images.append(image_path)
                        available_images = scoped_images
                    if not available_images:
                        source_label = "指定目录中没有剩余图片" if allowed_scope_dirs else "图片池已耗尽"
                        self.log.emit(f"⚠️ {source_label}，第 {row_idx+1} 行跳过", "orange")
                        continue

                    # ── 模式分支：API 驱动 vs CLIP 驱动 ──
                    if self.engine_mode == "api":
                        # 远程 API 模式逻辑
                        if not self.api_key:
                            self.log.emit("❌ 错误: 未配置 API Key，无法使用远程模式", "red")
                            break
                        
                        self.log.emit(f"   🌐 正在通过 API 请求视觉模型 ({self.model}) 进行智能匹配...", "black")
                        # 先从完整素材池按语义召回，再让视觉模型核验；绝不能按目录排序截取前几张。
                        candidate_batch = self._rank_visual_candidates(available_images, content, remark, limit=5)
                        
                        import json as _json
                        import requests
                        
                        messages = [
                            {"role": "system", "content": "你是一个图片筛选专家。请从给出的多张图片中，选出最符合文案描述的一张。"},
                            {"role": "user", "content": [
                            {"type": "text", "text": (
                                f"文案内容: {content}\n备注要求: {remark or '无'}\n\n"
                                f"请逐张看图后选择最合适的候选。若备注要求能被满足，必须先只在满足备注的图片中，"
                                f"按文案内容选择最合适的一张并返回 meets_requirement=true；若候选都无法满足备注，"
                                f"改按文案内容选择最合适的一张作为回退并返回 meets_requirement=false。"
                                f"仅返回 JSON：{{\"choice\":序号或-1, \"meets_requirement\":true或false}}。"
                            )}
                            ]}
                        ]
                        
                        for i, img_p in enumerate(candidate_batch):
                            b64 = self._encode_image(img_p)
                            messages[1]["content"].append({"type": "text", "text": f"图片 {i}:"})
                            messages[1]["content"].append({"type": "image_url", "image_url": {"url": b64}})

                        headers = {
                            "Authorization": f"Bearer {self.api_key}",
                            "Content-Type": "application/json",
                            "HTTP-Referer": "https://github.com/manus-ai/ai-assistant-pro",
                            "X-Title": "智能素材工作站"
                        }
                        payload = {
                            "model": self.model, 
                            "messages": messages, 
                            "max_tokens": 64, 
                            "temperature": 0,
                            "stream": False  # 强制非流式，提高兼容性
                        }

                        # ── 适配 Google Gemini 原生协议 ──
                        is_google = is_google_native_api(self.api_base)
                        
                        if is_google:
                            # Google 官方要求格式: /v1beta/models/{model}:generateContent
                            google_model = pick_google_model(self.model, "gemini-2.5-flash")
                            # 韩国直连优化：使用 URL 参数传递 Key，这是最稳健的方式
                            google_url = f"{self.api_base}/v1beta/models/{google_model}:generateContent?key={self.api_key}"
                            google_headers = {"Content-Type": "application/json"}
                            
                            # 转换 Payload 为 Google 格式
                            prompt_text = (
                                "System: 你是严谨的图片视觉核验员。\n"
                                f"User: 文案内容: {content}\n备注要求: {remark or '无'}\n\n"
                                "请逐张看图后选择最合适的候选。备注要求能满足时，先限定在满足备注的图片中再按文案选择，"
                                "并返回 meets_requirement=true；若候选都不满足备注，改按文案选择回退图，"
                                "并返回 meets_requirement=false。"
                                "仅返回 JSON：{\"choice\":序号或-1, \"meets_requirement\":true或false}。"
                            )
                            parts = [{"text": prompt_text}]
                            for i, img_p in enumerate(candidate_batch):
                                b64_raw = self._encode_image(img_p).split(",")[-1]
                                parts.append({"text": f"图片 {i}:"})
                                parts.append({"inline_data": {"mime_type": "image/jpeg", "data": b64_raw}})
                            google_payload = {"contents": [{"parts": parts}], "generationConfig": {"temperature": 0, "maxOutputTokens": 64}}
                        
                        # ── 带 429 指数退避重试的 API 请求 ──────────────────────
                        
                        # ── 增强型多 Key 轮询与重试机制 ──────────────────────
                        res_text = None
                        current_keys = self.api_keys if hasattr(self, "api_keys") and self.api_keys else [self.api_key]
                        
                        success_flag = False
                        for k_idx, active_key in enumerate(current_keys):
                            if self._stop or success_flag: break
                            
                            # 如果有多个 Key，打印切换日志
                            if len(current_keys) > 1:
                                self.log.emit(f"   🔑 正在尝试第 {k_idx+1}/{len(current_keys)} 个 API Key...", "gray")
                            
                            # 更新 Google URL (如果是 Google 模式)
                            if is_google:
                                google_url = f"{self.api_base}/v1beta/models/{google_model}:generateContent?key={active_key}"
                            
                            for _attempt in range(self.max_retries):
                                if self._stop: break
                                try:
                                    wait_for_api_slot(
                                        self.api_base, active_key,
                                        get_effective_api_interval(self.api_base, {"api_interval": self.api_interval}, self.api_interval),
                                        stop_check=lambda: self._stop,
                                        log_fn=self.log.emit,
                                        prefix="   ⏳ "
                                    )
                                    if is_google:
                                        r = requests.post(google_url, json=google_payload, headers=google_headers, timeout=60, verify=HTTP_VERIFY)
                                    else:
                                        # 更新 OpenAI 认证头
                                        headers["Authorization"] = f"Bearer {active_key}"
                                        r = requests.post(f"{self.api_base}/chat/completions", json=payload, headers=headers, timeout=60, verify=HTTP_VERIFY)
                                    
                                    # 处理频率限制或认证失败
                                    if r.status_code in [429, 401, 403]:
                                        err_msg = r.json().get("error", {}).get("message", r.text[:100])
                                        if r.status_code == 429:
                                            cooldown = parse_retry_after_seconds(r, (2 ** _attempt) * (20 if is_google else 3))
                                            apply_api_cooldown(self.api_base, active_key, cooldown)
                                            self.log.emit(f"   ⚠️ Key-{k_idx+1} 频率受限 (429): {extract_api_error_message(r)[:120]}", "orange")
                                            self.log.emit(f"   ⚠️ Key-{k_idx+1} 冷却 {cooldown:.0f}s 后重试/切换...", "orange")
                                        else:
                                            self.log.emit(f"   ❌ Key-{k_idx+1} 认证失败 (401/403)，准备切换下一个...", "red")
                                            break # 跳出重试循环，尝试下一个 Key
                                            
                                        continue
                                    
                                    r.raise_for_status()
                                    res_json = r.json()
                                    if is_google:
                                        # 健壮解析 Google 响应
                                        try:
                                            candidates = res_json.get("candidates", [])
                                            if not candidates:
                                                # 检查是否被安全过滤
                                                prompt_feedback = res_json.get("promptFeedback", {})
                                                if prompt_feedback:
                                                    reason = prompt_feedback.get("blockReason", "Unknown")
                                                    raise RuntimeError(f"Google 安全过滤拦截: {reason}")
                                                raise KeyError("candidates")
                                            
                                            content_obj = candidates[0].get("content", {})
                                            parts = content_obj.get("parts", [])
                                            if not parts:
                                                # 检查 finishReason
                                                finish_reason = candidates[0].get("finishReason", "Unknown")
                                                raise RuntimeError(f"Google 未返回内容, 原因: {finish_reason}")
                                            
                                            res_text = parts[0].get("text", "").strip()
                                        except (KeyError, IndexError) as parse_err:
                                            # 打印原始 JSON 辅助调试
                                            self.log.emit(f"   ⚠️ 解析 Google 返回出错: {parse_err}. 原始数据: {str(res_json)[:200]}...", "gray")
                                            raise parse_err
                                    else:
                                        res_text = res_json["choices"][0]["message"]["content"].strip()
                                    
                                    success_flag = True
                                    break # 成功拿到结果，跳出重试循环
                                except Exception as _api_err:
                                    if _attempt < self.max_retries - 1:
                                        self.log.emit(f"   ⚠️ Key-{k_idx+1} 发生异常，立即重试: {_api_err}", "orange")
                                        continue
                                    else:
                                        self.log.emit(f"   ⚠️ Key-{k_idx+1} 发生异常: {_api_err}", "orange")
                                        break # 尝试下一个 Key
                            
                            if success_flag: break # 成功拿到结果，跳出 Key 轮询循环

                        if not res_text:
                            raise RuntimeError(f"所有 {len(current_keys)} 个 API Key 均尝试失败，请检查配置。")


                        best_batch_idx, meets_requirement = self._parse_visual_choice(res_text, len(candidate_batch), bool(remark))
                        if best_batch_idx is None:
                            self.log.emit(
                                f"⚠️ 第 {row_idx+1} 行没有有效视觉候选，保留为空待人工确认。",
                                "orange"
                            )
                            self.progress.emit(int((idx + 1) / total_scripts * 100))
                            continue
                        selected_img_path = candidate_batch[best_batch_idx]
                        final_score = 95.0
                        reason = (f"API({self.model}) 视觉识别匹配"
                                  if meets_requirement else f"API({self.model}) 备注未满足，按文案视觉回退")
                        if not meets_requirement:
                            self.log.emit(
                                f"⚠️ 第 {row_idx+1} 行未找到满足备注的图片，已按文案视觉选择回退图：{os.path.basename(selected_img_path)}",
                                "orange"
                            )

                        # ── 写入匹配结果（API 模式专属，CLIP 分支有自己的写入逻辑）──
                        match_result[selected_img_path] = {
                            "row":   row_idx,
                            "score": final_score,
                            "reason": reason,
                            "cn":    cn_content,
                            "en":    en_content
                        }
                        used_images.add(selected_img_path)
                        self.log.emit(
                            f"✅ 匹配成功: 第 {row_idx+1} 行 -> "
                            f"{os.path.basename(selected_img_path)} (得分: {final_score})", "green"
                        )

                        # 不再做预防性固定等待；只有真实触发 429 后才进入冷却。
                        # API 模式已完成本行匹配，跳过下方 CLIP 专属代码块
                        self.progress.emit(int((idx + 1) / total_scripts * 100))
                        continue
                    elif self.engine_mode == "local":
                        if not self.local_engine:
                            self.error.emit("本地模型未加载，无法执行图文匹配")
                            return
                        if not getattr(self.local_engine, "supports_vision", False):
                            self.error.emit("当前本地模型是纯文字模型，不支持图文匹配。请切换到视觉模型，或改用远程 API / CLIP 极速模式。")
                            return

                        self.log.emit(f"   🖼️ 正在通过本地视觉模型 ({self.model}) 进行智能匹配...", "black")
                        candidate_limit = self._suggest_local_candidate_limit()
                        candidate_batch = self._rank_visual_candidates(available_images, content, remark, limit=candidate_limit)
                        self.log.emit(f"   🧠 本地显存保护已启用：本轮候选图 {len(candidate_batch)} 张，低显存推理模式 ON", "gray")
                        choice_prompt = (
                            f"文案内容: {content}\n"
                            f"备注要求: {remark}\n\n"
                            f"请逐张看图后选择最符合文案的一张。若备注要求能满足，必须先只在满足备注的图片中"
                            f"按文案选择并返回 meets_requirement=true；候选均不满足备注时，改按文案选择回退图，"
                            f"并返回 meets_requirement=false。"
                            f"只返回 JSON：{{\"choice\":序号或-1, \"meets_requirement\":true或false}}。"
                        )
                        res_text = self.local_engine.chat(
                            history=[{"role": "user", "content": choice_prompt}],
                            system_prompt="你是一个图片筛选专家。请从给出的多张图片中，选出最符合文案描述的一张。",
                            image_paths=candidate_batch,
                            max_new_tokens=64,
                            do_sample=False,
                            temperature=0.0,
                            prefer_low_memory=True,
                            cleanup_cache=True
                        )
                        best_batch_idx, meets_requirement = self._parse_visual_choice(res_text, len(candidate_batch), bool(remark))
                        if best_batch_idx is None:
                            self.log.emit(
                                f"⚠️ 第 {row_idx+1} 行没有有效视觉候选，保留为空待人工确认。",
                                "orange"
                            )
                            self.progress.emit(int((idx + 1) / total_scripts * 100))
                            continue
                        selected_img_path = candidate_batch[best_batch_idx]
                        final_score = 95.0
                        reason = (f"本地视觉模型({self.model}) 图文匹配"
                                  if meets_requirement else f"本地视觉模型({self.model}) 备注未满足，按文案视觉回退")
                        if not meets_requirement:
                            self.log.emit(
                                f"⚠️ 第 {row_idx+1} 行未找到满足备注的图片，已按文案视觉选择回退图：{os.path.basename(selected_img_path)}",
                                "orange"
                            )
                        match_result[selected_img_path] = {
                            "row":   row_idx,
                            "score": final_score,
                            "reason": reason,
                            "cn":    cn_content,
                            "en":    en_content
                        }
                        used_images.add(selected_img_path)
                        self.log.emit(
                            f"✅ 匹配成功: 第 {row_idx+1} 行 -> "
                            f"{os.path.basename(selected_img_path)} (得分: {final_score})", "green"
                        )
                        self.progress.emit(int((idx + 1) / total_scripts * 100))
                        continue
                    else:
                        # 原有的 CLIP 驱动逻辑
                        clip_model = ClipFastMatchThread._load_clip_model("OFA-Sys/chinese-clip-vit-large-patch14", True, lambda m, c="black": None)
                    
                    # --- 深度语义情感增强逻辑 ---
                    # 1. 直接情绪词
                    sad_words = ["悲伤", "难过", "忧郁", "痛苦", "伤心", "哭泣", "哀悼", "失落", "沮丧", "sad", "unhappy", "crying", "sorrow"]
                    happy_words = ["开心", "快乐", "兴奋", "喜悦", "高兴", "微笑", "大笑", "happy", "joy", "excited", "smile", "laugh"]
                    
                    # 2. 隐含情感的场景词
                    sad_scenes = ["灾难", "事故", "去世", "葬礼", "离别", "分手", "失败", "破产", "生病", "孤独", "寒冷", "废墟", "灾民", "乞讨"]
                    happy_scenes = ["祝福", "婚礼", "庆典", "成功", "奖杯", "团聚", "过年", "生日", "礼物", "聚会", "阳光", "花朵", "旅游", "中奖"]
                    
                    sentiment_prompt = ""
                    lower_text = (content + " " + remark).lower()
                    
                    # 综合判断
                    if any(k in lower_text for k in sad_words) or any(k in lower_text for k in sad_scenes):
                        sentiment_prompt = "，表情悲伤，忧郁，哭泣，深沉，sad expression, sorrowful face, depressed atmosphere"
                    elif any(k in lower_text for k in happy_words) or any(k in lower_text for k in happy_scenes):
                        sentiment_prompt = "，表情开心，快乐，大笑，阳光，happy expression, smiling face, joyful atmosphere"
                    
                    # 融合文案、备注和情感引导词
                    enhanced_content = content + sentiment_prompt
                    
                    # 提取文案特征
                    text_feat = clip_model.encode([enhanced_content], convert_to_numpy=True)[0]
                    if remark:
                        remark_feat = clip_model.encode([remark + sentiment_prompt], convert_to_numpy=True)[0]
                        # 优化：针对“图片比对视频”场景，大幅提升文案(视觉)权重，降低备注(音频/辅助)权重
                        # 将原来的 文案 0.3 + 备注 0.7 改为 文案 0.8 + 备注 0.2
                        text_feat = text_feat * 0.8 + remark_feat * 0.2
                    
                    # 计算所有可用图片的相似度
                    img_feats = []
                    valid_paths = []
                    
                    # 优先从缓存获取特征
                    for p in available_images:
                        if p in ClipFastMatchThread._img_feature_cache:
                            img_feats.append(ClipFastMatchThread._img_feature_cache[p])
                            valid_paths.append(p)
                    
                    # 如果缓存中没有，现场提取（仅针对未缓存的图片）
                    missing_paths = [p for p in available_images if p not in ClipFastMatchThread._img_feature_cache]
                    if missing_paths:
                        self.log.emit(f"   ⏳ 正在提取 {len(missing_paths)} 张新图片的特征...", "black")
                        from PIL import Image as _PILImage
                        for p in missing_paths:
                            try:
                                img = load_material_image(p)
                                img.thumbnail((336, 336))
                                feat = clip_model.encode([img], convert_to_numpy=True)[0]
                                ClipFastMatchThread._img_feature_cache[p] = feat
                                img_feats.append(feat)
                                valid_paths.append(p)
                            except: continue

                    if not img_feats:
                        self.log.emit(f"❌ 第 {row_idx+1} 行：无法获取图片特征", "red")
                        continue

                    # 计算余弦相似度并找到最佳匹配
                    import numpy as np
                    img_matrix = np.array(img_feats)
                    # 归一化特征向量
                    img_matrix = img_matrix / (np.linalg.norm(img_matrix, axis=1, keepdims=True) + 1e-8)
                    text_feat = text_feat / (np.linalg.norm(text_feat) + 1e-8)
                    
                    sims = img_matrix @ text_feat

                    # 如果备注命中了路径/文件夹名，则优先从这些图片中选
                    path_bonus, hit_count = ClipFastMatchThread._build_path_priority_bonus(remark, valid_paths)
                    if hit_count > 0:
                        self.log.emit(f"   📁 第 {row_idx+1} 行备注命中 {hit_count} 张路径/文件夹，优先从这些图片中选择", "gray")
                        sims = sims + path_bonus
                    best_idx = np.argmax(sims)
                    best_sim = sims[best_idx]
                    selected_img_path = valid_paths[best_idx]
                    
                    # 保存结果
                    final_score = round(float(best_sim) * 100, 1)
                    match_result[selected_img_path] = {
                        "row": row_idx,
                        "score": final_score,
                        "reason": f"CLIP全局最优(相似度:{best_sim:.3f}{' / 备注路径优先' if hit_count > 0 and path_bonus[best_idx] > 0 else ''})",
                        "cn": cn_content,
                        "en": en_content
                    }
                    used_images.add(selected_img_path)
                    self.log.emit(f"✅ 匹配成功: 第 {row_idx+1} 行 -> {os.path.basename(selected_img_path)} (得分: {final_score})", "green")

                except Exception as e:
                    self.log.emit(f"❌ 挑选出错 (第 {row_idx+1} 行): {str(e)}", "red")

                self.progress.emit(int((idx + 1) / total_scripts * 100))

            self.result.emit(match_result)

        except Exception as e:
            err_msg = traceback.format_exc()
            self.error.emit(f"AI 匹配线程异常: {e}\n{err_msg}")
            # 工作线程只发信号，不直接操作 Qt 界面。


# ─────────────────────────────────────────────
#  ProjectAutoMatchThread：单项目自动匹配后台线程
# ─────────────────────────────────────────────
class ProjectAutoMatchThread(QThread):
    """
    专门为流水线设计的线程类：封装了图片扫描、引擎加载、AI匹配的全流程。
    """
    progress = pyqtSignal(int)
    log      = pyqtSignal(str, str)
    result   = pyqtSignal(str, dict)  # (项目名, 结果)
    error    = pyqtSignal(str, str)   # (项目名, 错误信息)
    finished = pyqtSignal()

    def __init__(self, name, src_dir, scripts, api_key, api_base, model,
                 engine_mode="api", local_engine=None, max_scan=300, batch_size=5,
                 local_model_path=None, mmproj_path=None, clip_model_name=None, clip_use_gpu=True,
                 api_interval=5, max_retries=3, api_keys=None, ai_config=None, reuse_manifest=None,
                 excluded_image_paths=None, use_global_source_pool=True):
        super().__init__()
        self.project_name = name
        self.src_dir      = src_dir
        self.scripts      = scripts
        self.api_key      = api_key
        self.api_base     = api_base
        self.model        = model
        self.engine_mode  = engine_mode
        self.local_engine = local_engine
        self.max_scan     = max_scan
        self.batch_size   = batch_size
        self.local_model_path = local_model_path
        self.mmproj_path      = mmproj_path
        self.clip_model_name  = clip_model_name
        self.clip_use_gpu     = clip_use_gpu
        self.api_interval     = api_interval   # 传递给 AiImageMatchThread
        self.max_retries      = max_retries    # 传递给 AiImageMatchThread
        self.api_keys         = api_keys or ([api_key] if api_key else [])
        self.ai_config        = ai_config or {}
        self.reuse_manifest   = reuse_manifest if isinstance(reuse_manifest, dict) else None
        self.use_global_source_pool = bool(use_global_source_pool)
        self.excluded_image_paths = {
            os.path.normcase(os.path.abspath(str(path))) for path in (excluded_image_paths or [])
            if str(path or '').strip()
        }
        self._image_content_fingerprints = {}
        self._image_pool_signature = ''
        self._stop      = False
        self.sub_thread = None

    def stop(self):
        self._stop = True
        if self.sub_thread:
            self.sub_thread.stop()

    @staticmethod
    def _content_fingerprint(path):
        """路径可变，文件内容才是素材身份；采用完整 SHA-256 避免误复用。"""
        digest = hashlib.sha256()
        with open(path, 'rb') as source:
            while True:
                chunk = source.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)
        return digest.hexdigest()

    def _build_image_content_identity(self, image_paths):
        self.log.emit('🔐 正在核对素材内容身份（路径变化不会影响已确认的匹配结果）…', 'gray')
        pairs = []
        for index, path in enumerate(image_paths, 1):
            if self._stop:
                return [], {}
            try:
                fingerprint = self._content_fingerprint(path)
                pairs.append((fingerprint, path))
            except OSError as exc:
                self.log.emit(f'⚠️ 无法读取素材身份，仍可继续新匹配：{os.path.basename(path)} ({exc})', 'orange')
        pairs.sort(key=lambda item: (item[0], os.path.normcase(item[1])))
        fingerprint_map = {}
        for fingerprint, path in pairs:
            fingerprint_map.setdefault(fingerprint, []).append(path)
        self._image_content_fingerprints = {path: fingerprint for fingerprint, path in pairs}
        self._image_pool_signature = hashlib.sha256('\n'.join(fingerprint for fingerprint, _ in pairs).encode('ascii')).hexdigest()
        return pairs, fingerprint_map

    def _try_reuse_manifest(self, fingerprint_map):
        manifest = self.reuse_manifest or {}
        if str(manifest.get('image_pool_signature') or '') != str(self._image_pool_signature or ''):
            return None
        assignments = manifest.get('assignments')
        if not isinstance(assignments, list) or not assignments:
            return None
        expected_rows = {int(s['row']) for s in self.scripts
                         if str(s.get('cn') or s.get('en') or '').strip() or str(s.get('remark') or '').strip()}
        try:
            saved_rows = [int(item.get('row', -1)) for item in assignments]
        except (TypeError, ValueError, AttributeError):
            return None
        if set(saved_rows) != expected_rows or len(saved_rows) != len(expected_rows):
            self.log.emit('⚠️ 历史匹配结果缺项或重复，本次重新匹配，不复用不完整结果。', 'orange')
            return None
        reused, used_paths = {}, set()
        for assignment in assignments:
            fingerprint = str(assignment.get('image_fingerprint') or '')
            candidates = [path for path in fingerprint_map.get(fingerprint, []) if path not in used_paths]
            if not candidates:
                return None
            path = candidates[0]
            used_paths.add(path)
            reused[path] = {
                'row': int(assignment.get('row', -1)),
                'score': assignment.get('score', 0),
                'reason': '内容身份已确认：复用此前一致输入的匹配结果',
                'cn': assignment.get('cn', ''), 'en': assignment.get('en', ''),
                'content_fingerprint': fingerprint,
            }
        return reused

    def run(self):
        try:
            if self._stop: return
            scoped_roots = []
            for script in self.scripts:
                for directory in script.get('allowed_image_dirs', []) or []:
                    directory = normalize_user_path(directory)
                    if directory and os.path.isdir(directory):
                        scoped_roots.append(directory)
            scan_roots = []
            if self.use_global_source_pool and self.src_dir and os.path.isdir(self.src_dir):
                scan_roots.append(self.src_dir)
            scan_roots.extend(scoped_roots)
            unique_roots = []
            seen_roots = set()
            for directory in scan_roots:
                key = os.path.normcase(os.path.abspath(directory))
                if key not in seen_roots:
                    seen_roots.add(key)
                    unique_roots.append(directory)
            if not unique_roots:
                self.error.emit(self.project_name, "没有可用的素材来源目录或行内素材目录")
                return
            scope_desc = "、".join(unique_roots[:3]) + (" …" if len(unique_roots) > 3 else "")
            self.log.emit(f"📂 正在扫描候选目录: {scope_desc}", "black")
            
            # 1. 扫描图片
            valid_exts = MATERIAL_IMAGE_EXTS
            image_paths = []
            seen_images = set()
            for scan_root in unique_roots:
                for root, dirs, files in os.walk(scan_root):
                    dirs.sort(key=lambda item: str(item).casefold())
                    for f in sorted(files, key=lambda item: str(item).casefold()):
                        if f.lower().endswith(valid_exts):
                            path = os.path.normpath(os.path.join(root, f))
                            key = os.path.normcase(os.path.abspath(path))
                            if key not in seen_images:
                                seen_images.add(key)
                                image_paths.append(path)
                            if len(image_paths) >= self.max_scan:
                                break
                    if len(image_paths) >= self.max_scan:
                        break
                if len(image_paths) >= self.max_scan:
                    break
            image_paths.sort(key=lambda path: os.path.normcase(os.path.abspath(path)))
            if self.excluded_image_paths:
                before = len(image_paths)
                image_paths = [path for path in image_paths if os.path.normcase(os.path.abspath(path)) not in self.excluded_image_paths]
                excluded = before - len(image_paths)
                if excluded:
                    self.log.emit(f"🔒 已排除 {excluded} 张用户手工锁定图片；AI 只补空白图片路径。", 'blue')
            if not image_paths:
                self.error.emit(self.project_name, "可用图片均已被用户手工锁定；没有剩余图片可供自动补齐")
                return
            
            if not image_paths:
                self.error.emit(self.project_name, "目录下未找到有效图片")
                return
            
            self.log.emit(f"✅ 扫描完成，共找到 {len(image_paths)} 张图片", "green")
            if self._stop: return

            _pairs, fingerprint_map = self._build_image_content_identity(image_paths)
            if self._stop:
                return
            reused_result = self._try_reuse_manifest(fingerprint_map)
            if reused_result is not None:
                self.log.emit(f"♻️ 当前素材内容、文案、备注和模型设置均未变化；已复用 {len(reused_result)} 条已确认匹配，不重新分配。", 'green')
                self.result.emit(self.project_name, reused_result)
                return
            if self.reuse_manifest:
                self.log.emit('🔄 素材内容池已变化或历史结果不完整，将按当前输入重新匹配。', 'blue')

            # 2. 根据模式启动对应的匹配线程
            if self.engine_mode == "clip":
                self.sub_thread = ClipFastMatchThread(
                    image_paths, self.scripts, 
                    clip_model_name=self.clip_model_name or "OFA-Sys/chinese-clip-vit-large-patch14",
                    use_gpu=self.clip_use_gpu
                )
            else:
                # 传入 Key 列表以支持自动轮询
                self.sub_thread = AiImageMatchThread(
                    image_paths, self.scripts, self.api_key, self.api_base,
                    model=self.model, engine_mode=self.engine_mode, local_engine=self.local_engine,
                    api_interval=getattr(self, "api_interval", 5),
                    max_retries=getattr(self, "max_retries", 3),
                    api_keys=getattr(self, "api_keys", [self.api_key]),
                    clip_model_name=self.clip_model_name or "OFA-Sys/chinese-clip-vit-large-patch14",
                    clip_use_gpu=self.clip_use_gpu,
                )

            # 转发子线程信号
            self.sub_thread.progress.connect(self.progress.emit)
            self.sub_thread.log.connect(self.log.emit)
            
            # 阻塞等待子线程完成
            loop = QEventLoop()
            self.sub_thread.finished.connect(loop.quit)
            
            # 收集结果或错误
            match_res = None
            err_msg = None
            
            def on_res(res): nonlocal match_res; match_res = res
            def on_err(err): nonlocal err_msg; err_msg = err
            
            self.sub_thread.result.connect(on_res)
            self.sub_thread.error.connect(on_err)
            
            self.sub_thread.start()
            loop.exec()

            if self._stop: return
            
            
            if err_msg:
                self.error.emit(self.project_name, err_msg)
            elif match_res:
                # 已移除：匹配完成后自动触发 AI 语义审核（会显著拖慢“一键批量 AI 匹配”）
                # 如需审核，请在图文审核台手动点击“AI 图文审核”。

                for matched_path, info in match_res.items():
                    if isinstance(info, dict):
                        info['content_fingerprint'] = self._image_content_fingerprints.get(matched_path, '')
                self.result.emit(self.project_name, match_res)

            else:
                self.error.emit(self.project_name, "匹配任务未返回任何结果")

        except Exception as e:
            err_msg = traceback.format_exc()
            self.error.emit(self.project_name, f"流水线执行异常: {e}\n{err_msg}")
            # 工作线程只发信号，不直接操作 Qt 界面。
        finally:
            self.finished.emit()


class AiMatchDialog(QDialog):
    """
    弹出对话框：支持远程 API 模式和本地引擎加载模式。
    """
    def __init__(self, table, project_name, parent=None):
        super().__init__(parent)
        self.table = table
        self.project_name = project_name
        self.main_window = parent  # 保存父窗口引用
        self.ai_thread = None
        self.local_engine = None
        self.image_paths = []
        self.setWindowTitle(f"🧠 AI 智能池化筛选匹配 — {project_name}")
        self.setMinimumSize(720, 650)
        self.setAcceptDrops(True)
        self._init_ui()
        self._scan_local_models()
        self._load_engine_config_from_main()
        self._connect_engine_config_memory()

    def _connect_engine_config_memory(self):
        """让智能匹配对话框的引擎配置实时同步到主配置，避免每次打开都重新设置。"""
        try:
            self.engine_tabs.currentChanged.connect(lambda *_: self._sync_engine_config_to_main())
            self.api_key_input.textChanged.connect(lambda *_: self._sync_engine_config_to_main())
            self.api_base_input.textChanged.connect(lambda *_: self._sync_engine_config_to_main())
            self.model_combo.currentTextChanged.connect(lambda *_: self._sync_engine_config_to_main())
            self.local_model_combo.currentIndexChanged.connect(lambda *_: self._sync_engine_config_to_main())
            self.mmproj_combo.currentIndexChanged.connect(lambda *_: self._sync_engine_config_to_main())
        except Exception:
            pass

    def _load_engine_config_from_main(self):
        """从主界面配置恢复默认智能引擎设置。"""
        try:
            cfg = getattr(self.main_window, "ai_config", {})
            mode = cfg.get("mode", "clip")
            if mode == "local": self.engine_tabs.setCurrentIndex(1)
            elif mode == "clip": self.engine_tabs.setCurrentIndex(2)
            else: self.engine_tabs.setCurrentIndex(0)
            
            self.api_key_input.setText(cfg.get("api_key", ""))
            self.api_base_input.setText(cfg.get("api_base", ""))
            self.model_combo.setCurrentText(cfg.get("api_model", "gpt-4o-mini"))
            
            l_path = cfg.get("local_model_path", "")
            if l_path:
                idx = self.local_model_combo.findData(l_path)
                if idx >= 0: self.local_model_combo.setCurrentIndex(idx)
            m_path = cfg.get("mmproj_path", "")
            if m_path:
                idx = self.mmproj_combo.findData(m_path)
                if idx >= 0: self.mmproj_combo.setCurrentIndex(idx)
            clip_model = cfg.get("clip_model", "")
            if clip_model:
                self.clip_model_combo.setCurrentText(clip_model)
            self.clip_use_gpu_check.setChecked(bool(cfg.get("clip_use_gpu", True)))
            # 本地引擎实例仍然尝试从主窗口获取（如果已加载）
            self.local_engine = getattr(self.main_window, "local_engine", None)
        except Exception as e:
            write_debug(f"Load AiMatch engine config error: {e}")

    def _sync_engine_config_to_main(self):
        """把匹配窗口里的引擎配置同步回主界面配置。"""
        try:
            idx = self.engine_tabs.currentIndex()
            mode = "api"
            if idx == 1: mode = "local"
            elif idx == 2: mode = "clip"
            
            self.main_window.ai_config.update({
                "mode": mode,
                "api_key": self.api_key_input.text(),
                "api_base": self.api_base_input.text(),
                "api_model": self.model_combo.currentText(),
                "local_model_path": self.local_model_combo.currentData() or "",
                "mmproj_path": self.mmproj_combo.currentData() or "",
                "clip_model": self.clip_model_combo.currentText().strip() or "OFA-Sys/chinese-clip-vit-large-patch14",
                "clip_use_gpu": bool(self.clip_use_gpu_check.isChecked())
            })
            if hasattr(self.main_window, "trigger_save"):
                self.main_window.trigger_save()
        except Exception as e:
            write_debug(f"Sync AiMatch engine config error: {e}")

