class NoteWidget(QFrame):
    mode_changed = pyqtSignal(bool); data_changed = pyqtSignal()
    def __init__(self, parent=None):
        super().__init__(parent); self.is_floating = False; self.dragging = False; self.drag_pos = QPoint(); self.project_data = {}
        # 便签作为右侧可伸缩面板：不要让内部表格/工具栏的 sizeHint 把宽度锁死。
        # 停靠时由主窗口的分割条决定宽度；只保留足以阅读和编辑的下限。
        self.setMinimumWidth(180)
        self.setMinimumHeight(220)
        self.setMaximumWidth(16777215)
        self.setSizePolicy(_Expanding, _Expanding)
        self.init_ui()


    
    def setup_universal_auto_tab(self):
        """万能自动化执行 Tab：专业树形任务表格，支持原生复选框、项目代码列与逐行窗口。"""
