class ParameterWheelBlocker(QObject):
    """关闭参数控件的滚轮改值，同时覆盖运行时新增的控件。"""
    CONTROL_TYPES = (QComboBox, QSpinBox, QDoubleSpinBox, QSlider)

    def __init__(self, root):
        super().__init__(root)
        self.root = root

    def protect(self, widget):
        """给当前树及其后续新增的子控件都装上同一个过滤器。"""
        if not isinstance(widget, QWidget):
            return
        widgets = [widget] + widget.findChildren(QWidget)
        for child in widgets:
            if child.property("parameter_wheel_guard"):
                continue
            child.setProperty("parameter_wheel_guard", True)
            child.installEventFilter(self)

    @staticmethod
    def _is_parameter_control(widget):
        """输入框内部的行编辑器也要沿父级找到所属数值控件。"""
        current = widget
        while isinstance(current, QWidget):
            if isinstance(current, ParameterWheelBlocker.CONTROL_TYPES):
                return True
            current = current.parentWidget()
        return False

    def eventFilter(self, watched, event):
        wheel_type = QEvent.Type.Wheel if PYQT_VERSION == 6 else QEvent.Wheel
        child_added_type = QEvent.Type.ChildAdded if PYQT_VERSION == 6 else QEvent.ChildAdded
        if event.type() == child_added_type:
            # 裁剪任务表、字幕面板等可能在打开后才创建编辑器；不能只保护初始化时已有控件。
            self.protect(event.child())
            return False
        if event.type() == wheel_type and self._is_parameter_control(watched):
            event.ignore()
            return True
        return False


def disable_parameter_mouse_wheel(root):
    """为页面所有下拉、数值框和滑块关闭滚轮改值，不影响点击或手动输入。"""
    if root is None:
        return
    blocker = ParameterWheelBlocker(root)
    blocker.protect(root)
    # 保留强引用；否则 Python 回收过滤器后，Qt 不会再拦截滚轮。
    root._parameter_wheel_blocker = blocker


class SeedVCCudaStatusBadge(QWidget):
    """轻量 GPU 状态徽章：仅用 QPainter 绘制，不加载图片文件或额外图形引擎。"""
    DEFAULT_VISUAL_CONFIG = {
        'colors': ['#22d3ee', '#84cc16', '#dff7ff', '#a78bfa', '#d7c51b'],
        'speeds': [1.0, -1.0, 1.0, -1.0],
    }
    _visual_config = dict(DEFAULT_VISUAL_CONFIG)

    @classmethod
    def visual_config(cls):
        raw = dict(getattr(cls, '_visual_config', {}) or {})
        default = cls.DEFAULT_VISUAL_CONFIG
        colors = list(raw.get('colors', default['colors']) or [])[:5]
        speeds = list(raw.get('speeds', default['speeds']) or [])[:4]
        colors += default['colors'][len(colors):]
        speeds += default['speeds'][len(speeds):]
        clean_colors = [QColor(str(color)).name() if QColor(str(color)).isValid() else default['colors'][index] for index, color in enumerate(colors)]
        clean_speeds = []
        for index, value in enumerate(speeds):
            try: speed = max(-3.0, min(3.0, float(value)))
            except (TypeError, ValueError): speed = default['speeds'][index]
            clean_speeds.append(speed if abs(speed) >= 0.05 else (0.05 if default['speeds'][index] > 0 else -0.05))
        return {'colors': clean_colors, 'speeds': clean_speeds}

    @classmethod
    def set_visual_config(cls, config=None):
        cls._visual_config = dict(config or {})
        normalized = cls.visual_config()
        cls._visual_config = {'colors': list(normalized['colors']), 'speeds': list(normalized['speeds'])}
        app = QApplication.instance()
        if app is not None:
            for widget in app.allWidgets():
                if isinstance(widget, cls):
                    widget._layer_speeds = list(normalized['speeds'])
                    widget.update()

    def __init__(self, parent=None):
        super().__init__(parent)
        self._cuda_ready = False
        self._checked = False
        self._indeterminate = False
        self._processing = False
        self._phase = 0.0
        self._particles = []
        self._particle_spawn_credit = 0.0
        self._last_animation_tick = time.monotonic()
        # 各层交替顺/逆时针，保留原设计“齿轮互相咬合”的动感；数值固定而非随机，
        # 所以智能匹配、人声替换和任务中心会呈现完全相同的转速与方向。
        self._layer_speeds = list(self.visual_config()['speeds'])
        self._timer = QTimer(self)
        self._timer.setInterval(45)
        self._timer.timeout.connect(self._advance)
        # 最外圈含描边必须完全落在控件内；旧版中心 y=24、半径 27，
        # 上下各越界约 3px，Windows 布局会把圆环裁掉。
        self.setFixedSize(158, 64)
        self.setToolTip('CUDA 状态：尚未检测。点击“诊断 / 修复 CUDA PyTorch”进行只读检查。')

    def reset_state(self, tooltip='CUDA 状态：尚未检测。请先执行 GPU 诊断。'):
        """恢复未检测外观，供多个功能页共用同一套状态徽章。"""
        self._timer.stop()
        self._cuda_ready = False
        self._checked = False
        self._indeterminate = False
        self._processing = False
        self._phase = 0.0
        self._particles = []
        self._particle_spawn_credit = 0.0
        self._last_animation_tick = time.monotonic()
        self.setToolTip(str(tooltip or 'CUDA 状态：尚未检测。'))
        self.update()

    def set_cuda_state(self, ready, detail=''):
        self._checked, self._cuda_ready = True, bool(ready)
        self._indeterminate = (not self._cuda_ready) and ('诊断超时' in str(detail or '') or '检测超时' in str(detail or ''))
        self._last_animation_tick = time.monotonic()
        status = 'GPU CUDA 可用' if self._cuda_ready else ('GPU CUDA 检测超时' if self._indeterminate else 'GPU CUDA 不可用')
        self.setToolTip(status + ('\n' + str(detail) if detail else ''))
        if self._cuda_ready:
            if not self._timer.isActive(): self._timer.start()
        else:
            self._timer.stop()
            self._particles = []
            self._particle_spawn_credit = 0.0
        self.update()

    def set_processing(self, active):
        """仅在实际 GPU 推理期间进入高速动画，避免把“可用”误解为“正在运行”。"""
        self._processing = bool(active) and self._cuda_ready
        self._last_animation_tick = time.monotonic()
        self._timer.setInterval(16 if self._processing else 45)
        if self._cuda_ready and not self._timer.isActive():
            self._timer.start()
        self.update()

    def _advance(self):
        # 以真实经过时间推进而不是“每次定时器固定跳多少度”。后者在 Windows
        # 调度偶发延迟、以及 360° 回绕时会出现明显卡顿/倒跳错觉。高速状态控制在
        # 每帧约 20° 左右，仍有风火轮速度，却不会越过人眼连续旋转的采样极限。
        now = time.monotonic()
        elapsed = now - self._last_animation_tick
        self._last_animation_tick = now
        if elapsed <= 0.0 or elapsed > 0.12:
            # 窗口被遮挡、系统休眠或调试停顿后不补算一大段角度，恢复时保持平滑。
            self.update()
            return
        degrees_per_second = 1152.0 if self._processing else 48.0  # 3.2 / 0.13 圈每秒
        self._phase += elapsed * degrees_per_second
        self._advance_particles(elapsed)
        # 极长时间运行时仅做很少发生的数值整理，保留完整圈数的等效角度，
        # 不在日常动画中执行 0~360 的硬回绕。
        if abs(self._phase) > 1_000_000.0:
            self._phase = math.fmod(self._phase, 360.0)
        self.update()

    def _advance_particles(self, elapsed):
        """高速运行时从外圈沿切线甩出方块碎片，停止后让现有碎片自然淡出。"""
        if self._processing:
            self._particle_spawn_credit += elapsed * 42.0
            spawn_count = min(3, int(self._particle_spawn_credit))
            self._particle_spawn_credit -= spawn_count
            colors = self.visual_config()['colors']
            palette = (colors[0], '#38bdf8', colors[1], colors[3], colors[2])
            direction = 1.0 if self._layer_speeds[3] >= 0 else -1.0
            for _ in range(spawn_count):
                # 主要从四块外环的运动边缘脱落，并加入轻微随机偏移避免机械重复。
                angle_deg = self._phase * self._layer_speeds[3] + random.randrange(4) * 90.0 + random.uniform(-9.0, 9.0)
                angle = math.radians(angle_deg)
                radial_speed = random.uniform(9.0, 18.0)
                tangent_speed = direction * random.uniform(11.0, 23.0)
                radius = random.uniform(22.2, 24.0)
                lifetime = random.uniform(0.30, 0.56)
                self._particles.append({
                    'x': 30.0 + math.cos(angle) * radius,
                    'y': 32.0 + math.sin(angle) * radius,
                    'vx': math.cos(angle) * radial_speed - math.sin(angle) * tangent_speed,
                    'vy': math.sin(angle) * radial_speed + math.cos(angle) * tangent_speed,
                    'life': lifetime, 'max_life': lifetime,
                    'size': random.uniform(1.9, 3.7),
                    'rotation': random.uniform(0.0, 90.0),
                    'spin': random.uniform(-420.0, 420.0),
                    'color': random.choice(palette),
                })
        alive = []
        for particle in self._particles:
            particle['life'] -= elapsed
            if particle['life'] <= 0.0:
                continue
            particle['x'] += particle['vx'] * elapsed
            particle['y'] += particle['vy'] * elapsed
            particle['rotation'] += particle['spin'] * elapsed
            alive.append(particle)
        self._particles = alive[-24:]

    def _draw_particles(self, painter):
        painter.setPen(_NoPen)
        for particle in self._particles:
            fade = max(0.0, min(1.0, particle['life'] / max(0.001, particle['max_life'])))
            color = QColor(particle['color'])
            color.setAlpha(int(220 * fade * fade))
            size = particle['size'] * (0.55 + 0.45 * fade)
            painter.save()
            painter.translate(particle['x'], particle['y'])
            painter.rotate(particle['rotation'])
            painter.setBrush(color)
            painter.drawRect(QRectF(-size / 2.0, -size / 2.0, size, size))
            painter.restore()

    @staticmethod
    def _circle(center_x, center_y, radius):
        return QRectF(center_x - radius, center_y - radius, radius * 2, radius * 2)

    def _annular_sector(self, center_x, center_y, outer_radius, inner_radius, start_angle, span_angle):
        """构造具有真实内外圆边的环形扇区，径向边保持平直，不使用圆头粗线。"""
        outer = self._circle(center_x, center_y, outer_radius)
        inner = self._circle(center_x, center_y, inner_radius)
        path = QPainterPath()
        path.arcMoveTo(outer, start_angle)
        path.arcTo(outer, start_angle, span_angle)
        path.arcTo(inner, start_angle + span_angle, -span_angle)
        path.closeSubpath()
        return path

    def _segmented_ring(self, painter, center_x, center_y, outer_radius, inner_radius, color, layer, span, base_angle=0.0, alphas=(210, 160, 195, 135)):
        """每圈严格四块；透明度不同使相邻圈压叠后保留原设计的层次。"""
        rotation = math.fmod(self._phase * self._layer_speeds[layer], 360.0) if self._cuda_ready else 0.0
        edge = QColor(color)
        edge.setAlpha(105 if self._cuda_ready else 80)
        painter.setPen(QPen(edge, 0.55))
        for index in range(4):
            fill = QColor(color)
            fill.setAlpha(int(alphas[index % len(alphas)]) if self._cuda_ready else 92)
            painter.setBrush(fill)
            start = float(base_angle) + rotation + index * 90.0
            painter.drawPath(self._annular_sector(center_x, center_y, outer_radius, inner_radius, start, span))

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing if PYQT_VERSION == 6 else QPainter.Antialiasing)
        # 图标区固定为 64×64，圆心位于正方形几何中心；所有半径均从同一圆心
        # 计算，任何 DPI 和主题下都不会被压成椭圆。
        x, y = 30.0, 32.0
        active = self._cuda_ready
        colors = self.visual_config()['colors']
        cyan = QColor(colors[0] if active else '#9ca3af')
        lime = QColor(colors[1] if active else '#9ca3af')
        blue = QColor('#38bdf8' if active else '#9ca3af')
        violet = QColor(colors[3] if active else '#9ca3af')
        dim = QColor('#0f766e' if active else '#cbd5e1')
        # 由外到内均为四块环形模块。相邻色层在半径方向略微重叠，透明区域
        # 会自然叠出深浅变化；每层又保留不同宽度的四个缺口。
        self._segmented_ring(painter, x, y, 23.5, 18.2, cyan, 3, 82.0, 3.0, (205, 142, 185, 118))
        self._segmented_ring(painter, x, y, 19.1, 13.7, lime, 2, 76.0, 18.0, (188, 225, 142, 172))
        self._segmented_ring(painter, x, y, 14.8, 10.2, QColor(colors[2] if active else '#b8c1cc'), 1, 68.0, 38.0, (220, 150, 205, 128))
        self._segmented_ring(painter, x, y, 11.1, 8.1, violet, 0, 56.0, 17.0, (205, 132, 188, 155))
        # 原设计中四个金色短块位于最内圈缺口附近，同样使用环形扇区。
        self._segmented_ring(painter, x, y, 8.9, 7.4, QColor(colors[4] if active else '#9ca3af'), 2, 17.0, 36.5, (220, 180, 215, 165))
        painter.setPen(QPen(QColor('#67e8f9' if active else '#94a3b8'), 0.8))
        painter.setBrush(_NoBrush)
        painter.drawEllipse(self._circle(x, y, 6.9))
        # 粒子最后绘制，保证刚从外圈甩出的方块不会被环形模块完全遮住。
        self._draw_particles(painter)
        painter.setPen(QColor('#0891b2' if active else '#64748b'))
        title_font = QFont(); title_font.setPointSize(9); title_font.setBold(True)
        painter.setFont(title_font)
        painter.drawText(QRect(66, 12, 88, 18), _AlignCenter, 'CUDA GPU' if self._checked else 'CUDA 待检测')
        detail_font = QFont(); detail_font.setPointSize(8)
        painter.setFont(detail_font)
        painter.setPen(QColor('#16a34a' if active else '#94a3b8'))
        painter.drawText(QRect(66, 35, 88, 16), _AlignCenter, ('极速运行中' if self._processing else '可用 · 待命') if active else ('检测超时 · 重试' if self._indeterminate else ('不可用 · CPU' if self._checked else '点击诊断')))


class SeedVCCudaDiagnosticThread(QThread):
    """后台只读诊断，状态徽章不应因检查 Torch 而卡住页面。"""
    diagnosis_ready = pyqtSignal(object)

    def __init__(self, python_path, parent=None):
        super().__init__(parent)
        self.python_path = str(python_path or '')

    @staticmethod
    def probe(python_path):
        if not os.path.isfile(python_path):
            return {'ready': False, 'summary': f'尚未找到 Seed-VC 独立环境：{python_path}'}
        probe = (
            "import json\n"
            "try:\n"
            " import torch\n"
            " ready=bool(torch.cuda.is_available())\n"
            " payload={'ready':ready,'torch':str(torch.__version__),'cuda_build':str(torch.version.cuda),'device':(torch.cuda.get_device_name(0) if ready else '')}\n"
            "except Exception as exc:\n"
            " payload={'ready':False,'error':type(exc).__name__+': '+str(exc)}\n"
            "print(json.dumps(payload, ensure_ascii=False))\n"
        )
        try:
            result = subprocess.run([python_path, '-c', probe], capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=25, **_subprocess_no_window_kwargs())
            output_lines = (result.stdout or '').strip().splitlines()
            if not output_lines:
                raise RuntimeError((result.stderr or 'PyTorch 没有返回诊断结果。').strip())
            payload = json.loads(output_lines[-1])
            ready = bool(payload.get('ready'))
            if ready:
                summary = f"PyTorch {payload.get('torch', '未知')}｜CUDA {payload.get('cuda_build', '未知')}｜显卡 {payload.get('device', '未知')}"
            else:
                summary = payload.get('error') or f"当前 PyTorch {payload.get('torch', '未知')} 未检测到可用 CUDA（构建：{payload.get('cuda_build', '无')}）。"
            return {'ready': ready, 'summary': summary}
        except subprocess.TimeoutExpired:
            return {'ready': False, 'indeterminate': True, 'summary': 'CUDA 诊断超时：Seed-VC 的 PyTorch 在 25 秒内未完成加载。此结果不是“CUDA 不可用”；请稍后重试，未执行下载或安装。'}
        except Exception as exc:
            return {'ready': False, 'summary': f'CUDA 诊断无法完成：{type(exc).__name__}: {exc}'}

    def run(self):
        self.diagnosis_ready.emit(self.probe(self.python_path))


class SeedVCCudaRepairThread(QThread):
    """CUDA migration with an isolated staging venv and CPU rollback safety."""
    log = pyqtSignal(str, str)
    completed = pyqtSignal(bool, str)

    def __init__(self, python_path, parent=None):
        super().__init__(parent)
        self.python_path = str(python_path or '')

    def run(self):
        if not os.path.isfile(self.python_path):
            self.completed.emit(False, 'Seed-VC 环境不存在；完整安装应由“安装.bat”一次完成。')
            return
        if not has_nvidia_cuda():
            self.completed.emit(False, '未检测到 NVIDIA 显卡；此电脑将继续使用已安装的 CPU PyTorch。')
            return
        try:
            seed_root = os.path.dirname(os.path.dirname(os.path.dirname(self.python_path)))
            install_seed_vc_cuda_transactional(seed_root, self.python_path, lambda line: self.log.emit(line[-700:], 'gray'))
            diagnostic = SeedVCCudaDiagnosticThread.probe(self.python_path)
            if not diagnostic.get('ready'):
                raise RuntimeError(diagnostic.get('summary', 'CUDA 验证未通过。'))
            self.completed.emit(True, 'Seed-VC CUDA PyTorch 已验证并切换完成；原 CPU 环境只会在验证成功后才被替换。')
        except Exception as exc:
            self.completed.emit(False, 'CUDA 修复失败，已保留原有 CPU 环境：' + str(exc))


class AudioTranscribeCudaDiagnosticThread(QThread):
    """后台检查智能匹配使用的 CTranslate2 / PyTorch CUDA，避免页面初始化卡顿。"""
    diagnosis_ready = pyqtSignal(object)

    def run(self):
        try:
            ready, lines = VideoCopyMatchThread.get_audio_transcribe_cuda_diagnostic()
            self.diagnosis_ready.emit({'ready': bool(ready), 'lines': list(lines or [])})
        except Exception as exc:
            self.diagnosis_ready.emit({
                'ready': False,
                'lines': [f'智能匹配 CUDA 自动检测失败：{type(exc).__name__}: {exc}'],
            })


def subtitle_generation_blocked(parent):
    """只检查真实任务生命周期，不禁用按钮、不保留容易失效的 UI 忙碌标志。"""
    if not SeedVCBatchThread.replacement_busy():
        return False
    QMessageBox.information(parent, '请等待人声替换完成',
                            '正在执行或排队进行人声替换，暂时不能生成字幕。\n'
                            '请等待人声替换完成后再点击生成；任务失败或停止后也会自动解除限制。')
    return True


class SeedVCBatchThread(QThread):
    """独立 Seed-VC 批处理器：提取音频、转换声线、合回原画面。

    不接触任何 Qt 播放器、人工对位、视频编辑或源文件。所有模型/依赖都在
    ``seed-vc/.venv`` 中运行，停止时只终止自己的子进程。
    """
    progress = pyqtSignal(int)
    log = pyqtSignal(str, str)
    finished_all = pyqtSignal()
    failed = pyqtSignal(str)
    VIDEO_EXTS = ('.mp4', '.mov', '.mkv', '.avi', '.webm', '.m4v', '.wmv', '.flv', '.ts', '.mts')
    AUDIO_EXTS = ('.mp3', '.wav', '.flac', '.m4a', '.aac', '.ogg', '.opus', '.wma', '.aiff')
    MEDIA_EXTS = VIDEO_EXTS + AUDIO_EXTS
    # 同一轮软件运行中，同一个 Seed-VC venv 的 CUDA 结果只检查一次；
    # 安装/修复完成时显式失效，避免每个队列重复启动 torch 检测。
    _cuda_probe_cache = {}
    _cuda_probe_lock = Lock()
    _replacement_workers = weakref.WeakSet()
    _replacement_lock = Lock()

    @classmethod
    def replacement_busy(cls):
        for worker in list(cls._replacement_workers):
            try:
                if worker.isRunning():
                    return True
            except RuntimeError:
                # Qt 对象已释放，不能让失效引用永久挡住字幕生成。
                continue
        return False
    QUALITY_PROFILES = {
        'quick': ('快速试听', 18, 4, '160k'),
        'balanced': ('智能平衡（推荐）', 30, 8, '256k'),
        # 档位只定义推理质量和输出码率，绝不能决定是否走歌曲/F0 模型。
        # 是否使用 F0 由 ``song_mode`` 单独、明确地控制。
        'high': ('高保真', 40, 12, '320k'),
    }
    # 歌曲时半音值交给 Seed-VC F0；普通口播则在转换后以保持时长的专业
    # 变调执行。两条链路不能混用，否则口播会被误送进歌曲模型。
    VOICE_CHARACTER_PROFILES = {
        'natural': ('自然还原（推荐）', 0, '不附加音高偏移，优先忠实保留参考音色。'),
        'sweet_female': ('甜美女声', 1, '轻微提高音高，并配合柔和明亮的母版精修；甜美感仍主要来自真实女声参考。'),
        'gentle_female': ('温柔女声', 0, '保持自然音高，以温暖和低齿音处理突出柔和感。'),
        'bright_young_female': ('明亮少女声', 2, '轻度提高音高和存在感；参考过尖或齿音重时应降低“明亮度”。'),
        'warm_female': ('温暖知性女声', 0, '不强行升调，以中低频温暖感和清晰度为主。'),
        'clear_male': ('清晰男声', 0, '保持参考男声的自然中心，轻微增加对白清晰度。'),
        'warm_male': ('温暖男声', -1, '轻微下调并强化温暖感，避免压得过闷。'),
        'deep_male': ('沉稳低男声', -2, '适合本来偏低的男声参考；不是用来把女声强行变成男声。'),
        'boy': ('清亮少年声', 2, '轻度提高音高和空气感；请使用年龄相近的干净少年参考。'),
        # 童声必须区分性别：同为儿童，男童的基频与共振通常低于女童。此前的
        # 通用“稚嫩童声”默认偏女童，旧项目仍保留该 key，避免用户保存的预设失效。
        'girl_child': ('稚嫩女童声', 3, '女童方向：转换完成后再提高 3 半音，并上移共振；请使用干净的女童参考。'),
        'boy_child': ('稚嫩男童声', 1, '男童方向：转换完成后轻度提高 1 半音，保留较自然的胸声与共振；请使用干净的男童参考。'),
        'child': ('稚嫩女童声（兼容旧“稚嫩童声”）', 3, '旧项目兼容项，按女童方向处理；新项目请直接选择“稚嫩女童声”或“稚嫩男童声”。'),
        'mature_elderly': ('成熟老人声', -1, '仅轻微下调和增强中频质感；苍老气息、沙哑与共鸣取决于真实参考。'),
        'soft_breathy': ('轻柔气声', 0, '保持音高，减少刺耳齿音并略加空气感；不应替代真实带气息的参考。'),
        'custom': ('自定义微调', 0, '按下面“自定义音高微调”设置额外半音。'),
    }
    # 对普通口播的高质量后置变调：童声/少年声让共振随音高轻度上移，其余
    # 预设保留共振，避免把成年女声或男声变成不自然的“卡通腔”。
    VOICE_CHARACTER_FORMANT_MODE = {
        'sweet_female': 'preserved', 'bright_young_female': 'preserved',
        'deep_male': 'preserved', 'mature_elderly': 'preserved',
        'boy': 'shifted', 'girl_child': 'shifted', 'boy_child': 'shifted',
        'child': 'shifted', 'custom': 'preserved',
    }
    # 这是 Seed-VC 输出后的“人声母版精修”，只作用于转换后的人声，不处理
    # 背景音乐。数值均为保守 dB 级修正，避免把 EQ 伪装成真正的年龄/性别转换。
    # (明亮度, 温暖度, 清晰度, 齿音抑制, 空气感)
    VOICE_FINISH_DEFAULTS = {
        'natural': (0, 0, 0, 0, 0), 'sweet_female': (2, 0, 1, 2, 1),
        'gentle_female': (0, 2, 0, 2, 0), 'bright_young_female': (3, -1, 2, 2, 2),
        'warm_female': (0, 3, 1, 1, 0), 'clear_male': (0, 1, 2, 1, 0),
        'warm_male': (-1, 3, 1, 1, 0), 'deep_male': (-2, 3, 1, 1, 0),
        'boy': (2, 0, 1, 2, 2),
        'girl_child': (2, -2, 1, 3, 2), 'boy_child': (1, 0, 1, 2, 1),
        'child': (2, -2, 1, 3, 2),
        'mature_elderly': (-1, 2, 2, 1, 0), 'soft_breathy': (1, 1, 0, 3, 3),
        'custom': (0, 0, 0, 0, 0),
    }

    def __init__(self, seed_root, reference_audio, source_paths, output_dir, python_path='', diffusion_steps=40,
                 auto_install=True, same_dir_output=False, sibling_dir_output=False, output_suffix='-人声替换', hf_cache_path='',
                 preserve_background=True, song_mode=False, clean_reference=True, quality_profile='high',
                 voice_character='natural', custom_semitones=0, voice_brightness=0, voice_warmth=0,
                 voice_presence=0, voice_deess=0, voice_air=0, voice_highpass=0,
                 voice_lowpass=20000, voice_compression=0, voice_output_gain=0,
                 post_conversion_pitch_enabled=False, post_conversion_semitones=0,
                 cpu_usage_percent=80, speech_use_original_mix=True, parent=None):
        super().__init__(parent)
        self.seed_root = os.path.abspath(str(seed_root or '').strip())
        # 媒体来源可为本地/UNC/file:// 或 sftp://、ssh://。不要在 URL 上调用
        # abspath，否则 Windows 会把 “sftp:” 误当成本地目录名。
        self.reference_audio = self._normalize_local_source(reference_audio)
        # Keep a stable identity before the run replaces the reference with a
        # task-private PCM snapshot.  It is used solely for reproducible
        # diffusion seeding, never as a media path after preparation.
        self._reference_seed_identity = self.reference_audio
        raw_source_items = []
        for path in (source_paths or []):
            raw_source_items.extend(self.split_source_inputs(path))
        self.source_paths = [self._normalize_local_source(path) for path in raw_source_items if str(path).strip()]
        self.output_dir = self._normalize_local_source(output_dir) if str(output_dir or '').strip() else ''
        self.python_path = str(python_path or '').strip()
        self.diffusion_steps = max(4, min(100, int(diffusion_steps or 40)))
        self.auto_install, self.same_dir_output = bool(auto_install), bool(same_dir_output)
        self.sibling_dir_output = bool(sibling_dir_output) and not self.same_dir_output
        self.output_suffix = str(output_suffix or '-人声替换').strip() or '-人声替换'
        self.hf_cache_path = os.path.abspath(str(hf_cache_path or '').strip()) if str(hf_cache_path or '').strip() else ''
        self.preserve_background = bool(preserve_background)
        # Seed-VC 的 F0 条件会沿用原人声的音高曲线。普通口播不需要它；
        # 歌曲/唱腔开启后，旋律、长音和多数抑扬顿挫才不会被当作平直语音重建。
        self.song_mode = bool(song_mode)
        # Demucs is excellent at creating a background stem, but the separated
        # vocal can contain phase/codec artifacts.  For spoken video, feeding
        # that damaged stem into Seed-VC is worse than feeding the original
        # dialogue.  Songs remain an explicit exception because their backing
        # track is normally much stronger than the vocal.
        self.speech_use_original_mix = bool(speech_use_original_mix)
        self.clean_reference = bool(clean_reference)
        self.quality_profile = str(quality_profile or 'high').strip().lower()
        if self.quality_profile not in self.QUALITY_PROFILES: self.quality_profile = 'high'
        self.voice_character = str(voice_character or 'natural').strip().lower()
        if self.voice_character not in self.VOICE_CHARACTER_PROFILES: self.voice_character = 'natural'
        try: self.custom_semitones = max(-6, min(6, int(custom_semitones or 0)))
        except (TypeError, ValueError): self.custom_semitones = 0
        def _finish_value(value, lower=-6, upper=6):
            try: return max(lower, min(upper, int(value or 0)))
            except (TypeError, ValueError): return 0
        self.voice_brightness = _finish_value(voice_brightness)
        self.voice_warmth = _finish_value(voice_warmth)
        self.voice_presence = _finish_value(voice_presence)
        self.voice_deess = _finish_value(voice_deess, 0, 6)
        self.voice_air = _finish_value(voice_air, -6, 6)
        self.voice_highpass = _finish_value(voice_highpass, 0, 180)
        self.voice_lowpass = _finish_value(voice_lowpass, 3000, 20000)
        self.voice_compression = _finish_value(voice_compression, 0, 100)
        self.voice_output_gain = _finish_value(voice_output_gain, -12, 12)
        # All target-character pitch work is deliberately *post conversion*.
        # Do not alter the reference before Seed-VC reads its timbre: doing so
        # is a common cause of metallic / "electronic" voices.
        self.post_conversion_pitch_enabled = bool(post_conversion_pitch_enabled)
        try: self.post_conversion_semitones = max(-6, min(6, int(post_conversion_semitones or 0)))
        except (TypeError, ValueError): self.post_conversion_semitones = 0
        try: self.cpu_usage_percent = max(40, min(100, int(cpu_usage_percent or 80)))
        except (TypeError, ValueError): self.cpu_usage_percent = 80
        self._stop_requested = False
        self._active_process = None
        self._process_lock = Lock()
        # 参考音频净化也会复用 _stream()；在批次循环开始前先给进度字段
        # 一个安全值，并暂不发送批量进度，避免参考净化访问未初始化字段。
        self._batch_total = 1
        self._batch_index = 0
        self._batch_progress_ready = False
        if type(self) is SeedVCBatchThread:
            SeedVCBatchThread._replacement_workers.add(self)

    @staticmethod
    def _remote_uri(value):
        from urllib.parse import urlparse
        parsed = urlparse(str(value or '').strip())
        return parsed if parsed.scheme.lower() in ('sftp', 'ssh') and parsed.hostname else None

    @classmethod
    def _normalize_local_source(cls, value):
        text = str(value or '').strip()
        if not text:
            return ''
        remote = cls._remote_uri(text)
        if remote:
            return text
        # file:// 方便粘贴浏览器或资源管理器生成的地址；UNC（\\server\share）保持原样。
        if text.lower().startswith('file://'):
            from urllib.parse import unquote, urlparse
            parsed = urlparse(text)
            if parsed.netloc:
                text = '\\\\' + parsed.netloc + unquote(parsed.path).replace('/', '\\')
            else:
                text = unquote(parsed.path).lstrip('/').replace('/', '\\')
        return os.path.abspath(text)

    @staticmethod
    def split_source_inputs(value):
        """多行粘贴为主，也兼容单行用分号隔开的 Windows 路径列表。"""
        text = str(value or '').replace('\r', '\n').strip()
        if not text:
            return []
        entries = []
        for line in text.split('\n'):
            line = line.strip().strip('"').strip("'")
            if not line:
                continue
            # URL 的查询参数可能含分号，故只对明显的本地路径列表做分号兼容。
            parts = [line]
            if ';' in line and '://' not in line:
                parts = [part.strip().strip('"').strip("'") for part in line.split(';')]
            entries.extend(part for part in parts if part)
        return list(dict.fromkeys(entries))

    def request_stop(self):
        self._stop_requested = True
        try:
            with self._process_lock:
                process = self._active_process
            if process is not None and process.poll() is None:
                process.terminate()
        except Exception:
            pass

    def _env(self, cpu=False):
        env = os.environ.copy()
        if self.hf_cache_path:
            os.makedirs(self.hf_cache_path, exist_ok=True)
            env.update({'HF_HOME': self.hf_cache_path, 'HF_HUB_CACHE': os.path.join(self.hf_cache_path, 'hub'),
                        'HUGGINGFACE_HUB_CACHE': os.path.join(self.hf_cache_path, 'hub'),
                        'TRANSFORMERS_CACHE': os.path.join(self.hf_cache_path, 'transformers')})
        env.update({'PYTHONUNBUFFERED': '1', 'PYTHONUTF8': '1', 'PYTHONIOENCODING': 'utf-8'})
        if cpu:
            env['CUDA_VISIBLE_DEVICES'] = ''
            # CPU inference otherwise inherits conservative or conflicting
            # thread defaults from another app.  The budget applies to every
            # standard numerical backend used by Seed-VC/Demucs/PyTorch.
            total_threads = max(1, int(os.cpu_count() or 1))
            thread_budget = max(1, min(total_threads, int(total_threads * self.cpu_usage_percent / 100.0)))
            for key in ('OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'NUMEXPR_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS', 'BLIS_NUM_THREADS'):
                env[key] = str(thread_budget)
            env['TOKENIZERS_PARALLELISM'] = 'false'
        return env

    def _cpu_thread_budget(self):
        total = max(1, int(os.cpu_count() or 1))
        return total, max(1, min(total, int(total * self.cpu_usage_percent / 100.0)))

    def _run(self, command, timeout=600, env=None):
        return subprocess.run(command, capture_output=True, text=True, encoding='utf-8', errors='replace',
                              timeout=timeout, env=env, **_subprocess_no_window_kwargs())

    def _audio_mean_volume_db(self, audio_path):
        """Return FFmpeg's mean volume for a local audio file, or None.

        Demucs can damage an already dry reference more than it helps.  The
        measurement is intentionally done on its two separated WAVs instead
        of guessing from a filename or from a user's checkbox.
        """
        result = self._run(['ffmpeg', '-hide_banner', '-i', audio_path, '-af', 'volumedetect', '-f', 'null', '-'], 300)
        text = (result.stdout or '') + '\n' + (result.stderr or '')
        match = re.search(r'mean_volume:\s*(-?(?:\d+(?:\.\d+)?|inf))\s*dB', text, re.I)
        if not match:
            return None

    def _audio_integrated_lufs(self, audio_path):
        """Read integrated loudness without changing the supplied media."""
        result = self._run([
            'ffmpeg', '-hide_banner', '-i', audio_path,
            '-af', 'loudnorm=I=-16:TP=-1.0:LRA=11:print_format=json', '-f', 'null', '-'
        ], 300)
        text = (result.stdout or '') + '\n' + (result.stderr or '')
        match = re.search(r'"input_i"\s*:\s*"\s*(-?\d+(?:\.\d+)?)\s*"', text)
        try:
            return float(match.group(1)) if match else None
        except (AttributeError, TypeError, ValueError):
            return None

    def _match_output_loudness(self, source_audio, rendered_audio, output_audio):
        """Return a level-matched render, preserving the source's listening level.

        Seed-VC and a conservative background duck can both leave a valid but
        much quieter result.  Users experience that as thin or broken audio.
        A bounded gain match restores the original video level without adding
        compression; the limiter is only a safety guard for unforeseen peaks.
        """
        source_lufs = self._audio_integrated_lufs(source_audio)
        rendered_lufs = self._audio_integrated_lufs(rendered_audio)
        if source_lufs is None or rendered_lufs is None:
            self.log.emit('响度核对未取得完整数据，保留 Seed-VC 原始成片响度，不额外处理。', 'orange')
            return rendered_audio
        gain = max(-8.0, min(8.0, source_lufs - rendered_lufs))
        if abs(gain) < 0.7:
            self.log.emit(f'响度核对：原片 {source_lufs:.1f} LUFS，成片 {rendered_lufs:.1f} LUFS，差异很小，未额外增益。', 'gray')
            return rendered_audio
        result = self._run([
            'ffmpeg', '-y', '-hide_banner', '-i', rendered_audio,
            '-af', f'volume={gain:.2f}dB,alimiter=limit=0.97', '-ac', '2', '-ar', '44100', output_audio
        ], 600)
        if result.returncode != 0 or not os.path.isfile(output_audio):
            self.log.emit('响度回齐失败，已保留未回齐的成片，未中断任务。', 'orange')
            return rendered_audio
        self.log.emit(f'响度回齐：原片 {source_lufs:.1f} LUFS，混音后 {rendered_lufs:.1f} LUFS，已安全补偿 {gain:+.1f} dB。', 'green')
        return output_audio
        try:
            value = match.group(1).lower()
            return -120.0 if value == '-inf' else float(value)
        except (TypeError, ValueError):
            return None

    def _should_use_cleaned_reference(self, vocals_path, background_path):
        """Only accept Demucs reference separation when accompaniment is real.

        A background more than 15 dB below the separated vocal is normally
        low-level room noise or separation residue.  Feeding a dry reference
        through Demucs in that case creates synthetic high-frequency artifacts
        and weakens the target speaker embedding, so preserve the original.
        """
        vocal_db = self._audio_mean_volume_db(vocals_path)
        background_db = self._audio_mean_volume_db(background_path)
        if vocal_db is None or background_db is None:
            self.log.emit('参考人声净化无法可靠判断伴奏强度，已保护原始参考音频，不进行可能造成失真的二次分离。', 'orange')
            return False
        difference = vocal_db - background_db
        if difference >= 15.0:
            self.log.emit(f'参考人声净化已保护干净参考：背景比人声低 {difference:.1f}dB，判定为底噪/分离残留，直接使用原参考。', 'green')
            return False
        self.log.emit(f'参考人声净化检测到明显伴奏/环境声（背景仅低 {difference:.1f}dB），将使用分离后人声。', 'blue')
        return True

    def _stream(self, command, timeout=3600, cpu=False, activity_hint='正在处理媒体'):
        kwargs = _subprocess_no_window_kwargs()
        kwargs.update({'stdout': subprocess.PIPE, 'stderr': subprocess.STDOUT, 'text': True,
                       'encoding': 'utf-8', 'errors': 'replace', 'bufsize': 1, 'cwd': self.seed_root,
                       'env': self._env(cpu)})
        process = subprocess.Popen(command, **kwargs)
        with self._process_lock: self._active_process = process
        output, started, last_notice = [], time.monotonic(), time.monotonic()
        activity = str(activity_hint or '正在处理媒体')
        lines = queue.Queue()
        def read_output():
            try:
                for line in iter(process.stdout.readline, ''):
                    lines.put(line)
            finally:
                lines.put(None)
        threading.Thread(target=read_output, name='seed-vc-output-reader', daemon=True).start()
        try:
            while True:
                if self._stop_requested:
                    process.terminate(); break
                try:
                    line = lines.get(timeout=1.5)
                except queue.Empty:
                    line = ''
                if line is None:
                    break
                if line:
                    line = str(line).strip()
                    if line:
                        output.append(line)
                        match = re.search(r'(\d{1,3})\s*%', line)
                        if match and self._batch_progress_ready:
                            local = max(0, min(100, int(match.group(1))))
                            self.progress.emit(int(((self._batch_index - 1) * 100 + local) / self._batch_total))
                        lowered = line.lower()
                        model_phase = any(token in lowered for token in ('download', 'fetch', 'huggingface', 'checkpoint', 'model', 'loading'))
                        if model_phase:
                            activity = '正在下载或加载模型'
                        elif ('seed-vc阶段' in line.lower() or 'it/s]' in lowered or re.search(r'\d+/\d+\s*\[', line)):
                            activity = '正在转换人声（扩散推理）'
                        self.log.emit(f'Seed-VC：{line[-500:]}', 'blue' if (match or model_phase) else 'gray')
                elif time.monotonic() - last_notice >= 12:
                    elapsed = int(time.monotonic() - started)
                    self.log.emit(f'Seed-VC {activity}（已用时 {elapsed // 60}分{elapsed % 60:02d}秒，程序仍在运行）…', 'orange')
                    last_notice = time.monotonic()
                if time.monotonic() - started > timeout:
                    process.kill(); raise TimeoutError(f'Seed-VC 推理超过 {timeout // 60} 分钟，已停止。')
                if process.poll() is not None and lines.empty():
                    break
            try: process.wait(timeout=30)
            except Exception: process.kill()
            return process.returncode or 0, '\n'.join(output)
        finally:
            with self._process_lock: self._active_process = None
            try:
                if process.stdout: process.stdout.close()
            except Exception: pass

    def _venv_python(self):
        return os.path.join(self.seed_root, '.venv', 'Scripts' if os.name == 'nt' else 'bin', 'python.exe' if os.name == 'nt' else 'python')

    @classmethod
    def _cuda_cache_key(cls, python_path):
        return os.path.normcase(os.path.abspath(str(python_path or '')))

    @classmethod
    def cache_cuda_result(cls, python_path, ready):
        with cls._cuda_probe_lock:
            cls._cuda_probe_cache[cls._cuda_cache_key(python_path)] = bool(ready)

    @classmethod
    def invalidate_cuda_cache(cls, python_path=''):
        with cls._cuda_probe_lock:
            if python_path:
                cls._cuda_probe_cache.pop(cls._cuda_cache_key(python_path), None)
            else:
                cls._cuda_probe_cache.clear()

    def _install_or_repair(self):
        inference = os.path.join(self.seed_root, 'inference.py')
        if not os.path.isfile(inference):
            if not self.auto_install:
                raise FileNotFoundError('Seed-VC 尚未安装：未找到 inference.py。请开启自动安装或选择正确项目目录。')
            if os.path.isdir(self.seed_root) and os.listdir(self.seed_root):
                nested = os.path.join(self.seed_root, 'seed-vc')
                # 仅兼容旧版本“父目录/seed-vc”的已完成安装。此前只要目标
                # 目录非空就继续拼接一层 seed-vc，会把中断的首次安装放错位置。
                if os.path.isfile(os.path.join(nested, 'inference.py')):
                    self.seed_root = nested
            self.log.emit('首次使用：正在下载 Seed-VC 项目…', 'blue')
            os.makedirs(os.path.dirname(self.seed_root), exist_ok=True)
            # 不使用 Git 的 main 分支：该引用会随上游变动，无法保证首次安装
            # 获得的是审查过的源码。固定提交 ZIP 同时适用于有/无 Git 的电脑。
            self.log.emit('正在下载已审核的固定版 Seed-VC 项目…', 'blue')
            try:
                self._download_seed_vc_archive()
            except Exception as exc:
                raise RuntimeError('Seed-VC 项目下载失败。请检查网络、磁盘空间和项目目录写入权限。\n' + str(exc)) from exc
            if not os.path.isfile(os.path.join(self.seed_root, 'inference.py')):
                raise RuntimeError('Seed-VC 项目下载后仍未找到 inference.py，已停止安装以保护现有目录。')
        venv_python = self._venv_python()
        if not os.path.isfile(venv_python):
            self.log.emit('正在创建 Seed-VC 独立 Python 环境…', 'blue')
            result = self._run([sys.executable, '-m', 'venv', os.path.join(self.seed_root, '.venv')], 600)
            if result.returncode != 0: raise RuntimeError('创建 Seed-VC 独立环境失败：\n' + (result.stderr or '')[-1200:])
        self.python_path = venv_python
        marker = os.path.join(self.seed_root, '.videotaskhub_seed_vc_ready')
        check = self._run([venv_python, '-c', 'import torch, munch, einops; from dac.nn.quantize import VectorQuantize'], 120)
        if check.returncode == 0 and os.path.isfile(marker): return False
        self.log.emit('正在安装/修复 Seed-VC 独立依赖，首次运行可能需要较长时间…', 'blue')
        try:
            install_seed_vc_dependencies(self.seed_root, venv_python, lambda line: self.log.emit('Seed-VC：' + line[-700:], 'gray'))
        except Exception as exc:
            raise RuntimeError('Seed-VC 依赖安装失败：\n' + str(exc)) from exc
        check = self._run([venv_python, '-c', 'import torch, munch, einops, webrtcvad; from dac.nn.quantize import VectorQuantize'], 180)
        if check.returncode != 0: raise RuntimeError('Seed-VC 依赖验证失败：\n' + (check.stderr or check.stdout or '')[-1600:])
        return True

    def _download_seed_vc_archive(self):
        """无需 Git 的全新电脑安装：下载官方仓库 ZIP 后原子放入项目目录。"""
        parent = os.path.dirname(self.seed_root)
        os.makedirs(parent, exist_ok=True)
        workspace = tempfile.mkdtemp(prefix='videotaskhub_seed_vc_bootstrap_', dir=parent)
        archive = os.path.join(workspace, 'seed-vc.zip')
        unpacked = os.path.join(workspace, 'unpacked')
        try:
            request = urllib.request.Request(
                f'https://github.com/Plachtaa/seed-vc/archive/{SEED_VC_COMMIT}.zip',
                headers={'User-Agent': 'VideoTaskHub-Installer/1'},
            )
            with urllib.request.urlopen(request, timeout=60) as response:
                final = urllib.parse.urlparse(response.geturl())
                if final.scheme.lower() != 'https' or (final.hostname or '').lower() not in {'github.com', 'codeload.github.com'}:
                    raise RuntimeError('Seed-VC 下载被重定向到非受信任地址。')
                if int(response.headers.get('Content-Length') or 0) > 1024 * 1024 * 1024:
                    raise RuntimeError('Seed-VC 安装包异常过大。')
                written = 0
                with open(archive, 'wb') as output:
                    while chunk := response.read(1024 * 1024):
                        written += len(chunk)
                        if written > 1024 * 1024 * 1024:
                            raise RuntimeError('Seed-VC 安装包超过允许大小。')
                        output.write(chunk)
            with zipfile.ZipFile(archive, 'r') as package:
                safe_root = os.path.abspath(unpacked)
                unpacked_size = 0
                for member in package.infolist():
                    # ZIP member names are POSIX paths.  Reject Windows
                    # separators and any path that cannot remain in safe_root.
                    if not member.filename or '\\' in member.filename:
                        raise RuntimeError('Seed-VC 安装包包含不安全的文件路径。')
                    # ZIP 可携带 Unix 符号链接；若按普通文件解压，它可能把后续
                    # 写入引向工作区外。安装器不需要此类成员，直接拒绝。
                    if ((int(member.external_attr) >> 16) & 0o170000) == 0o120000:
                        raise RuntimeError('Seed-VC 安装包包含不允许的符号链接。')
                    relative = os.path.normpath(member.filename)
                    destination = os.path.abspath(os.path.join(safe_root, relative))
                    if os.path.commonpath([safe_root, destination]) != safe_root:
                        raise RuntimeError('Seed-VC 安装包尝试写入目标目录之外。')
                    if member.is_dir():
                        os.makedirs(destination, exist_ok=True)
                        continue
                    unpacked_size += max(0, int(member.file_size))
                    if unpacked_size > 1024 * 1024 * 1024:
                        raise RuntimeError('Seed-VC 安装包解压后超过允许大小。')
                    os.makedirs(os.path.dirname(destination), exist_ok=True)
                    with package.open(member, 'r') as source, open(destination, 'wb') as output:
                        shutil.copyfileobj(source, output, length=1024 * 1024)
            folders = [os.path.join(unpacked, name) for name in os.listdir(unpacked)]
            source = next((path for path in folders if os.path.isfile(os.path.join(path, 'inference.py'))), '')
            if not source:
                raise RuntimeError('官方 ZIP 内容不完整，未找到 inference.py。')
            if os.path.isdir(self.seed_root):
                # 中断过的首装可能已经留下 .venv、缓存或少量源码。合并官方
                # 源码而不删除既有文件，既可续装，也不会误删用户下载的模型。
                shutil.copytree(source, self.seed_root, dirs_exist_ok=True)
            elif os.path.exists(self.seed_root):
                raise RuntimeError(f'Seed-VC 目标路径不是目录：{self.seed_root}')
            else:
                shutil.move(source, self.seed_root)
        finally:
            shutil.rmtree(workspace, ignore_errors=True)

    def _device_is_cuda(self):
        cache_key = self._cuda_cache_key(self.python_path)
        with self._cuda_probe_lock:
            known = self._cuda_probe_cache.get(cache_key)
        if known is not None:
            self.log.emit('Seed-VC 设备检测：复用本次运行的 CUDA 诊断结果（' + ('GPU 可用）。' if known else 'CPU 兼容模式）。'), 'green' if known else 'orange')
            return bool(known)
        result = self._run([self.python_path, '-c', "import torch; print('CUDA=' + str(torch.cuda.is_available())); print(torch.__version__)"], 90, self._env())
        detail = (result.stdout or result.stderr or '').strip().replace('\n', '｜')
        cuda = 'CUDA=True' in detail
        self.cache_cuda_result(self.python_path, cuda)
        self.log.emit(f'Seed-VC 设备检测：{detail}；' + ('使用 GPU FP16。' if cuda else '使用 CPU FP32，速度会较慢。'), 'green' if cuda else 'orange')
        return cuda

    def _ensure_vocal_separator(self):
        """按需准备 Demucs 与稳定 WAV 写出依赖，绝不改动主程序环境。"""
        check = self._run([
            self.python_path, '-c',
            'import demucs, soundfile; print("separator-ready")',
        ], 60, self._env())
        if check.returncode == 0:
            return
        self.log.emit('正在修复人声分离组件（Demucs / SoundFile）…', 'blue')
        demucs_check = self._run([self.python_path, '-c', 'import demucs'], 60, self._env())
        if demucs_check.returncode != 0:
            install = self._run([self.python_path, '-m', 'pip', 'install', 'demucs==4.0.1'], 1800, self._env())
            if install.returncode != 0:
                raise RuntimeError('人声分离组件安装失败，无法安全保留背景音乐与环境音。\n' + (install.stderr or install.stdout or '')[-1200:])
        verify = self._run([
            self.python_path, '-c',
            'import demucs, soundfile; print("separator-ready")',
        ], 60, self._env())
        if verify.returncode != 0:
            raise RuntimeError('人声分离组件验证失败。\n' + (verify.stderr or verify.stdout or '')[-800:])

    def _separate_vocals(self, original_mix, work_dir, cuda):
        """将原混音分为 vocals/no_vocals；后者保留音乐与绝大多数环境音。"""
        separated_root = os.path.join(work_dir, 'separated')
        device = 'cuda' if cuda else 'cpu'
        self.log.emit('正在分离人声与背景音乐/环境音（首次可能下载分离模型）…', 'blue')
        compat_script = os.path.join(base_dir, 'demucs_compat.py')
        if not os.path.isfile(compat_script):
            raise RuntimeError('人声分离兼容组件缺失，请完整更新程序文件后重试。')
        command = [self.python_path, compat_script, '--two-stems', 'vocals', '--out', separated_root,
                   '--device', device, original_mix]
        code, output = self._stream(command, 3600, cpu=not cuda, activity_hint='正在分离人声和背景音乐/环境音')
        if code != 0 and cuda and not self._stop_requested:
            self.log.emit('GPU 人声分离失败，自动改用 CPU 重试当前视频。', 'orange')
            command[command.index('--device') + 1] = 'cpu'
            code, output = self._stream(command, 7200, cpu=True, activity_hint='正在以 CPU 分离人声和背景音乐/环境音')
        if code != 0:
            raise RuntimeError('人声分离失败，已停止以避免输出丢失背景音的成片。\n' + output[-1600:])
        vocals, background = [], []
        for root, _dirs, files in os.walk(separated_root):
            for name in files:
                lowered = name.lower()
                full = os.path.join(root, name)
                if lowered == 'vocals.wav': vocals.append(full)
                elif lowered == 'no_vocals.wav': background.append(full)
        if not vocals or not background:
            raise RuntimeError('人声分离未返回 vocals.wav / no_vocals.wav，已停止以保护原背景音。')
        return max(vocals, key=os.path.getmtime), max(background, key=os.path.getmtime)

    def _get_sftp_client(self, uri):
        """用 SSH Agent/密钥或 URL 中的凭据连接 SFTP；日志绝不输出密码。"""
        try:
            import paramiko
        except ImportError:
            self.log.emit('首次使用 SFTP/SSH：正在安装安全传输组件 paramiko…', 'blue')
            install = self._run([sys.executable, '-m', 'pip', 'install', 'paramiko==5.1.0'], 1200)
            if install.returncode != 0:
                raise RuntimeError('无法安装 SFTP/SSH 传输组件 paramiko。请联网后重试，或在主程序环境执行 pip install paramiko==5.1.0。\n' + (install.stderr or '')[-800:])
            import paramiko
        from urllib.parse import parse_qs, unquote, urlparse
        parsed = urlparse(uri)
        query = parse_qs(parsed.query)
        key_file = unquote(str(query.get('key', [''])[0] or '')).strip() or None
        if key_file and not os.path.isfile(key_file):
            raise FileNotFoundError(f'SSH 私钥文件不存在：{key_file}')
        username = unquote(parsed.username or '') or os.environ.get('USERNAME', '')
        password = unquote(parsed.password or '') or None
        port = int(parsed.port or 22)
        self.log.emit(f'正在连接 SFTP：{username}@{parsed.hostname}:{port}…', 'blue')
        client = paramiko.SSHClient()
        client.load_system_host_keys()
        # 仅信任用户系统 known_hosts 中的主机，禁止首次连接静默接受未知指纹。
        client.set_missing_host_key_policy(paramiko.RejectPolicy())
        client.connect(parsed.hostname, port=port, username=username, password=password,
                       key_filename=key_file, allow_agent=True, look_for_keys=True,
                       timeout=25, banner_timeout=25, auth_timeout=25)
        return client, client.open_sftp(), unquote(parsed.path or '/') or '/'

    def _sftp_download(self, uri, local_target):
        """递归下载 SFTP 文件或目录到本次任务的临时区，完成后由 finally 删除。"""
        import posixpath
        import stat
        client = sftp = None
        try:
            client, sftp, remote_path = self._get_sftp_client(uri)
            remote_path = posixpath.normpath(remote_path)
            info = sftp.stat(remote_path)
            def download_file(remote_file, local_file, size=0):
                os.makedirs(os.path.dirname(local_file), exist_ok=True)
                last = [-1]
                def callback(done, total):
                    if self._stop_requested:
                        raise RuntimeError('已停止远程下载')
                    total = total or size or 1
                    percent = int(max(0, min(100, done * 100 / total)))
                    if percent != last[0] and (percent in (0, 100) or percent - last[0] >= 5):
                        last[0] = percent
                        self.log.emit(f'远程下载：{os.path.basename(remote_file)} {percent}%', 'gray')
                sftp.get(remote_file, local_file, callback=callback)
            def download_tree(remote_dir, local_dir):
                os.makedirs(local_dir, exist_ok=True)
                for item in sftp.listdir_attr(remote_dir):
                    if self._stop_requested:
                        raise RuntimeError('已停止远程下载')
                    remote_child = posixpath.join(remote_dir, item.filename)
                    local_child = os.path.join(local_dir, item.filename)
                    if stat.S_ISDIR(item.st_mode):
                        download_tree(remote_child, local_child)
                    elif stat.S_ISREG(item.st_mode):
                        download_file(remote_child, local_child, item.st_size)
            self.log.emit(f'正在下载远程媒体到隔离临时区：{remote_path}', 'blue')
            if stat.S_ISDIR(info.st_mode):
                local_dir = os.path.join(local_target, os.path.basename(remote_path.rstrip('/')) or 'remote_media')
                download_tree(remote_path, local_dir)
                return local_dir
            local_file = os.path.join(local_target, os.path.basename(remote_path) or 'remote_media')
            download_file(remote_path, local_file, info.st_size)
            return local_file
        finally:
            try:
                if sftp: sftp.close()
                if client: client.close()
            except Exception:
                pass

    def _sftp_upload(self, uri, local_file, relative_path=''):
        """将成片上传到明确指定的 SFTP 输出目录；不覆盖原远程视频。"""
        import posixpath
        client = sftp = None
        try:
            client, sftp, remote_dir = self._get_sftp_client(uri)
            remote_dir = posixpath.join(remote_dir, *[part for part in str(relative_path).replace('\\', '/').split('/') if part and part != '.'])
            parent = posixpath.dirname(remote_dir)
            # 逐级创建目录，兼容大多数 SFTP 服务端。
            current = '/'
            for part in [item for item in parent.split('/') if item]:
                current = posixpath.join(current, part)
                try: sftp.stat(current)
                except IOError: sftp.mkdir(current)
            remote_file = posixpath.join(parent, os.path.basename(local_file))
            stem, ext = posixpath.splitext(remote_file); serial = 2
            while True:
                try: sftp.stat(remote_file)
                except IOError: break
                remote_file = f'{stem}_{serial}{ext}'; serial += 1
            self.log.emit(f'正在上传成片：{os.path.basename(local_file)}', 'blue')
            sftp.put(local_file, remote_file)
            self.log.emit(f'已上传：{remote_file}', 'green')
            return remote_file
        finally:
            try:
                if sftp: sftp.close()
                if client: client.close()
            except Exception:
                pass

    def _media_items(self):
        result = []
        for raw in self.source_paths:
            if os.path.isfile(raw) and raw.lower().endswith(self.MEDIA_EXTS): result.append(raw)
            elif os.path.isdir(raw):
                for root, _dirs, names in os.walk(raw):
                    for name in sorted(names, key=str.casefold):
                        stem = os.path.splitext(name)[0]
                        if name.lower().endswith(self.MEDIA_EXTS) and not (self.same_dir_output and stem.endswith(self.output_suffix)):
                            result.append(os.path.join(root, name))
        return list(dict.fromkeys(os.path.abspath(item) for item in result))

    def _sibling_output_target(self, source):
        """按最具体的来源根目录生成同级输出目录，并保留来源内部相对结构。"""
        source = os.path.abspath(str(source or ''))
        candidates = []
        for raw in self.source_paths:
            raw = os.path.abspath(str(raw or ''))
            root = raw if os.path.isdir(raw) else os.path.dirname(raw)
            try:
                if os.path.commonpath((source, root)) == root:
                    candidates.append(root)
            except (OSError, ValueError):
                continue
        source_root = max(candidates, key=len) if candidates else os.path.dirname(source)
        normalized_root = os.path.normpath(source_root)
        parent = os.path.dirname(normalized_root)
        folder_name = os.path.basename(normalized_root)
        if not folder_name:
            # 盘符根目录没有普通文件夹名；仍在该盘符下创建明确的新目录，绝不覆盖根目录。
            parent = normalized_root
            folder_name = '根目录'
        sibling_root = os.path.join(parent, folder_name + self.output_suffix)
        relative = os.path.relpath(source, source_root)
        return os.path.join(sibling_root, relative)

    def _effective_quality(self, cuda):
        """质量优先：设备只改变速度与精度，不得静默减少扩散步数。"""
        label, gpu_target, _cpu_limit, bitrate = self.QUALITY_PROFILES[self.quality_profile]
        requested = self.diffusion_steps
        # CUDA 只决定执行速度和 FP16/FP32；CPU 也必须按用户选择的质量
        # 完成推理。高保真档位至少保持 40 步，避免“GPU 推荐”误变成
        # “CPU 自动降质”。快速/平衡档位则尊重用户手动指定的步数。
        steps = max(requested, gpu_target) if self.quality_profile == 'high' else requested
        return label, max(4, int(steps)), bitrate

    def _voice_character_pitch_shift(self):
        """Return the selected bounded target-voice pitch adjustment."""
        label, preset_shift, description = self.VOICE_CHARACTER_PROFILES[self.voice_character]
        shift = self.custom_semitones if self.voice_character == 'custom' else preset_shift
        return label, max(-6, min(6, int(shift))), description

    def _stable_inference_seed(self, source):
        """Derive a reproducible Seed-VC seed from media and active settings.

        Seed-VC's diffusion inference starts from random noise.  Without an
        explicit seed identical inputs can drift between runs, making a good
        target voice impossible to reproduce or debug.
        """
        try:
            source_path = os.path.normcase(os.path.abspath(str(source or '')))
            source_stat = os.stat(source_path)
            source_identity = f'{source_path}|{source_stat.st_size}|{source_stat.st_mtime_ns}'
        except Exception:
            source_identity = str(source or '')
        reference_identity = str(getattr(self, '_reference_seed_identity', self.reference_audio) or '')
        try:
            reference_path = os.path.normcase(os.path.abspath(reference_identity))
            reference_stat = os.stat(reference_path)
            reference_identity = f'{reference_path}|{reference_stat.st_size}|{reference_stat.st_mtime_ns}'
        except Exception:
            pass
        raw = '|'.join((
            'videotaskhub-seed-vc-v1', source_identity, reference_identity,
            str(self.quality_profile), str(self.song_mode), str(self.diffusion_steps),
            str(self.voice_character), str(self.custom_semitones),
            str(self.post_conversion_pitch_enabled), str(self.post_conversion_semitones),
        ))
        return int(hashlib.sha256(raw.encode('utf-8', errors='replace')).hexdigest()[:8], 16) & 0x7fffffff

    @classmethod
    def speech_pitch_filter(cls, voice_character, semitones):
        """Return a duration-preserving Rubber Band filter for spoken voice.

        This is intentionally separate from Seed-VC F0: ordinary dialog must
        not use the singing model merely because a voice-character preset has
        a non-zero pitch adjustment.
        """
        try:
            shift = max(-6, min(6, int(semitones or 0)))
        except (TypeError, ValueError):
            shift = 0
        if not shift:
            return ''
        ratio = 2.0 ** (shift / 12.0)
        formant = cls.VOICE_CHARACTER_FORMANT_MODE.get(str(voice_character or ''), 'preserved')
        return ('rubberband=pitch={:.9f}:tempo=1:transients=smooth:detector=soft:'
                'phase=laminar:formant={}:pitchq=quality:channels=together').format(ratio, formant)

    def _apply_speech_voice_character_pitch(self, input_audio, output_audio, semitones):
        """Apply a real spoken-voice character pitch adjustment after Seed-VC.

        Rubber Band keeps duration unchanged and is available in the bundled
        FFmpeg used by the workstation.  A standard-filter fallback still
        honours the user's setting on a reduced FFmpeg build instead of
        silently ignoring the preset.
        """
        pitch_filter = self.speech_pitch_filter(self.voice_character, semitones)
        if not pitch_filter:
            return input_audio
        rendered = self._run([
            'ffmpeg', '-y', '-hide_banner', '-i', input_audio, '-af', pitch_filter,
            '-ac', '1', '-ar', '44100', output_audio
        ], 1200)
        if rendered.returncode == 0 and os.path.isfile(output_audio):
            mode = self.VOICE_CHARACTER_FORMANT_MODE.get(self.voice_character, 'preserved')
            self.log.emit(f'普通口播目标声线已应用：{semitones:+d} 半音｜共振{("随音高调整" if mode == "shifted" else "保持自然")}｜保持原时长。', 'green')
            return output_audio
        # Standard FFmpeg fallback: pitch then compensate tempo.  Note that
        # asetrate/aresample changes the effective duration before atempo;
        # the old 1/ratio compensation was wrong and shortened transformed
        # audio, which could in turn desynchronise/cut the final video.
        ratio = 2.0 ** (float(semitones) / 12.0)
        fallback = f'asetrate=44100*{ratio:.9f},aresample=44100,atempo={1.0 / (ratio * ratio):.9f}'
        fallback_rendered = self._run([
            'ffmpeg', '-y', '-hide_banner', '-i', input_audio, '-af', fallback,
            '-ac', '1', '-ar', '44100', output_audio
        ], 1200)
        if fallback_rendered.returncode == 0 and os.path.isfile(output_audio):
            self.log.emit(f'普通口播目标声线已应用：{semitones:+d} 半音（兼容变调链路，建议安装含 Rubber Band 的 FFmpeg 以获得更自然共振）。', 'orange')
            return output_audio
        self.log.emit('目标声线音高调整失败，已保留 Seed-VC 原始人声：' + ((fallback_rendered.stderr or rendered.stderr or '')[-400:]), 'orange')
        return input_audio

    def _voice_finish_summary(self):
        """Human-readable, bounded post-conversion vocal finishing parameters."""
        values = {
            '明亮度': self.voice_brightness, '温暖度': self.voice_warmth,
            '清晰度': self.voice_presence, '齿音抑制': self.voice_deess,
            '空气感': self.voice_air,
        }
        changed = [f'{name}{value:+d}dB' for name, value in values.items() if value]
        if self.voice_highpass: changed.append(f'高通 {self.voice_highpass}Hz')
        if self.voice_lowpass < 20000: changed.append(f'低通 {self.voice_lowpass}Hz')
        if self.voice_compression: changed.append(f'压缩 {self.voice_compression}%')
        if self.voice_output_gain: changed.append(f'输出增益 {self.voice_output_gain:+d}dB')
        return '自然不修饰' if not changed else '｜'.join(changed)

    def _apply_voice_finishing(self, input_audio, output_audio):
        """Apply conservative EQ/dynamics to the converted vocal only.

        This deliberately avoids optional third-party FFmpeg filters such as
        rubberband or deesser: a standard FFmpeg build can render the same
        project on another computer.  It is a finishing stage, never claimed
        to synthesize an age, gender, or vocal tract that is absent from the
        reference recording.
        """
        if not any((self.voice_brightness, self.voice_warmth, self.voice_presence,
                    self.voice_deess, self.voice_air, self.voice_highpass,
                    self.voice_lowpass < 20000, self.voice_compression,
                    self.voice_output_gain)):
            return input_audio
        filters = self.voice_finishing_filters({
            'voice_brightness': self.voice_brightness, 'voice_warmth': self.voice_warmth,
            'voice_presence': self.voice_presence, 'voice_deess': self.voice_deess,
            'voice_air': self.voice_air, 'voice_highpass': self.voice_highpass,
            'voice_lowpass': self.voice_lowpass, 'voice_compression': self.voice_compression,
            'voice_output_gain': self.voice_output_gain,
        })
        rendered = self._run([
            'ffmpeg', '-y', '-hide_banner', '-i', input_audio,
            '-af', ','.join(filters), '-ac', '1', '-ar', '44100', output_audio
        ], 1200)
        if rendered.returncode != 0 or not os.path.isfile(output_audio):
            self.log.emit('目标声线母版精修失败，已安全使用 Seed-VC 原始人声：' + (rendered.stderr or '')[-400:], 'orange')
            return input_audio
        return output_audio

    @staticmethod
    def voice_finishing_filters(values):
        """Return an FFmpeg-standard filter chain shared by preview and export."""
        def number(key, default=0, lower=-99999, upper=99999):
            try: return max(lower, min(upper, int(values.get(key, default) or default)))
            except (TypeError, ValueError): return default
        brightness = number('voice_brightness', 0, -6, 6)
        warmth = number('voice_warmth', 0, -6, 6)
        presence = number('voice_presence', 0, -6, 6)
        deess = number('voice_deess', 0, 0, 6)
        air = number('voice_air', 0, -6, 6)
        highpass = number('voice_highpass', 0, 0, 180)
        lowpass = number('voice_lowpass', 20000, 3000, 20000)
        compression = number('voice_compression', 0, 0, 100)
        output_gain = number('voice_output_gain', 0, -12, 12)
        filters = []
        # Low-mid warmth, intelligibility presence, and two high-frequency bands.
        # q values are intentionally broad to prevent a harsh, ringing sound.
        if warmth: filters.append(f'equalizer=f=190:t=q:w=1.15:g={warmth}')
        if presence: filters.append(f'equalizer=f=3200:t=q:w=1.25:g={presence}')
        if brightness: filters.append(f'equalizer=f=7200:t=q:w=0.85:g={brightness}')
        if deess: filters.append(f'equalizer=f=6800:t=q:w=2.2:g=-{deess}')
        if air: filters.append(f'equalizer=f=11200:t=q:w=0.72:g={air}')
        if highpass: filters.append(f'highpass=f={highpass}:poles=2')
        if lowpass < 20000: filters.append(f'lowpass=f={lowpass}:poles=2')
        # 0% disables compression.  The range is mapped conservatively so this
        # remains transparent for dialog and does not crush musical phrasing.
        if compression:
            ratio = 1.15 + (compression / 100.0) * 2.35
            filters.append(f'acompressor=threshold=0.18:ratio={ratio:.2f}:attack=12:release=110:makeup=1')
        if output_gain: filters.append(f'volume={output_gain}dB')
        filters.append('alimiter=limit=0.96')
        return filters

    def run(self):
        temporary_root = ''
        acquired = False
        try:
            # 工作流与独立入口共用队列，避免同时抢占模型/显存；停止等待不会误释放他人的锁。
            acquired = self._replacement_lock.acquire(blocking=False)
            if not acquired:
                self.log.emit('另一个人声替换任务正在执行，本任务在后台排队等待；界面仍可操作。', 'orange')
            while not acquired:
                if self._stop_requested:
                    raise RuntimeError('已停止排队中的人声替换任务')
                acquired = self._replacement_lock.acquire(timeout=0.2)
            if self._stop_requested:
                raise RuntimeError('已停止人声替换任务')
            temporary_root = tempfile.mkdtemp(prefix='videotaskhub_seed_vc_job_')
            # 缓存目录若被用户在资源管理器中误删，任务开始前自动重建；
            # 模型文件如已被删除会按现有下载机制补齐，但绝不静默改到未知位置。
            if not self.hf_cache_path:
                self.hf_cache_path = os.path.abspath(os.path.join(os.path.dirname(self.seed_root), 'seed-vc-model-cache'))
            try:
                os.makedirs(self.hf_cache_path, exist_ok=True)
            except Exception as exc:
                raise RuntimeError(f'模型缓存目录无法使用：{self.hf_cache_path}\n请在“模型缓存目录”中选择本地或网络共享文件夹。\n{exc}')
            environment_changed = self._install_or_repair()
            if environment_changed:
                # 首次安装/修复可能刚把 CPU Torch 替换为 CUDA Torch；旧的“不可用”
                # 诊断结果必须失效一次，随后本轮会缓存新的真实结果。
                self.invalidate_cuda_cache(self.python_path)
            os.makedirs(temporary_root, exist_ok=True)
            remote_source = any(self._remote_uri(path) for path in self.source_paths)
            remote_output = self._remote_uri(self.output_dir)
            if remote_source and (self.same_dir_output or self.sibling_dir_output):
                raise RuntimeError('远程视频来源不能使用“素材所在目录”或“源目录同级目录”输出。请选择统一输出目录，并填写本地或 SFTP 输出位置。')
            if self._remote_uri(self.reference_audio):
                self.reference_audio = self._sftp_download(self.reference_audio, os.path.join(temporary_root, 'reference'))
            if not os.path.isfile(self.reference_audio): raise FileNotFoundError('目标音色参考音频不存在。')
            # 在任务私有目录保存可读 PCM 快照；推理不再直接依赖可被其他任务改动的参考文件。
            reference_snapshot = os.path.join(temporary_root, 'reference_snapshot.wav')
            prepared = self._run(['ffmpeg', '-y', '-hide_banner', '-i', self.reference_audio,
                                  '-map', '0:a:0', '-vn', '-ac', '2', '-ar', '44100',
                                  '-c:a', 'pcm_s16le', reference_snapshot], 600)
            if prepared.returncode != 0:
                raise RuntimeError('参考音频无法读取或转换：' + self.reference_audio + '\n' + (prepared.stderr or '')[-1000:])
            with wave.open(reference_snapshot, 'rb') as reference_file:
                if reference_file.getnframes() <= 0:
                    raise RuntimeError('参考音频为空：' + self.reference_audio)
            self.reference_audio = reference_snapshot
            resolved_sources = []
            for number, source in enumerate(self.source_paths, 1):
                if self._stop_requested:
                    raise RuntimeError('已停止远程下载')
                if self._remote_uri(source):
                    resolved_sources.append(self._sftp_download(source, os.path.join(temporary_root, f'source_{number:03d}')))
                else:
                    resolved_sources.append(source)
            self.source_paths = resolved_sources
            if remote_output:
                # Seed-VC 和 ffmpeg 必须写本地文件；单个任务结束后立即上传成片。
                self.output_dir = os.path.join(temporary_root, 'remote_output')
            media_items = self._media_items()
            if not media_items: raise RuntimeError('来源中没有可处理的视频或音频。')
            if not self.same_dir_output and not self.sibling_dir_output: os.makedirs(self.output_dir, exist_ok=True)
            cuda = self._device_is_cuda()
            quality_label, steps, audio_bitrate = self._effective_quality(cuda)
            self.log.emit(f'音质档位：{quality_label}｜推理步数：{steps}｜输出音频：AAC {audio_bitrate}｜设备：' + ('GPU' if cuda else 'CPU FP32（保持所选质量，耗时会更长）'), 'green' if cuda else 'orange')
            if not cuda:
                cpu_total, cpu_budget = self._cpu_thread_budget()
                self.log.emit(f'CPU 推理资源：{self.cpu_usage_percent}%｜线程预算：{cpu_budget}/{cpu_total}。已同步给 PyTorch / OpenMP / MKL 等计算库；个别模型阶段仍可能无法占满全部核心。', 'blue')
            character_label, character_shift, character_note = self._voice_character_pitch_shift()
            final_pitch_shift = character_shift + (self.post_conversion_semitones if self.post_conversion_pitch_enabled else 0)
            final_pitch_shift = max(-6, min(6, final_pitch_shift))
            self.log.emit(
                f'目标声线优化：{character_label}｜预设建议成片后调整：{character_shift:+d} 半音。{character_note}',
                'green' if character_shift else 'gray'
            )
            if self.post_conversion_pitch_enabled:
                self.log.emit(f'成片后音调微调已启用：{self.post_conversion_semitones:+d} 半音；与预设合计 {final_pitch_shift:+d} 半音。只作用于 Seed-VC 转换完成的人声，不会预先改变参考声线。', 'green')
            self.log.emit('目标声线母版精修：' + self._voice_finish_summary() + '（仅转换后人声，不影响背景音乐）', 'green' if self._voice_finish_summary() != '自然不修饰' else 'gray')
            # 甜美女声、轻声与高音区最怕参考里混入伴奏、和声或环境声：这些会让
            # 声纹特征向中性/低沉漂移。参考人声净化应同时适用于口播和歌曲，不能
            # 再仅在歌曲模式中生效。
            if self.preserve_background or self.clean_reference:
                self._ensure_vocal_separator()
            seed_target_audio = self.reference_audio
            if self.clean_reference:
                # Seed-VC 会将目标参考的前 25 秒直接用于语义和声纹提示。歌曲参考
                # 含伴奏/和声时会污染目标声纹，先仅保留参考人声能明显减轻漂移。
                reference_work = os.path.join(temporary_root, 'reference_clean')
                os.makedirs(reference_work, exist_ok=True)
                reference_mix = os.path.join(reference_work, 'reference_mix.wav')
                reference_extract = self._run(['ffmpeg', '-y', '-hide_banner', '-i', self.reference_audio, '-map', '0:a:0', '-vn', '-ac', '2', '-ar', '44100', reference_mix], 600)
                if reference_extract.returncode != 0:
                    self.log.emit('参考音频预处理失败，已安全使用原参考音频：' + (reference_extract.stderr or '')[-300:], 'orange')
                else:
                    try:
                        reference_vocals, reference_background = self._separate_vocals(reference_mix, reference_work, cuda)
                        if self._should_use_cleaned_reference(reference_vocals, reference_background):
                            cleaned_reference = os.path.join(reference_work, 'reference_vocals.wav')
                            normalize_reference = self._run(['ffmpeg', '-y', '-hide_banner', '-i', reference_vocals, '-ac', '1', '-ar', '44100', cleaned_reference], 600)
                            if normalize_reference.returncode == 0 and os.path.isfile(cleaned_reference):
                                seed_target_audio = cleaned_reference
                                self.log.emit('参考人声净化完成：已去除检测到的伴奏/环境声，目标声纹将以纯人声提取。', 'green')
                            else:
                                self.log.emit('参考人声净化未生成可用音频，已安全使用原参考音频。', 'orange')
                    except Exception as exc:
                        self.log.emit(f'参考人声净化失败，已安全使用原参考音频：{exc}', 'orange')
            self._batch_total, self._batch_index = len(media_items), 0
            self.log.emit(f'已找到 {len(media_items)} 个视频/音频素材；开始 Seed-VC 人声替换。', 'blue')
            if self.song_mode:
                self.log.emit('歌曲模式已启用：将保留原唱的音高曲线、旋律走向与唱腔节奏。', 'green')
            else:
                self.log.emit('普通语音模式：如来源是歌曲，请勾选“歌曲模式”以保留旋律与音高。', 'gray')
                if final_pitch_shift:
                    self.log.emit(f'普通口播目标声线：Seed-VC 将保持普通语音模型；转换完成后会实际执行 {final_pitch_shift:+d} 半音的保持时长变调，不启用歌曲 F0。', 'green')
            cache_hint = self.hf_cache_path or os.path.join(self.seed_root, 'checkpoints')
            try:
                cached_files = sum(1 for _root, _dirs, names in os.walk(cache_hint) for name in names if name.lower().endswith(('.bin', '.pt', '.pth', '.safetensors', '.ckpt')))
            except Exception:
                cached_files = 0
            if not cached_files:
                self.log.emit(f'首次模型下载准备：本地缓存暂未发现模型文件。Seed-VC 即将从 Hugging Face/官方源下载模型，下载进度与详情会持续显示；请勿关闭窗口。缓存位置：{cache_hint}', 'orange')
            else:
                self.log.emit(f'检测到本地模型缓存（{cached_files} 个模型文件）：{cache_hint}。仍可能补充少量缺失模型。', 'green')
            self._batch_progress_ready = True
            for self._batch_index, source in enumerate(media_items, 1):
                if self._stop_requested: break
                work = os.path.join(temporary_root, f'{self._batch_index:05d}'); os.makedirs(work, exist_ok=True)
                original_mix = os.path.join(work, 'original_mix.wav')
                source_wav, converted_dir = os.path.join(work, 'source_vocal.wav'), os.path.join(work, 'converted')
                os.makedirs(converted_dir, exist_ok=True)
                # 始终保留原始立体声混音作为背景音来源；不能再把整条混音当成“人声”。
                extract = self._run(['ffmpeg', '-y', '-hide_banner', '-i', source, '-map', '0:a:0', '-vn', '-ac', '2', '-ar', '44100', original_mix], 600)
                if extract.returncode != 0: raise RuntimeError(f'提取音频失败：{os.path.basename(source)}\n' + (extract.stderr or '')[-1000:])
                background_wav = ''
                # 高保真档位只改变扩散步数和 AAC 码率。F0/44.1k 歌曲模型只在
                # 用户明确勾选“歌曲模式”时才允许启用：普通口播若被强行送入
                # F0 自动校音链路，会破坏自然语调和目标声线。
                preserve_target_pitch = bool(self.song_mode)
                voice_sample_rate = '44100' if preserve_target_pitch else '22050'
                if self.preserve_background:
                    vocals_wav, background_wav = self._separate_vocals(original_mix, work, cuda)
                    # 普通口播的分离人声常带有水声、相位抖动或编码毛刺。这些
                    # 伪影一旦送入扩散模型会被放大成“破损嗓音”。因此默认用原始
                    # 音轨作为转换输入；Demucs 仅负责生成待混回的背景轨。歌曲
                    # 或用户明确关闭此保护时，才用分离后人声作为模型输入。
                    conversion_input = vocals_wav if (preserve_target_pitch or not self.speech_use_original_mix) else original_mix
                    source_kind = '分离人声（歌曲/F0 链路）' if conversion_input == vocals_wav else '原始音轨（口播防分离伪影）'
                    vocal_extract = self._run(['ffmpeg', '-y', '-hide_banner', '-i', conversion_input, '-ac', '1', '-ar', voice_sample_rate, source_wav], 600)
                    if vocal_extract.returncode != 0:
                        raise RuntimeError(f'提取{source_kind}失败：{os.path.basename(source)}\n' + (vocal_extract.stderr or '')[-1000:])
                    self.log.emit(f'转换输入：{source_kind}；背景分离轨只用于最后混回。', 'green')
                else:
                    vocal_extract = self._run(['ffmpeg', '-y', '-hide_banner', '-i', original_mix, '-ac', '1', '-ar', voice_sample_rate, source_wav], 600)
                    if vocal_extract.returncode != 0:
                        raise RuntimeError(f'提取人声音频失败：{os.path.basename(source)}\n' + (vocal_extract.stderr or '')[-1000:])
                # F0 只负责保留来源旋律/唱腔，绝不拿目标声线预设去预先升降参考
                # 音高。所有预设及用户的“成片后音调微调”均在 Seed-VC 完成后
                # 处理转换出的人声，避免把参考提示扭成电音。
                effective_pitch_shift = 0
                inference_seed = self._stable_inference_seed(source)
                command = [self.python_path, os.path.join(self.seed_root, 'inference.py'), '--source', source_wav, '--target', seed_target_audio,
                           '--output', converted_dir, '--diffusion-steps', str(steps), '--length-adjust', '1.0', '--f0-condition', str(preserve_target_pitch),
                           '--auto-f0-adjust', str(preserve_target_pitch), '--semi-tone-shift', str(effective_pitch_shift), '--seed', str(inference_seed), '--fp16', str(cuda)]
                self.log.emit(f'本次扩散随机种子：{inference_seed}（相同源文件、参考与设置将稳定复现相同结果）。', 'gray')
                if preserve_target_pitch:
                    self.log.emit('歌曲模式：使用 44.1kHz F0 模型保留原唱旋律与音高中心；目标声线预设及成片后音调微调将在转换完成后作用于人声。', 'green')
                else:
                    self.log.emit('普通口播链路：已关闭 F0 与自动音高调整；高保真仅保持当前扩散步数和 AAC 输出质量。', 'green')
                self.log.emit(f'[{self._batch_index}/{len(media_items)}] 正在转换人声：{os.path.basename(source)}', 'gray')
                code, output = self._stream(command, 3600, cpu=not cuda, activity_hint='正在转换人声（扩散推理）')
                # A user may point the system setting to an older external
                # Seed-VC checkout.  It will not understand our new --seed
                # argument; keep conversion usable and explain why that old
                # checkout cannot reproduce diffusion output until updated.
                seed_argument_error = ('--seed' in str(output) and ('unrecognized arguments' in str(output).lower() or 'no such option' in str(output).lower()))
                if code != 0 and seed_argument_error:
                    seed_index = command.index('--seed')
                    del command[seed_index:seed_index + 2]
                    self.log.emit('当前自定义 Seed-VC 项目版本不支持固定随机种子；已兼容运行，但建议使用工作站内置/最新版 Seed-VC 以获得可复现声线。', 'orange')
                    code, output = self._stream(command, 3600, cpu=not cuda, activity_hint='正在转换人声（扩散推理）')
                audio_read_error = any(marker in str(output).lower() for marker in
                                       ('nobackenderror', 'filenotfounderror', 'libsndfileerror', 'error opening', 'format not recognised'))
                if code != 0 and cuda and not self._stop_requested and not audio_read_error:
                    self.log.emit('GPU 推理失败，自动改用 CPU FP32 重试此视频。', 'orange')
                    command[-1] = 'False'
                    code, output = self._stream(command, 7200, cpu=True, activity_hint='正在以 CPU 保持原扩散步数转换人声（扩散推理）')
                if code != 0: raise RuntimeError(f'Seed-VC 推理失败：{os.path.basename(source)}\n{output[-1600:]}')
                audio_files = [os.path.join(root, name) for root, _dirs, names in os.walk(converted_dir) for name in names if name.lower().endswith(('.wav', '.flac', '.mp3'))]
                if not audio_files: raise RuntimeError(f'Seed-VC 未生成输出音频：{os.path.basename(source)}')
                converted = max(audio_files, key=os.path.getmtime)
                character_vocal = converted
                if final_pitch_shift:
                    character_vocal = self._apply_speech_voice_character_pitch(
                        converted, os.path.join(work, 'character_vocal.wav'), final_pitch_shift
                    )
                finished_vocal = self._apply_voice_finishing(character_vocal, os.path.join(work, 'finished_vocal.wav'))
                final_audio = finished_vocal
                if self.preserve_background:
                    final_audio = os.path.join(work, 'mixed_audio.wav')
                    # Demucs 的 no_vocals 可能含少量原说话人残留。背景先降低
                    # 到安全比例，再由转换人声作 sidechain 强力压低说话时段，
                    # 防止原说话人与 Seed-VC 人声叠加造成破损、金属或变老。
                    mix = self._run([
                        'ffmpeg', '-y', '-hide_banner', '-i', background_wav, '-i', finished_vocal,
                        '-filter_complex', '[0:a]volume=0.72[bg];[bg][1:a]sidechaincompress=threshold=0.012:ratio=20:attack=2:release=320:makeup=1[ducked];[ducked][1:a]amix=inputs=2:duration=longest:normalize=0,alimiter=limit=0.97[mix]',
                        '-map', '[mix]', '-ac', '2', '-ar', '44100', final_audio
                    ], 1200)
                    if mix.returncode != 0:
                        raise RuntimeError(f'混回背景音乐与环境音失败：{os.path.basename(source)}\n' + (mix.stderr or '')[-1200:])
                    self.log.emit('声线优先混音完成：背景轨已预衰减，并在说话期间强力压低，减少原人声残留对目标声线的干扰。', 'green')
                final_audio = self._match_output_loudness(original_mix, final_audio, os.path.join(work, 'level_matched_audio.wav'))
                if self.same_dir_output:
                    stem, ext = os.path.splitext(os.path.basename(source)); target = os.path.join(os.path.dirname(source), stem + self.output_suffix + ext)
                elif self.sibling_dir_output:
                    target = self._sibling_output_target(source)
                else:
                    source_roots = [path if os.path.isdir(path) else os.path.dirname(path) for path in self.source_paths]
                    try:
                        common_root = os.path.commonpath(source_roots)
                    except ValueError:
                        # 多盘符/多个网络共享同时处理时没有共同祖先；保留文件名即可，
                        # 并让后面的防覆盖逻辑自动生成序号。
                        common_root = os.path.dirname(source)
                    relative = os.path.relpath(source, common_root); target = os.path.join(self.output_dir, relative)
                if os.path.normcase(target) == os.path.normcase(source): raise RuntimeError('输出路径不能覆盖原视频。')
                # 已存在的成片绝不静默覆盖；批量重复运行自动生成 _2、_3…版本。
                if os.path.exists(target):
                    folder, name = os.path.dirname(target), os.path.basename(target)
                    stem, ext = os.path.splitext(name); serial = 2
                    while os.path.exists(os.path.join(folder, f'{stem}_{serial}{ext}')):
                        serial += 1
                    target = os.path.join(folder, f'{stem}_{serial}{ext}')
                os.makedirs(os.path.dirname(target), exist_ok=True)
                is_video = source.lower().endswith(self.VIDEO_EXTS)
                if is_video:
                    # Converted dialogue can be a fraction shorter than the
                    # source container. Pad only the tail silence, then stop
                    # at the original video end: never trim the final frame.
                    mux = self._run(['ffmpeg', '-y', '-hide_banner', '-i', source, '-i', final_audio, '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-c:a', 'aac', '-b:a', audio_bitrate, '-ac', '2', '-af', 'apad', '-shortest', target], 1200)
                    failure_label = '合成视频失败'
                else:
                    ext = os.path.splitext(target)[1].lower()
                    codec_map = {'.wav': 'pcm_s16le', '.flac': 'flac', '.mp3': 'libmp3lame', '.ogg': 'libvorbis', '.opus': 'libopus', '.wma': 'wmav2'}
                    codec = codec_map.get(ext, 'aac')
                    audio_command = ['ffmpeg', '-y', '-hide_banner', '-i', final_audio, '-c:a', codec]
                    if codec in ('aac', 'libmp3lame', 'libvorbis', 'libopus'):
                        audio_command.extend(['-b:a', audio_bitrate])
                    audio_command.extend(['-ac', '2', target])
                    mux = self._run(audio_command, 1200)
                    failure_label = '导出替换人声后的音频失败'
                if mux.returncode != 0: raise RuntimeError(f'{failure_label}：{os.path.basename(source)}\n' + (mux.stderr or '')[-1200:])
                if remote_output:
                    relative_target = os.path.relpath(target, self.output_dir)
                    uploaded_target = self._sftp_upload(remote_output.geturl(), target, relative_target)
                    self.log.emit(f'远程输出完成：{uploaded_target}', 'green')
                self.progress.emit(int(self._batch_index * 100 / len(media_items))); self.log.emit(f'已输出：{target}', 'green')
            self.finished_all.emit()
        except Exception as exc:
            self.failed.emit(str(exc))
        finally:
            try:
                if temporary_root:
                    shutil.rmtree(temporary_root, ignore_errors=True)
            except Exception:
                pass
            finally:
                if acquired:
                    self._replacement_lock.release()


class SeedVCSetupThread(SeedVCBatchThread):
    """仅恢复 Seed-VC 项目与依赖，不要求用户先填写待处理媒体。"""
    setup_finished = pyqtSignal(bool, str)

    def __init__(self, seed_root, hf_cache_path='', parent=None):
        super().__init__(seed_root, '', [], '', auto_install=True, hf_cache_path=hf_cache_path, parent=parent)

    def run(self):
        try:
            if not self.hf_cache_path:
                self.hf_cache_path = os.path.abspath(os.path.join(os.path.dirname(self.seed_root), 'seed-vc-model-cache'))
            os.makedirs(self.hf_cache_path, exist_ok=True)
            self.log.emit('检测到 Seed-VC 环境未完成，正在从上次中断处继续安装…', 'blue')
            changed = self._install_or_repair()
            if changed:
                self.invalidate_cuda_cache(self.python_path)
            self.setup_finished.emit(True, 'Seed-VC 运行环境已就绪。现在可开始批量替换人声。')
        except Exception as exc:
            self.setup_finished.emit(False, 'Seed-VC 自动续装未完成：' + str(exc))


class VideoThumbnailCache:
    """视频审核用的受限缩略图缓存。

    缩略图绝不写回素材目录，也不经由播放器解码。缓存键包含路径、文件大小与
    修改时间，源视频被替换后会自然失效；总容量达到上限时清理最久未使用项。
    """
    MAX_BYTES = 500 * 1024 * 1024
    _prune_lock = Lock()
    _last_prune_at = 0.0

    @classmethod
    def folder(cls):
        path = os.path.join(USER_DATA_DIR, 'thumbnail_cache_v1')
        os.makedirs(path, exist_ok=True)
        return path

    @classmethod
    def output_path(cls, video_path):
        stat = os.stat(video_path)
        normalized = os.path.normcase(os.path.abspath(video_path))
        key = f'v1|{normalized}|{stat.st_mtime_ns}|{stat.st_size}'
        token = hashlib.sha256(key.encode('utf-8', errors='replace')).hexdigest()
        return os.path.join(cls.folder(), f'{token}.jpg')

    @classmethod
    def touch(cls, path):
        try:
            now = time.time()
            os.utime(path, (now, now))
        except Exception:
            pass

    @classmethod
    def prune_if_needed(cls, force=False):
        """最多每 10 分钟扫一次；避免加载审核表时对磁盘产生额外压力。"""
        now = time.monotonic()
        with cls._prune_lock:
            if not force and now - cls._last_prune_at < 600:
                return
            cls._last_prune_at = now
            try:
                entries = []
                total = 0
                for entry in os.scandir(cls.folder()):
                    if not entry.is_file() or not entry.name.lower().endswith('.jpg'):
                        continue
                    try:
                        stat = entry.stat()
                        total += stat.st_size
                        entries.append((stat.st_atime or stat.st_mtime, stat.st_size, entry.path))
                    except OSError:
                        continue
                if total <= cls.MAX_BYTES:
                    return
                for _used_at, size, path in sorted(entries, key=lambda item: item[0]):
                    try:
                        os.remove(path)
                        total -= size
                    except OSError:
                        pass
                    if total <= cls.MAX_BYTES:
                        break
            except Exception:
                pass

    @classmethod
    def get_or_create(cls, video_path, run_command, cancelled=None):
        """返回缓存图；调用方必须在后台线程中执行本方法。"""
        try:
            if cancelled is not None and cancelled():
                return ''
            output = cls.output_path(video_path)
            if os.path.isfile(output) and os.path.getsize(output) >= 512:
                cls.touch(output)
                return output
            temporary = output + f'.{os.getpid()}.{threading.get_ident()}.tmp.jpg'
            try:
                if os.path.isfile(temporary):
                    os.remove(temporary)
            except OSError:
                pass
            # 0.35 秒通常已跨过容器开头的黑帧，同时仍能代表短视频的开场画面。
            result = run_command([
                'ffmpeg', '-y', '-hide_banner', '-ss', '0.35', '-i', video_path,
                '-frames:v', '1', '-vf', 'scale=320:-2:force_original_aspect_ratio=decrease',
                '-q:v', '5', temporary,
            ], 25)
            if cancelled is not None and cancelled():
                try: os.remove(temporary)
                except OSError: pass
                return ''
            if result.returncode != 0 or not os.path.isfile(temporary) or os.path.getsize(temporary) < 512:
                try: os.remove(temporary)
                except OSError: pass
                return ''
            os.replace(temporary, output)
            cls.touch(output)
            cls.prune_if_needed()
            return output
        except Exception:
            return ''


class ManualFolderCoverThread(QThread):
    """人工对位中由用户手动触发的当前目录封面图生成器。"""
    progress = pyqtSignal(int, int, str, bool)
    completed = pyqtSignal(int, int, object, bool)

    def __init__(self, video_paths, parent=None):
        super().__init__(parent)
        self.video_paths = [os.path.abspath(str(path or '')) for path in (video_paths or []) if os.path.isfile(str(path or ''))]
        self._cancel_requested = Event()

    def cancel(self):
        self._cancel_requested.set()

    def _run_ffmpeg(self, command, timeout):
        try:
            return subprocess.run(
                command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                timeout=timeout, **_subprocess_no_window_kwargs(),
            )
        except Exception:
            return subprocess.CompletedProcess(command, 1)

    def run(self):
        completed_paths = []
        total = len(self.video_paths)
        finished = 0
        for path in self.video_paths:
            if self._cancel_requested.is_set():
                break
            cover_path = VideoThumbnailCache.get_or_create(
                path, self._run_ffmpeg, self._cancel_requested.is_set,
            )
            if cover_path:
                completed_paths.append(path)
            finished += 1
            self.progress.emit(finished, total, path, bool(cover_path))
        self.completed.emit(finished, total, completed_paths, self._cancel_requested.is_set())


class ManualAuditRemoteSourceResolveThread(QThread):
    """将审核页面的远程媒体/CSV 安全落到一次性本地工作区。

    审核器和 ffmpeg 只接收本地文件。这里刻意不把 URL 交给播放器，也不修改
    远端来源；每次加载审核队列才下载，下一次加载或退出软件时统一释放工作区。
    """
    resolved = pyqtSignal(object, str, str)  # 媒体本地路径、CSV 本地路径、临时目录
    progress = pyqtSignal(str)
    failed = pyqtSignal(str)

    def __init__(self, media_input, csv_input='', parent=None):
        super().__init__(parent)
        self.media_input = str(media_input or '')
        self.csv_input = str(csv_input or '').strip()
        self._stop_requested = False

    def request_stop(self):
        self._stop_requested = True

    @staticmethod
    def _remote_uri(value):
        parsed = urllib.parse.urlparse(str(value or '').strip())
        return parsed if parsed.scheme.lower() in ('sftp', 'ssh') and parsed.hostname else None

    def _connect(self, uri):
        try:
            import paramiko
        except ImportError:
            # 远程审核是用户主动触发的功能；首次仅补装这一项安全传输依赖，
            # 不影响 Seed-VC 的隔离环境，也不改动任何媒体文件。
            self.progress.emit('首次使用 SFTP/SSH：正在后台安装安全传输组件…')
            result = subprocess.run(
                [sys.executable, '-m', 'pip', 'install', 'paramiko==5.1.0'],
                capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=1200,
                **_subprocess_no_window_kwargs(),
            )
            if result.returncode != 0:
                detail = (result.stderr or result.stdout or '').strip()[-700:]
                raise RuntimeError('安全传输组件安装失败。请检查网络后重试。\n' + detail)
            try:
                import paramiko
            except ImportError as exc:
                raise RuntimeError('安全传输组件安装后仍无法加载，请重启软件后重试。') from exc
        from urllib.parse import parse_qs, unquote, urlparse
        parsed = urlparse(uri)
        query = parse_qs(parsed.query)
        key_file = unquote(str(query.get('key', [''])[0] or '')).strip() or None
        if key_file and not os.path.isfile(key_file):
            raise FileNotFoundError(f'SSH 私钥文件不存在：{key_file}')
        username = unquote(parsed.username or '') or os.environ.get('USERNAME', '')
        password = unquote(parsed.password or '') or None
        port = int(parsed.port or 22)
        self.progress.emit(f'正在连接远程来源：{username}@{parsed.hostname}:{port}…')
        client = paramiko.SSHClient()
        client.load_system_host_keys()
        # 远程来源同样必须由系统 known_hosts 明确授权。
        client.set_missing_host_key_policy(paramiko.RejectPolicy())
        client.connect(parsed.hostname, port=port, username=username, password=password,
                       key_filename=key_file, allow_agent=True, look_for_keys=True,
                       timeout=25, banner_timeout=25, auth_timeout=25)
        return client, client.open_sftp(), unquote(parsed.path or '/') or '/'

    def _download_remote(self, uri, local_root, label):
        import posixpath
        import stat
        client = sftp = None
        try:
            client, sftp, remote_path = self._connect(uri)
            remote_path = posixpath.normpath(remote_path)
            info = sftp.stat(remote_path)
            def download_file(remote_file, local_file, size=0):
                os.makedirs(os.path.dirname(local_file), exist_ok=True)
                last = [-1]
                def callback(done, total):
                    if self._stop_requested:
                        raise RuntimeError('已停止远程下载')
                    percent = int(max(0, min(100, done * 100 / (total or size or 1))))
                    if percent != last[0] and (percent in (0, 100) or percent - last[0] >= 5):
                        last[0] = percent
                        self.progress.emit(f'远程下载 {label}：{os.path.basename(remote_file)} {percent}%')
                sftp.get(remote_file, local_file, callback=callback)
            def download_tree(remote_dir, local_dir):
                os.makedirs(local_dir, exist_ok=True)
                for item in sftp.listdir_attr(remote_dir):
                    if self._stop_requested:
                        raise RuntimeError('已停止远程下载')
                    remote_child = posixpath.join(remote_dir, item.filename)
                    local_child = os.path.join(local_dir, item.filename)
                    if stat.S_ISDIR(item.st_mode):
                        download_tree(remote_child, local_child)
                    elif stat.S_ISREG(item.st_mode):
                        download_file(remote_child, local_child, item.st_size)
            self.progress.emit(f'正在下载远程{label}到隔离审核工作区：{remote_path}')
            if stat.S_ISDIR(info.st_mode):
                target = os.path.join(local_root, os.path.basename(remote_path.rstrip('/')) or 'remote_media')
                download_tree(remote_path, target)
            else:
                target = os.path.join(local_root, os.path.basename(remote_path) or 'remote_file')
                download_file(remote_path, target, info.st_size)
            return target
        finally:
            try:
                if sftp: sftp.close()
                if client: client.close()
            except Exception:
                pass

    def run(self):
        temporary_root = ''
        try:
            media_paths = []
            raw_media = SeedVCBatchThread.split_source_inputs(self.media_input)
            if not raw_media:
                raise RuntimeError('请先填写视频、音频文件或目录。')
            has_remote = any(self._remote_uri(value) for value in raw_media) or bool(self._remote_uri(self.csv_input))
            if has_remote:
                temporary_root = tempfile.mkdtemp(prefix='videotaskhub_audit_')
            for index, raw in enumerate(raw_media, 1):
                if self._stop_requested:
                    raise RuntimeError('已停止加载')
                if self._remote_uri(raw):
                    media_paths.append(self._download_remote(raw, os.path.join(temporary_root, f'media_{index:03d}'), '媒体'))
                else:
                    path = normalize_user_path(raw)
                    if os.path.isfile(path) or os.path.isdir(path):
                        media_paths.append(path)
                    else:
                        raise FileNotFoundError(f'来源不存在或当前无法访问：{raw}')
            csv_path = ''
            if self.csv_input:
                if self._remote_uri(self.csv_input):
                    csv_path = self._download_remote(self.csv_input, os.path.join(temporary_root, 'csv'), 'CSV 文案')
                else:
                    csv_path = normalize_user_path(self.csv_input)
                    if not os.path.isfile(csv_path):
                        raise FileNotFoundError(f'CSV 文件不存在或当前无法访问：{self.csv_input}')
            self.resolved.emit(media_paths, csv_path, temporary_root)
        except Exception as exc:
            if temporary_root:
                shutil.rmtree(temporary_root, ignore_errors=True)
            self.failed.emit(str(exc))


class ManualAuditQueueLoadThread(QThread):
    """视频审核页的后台目录加载器；输入路径本身绝不触发本线程。"""
    row_ready = pyqtSignal(object)
    progress = pyqtSignal(int, int)
    completed = pyqtSignal(int, int, bool)
    failed = pyqtSignal(str)
    MEDIA_EXTS = tuple(dict.fromkeys(UniversalMatchThread.VIDEO_EXTS + UniversalMatchThread.AUDIO_EXTS + ('.mts',)))

    def __init__(self, media_input, recursive=True, make_thumbnail=True, analyse_audio=True, scripts=None, specified_csv_path='', parent=None):
        super().__init__(parent)
        self.media_input = str(media_input or '')
        self.recursive = bool(recursive)
        self.make_thumbnail = bool(make_thumbnail)
        self.analyse_audio = bool(analyse_audio)
        # ``scripts`` 仅代表用户明确指定的 CSV。未指定或该 CSV 未命中时，才按每个
        # 媒体自身所在目录寻找 CSV；绝不能把批量任务中另一个项目的文案带过来。
        self.scripts = {str(key).casefold(): dict(value or {}) for key, value in dict(scripts or {}).items() if str(key).strip()}
        self.specified_csv_path = os.path.normcase(os.path.abspath(str(specified_csv_path or ''))) if specified_csv_path else ''
        self.csv_script_count = len(self.scripts)
        self.matched_count = 0
        self.specified_matches = 0
        self.local_bilingual_matches = 0
        self.local_foreign_matches = 0
        self.local_chinese_matches = 0
        self.local_conflicts = 0
        self.local_csv_files = 0
        self._local_csv_cache = {}
        self._stop_requested = False

    def request_stop(self):
        self._stop_requested = True

    @staticmethod
    def _run(command, timeout=60):
        return subprocess.run(command, capture_output=True, text=True, encoding='utf-8', errors='replace', timeout=timeout, **_subprocess_no_window_kwargs())

    def _collect_files(self):
        found, seen = [], set()
        for raw in self.media_input.splitlines():
            value = normalize_user_path(raw.strip().strip('"').strip("'")) if raw.strip() else ''
            if not value or self._stop_requested:
                continue
            if os.path.isfile(value):
                candidates = [value]
            elif os.path.isdir(value):
                candidates = []
                if self.recursive:
                    for root, _dirs, files in os.walk(value):
                        if self._stop_requested:
                            break
                        candidates.extend(os.path.join(root, name) for name in files)
                else:
                    try:
                        candidates = [os.path.join(value, name) for name in os.listdir(value)]
                    except OSError:
                        candidates = []
            else:
                continue
            for path in candidates:
                if self._stop_requested:
                    break
                absolute = os.path.abspath(path)
                key = os.path.normcase(absolute)
                if key not in seen and os.path.isfile(absolute) and os.path.splitext(absolute)[1].lower() in self.MEDIA_EXTS:
                    seen.add(key); found.append(absolute)
        return sorted(found, key=lambda value: (os.path.dirname(value).lower(), os.path.basename(value).lower()))

    def _duration(self, path):
        try:
            result = self._run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'default=noprint_wrappers=1:nokey=1', path], 30)
            return max(0.0, float((result.stdout or '').strip() or 0)) if result.returncode == 0 else 0.0
        except Exception:
            return 0.0

    @staticmethod
    def read_csv_scripts(path):
        """读取审核 CSV；同时兼容三列表头和无表头的“代码 + 外文”简表。"""
        path = os.path.abspath(str(path or ''))
        if not os.path.isfile(path):
            return {}, 'CSV 文件不存在。'
        raw = ''
        for encoding in ('utf-8-sig', 'utf-8', 'gb18030'):
            try:
                with open(path, 'r', encoding=encoding, errors='strict', newline='') as file:
                    raw = file.read()
                break
            except Exception:
                continue
        if not raw:
            return {}, 'CSV 无法读取。'
        try:
            try:
                # Sniffer 对“字段内带逗号 + 双引号”的长文案会偶尔误判
                # doublequote=False，进而把同一个外文单元格拆成多列。它只能用来
                # 判断分隔符；文本 CSV 一律采用标准双引号转义规则。
                delimiter = csv.Sniffer().sniff(raw[:8192], delimiters=',;\t|').delimiter
            except csv.Error:
                delimiter = ','
            rows = list(csv.reader(io.StringIO(raw), delimiter=delimiter, quotechar='"', doublequote=True))
        except Exception as exc:
            return {}, f'CSV 格式无法识别：{exc}'
        if not rows:
            return {}, 'CSV 没有数据。'
        def header_name(value):
            value = unicodedata.normalize('NFKC', str(value or '')).strip().casefold()
            return re.sub(r'[\s_()（）:：\-]+', '', value)
        first = [header_name(value) for value in rows[0]]
        code_names = tuple(header_name(value) for value in ('代码', 'code', '编号', 'id', '项目代码', '文案代码', '视频代码', '文件代码', '代码（拖入AI）'))
        cn_names = tuple(header_name(value) for value in ('中文文案', '中文', 'cn', 'chinese', '中文台词', '中文文本', '原文'))
        en_names = tuple(header_name(value) for value in ('英文文案', '英文', 'en', 'english', '越南文案', '越南文', '越南语文案', '越南语', '外文文案', '外文', '译文'))
        header_mode = any(value in code_names for value in first)
        header_index = {value: index for index, value in enumerate(first)} if header_mode else {}
        def clean_cell(value):
            """清理部分导出器写出的三重引号外壳，但不截断内部逗号或换行。"""
            text = str(value or '').strip()
            if len(text) >= 2 and text.startswith('"') and text.endswith('"'):
                text = text[1:-1].replace('""', '"').strip()
            return text
        def cell(row, names):
            for name in names:
                index = header_index.get(name)
                if index is not None and index < len(row):
                    return clean_cell(row[index])
            return ''
        result = {}
        for row in (rows[1:] if header_mode else rows):
            if not row:
                continue
            code = cell(row, code_names) if header_mode else clean_cell(row[0] if row else '')
            cn = cell(row, cn_names) if header_mode else ''
            en = cell(row, en_names) if header_mode else (clean_cell(row[1]) if len(row) > 1 else '')
            if code and (cn or en):
                # 同一 CSV 的重复代码以最后一行为准，保持原导出工具的覆盖习惯。
                result[code] = {'code': code, 'cn': cn, 'en': en, 'csv_path': path}
        return result, '' if result else 'CSV 中没有可用的“代码 + 文案”记录。'

    def _channel_peaks(self, path):
        """只取峰值供审核筛查，不在此处做任何音频处理。"""
        try:
            result = self._run(['ffmpeg', '-hide_banner', '-i', path, '-map', '0:a:0', '-vn', '-af', 'astats=metadata=0:reset=0', '-f', 'null', '-'], 90)
            if result.returncode != 0:
                return None, None
            current, peaks = None, {}
            for line in ((result.stderr or '') + '\n' + (result.stdout or '')).splitlines():
                found_channel = re.search(r'Channel:\s*(\d+)', line)
                if found_channel:
                    current = int(found_channel.group(1)); continue
                found_peak = re.search(r'Peak level dB:\s*(-?(?:\d+(?:\.\d*)?|\.\d+)|-inf)', line, re.I)
                if found_peak and current is not None and current not in peaks:
                    raw = found_peak.group(1).lower(); peaks[current] = -120.0 if raw == '-inf' else float(raw)
            if not peaks:
                return None, None
            if 2 not in peaks:
                return peaks.get(1), peaks.get(1)
            return peaks.get(1), peaks.get(2)
        except Exception:
            return None, None

    def _thumbnail(self, path):
        if not self.make_thumbnail or os.path.splitext(path)[1].lower() not in UniversalMatchThread.VIDEO_EXTS:
            return ''
        return VideoThumbnailCache.get_or_create(path, self._run, lambda: self._stop_requested)

    def _find_csv_script(self, path, scripts=None):
        """先精确匹配完整代码；成片改名后再用“项目代码基底 + 序号”匹配。

        例如 CSV 为 ``2026-...-年轻男天使-01``，成片名可能只保留翻译后的
        ``...-Thiên Thần-01-文案``。此时只看 ``01`` 会串项目，必须同时要求
        父目录路径仍含原项目代码基底，才允许回退匹配。
        """
        def normalized(value):
            value = unicodedata.normalize('NFKC', str(value or '')).casefold()
            value = re.sub(r'[\u2010-\u2015\u2212]+', '-', value)
            value = re.sub(r'[\s_]+', '-', value)
            return re.sub(r'-+', '-', value).strip('-')

        raw_path = os.path.abspath(str(path or ''))
        filename = normalized(os.path.splitext(os.path.basename(raw_path))[0])
        source_scripts = self.scripts if scripts is None else scripts
        codes = [(normalized(code), script) for code, script in dict(source_scripts or {}).items() if normalized(code)]

        # 1. 成片文件名本身带完整代码时优先采用；代码越长越具体。
        matches = [(len(code), script) for code, script in codes if code in filename]
        if matches:
            return max(matches, key=lambda value: value[0])[1]

        # 1.5 成片常会在文件名中保留完整中文/外文文案，但项目代号或人物译名会被
        # 改写（例如 CSV 是“JQ-玛利亚”，成片是“景乾-玛丽亚”）。不能只按 01、02
        # 猜测；当文件名中确实包含足够长且可区分的文案开头时，按文案内容安全回填。
        def content_key(value):
            return re.sub(r'[\W_]+', '', normalized(value), flags=re.UNICODE)

        filename_content = content_key(filename)
        content_matches = []
        for _code, script in codes:
            for field in ('cn', 'en'):
                content = content_key(script.get(field, ''))
                # 至少 12 个有效字符，且使用最多前 28 个字符，避免“孩子/阿门”等
                # 常见短句造成误配，同时可兼容受文件名长度限制而截断的长文案。
                if len(content) < 12:
                    continue
                probe = content[:min(28, len(content))]
                if probe in filename_content:
                    content_matches.append((len(probe), script))
                    break
        if content_matches:
            return max(content_matches, key=lambda value: value[0])[1]

        # 2. 许多项目的成片只叫 1.mp4、2.mp4，真正的文案代码位于最近的父目录。
        #    必须在任何“数字序号回退”之前检查完整目录代码，否则每个文件夹中的
        #    1.mp4 都会被误配到 CSV 的第 01 行。
        parent = os.path.dirname(raw_path)
        while parent and os.path.dirname(parent) != parent:
            component = normalized(os.path.basename(parent))
            matches = [(len(code), script) for code, script in codes if code in component]
            if matches:
                return max(matches, key=lambda value: value[0])[1]
            parent = os.path.dirname(parent)

        # 3. 纯数字成片（1.mp4、02.mp4）按编号回填，但必须在当前 CSV 集合中
        #    找到唯一候选。多个项目均有 01 时绝不猜测，仍交给人工审核。
        pure_number = re.fullmatch(r'0*(\d{1,5})', filename)
        if pure_number:
            serial = int(pure_number.group(1))
            numeric_matches = []
            for code, script in codes:
                found = re.search(r'(?:^|-)0*(\d{1,5})$', code)
                if found and int(found.group(1)) == serial:
                    numeric_matches.append(script)
            if len(numeric_matches) == 1:
                return numeric_matches[0]
            return None

        # 4. 改名后的成片可能只保留“译文-01-文案”。只有文件名除序号外还有
        #    实际文字时才允许回退；纯 1.mp4/2.mp4 是文件夹内片段号，不能冒充文案号。
        full_path = normalized(raw_path)
        filename_without_digits = re.sub(r'[\d\W_-]+', '', filename, flags=re.UNICODE)
        if not filename_without_digits:
            return None
        fallback = []
        for code, script in codes:
            found = re.match(r'^(.*?)[_\-\s](\d{1,5})$', code)
            if not found:
                continue
            base, serial = found.group(1), int(found.group(2))
            serial_pattern = rf'(?<!\d)0*{serial}(?!\d)'
            if base and base in full_path and re.search(serial_pattern, filename):
                fallback.append((len(base), script))
        return max(fallback, key=lambda value: value[0])[1] if fallback else None

    def _local_csv_candidates(self, media_path):
        """返回媒体同目录的有效 CSV。

        只扫第一层，且排除已经作为“指定 CSV”读取过的文件。这样递归加载多个
        项目时，每一条视频只会接触它自己项目目录里的候选文案。
        """
        directory = os.path.normcase(os.path.abspath(os.path.dirname(str(media_path or ''))))
        if directory in self._local_csv_cache:
            return self._local_csv_cache[directory]
        candidates = []
        try:
            names = sorted(os.listdir(directory), key=str.casefold)
        except OSError:
            names = []
        for name in names:
            if not name.lower().endswith('.csv'):
                continue
            csv_path = os.path.abspath(os.path.join(directory, name))
            if self.specified_csv_path and os.path.normcase(csv_path) == self.specified_csv_path:
                continue
            scripts, error = self.read_csv_scripts(csv_path)
            self.local_csv_files += 1
            if scripts and not error:
                candidates.append((csv_path, scripts))
        self._local_csv_cache[directory] = candidates
        return candidates

    @staticmethod
    def _script_completeness(script):
        script = dict(script or {})
        if str(script.get('cn', '') or '').strip() and str(script.get('en', '') or '').strip():
            return 3
        if str(script.get('en', '') or '').strip():
            return 2
        return 1 if str(script.get('cn', '') or '').strip() else 0

    @staticmethod
    def _script_identity(script):
        script = dict(script or {})
        return (str(script.get('cn', '') or '').strip(), str(script.get('en', '') or '').strip())

    def _resolve_script_for_media(self, path):
        """指定 CSV 优先；未命中才用同目录 CSV，并优先完整中英对照。"""
        specified = self._find_csv_script(path, self.scripts) if self.scripts else None
        if specified:
            self.specified_matches += 1
            return specified, '指定 CSV'

        local_matches = []
        for _csv_path, local_scripts in self._local_csv_candidates(path):
            script = self._find_csv_script(path, local_scripts)
            if script:
                local_matches.append(script)
        if not local_matches:
            return None, ''

        best_level = max(self._script_completeness(script) for script in local_matches)
        best = [script for script in local_matches if self._script_completeness(script) == best_level]
        # 两个本地 CSV 同时给出不同的同等级内容时，不按文件名碰运气；直接留空。
        identities = {self._script_identity(script) for script in best}
        if len(identities) != 1:
            self.local_conflicts += 1
            return None, '本地 CSV 内容冲突'
        selected = best[0]
        if best_level == 3:
            self.local_bilingual_matches += 1
            source = '同目录 CSV｜中英对照'
        elif best_level == 2:
            self.local_foreign_matches += 1
            source = '同目录 CSV｜仅外文'
        else:
            self.local_chinese_matches += 1
            source = '同目录 CSV｜仅中文'
        return selected, source

    def run(self):
        try:
            VideoThumbnailCache.prune_if_needed()
            files = self._collect_files(); total = len(files); loaded = 0
            for index, path in enumerate(files, 1):
                if self._stop_requested:
                    break
                duration = self._duration(path)
                left, right = self._channel_peaks(path) if self.analyse_audio else (None, None)
                has_txt = os.path.isfile(os.path.splitext(path)[0] + '.txt')
                script, csv_source = self._resolve_script_for_media(path)
                if script:
                    self.matched_count += 1
                imbalance = left is not None and right is not None and abs(left - right) >= 14 and min(left, right) <= -25
                status = '⚠ 单耳风险' if imbalance else ('✓ 终审待审核' if script else ('⚠ 缺少 TXT' if not has_txt else '预审待审核'))
                self.row_ready.emit({'path': path, 'thumbnail': self._thumbnail(path), 'duration': duration, 'left_peak': left, 'right_peak': right, 'has_txt': has_txt, 'script': script or {}, 'script_source': csv_source or ('同目录 TXT 预审' if has_txt else '未找到文案'), 'status': status})
                loaded += 1; self.progress.emit(loaded, total)
            self.completed.emit(loaded, total, bool(self._stop_requested))
        except Exception as exc:
            self.failed.emit(str(exc))


class ManualPreviewFrameThread(QThread):
    """人工对位的首帧提取只在后台运行，不能阻塞列表选择或 Qt 绘制。"""
    frame_ready = pyqtSignal(str, str, int)

    def __init__(self, video_path, cache_dir, generation, parent=None):
        super().__init__(parent)
        self.video_path = os.path.abspath(str(video_path or ''))
        self.cache_dir = str(cache_dir or '')
        self.generation = int(generation or 0)
        self._cancel_requested = Event()
        self._process = None
        self._process_lock = Lock()

    def cancel(self):
        """首帧只是辅助画面；文件删除/切换时必须可立即放弃，绝不占住源视频。"""
        self._cancel_requested.set()
        try:
            with self._process_lock:
                process = self._process
            if process is not None and process.poll() is None:
                process.terminate()
        except Exception:
            pass

    def run(self):
        frame_path = ''
        try:
            if self._cancel_requested.is_set() or not os.path.isfile(self.video_path):
                self.frame_ready.emit(self.video_path, '', self.generation)
                return
            stamp = int(os.path.getmtime(self.video_path))
            key = f'{self.video_path}|{stamp}'
            os.makedirs(self.cache_dir, exist_ok=True)
            frame_path = os.path.join(self.cache_dir, f"{hashlib.md5(key.encode('utf-8', errors='replace')).hexdigest()}.jpg")
            if not os.path.isfile(frame_path) and not self._cancel_requested.is_set():
                process = subprocess.Popen(
                    ['ffmpeg', '-y', '-hide_banner', '-ss', '0.10', '-i', self.video_path, '-frames:v', '1', '-q:v', '2', frame_path],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                    **_subprocess_no_window_kwargs()
                )
                with self._process_lock:
                    self._process = process
                deadline = time.monotonic() + 15.0
                while process.poll() is None and time.monotonic() < deadline:
                    if self._cancel_requested.is_set():
                        try:
                            process.terminate()
                        except Exception:
                            pass
                        break
                    time.sleep(0.04)
                if process.poll() is None:
                    try:
                        process.kill()
                    except Exception:
                        pass
                try:
                    process.wait(timeout=1.0)
                except Exception:
                    pass
                with self._process_lock:
                    self._process = None
            if self._cancel_requested.is_set() or not os.path.isfile(frame_path):
                frame_path = ''
        except Exception:
            frame_path = ''
        finally:
            with self._process_lock:
                self._process = None
        self.frame_ready.emit(self.video_path, frame_path, self.generation)


class ManualPreviewProxyThread(QThread):
    """为独立预览生成受限、可随机定位的编辑代理。

    普通 H.264/H.265 原片常有很长的 GOP；拖动时间线时，播放器不得不从前一个
    关键帧反复解码，反向擦帧尤其明显。这里生成低分辨率、全帧内 H.264 代理，
    让每一帧都能独立解码。代理只在系统缓存目录创建，绝不改写或移动用户原片。
    """
    ready = pyqtSignal(object, object)  # (代理路径列表, 原路径 -> 代理路径)
    failed = pyqtSignal(str)
    CACHE_FORMAT_VERSION = 'preview-quality-v2'
    MAX_CACHE_BYTES = 6 * 1024 * 1024 * 1024
    MIN_VALID_PROXY_BYTES = 8 * 1024

    def __init__(self, source_paths, parent=None, quality='smooth'):
        super().__init__(parent)
        self.source_paths = [os.path.abspath(str(path)) for path in (source_paths or []) if os.path.isfile(str(path))]
        self.quality = 'original' if str(quality or '').strip().lower() == 'original' else 'smooth'
        self.proxy_details_by_proxy = {}

    @staticmethod
    def _cache_root():
        base = os.environ.get('LOCALAPPDATA') or os.environ.get('XDG_CACHE_HOME') or tempfile.gettempdir()
        return os.path.join(base, 'VideoTaskHub', 'manual-preview-proxies')

    @staticmethod
    def _proxy_path(source, cache_root, quality='smooth'):
        stat = os.stat(source)
        quality = 'original' if str(quality or '').strip().lower() == 'original' else 'smooth'
        fingerprint = f'{ManualPreviewProxyThread.CACHE_FORMAT_VERSION}|{quality}|{source}|{stat.st_size}|{stat.st_mtime_ns}'
        key = hashlib.sha256(fingerprint.encode('utf-8', errors='replace')).hexdigest()
        # 高清模式是原始画质的安全副本，保留受支持容器后缀；流畅模式固定 MP4。
        suffix = '.mp4'
        if quality == 'original':
            raw_suffix = os.path.splitext(source)[1].lower()
            suffix = raw_suffix if raw_suffix in {'.mp4', '.mov', '.mkv', '.avi', '.webm', '.m4v'} else '.mp4'
        return os.path.join(cache_root, key + suffix)

    @staticmethod
    def _ffmpeg_binary():
        configured = os.environ.get('WT_FFMPEG_PATH', '').strip()
        if configured and os.path.isfile(configured):
            return os.path.abspath(configured)
        candidate = shutil.which('ffmpeg') or shutil.which('ffmpeg.exe')
        return os.path.abspath(candidate) if candidate and os.path.isfile(candidate) else ''

    @classmethod
    def _cleanup_cache(cls, cache_root, incoming_bytes=0):
        """只回收本功能自己创建的安全缓存文件，绝不越出 cache_root。"""
        root = os.path.realpath(cache_root)
        entries = []
        total = 0
        try:
            for entry in os.scandir(root):
                if not entry.is_file(follow_symlinks=False):
                    continue
                if not entry.name.lower().endswith(('.mp4', '.mov', '.mkv', '.avi', '.webm', '.m4v', '.part')):
                    continue
                try:
                    stat = entry.stat(follow_symlinks=False)
                    # 另一独立预览窗口可能正在写自己的原子临时文件；不能把活跃
                    # 任务的 .part.mp4 当成可回收缓存。仅清理超过一小时的遗留件。
                    if '.part.' in entry.name.lower() and time.time() - float(stat.st_mtime) < 3600:
                        continue
                    total += max(0, int(stat.st_size))
                    entries.append((float(stat.st_mtime), entry.path, int(stat.st_size)))
                except OSError:
                    continue
            target_limit = max(0, cls.MAX_CACHE_BYTES - max(0, int(incoming_bytes or 0)))
            for _mtime, path, size in sorted(entries):
                if total <= target_limit:
                    break
                # 再次确认 realpath 仍在受控目录，防御链接/替换竞争。
                if os.path.commonpath((root, os.path.realpath(path))) != root:
                    continue
                try:
                    os.remove(path)
                    total -= size
                except OSError:
                    pass
        except OSError:
            pass

    def _build_intra_proxy(self, source, target, ffmpeg_bin):
        """以参数列表调用 FFmpeg；不使用 shell，因此路径不能注入命令。"""
        # 保留 .mp4 后缀，使 FFmpeg 能在无交互模式下可靠推断封装格式。
        partial = target + f'.{os.getpid()}.part.mp4'
        try:
            if os.path.exists(partial):
                os.remove(partial)
            # 540p 是交互预览的平衡点；g=1 使每帧为关键帧，时间线跳转无需回溯。
            command = [
                ffmpeg_bin, '-y', '-hide_banner', '-loglevel', 'error', '-nostdin',
                '-i', source, '-map', '0:v:0', '-map', '0:a?',
                '-vf', 'scale=960:540:force_original_aspect_ratio=decrease:force_divisible_by=2',
                '-c:v', 'libx264', '-preset', 'ultrafast', '-tune', 'fastdecode', '-crf', '20',
                '-g', '1', '-keyint_min', '1', '-sc_threshold', '0', '-pix_fmt', 'yuv420p',
                '-c:a', 'aac', '-b:a', '128k', '-movflags', '+faststart', partial,
            ]
            completed = subprocess.run(
                command, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
                timeout=900, check=False, **_subprocess_no_window_kwargs()
            )
            if completed.returncode != 0 or not os.path.isfile(partial) or os.path.getsize(partial) < self.MIN_VALID_PROXY_BYTES:
                return False
            os.replace(partial, target)
            return True
        except (OSError, subprocess.SubprocessError):
            return False
        finally:
            if os.path.isfile(partial):
                try:
                    os.remove(partial)
                except OSError:
                    pass

    def _build_compatible_copy(self, source, target):
        """无 FFmpeg 或极少数异常编码时的兼容回退，仍不触碰原文件。"""
        partial = target + f'.{os.getpid()}.part.mp4'
        try:
            shutil.copy2(source, partial)
            os.replace(partial, target)
            return os.path.isfile(target) and os.path.getsize(target) > 0
        finally:
            if os.path.isfile(partial):
                try:
                    os.remove(partial)
                except OSError:
                    pass

    def run(self):
        try:
            cache_root = self._cache_root()
            os.makedirs(cache_root, exist_ok=True)
            cache_root = os.path.abspath(cache_root)
            self._cleanup_cache(cache_root)
            ffmpeg_bin = self._ffmpeg_binary()
            proxy_paths, mapping = [], {}
            for source in self.source_paths:
                if not os.path.isfile(source):
                    raise FileNotFoundError(f'预览源文件不存在：{source}')
                target = self._proxy_path(source, cache_root, self.quality)
                # 缓存按路径、大小、修改时间和代理规格隔离；命中时不再读取原视频。
                is_intra_proxy = os.path.isfile(target) and os.path.getsize(target) >= self.MIN_VALID_PROXY_BYTES
                if not is_intra_proxy and self.quality == 'smooth':
                    self._cleanup_cache(cache_root, incoming_bytes=min(max(os.path.getsize(source), 0) * 3, 768 * 1024 * 1024))
                    is_intra_proxy = bool(ffmpeg_bin and self._build_intra_proxy(source, target, ffmpeg_bin))
                if not is_intra_proxy and not self._build_compatible_copy(source, target):
                    raise RuntimeError(f'无法建立预览缓存：{os.path.basename(source)}')
                proxy_paths.append(target)
                mapping[source] = target
                self.proxy_details_by_proxy[target] = {
                    'mode': 'intra_proxy' if is_intra_proxy else ('original_quality_copy' if self.quality == 'original' else 'compatible_copy'),
                    'source': source,
                }
            self.ready.emit(proxy_paths, mapping)
        except Exception as exc:
            self.failed.emit(str(exc))


class MediaSessionCoordinator(QObject):
    """内嵌播放器的全局交接器。

    窗口可以各自拥有会话，但 Windows 媒体后端/硬件解码器不是彼此独立的。任何
    新的编辑或预览会话启动前，都先让已登记会话在其画面控件仍有效时释放来源，
    防止“刚关闭预览就创建编辑播放器”的原生解码器竞争。
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self._sessions = []
        self._request_token = 0

    def register(self, session):
        if session is not None and session not in self._sessions:
            self._sessions.append(session)
            try:
                session.destroyed.connect(lambda *_args, item=session: self.unregister(item))
            except Exception:
                pass

    def unregister(self, session):
        self._sessions = [item for item in self._sessions if item is not session and getattr(item, '_alive', False)]

    def request_quiet_media_window(self, callback, timeout_ms=2200):
        """取得新的独占播放窗口；超时不强行开第二个解码器。"""
        self._request_token += 1
        token = self._request_token
        sessions = [item for item in self._sessions if getattr(item, '_alive', False) and not item.is_source_released()]
        for session in sessions:
            try:
                session.prepare_for_handoff()
            except Exception:
                pass
        started = time.monotonic()

        def finish(ready):
            if token != self._request_token:
                return
            try:
                callback(bool(ready))
            except Exception:
                pass

        def check():
            if token != self._request_token:
                return
            active = [item for item in sessions if getattr(item, '_alive', False) and not item.is_source_released()]
            if not active:
                # 来源清空后再给 Windows 媒体后端一个短的安静窗口；这不是用固定
                # 延时替代释放确认，而是避免 NoMedia 信号与新 setSource 同一轮事件
                # 循环交叉。
                QTimer.singleShot(180, lambda: finish(True))
            elif (time.monotonic() - started) * 1000 >= int(timeout_ms):
                finish(False)
            else:
                QTimer.singleShot(45, check)
        QTimer.singleShot(0, check)


_MEDIA_SESSION_COORDINATOR = None


def get_media_session_coordinator():
    global _MEDIA_SESSION_COORDINATOR
    if _MEDIA_SESSION_COORDINATOR is None:
        _MEDIA_SESSION_COORDINATOR = MediaSessionCoordinator(QApplication.instance())
    return _MEDIA_SESSION_COORDINATOR


class UnifiedMediaSession(QObject):
    """全软件唯一的内嵌媒体会话核心。

    人工对位、预拼接与视频编辑都必须通过本类加载、定位、暂停、切段与释放。
    VLC 只允许作为外部受控播放器存在，绝不再混入软件内预览或文件操作路径。
    """
    status_changed = pyqtSignal(object)
    playback_changed = pyqtSignal(bool)
    position_changed = pyqtSignal(int)
    duration_changed = pyqtSignal(int)
    ended = pyqtSignal()
    failed = pyqtSignal(str)
    handoff_released = pyqtSignal()
    def __init__(self, surface, parent=None, switch_delay_ms=180):
        super().__init__(parent)
        if not HAS_QT_MEDIA:
            raise RuntimeError('Qt Multimedia 不可用')
        self.player = QMediaPlayer(self)
        self.audio_output = None
        self._volume_percent = 100
        self._media_devices = None
        self._audio_device_recovery_timer = QTimer(self)
        self._audio_device_recovery_timer.setSingleShot(True)
        self._audio_device_recovery_timer.timeout.connect(self._recover_default_audio_output)
        if PYQT_VERSION == 6 and QAudioOutput is not None:
            self.audio_output = QAudioOutput(self)
            self.player.setAudioOutput(self.audio_output)
            self.audio_set_volume(self._volume_percent)
            # 蓝牙耳机断电、USB 声卡拔出或 Windows 修改默认输出时，旧的
            # QAudioOutput 有时仍指向已消失设备，画面继续播放却彻底无声。
            # 监听系统设备列表变化，并延迟一个事件周期重建输出端到新默认设备。
            try:
                if QMediaDevices is not None:
                    self._media_devices = QMediaDevices(self)
                    self._media_devices.audioOutputsChanged.connect(self._queue_default_audio_output_recovery)
            except Exception:
                self._media_devices = None
        self.player.setVideoOutput(surface)
        self._surface = surface
        self._alive = True
        self._current_path = ''
        self._desired_path = ''
        self._desired_position = 0
        self._desired_rate = 1.0
        self._desired_playing = False
        self._generation = 0
        self._active_generation = 0
        self._applied_generation = -1
        # Qt 的 EndOfMedia 会在换源后的极短窗口里仍保留上一段状态。把“就绪”和
        # “片尾已消费”绑定到媒体代次，业务层绝不能用一个陈旧的片尾状态连跳数段。
        self._ready_generation = -1
        self._ended_generation = -1
        self._consumed_end_generation = -1
        self._pending_generation = 0
        self._source_release_pending = False
        self._close_requested = False
        # Windows Media Foundation 有时会先报告 LoadedMedia，随后才给出音轨列表。
        # 连续预览下一段若只在第一次 LoadedMedia 选择音轨，后段会出现“画面正常
        # 但无声”。单独延迟复核音轨和 QAudioOutput，不重开视频解码器。
        self._audio_route_attempts = 0
        self._audio_route_generation = -1
        self._audio_route_timer = QTimer(self)
        self._audio_route_timer.setSingleShot(True)
        self._audio_route_timer.timeout.connect(self._ensure_audio_route)
        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.setInterval(max(80, int(switch_delay_ms or 180)))
        self._timer.timeout.connect(self._flush_media_switch)
        self.player.mediaStatusChanged.connect(self._on_media_status)
        try:
            self.player.tracksChanged.connect(self.ensure_audio_output)
        except Exception:
            pass
        try:
            self.player.positionChanged.connect(lambda value: self.position_changed.emit(max(0, int(value or 0))))
            self.player.durationChanged.connect(lambda value: self.duration_changed.emit(max(0, int(value or 0))))
            if PYQT_VERSION == 6:
                self.player.playbackStateChanged.connect(self._on_playback_state)
                self.player.errorOccurred.connect(self._on_error)
            else:
                self.player.stateChanged.connect(self._on_playback_state)
                self.player.error.connect(self._on_error)
        except Exception:
            pass
        get_media_session_coordinator().register(self)

    def _queue_default_audio_output_recovery(self):
        if self._alive and PYQT_VERSION == 6 and self.audio_output is not None:
            self._audio_device_recovery_timer.start(450)

    def _recover_default_audio_output(self):
        """Windows 默认声卡变更后无缝把正在播放的媒体接到新输出。"""
        if not self._alive or PYQT_VERSION != 6 or QAudioOutput is None:
            return
        try:
            previous = self.audio_output
            volume = previous.volume() if previous is not None else 1.0
            replacement = QAudioOutput(self)
            if QMediaDevices is not None:
                replacement.setDevice(QMediaDevices.defaultAudioOutput())
            replacement.setVolume(max(0.0, min(1.0, float(volume))))
            self.player.setAudioOutput(replacement)
            self.audio_output = replacement
            self.audio_set_volume(self._volume_percent)
            if previous is not None:
                previous.deleteLater()
            # 保留当前时间与播放意图；重新 play 一次让 WMF 立即取得新设备，
            # 无需重新扫描文件或让用户手工关闭再打开预览。
            if self._desired_playing and self._current_path and not self._timer.isActive():
                self.player.play()
        except Exception as exc:
            write_debug(f'[媒体] 默认音频输出恢复失败：{exc}')

    def set_media(self, path):
        """兼容旧调用；新代码优先用 load() 原子提交路径、定位与播放意图。"""
        path = os.path.abspath(str(path or '').strip()) if path else ''
        if not self._alive or not path:
            return
        # 同一媒体内拖动时间线不能再次 stop/setSource。那会丢掉正在运行的解码
        # 队列，短视频反复定位时尤其容易表现为画面和声音一同卡住。
        if path == self._current_path and not self._timer.isActive():
            self._desired_path = path
            return
        self._generation += 1
        self._desired_path = path
        self._desired_position = 0
        self._timer.start()

    def bind_surface(self, surface):
        """由会话自身重新绑定画面，不让业务页面直接触碰 QMediaPlayer。"""
        if not self._alive or surface is None:
            return False
        try:
            self._surface = surface
            self.player.setVideoOutput(surface)
            return True
        except Exception:
            return False

    def load(self, path, position=0, playing=True, rate=1.0):
        """以一个意图完成“载入 / 定位 / 播放”。

        同片段只 seek，跨片段才更换媒体源；每次快速拖动只保留最后一次意图。
        """
        path = os.path.abspath(str(path or '').strip()) if path else ''
        if not self._alive or not path:
            return False
        self._desired_path = path
        self._desired_position = max(0, int(position or 0))
        self._desired_playing = bool(playing)
        self._desired_rate = max(.25, min(4.0, float(rate or 1.0)))
        if path == self._current_path and not self._timer.isActive():
            self._apply_current_intent()
            return False
        self._generation += 1
        self._timer.start()
        return True

    def _apply_current_intent(self):
        """仅对当前已激活的 Qt 媒体应用最后一次用户意图。"""
        if not self._alive:
            return
        try:
            self.player.setPlaybackRate(float(self._desired_rate or 1.0))
            self.player.setPosition(max(0, int(self._desired_position or 0)))
            if self._desired_playing:
                self.player.play()
            else:
                self.player.pause()
        except Exception:
            pass

    def _flush_media_switch(self):
        if not self._alive or not self._desired_path:
            return
        path = self._desired_path
        generation = self._generation
        self._pending_generation = generation
        try:
            # EndOfMedia 后的 Windows 媒体后端不能在同一个调用栈里既 stop 又
            # setSource；先让停止事件返回事件循环，第二段才会真正开始解码。
            self.player.stop()
            def assign_new_source():
                if (not self._alive or generation != self._generation
                        or path != self._desired_path):
                    return
                try:
                    self._current_path = path
                    self._active_generation = generation
                    self._applied_generation = -1
                    self._ready_generation = -1
                    self._ended_generation = -1
                    self._consumed_end_generation = -1
                    if PYQT_VERSION == 6:
                        self.player.setSource(QUrl.fromLocalFile(path))
                    else:
                        self.player.setMedia(QMediaContent(QUrl.fromLocalFile(path)))
                except Exception:
                    pass
            QTimer.singleShot(45, assign_new_source)
        except Exception:
            pass

    def _on_media_status(self, status):
        if not self._alive:
            return
        try:
            self.status_changed.emit(status)
            ended_status = QMediaPlayer.MediaStatus.EndOfMedia if PYQT_VERSION == 6 else QMediaPlayer.EndOfMedia
            if status == ended_status:
                self._desired_playing = False
                # 某些 Windows 后端在切换来源时会晚到一条旧的 EndOfMedia；同一
                # 代次只发一次，切段控制器可安全地“消费”该事件一次。
                if self._ended_generation != self._active_generation:
                    self._ended_generation = self._active_generation
                    self.ended.emit()
                return
            ready_states = ({QMediaPlayer.MediaStatus.LoadedMedia, QMediaPlayer.MediaStatus.BufferedMedia}
                            if PYQT_VERSION == 6 else {QMediaPlayer.LoadedMedia, QMediaPlayer.BufferedMedia})
            if status not in ready_states:
                return
            # QMediaPlayer 在播放时会反复往返 BufferedMedia / LoadedMedia。若每次
            # 都 setPosition(同一值)，播放头就会永远卡在该位置。每次换源只允许
            # 首次就绪时定位一次；之后的状态变化只代表缓冲，不得回拉播放头。
            if self._applied_generation != self._active_generation:
                self.audio_set_volume(self._volume_percent)
                self._apply_current_intent()
                self._applied_generation = self._active_generation
            self._ready_generation = self._active_generation
            self.ensure_audio_output()
        except Exception:
            pass

    def ensure_audio_output(self):
        """为当前媒体补选音轨并复核音频输出，专门处理 Windows 后段静音。"""
        if not self._alive:
            return
        self._audio_route_generation = self._active_generation
        self._audio_route_attempts = 0
        self._audio_route_timer.start(0)

    def _ensure_audio_route(self):
        if not self._alive or self._audio_route_generation != self._active_generation:
            return
        try:
            if PYQT_VERSION == 6 and self.audio_output is not None:
                # 某些 Windows 后端换源后会短暂脱离既有输出；重新挂回同一输出对象
                # 不改变用户音量，也不需要重启播放器。
                self.player.setAudioOutput(self.audio_output)
                self.audio_output.setMuted(self._volume_percent <= 0)
                self.audio_output.setVolume(self._volume_percent / 100.0)
                tracks = list(self.player.audioTracks() or [])
                active_track = int(self.player.activeAudioTrack())
                if tracks and (active_track < 0 or active_track >= len(tracks)):
                    self.player.setActiveAudioTrack(0)
                    active_track = 0
                # 音轨元数据常比 LoadedMedia 晚到；有限次重试只检查音频路由，
                # 不 seek、不 stop、不打断连续播放。
                if not tracks and self._current_path and self._audio_route_attempts < 8:
                    self._audio_route_attempts += 1
                    self._audio_route_timer.start(180)
        except Exception as exc:
            write_debug(f'[媒体] 音频输出复核失败：{exc}')

    def _on_playback_state(self, state):
        try:
            active = QMediaPlayer.PlaybackState.PlayingState if PYQT_VERSION == 6 else QMediaPlayer.PlayingState
            self.playback_changed.emit(bool(state == active))
        except Exception:
            pass

    def _on_error(self, *_args):
        try:
            self.failed.emit(str(self.player.errorString() or '媒体解码失败'))
        except Exception:
            self.failed.emit('媒体解码失败')

    def stop(self):
        self._desired_playing = False
        try: self.player.stop()
        except Exception: pass

    def play(self):
        self._desired_playing = True
        try:
            # 正在等待新媒体时只记录意图；绝不让旧媒体在切段途中被重新播放。
            if not self._timer.isActive() and self._desired_path == self._current_path:
                self.player.play()
        except Exception: pass

    def pause(self):
        self._desired_playing = False
        try: self.player.pause()
        except Exception: pass

    def set_pause(self, value):
        self.pause() if value else self.play()

    def set_time(self, value):
        self._desired_position = max(0, int(value or 0))
        try:
            if self.get_length() > 0 and not self._timer.isActive() and self._desired_path == self._current_path:
                self.player.setPosition(self._desired_position)
        except Exception:
            pass

    def get_time(self):
        try: return max(0, int(self.player.position() or 0))
        except Exception: return 0

    def get_length(self):
        try: return max(0, int(self.player.duration() or 0))
        except Exception: return 0

    def set_rate(self, rate):
        self._desired_rate = max(.25, min(4.0, float(rate or 1.0)))
        try: self.player.setPlaybackRate(self._desired_rate)
        except Exception: pass

    def is_playing(self):
        try:
            active = QMediaPlayer.PlaybackState.PlayingState if PYQT_VERSION == 6 else QMediaPlayer.PlayingState
            return self.player.playbackState() == active if PYQT_VERSION == 6 else self.player.state() == active
        except Exception:
            return False

    def has_ended(self):
        """Qt 的真实片尾状态；不再混用已废弃的 VLC State。"""
        try:
            ended = QMediaPlayer.MediaStatus.EndOfMedia if PYQT_VERSION == 6 else QMediaPlayer.EndOfMedia
            return self.player.mediaStatus() == ended
        except Exception:
            return False

    def is_source_released(self):
        """供跨窗口交接判断：来源已清空且没有待执行的释放操作。"""
        return bool(not self._current_path and not self._desired_path and not self._source_release_pending)

    def prepare_for_handoff(self):
        """在渲染控件销毁前释放来源，供另一个媒体窗口安全接管。"""
        if not self._alive:
            return
        if self.is_source_released():
            QTimer.singleShot(0, self.handoff_released.emit)
            return
        self.release_source()

    def is_ready_for(self, path):
        """仅当指定的新来源已真正就绪时返回 True，排除旧来源残留时长/片尾状态。"""
        try:
            normalized = os.path.abspath(str(path or '').strip())
            if (not normalized or normalized != self._current_path
                    or normalized != self._desired_path
                    or self._ready_generation != self._active_generation):
                return False
            ready_states = ({QMediaPlayer.MediaStatus.LoadedMedia, QMediaPlayer.MediaStatus.BufferedMedia}
                            if PYQT_VERSION == 6 else {QMediaPlayer.LoadedMedia, QMediaPlayer.BufferedMedia})
            return self.player.mediaStatus() in ready_states
        except Exception:
            return False

    def consume_end(self):
        """返回当前来源的一次真实片尾；同一片段只能消费一次。"""
        try:
            if (self._ended_generation != self._active_generation
                    or self._consumed_end_generation == self._active_generation):
                return False
            self._consumed_end_generation = self._active_generation
            return True
        except Exception:
            return False

    def release_source(self):
        """在停止后的下一轮事件循环释放文件句柄，供删除、改名和移动统一使用。"""
        if not self._alive or self._source_release_pending:
            return False
        self._source_release_pending = True
        self._desired_playing = False
        self._generation += 1
        self._timer.stop()
        try:
            self.player.stop()
        except Exception:
            pass
        def release():
            if not self._alive:
                return
            try:
                if PYQT_VERSION == 6:
                    self.player.setSource(QUrl())
                else:
                    self.player.setMedia(QMediaContent())
                self._current_path = ''
                self._desired_path = ''
                self._desired_position = 0
                self._applied_generation = -1
                self._ready_generation = -1
                self._ended_generation = -1
                self._consumed_end_generation = -1
            except Exception:
                pass
            finally:
                self._source_release_pending = False
                self.handoff_released.emit()
        QTimer.singleShot(80, release)
        return True

    def audio_set_volume(self, value):
        try:
            self._volume_percent = max(0, min(100, int(value or 0)))
            if self.audio_output is not None:
                self.audio_output.setMuted(self._volume_percent == 0)
                self.audio_output.setVolume(self._volume_percent / 100.0)
            elif PYQT_VERSION != 6:
                self.player.setMuted(self._volume_percent == 0)
                self.player.setVolume(self._volume_percent)
        except Exception:
            pass

    def video_set_adjust_int(self, *_args): pass
    def video_set_adjust_float(self, *_args): pass

    def close(self):
        """将会话移入全局回收区，再延迟销毁。

        QMediaPlayer 的 Windows 后端在 ``stop`` 后仍会投递一小段原生解码回调。
        若在关闭 QDialog 的同一个事件栈里清空来源、删除播放器和销毁 QVideoWidget，
        回调会访问无效窗口句柄并让整个进程退出。关闭窗口时只做安全的解绑；播放器
        留在全局回收区完成静默释放，之后才删除自身。
        """
        if not self._alive or self._close_requested:
            return
        self._close_requested = True
        # 必须最先失活；stop 可能同步发出状态信号，业务层不得再读取它。
        self._alive = False
        self._desired_playing = False
        self._generation += 1
        self._timer.stop()
        self._source_release_pending = False
        try:
            self.player.stop()
        except Exception:
            pass
        # 必须在 QVideoWidget 仍存在时解除绑定；此后播放器不再持有已关闭窗口的
        # 原生句柄。来源清空留给下一轮事件循环以外的回收阶段。
        try:
            self.player.setVideoOutput(None)
        except Exception:
            pass
        self._surface = None
        self._current_path = ''
        self._desired_path = ''
        self._desired_position = 0
        self._ready_generation = -1
        self._ended_generation = -1
        self._consumed_end_generation = -1
        coordinator = get_media_session_coordinator()
        try:
            # 会话不能继续作为即将销毁的预览窗口的子对象。
            self.setParent(coordinator)
        except Exception:
            pass

        def release_retired_media():
            try:
                if PYQT_VERSION == 6:
                    self.player.setSource(QUrl())
                else:
                    self.player.setMedia(QMediaContent())
            except Exception:
                pass
            def dispose_retired_media():
                try:
                    coordinator.unregister(self)
                    self.deleteLater()
                except Exception:
                    pass
            QTimer.singleShot(650, dispose_retired_media)

        # 让 QDialog 先完成 finished/hide 以及 Windows 的窗口句柄解绑，再操作来源。
        QTimer.singleShot(420, release_retired_media)


# 旧调用点兼容名；新代码统一使用 UnifiedMediaSession。
SafeQtPreviewPlayer = UnifiedMediaSession


class BoundedStaticPreviewLabel(QLabel):
    """预览封面永远只在既有播放器区域内缩放，不能参与顶层窗口的尺寸计算。"""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setSizePolicy(_Ignored, _Ignored)
        self.setMinimumSize(0, 0)

    def sizeHint(self):
        # QLabel 的默认 sizeHint 会直接取原始 Pixmap 尺寸。高分辨率封面一旦被
        # 放入 QStackedLayout，就会反向把人工对位台撑大；返回稳定的工作区参考值。
        return QSize(320, 180)

    def minimumSizeHint(self):
        return QSize(0, 0)


class ManualVideoAlignmentDialog(QDialog):
    """未匹配视频的人工对位工作台：左侧视频队列，右侧内嵌播放、候选文本和一键绑定。"""
    def __init__(self, unmatched_items, text_sources, on_applied=None, preferences=None, on_preferences_changed=None, media_roots=None, on_refresh_requested=None, history_options=None, on_history_selection_changed=None, on_rerun_audio_requested=None, parent=None):
        # 人工对位必须是独立顶层窗口：若把主窗口传给 QDialog 的构造器，Windows
        # 会把它视为主窗口的附属窗口，主窗口最小化时也会一同隐藏。这里不建立
        # Qt 父子关系；parent 只作为主题、配置和结果回写的逻辑宿主保留。
        super().__init__(None)
        self.setWindowTitle("人工对位工作台")
        self.setProperty("theme_dialog", "true")
        self.setProperty("theme_scale_with_owner", True)
        self.setObjectName("manual_alignment_dialog")
        self._theme_owner = parent
        self.resize(1180, 760)
        try:
            if PYQT_VERSION == 6:
                self.setWindowFlags(Qt.WindowType.Window | Qt.WindowType.WindowMinimizeButtonHint | Qt.WindowType.WindowMaximizeButtonHint | Qt.WindowType.WindowCloseButtonHint)
            else:
                self.setWindowFlags(Qt.Window | Qt.WindowMinimizeButtonHint | Qt.WindowMaximizeButtonHint | Qt.WindowCloseButtonHint)
        except Exception:
            pass
        self.items = [dict(x or {}) for x in (unmatched_items or []) if str((x or {}).get('res', '')).strip()]
        self.media_roots = [os.path.abspath(str(path).strip()) for path in (media_roots or []) if str(path).strip() and os.path.isdir(str(path).strip())]
        # 文件操作是独立服务：只接受这里冻结的素材根目录，绝不读取播放器、当前
        # 行或工作区路径。人工对位的所有改名/移动/删除都必须走它。
        self.file_engine = FileOperationEngine(self.media_roots)
        self.text_sources = [str(x).strip() for x in (text_sources or []) if str(x).strip()]
        self.on_applied = on_applied
        preferences = preferences or {}
        self.show_existing_text_default = bool(preferences.get('show_existing_text', True))
        self.numeric_text_only_default = bool(preferences.get('numeric_text_only', False))
        # 人工对位的文件操作优先级高于播放。默认不自动启动任何解码器；用户
        # 点击时才打开独立轻量预览窗口，主工作台始终保持为纯文件/文案操作界面。
        self.auto_play_default = bool(preferences.get('auto_play', False))
        self.media_list_width_default = int(preferences.get('media_list_width', 0) or 0)
        saved_playback_mode = str(preferences.get('playback_mode', 'isolated') or 'isolated').strip().lower()
        # 旧版本把 internal 作为默认值保存；升级后迁移为隔离预览，而不是继续
        # 在人工对位主窗口内初始化解码器。用户仍可在下拉框主动选回兼容模式。
        self.playback_mode_default = 'isolated' if saved_playback_mode == 'internal' else saved_playback_mode
        if self.playback_mode_default not in {'isolated', 'internal', 'external', 'vlc_controlled'}:
            self.playback_mode_default = 'isolated'
        self.external_player_path_default = str(preferences.get('external_player_path', '') or '').strip()
        self.history_enabled_default = bool(preferences.get('history_enabled', True))
        self.history_selection_default = str(preferences.get('history_selection', 'auto') or 'auto')
        try:
            self.similarity_threshold_default = max(0.0, min(100.0, float(preferences.get('similarity_threshold', 64.0))))
        except Exception:
            self.similarity_threshold_default = 64.0
        self.on_preferences_changed = on_preferences_changed
        self.on_refresh_requested = on_refresh_requested
        self.on_rerun_audio_requested = on_rerun_audio_requested
        self.rerun_audio_directory = str(preferences.get('rerun_audio_directory', '') or '')
        self.show_smart_audio_directory = bool(preferences.get('show_smart_audio_directory', False))
        self.history_options = list(history_options or [])
        self.on_history_selection_changed = on_history_selection_changed
        self.on_deleted = getattr(parent, '_on_manual_video_deleted', None) if parent is not None else None
        self.view_mode = 'all'
        self.text_items = self._collect_text_items()
        self.player = None
        self.vlc_instance = None
        self.vlc_media = None
        # 人工对位保留自己的内嵌播放器，供单条素材快速核对。多选横向拼接预览
        # 与视频编辑绝不借用此会话，而是在取得媒体交接许可后创建各自的独立窗口。
        self._isolated_preview_mode = self.playback_mode_default == 'isolated'
        self._isolated_preview_opening = False
        self._isolated_preview_host = None
        self._manual_preview_proxy_thread = None
        self._use_qt_media = bool(HAS_QT_MEDIA)
        self.media_session = None
        self.qt_media_player = None
        self.qt_audio_output = None
        # 删除中的旧 Media 不立即 release。Windows 下 libVLC 的解码线程可能在
        # stop() 返回后仍短暂访问它；提前 release 是人工对位删除时原生崩溃的主因。
        self._retired_vlc_media = []
        # 删除期间连 set_media(None) / release 都不能认为安全：某些 VLC 版本会在
        # 状态已返回 Stopped 后继续由原生渲染线程访问 player。删除时退休整个
        # player/instance，直到工作台关闭或应用退出才交给运行时统一回收。
        self._retired_vlc_players = []
        # 变速工作台的临时预览播放器同样不能在关闭弹窗后立即析构。保留到
        # 人工对位窗口关闭，避免 VLC 原生渲染线程在输出刚启动时访问已释放对象。
        # 已关闭编辑台的 VLC 不能立刻析构；但绝不能把它重新绑定到新的 HWND。
        # Windows libVLC 支持 stop 后延迟回收，却不保证跨已销毁窗口重绑安全。
        self._retired_speed_preview_players = []
        self.current_item = None
        self.current_video = ''
        # VLC 在 stop() 后仍会保留上一条 media；单独记录实际已装载文件，
        # 供手动播放时判断是否必须切换，而不能误续播旧视频。
        self._loaded_video_path = ''
        # 多选预拼接预览只维护播放队列；不创建、不改写、不拼接任何文件。
        self._sequence_preview_paths = []
        self._sequence_preview_index = -1
        self._sequence_preview_active = False
        self._sequence_preview_expected_path = ''
        self.current_text_root = ''
        self.current_media_folder = ''
        self.seeking = False
        self.duration_ms = 0
        self._static_preview_source = ''
        self._static_preview_pixmap = QPixmap()
        self._video_frame_cache = {}
        # 选择列表时只保留最后一个待提取首帧。旧实现每次 selectionChanged 都在
        # GUI 线程同步执行 FFmpeg，普通素材快速点选也会卡住甚至诱发原生组件失稳。
        self._static_preview_generation = 0
        self._static_preview_pending = ('', 0)
        self._static_preview_thread = None
        self.manual_cover_generation_thread = None
        # 首帧截图不再是人工对位的必要步骤。它会额外启动 FFmpeg、持有源文件，
        # 并在短视频连续选择时把“辅助画面”放大成删除/切换的不稳定因素。保留
        # 已有缓存可立即显示，但禁止为新选择自动提取；真实播放画面才是主预览。
        self._auto_static_frame_extraction = False
        # 首帧、试听等会读取源视频的后台任务必须登记到同一台账。删除、移动、
        # 改名和窗口关闭据此决定等待，而不是只知道播放器是否正在播放。
        self._background_media_threads = []
        self._static_preview_timer = QTimer(self)
        self._static_preview_timer.setSingleShot(True)
        self._static_preview_timer.timeout.connect(self._launch_queued_static_preview)
        # 每次切换媒体或删除媒体都会递增。延迟定位回调只能操作当前代的播放器，
        # 防止快速切换/删除后仍有旧回调触碰已经释放的 VLC 对象。
        self._playback_epoch = 0
        self.deleting_video = False
        self.play_timer = QTimer(self)
        self.play_timer.setInterval(300)
        self.play_timer.timeout.connect(self._poll_player_state)
        # 快速点选时只加载最后一个视频，避免连续 stop/set_media/play 争用 VLC 原生线程。
        self._video_load_timer = QTimer(self)
        self._video_load_timer.setSingleShot(True)
        self._video_load_timer.timeout.connect(self._flush_queued_video_load)
        self._pending_video_path = ''
        self._pending_video_epoch = -1
        # libVLC 的 stop() 是异步的。所有媒体替换都要等旧媒体确实停止后再进行；
        # 不能让快速点选把正在被 native 解码线程使用的 Media 对象直接覆盖/释放。
        self._media_switch_in_progress = False
        # libVLC 的 stop 是异步原生调用；同一轮状态转换只允许请求一次，避免
        # 刷新、选中变化和延迟加载对同一个解码线程重复调用 stop。
        self._native_stop_pending = False
        # 删除只在“待删文件正是 VLC 已装载媒体”时才允许触碰 VLC。这个标记
        # 不能由 player 是否存在推断：播放器常驻但没有媒体时，调用 stop()/get_state()
        # 仍可能触发 Windows libVLC 的原生访问冲突。
        self._delete_requires_player_stop = False
        # 删除是异步安全流程。无论首帧提取、播放器或文件锁出现何种异常，都必须
        # 在总超时后回到可操作状态，绝不允许按钮永久灰掉。
        self._delete_operation_token = 0
        self._pending_delete_path = ''
        self._closing_player = False
        self._controlled_vlc_process = None
        self._controlled_vlc_port = 0
        self._controlled_vlc_password = ''
        # 受控 VLC 必须严格串行：Windows 上 terminate() 是异步的，若马上创建
        # 新进程会短时间堆积大量 VLC（崩溃日志中的根因）。保留退出中的进程引用，
        # 只在它真正退出后再启动最新一次用户选择的视频。
        self._controlled_vlc_terminating_process = None
        self._controlled_vlc_media_path = ''
        self._controlled_vlc_start_serial = 0
        self._controlled_vlc_pending_path = ''
        # 普通外部播放器同样由本工作台管理：切换视频/模式时关闭上一实例，
        # 避免它与内嵌或受控 VLC 同时播放旧视频。
        self._external_player_process = None
        self._external_player_terminating_process = None
        self._external_player_media_path = ''
        self._controlled_vlc_start_timer = QTimer(self)
        self._controlled_vlc_start_timer.setSingleShot(True)
        self._controlled_vlc_start_timer.timeout.connect(self._dispatch_controlled_vlc_start)
        self._controlled_vlc_start_callback = None
        self._controlled_vlc_launch_timer = QTimer(self)
        self._controlled_vlc_launch_timer.setSingleShot(True)
        self._controlled_vlc_launch_timer.timeout.connect(self._dispatch_controlled_vlc_launch)
        self._controlled_vlc_launch_callback = None
        # QMenu 关闭后，匿名 singleShot 回调在部分 Windows/PyQt 环境会丢失。
        # 文件操作由窗口持有的单一计时器派发，确保有明确的成功或失败结果。
        self._manual_file_operation_timer = QTimer(self)
        self._manual_file_operation_timer.setSingleShot(True)
        self._manual_file_operation_timer.timeout.connect(self._dispatch_manual_file_operation)
        self._manual_file_operation_callback = None
        self._manual_file_operation_stage = ''
        self._build_ui()
        # 工作台内容较宽时由内部滚动条承载，顶层窗口绝不能因此超过低分辨率屏幕。
        self.setMinimumSize(460, 340)
        # 隔离预览模式不在人工对位主窗口创建 Qt/VLC 解码器，避免播放器污染
        # 绑定、改名、删除等基础能力。
        if not self._isolated_preview_mode:
            self._init_player()
        self._fill_video_list()
        self._manual_trace('dialog_initialized', item_count=len(self.items), auto_play=self.auto_play_default)
        QTimer.singleShot(0, lambda: center_window_on_screen(self))
        self._select_initial_media_item()

    def _manual_trace(self, event, **details):
        """记录人工对位播放器的最后操作；原生崩溃后可据此还原触发链。"""
        try:
            record = {
                'time': datetime.now().isoformat(timespec='milliseconds'),
                'event': str(event),
                'current_video': str(getattr(self, 'current_video', '') or ''),
                'loaded_video': str(getattr(self, '_loaded_video_path', '') or ''),
                'epoch': int(getattr(self, '_playback_epoch', 0) or 0),
                'deleting': bool(getattr(self, 'deleting_video', False)),
                **details,
            }
            with open(MANUAL_ALIGNMENT_CRASH_LOG, 'a', encoding='utf-8') as log_file:
                log_file.write(json.dumps(record, ensure_ascii=False, default=str) + '\n')
        except Exception:
            pass

    def _queue_manual_file_operation(self, callback, delay_ms=0, stage=''):
        """保活右键文件操作回调，避免菜单关闭后操作未派发。"""
        self._manual_file_operation_callback = callback
        self._manual_file_operation_stage = str(stage or '')
        self._manual_trace('file_operation_queued', stage=self._manual_file_operation_stage, delay_ms=int(delay_ms or 0))
        self._manual_file_operation_timer.start(max(0, int(delay_ms or 0)))

    def _dispatch_manual_file_operation(self):
        callback = self._manual_file_operation_callback
        stage = self._manual_file_operation_stage
        self._manual_file_operation_callback = None
        self._manual_file_operation_stage = ''
        if not callable(callback):
            self._manual_trace('file_operation_dispatch_missing_callback', stage=stage)
            self._finish_manual_file_operation('文件操作未能启动，请重新执行剪切和粘贴。')
            return
        self._manual_trace('file_operation_dispatching', stage=stage)
        callback()

    def _select_initial_media_item(self):
        """首次打开优先选中有对白结果的未匹配视频，而不是列表首个文件夹。"""
        if not hasattr(self, 'video_list') or not self.video_list.count():
            return
        fallback_row = -1
        unmatched_row = -1
        for row in range(self.video_list.count()):
            data = self.video_list.item(row).data(_UserRole) or {}
            if data.get('kind') != 'media':
                continue
            if fallback_row < 0:
                fallback_row = row
            if str(data.get('_transcript_preview', '') or '').strip() and self._video_status(data) == 'unmatched':
                self.video_list.setCurrentRow(row)
                return
            if unmatched_row < 0 and self._video_status(data) == 'unmatched':
                unmatched_row = row
        self.video_list.setCurrentRow(unmatched_row if unmatched_row >= 0 else (fallback_row if fallback_row >= 0 else 0))

    @staticmethod
    def _make_manual_refresh_icon():
        """绘制真正的环形刷新箭头，不依赖字体字符或小方块图标。"""
        pixmap = QPixmap(22, 22)
        pixmap.fill(Qt.GlobalColor.transparent if PYQT_VERSION == 6 else Qt.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing if PYQT_VERSION == 6 else QPainter.Antialiasing)
        pen = QPen(QColor('#ffffff'))
        pen.setWidth(2)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap if PYQT_VERSION == 6 else Qt.RoundCap)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush if PYQT_VERSION == 6 else Qt.NoBrush)
        # 顺时针环形箭头：弧线与箭头头部都固定画在 22×22 画布中心。
        painter.drawArc(QRect(3, 3, 16, 16), 35 * 16, 285 * 16)
        painter.setBrush(QColor('#ffffff'))
        painter.setPen(Qt.PenStyle.NoPen if PYQT_VERSION == 6 else Qt.NoPen)
        painter.drawPolygon(QPoint(18, 3), QPoint(20, 9), QPoint(14, 7))
        painter.end()
        return QIcon(pixmap)

