            try:
                preview_player.load(media_path, max(0, int(start_ms)), autoplay, float(rate))
            except Exception as exc:
                status.setText(f'加载预览失败：{exc}'); return
            def finish_load(attempt=0):
                if not preview_state['alive'] or token != preview_state['load_token']: return
