        buttons = QHBoxLayout(); preview = QPushButton('▶ 预览当前调整'); effect_preview = QPushButton('🔊 真实试听音效'); normal = QPushButton('↺ 恢复原视频'); fullscreen = QPushButton('⛶ 全屏'); fullscreen.setToolTip('进入或退出全屏；Esc 可退出。'); cancel = QPushButton('取消'); output = QPushButton('开始输出'); output.setObjectName('action_btn')
        effect_preview.setToolTip('有选区音效时从 A 开始生成当前源视频内最多 20 秒试听；支持淡化、静音、音高与空间效果。普通播放仍是原视频。')
        buttons.addWidget(preview); buttons.addWidget(effect_preview); buttons.addWidget(normal); buttons.addWidget(fullscreen); buttons.addStretch(); buttons.addWidget(cancel); buttons.addWidget(output); layout.addLayout(buttons)
        def preview_speed():
            # Qt 播放器只能实时变速，不能无损实时改音高、混响或清晰化。只要这些
            # 音频参数有任一项启用，主预览按钮自动走后台渲染后的真实试听，避免用户
            # 调了音高却仍在听原音这一误导。
            if any(audio_edit_state.values()) or abs(float(pitch.value() or 0.0)) > 0.001 or reverb.value() > 0 or dereverb.value() > 0:
                preview_effects()
                return
            index, current = segment_for_position(timeline.value())
            load_preview_segment(index, current, speed.value(), True); status.setText(f'正在预览 {speed.value():.2f}×，可任意拖动时间轴。')
        def restore_original():
            index, current = segment_for_position(timeline.value())
            load_preview_segment(index, current, 1.0, False); status.setText('已恢复原视频试听，可定位后播放。')
