            painter.setBrush(QColor('#66e3ff')); painter.setPen(_NoPen)
            # 四角可等比调整，四边中点可只调整宽/高；命中区 34px，便于鼠标发现。
            for point in (rect.topLeft(), rect.topRight(), rect.bottomLeft(), rect.bottomRight()): painter.drawEllipse(point - QPointF(9, 9), 9, 9)
            for point in (QPointF(rect.left(), rect.center().y()), QPointF(rect.right(), rect.center().y())): painter.drawRect(QRectF(point.x() - 7, point.y() - 4, 14, 8))
            for point in (QPointF(rect.center().x(), rect.top()), QPointF(rect.center().x(), rect.bottom())): painter.drawRect(QRectF(point.x() - 4, point.y() - 7, 8, 14))
