            metrics = QFontMetrics(font); line_height = max(float(metrics.height()) * 1.22, float(font.pointSize()) * 1.2)
            content = self._content_rect(); total_height = line_height * len(self._runs); baseline = content.top() + max(0.0, (max(content.height(), self.box_height) - total_height) / 2.0) + metrics.ascent()
            outer, inner, shadow, glow = QColor(str(style.get('outline', '#111827'))), QColor(str(style.get('inner_outline', '#FFFFFF'))), QColor(str(style.get('shadow_color', '#000000'))), QColor(str(style.get('glow_color', '#60A5FA')))
            outer_w, inner_w, shadow_w, glow_w = float(style.get('outline_width', 0) or 0), float(style.get('inner_outline_width', 0) or 0), float(style.get('shadow', 0) or 0), float(style.get('glow_size', 0) or 0)
