        no = QMessageBox.StandardButton.No if PYQT_VERSION == 6 else QMessageBox.No
        if QMessageBox.question(self, '删除字幕预设', f'确定删除自定义预设“{name}”？\n此操作不会影响视频、字幕文本或其他预设。', yes | no, no) != yes:
            return
