def _render_subtitle_job(job_path):
    """用编辑器的同一个 QGraphicsScene 绘制导出帧，不再二次解释为 ASS 字体/坐标。"""
    from fractions import Fraction
    with open(job_path, 'r', encoding='utf-8') as file:
        job = json.load(file)
    source, target = str(job['source']), str(job['target'])
    words, style = list(job['words']), dict(job['style'])
    probe = subprocess.run(['ffprobe', '-v', 'error', '-select_streams', 'v:0',
                            '-show_entries', 'stream=width,height,avg_frame_rate:format=duration',
                            '-of', 'json', source], capture_output=True, text=True, encoding='utf-8', errors='replace', **_subprocess_no_window_kwargs())
    if probe.returncode != 0: raise RuntimeError('读取视频尺寸与帧率失败：' + probe.stderr[-600:])
    metadata = json.loads(probe.stdout or '{}')
    stream = next(iter(metadata.get('streams') or []), {})
    width, height = int(stream.get('width') or 0), int(stream.get('height') or 0)
    fps = Fraction(str(stream.get('avg_frame_rate') or '0/1'))
    duration = float((metadata.get('format') or {}).get('duration') or 0)
    if min(width, height) < 1 or fps <= 0 or duration <= 0: raise RuntimeError('无法确认视频的分辨率、帧率或时长。')
    app = QApplication.instance() or QApplication([])
    register_bundled_open_fonts()
    editor = SubtitleVisualEditorDialog(source, words, style=style)
    editor._video_native_size(QSize(width, height))
    if editor.video_item is not None: editor.video_item.hide()
    editor.scene.setBackgroundBrush(QColor(0, 0, 0, 0))
    editor.scene.setSceneRect(QRectF(0, 0, width, height))
    if hasattr(editor, 'caption_item'): editor.caption_item.setSelected(False)
    frame_count = math.ceil(duration * float(fps)) + 1
    rate = f'{fps.numerator}/{fps.denominator}'
    command = ['ffmpeg', '-y', '-hide_banner', '-loglevel', 'error', '-i', source,
               '-f', 'rawvideo', '-pixel_format', 'rgba', '-video_size', f'{width}x{height}',
               '-framerate', rate, '-i', 'pipe:0',
               '-filter_complex', '[0:v][1:v]overlay=0:0:format=auto:eof_action=pass,format=yuv420p[v]',
               '-map', '[v]', '-map', '0:a?', '-c:v', 'libx264', '-preset', 'slow', '-crf', '15',
               '-c:a', 'copy', '-map_metadata', '0', '-movflags', '+faststart', target]
    encoder = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.DEVNULL,
                               stderr=subprocess.PIPE, **_subprocess_no_window_kwargs())
    scene_rect = QRectF(0, 0, width, height)
    image = QImage(width, height, QImage.Format.Format_RGBA8888 if PYQT_VERSION == 6 else QImage.Format_RGBA8888)
    preview_frame = round(float(job.get('preview_at', -1) or -1) * float(fps))
    try:
        for frame in range(frame_count):
            moment = frame / float(fps)
            segment_index = next((index for index, segment in enumerate(editor.segments)
                                  if segment['start'] <= moment < segment['end']), None)
            editor.position_slider.setValue(round(moment * 1000))
            if segment_index is None:
                if hasattr(editor, 'caption_item'): editor.caption_item.hide()
            else:
                editor.current_segment = segment_index
                editor._refresh_caption()
                editor.caption_item.setSelected(False); editor.caption_item.show()
            image.fill(QColor(0, 0, 0, 0))
            painter = QPainter(image)
            # QGraphicsView 的屏幕预览已开启抗锯齿；离屏 QImage 默认没有这些
            # 提示，文字路径和圆角描边会在成片里出现明显阶梯。逐帧导出必须显式
            # 开启，才能让 1:1 原始尺寸的画面保持与编辑器一致的细腻边缘。
            try:
                painter.setRenderHint(QPainter.RenderHint.Antialiasing if PYQT_VERSION == 6 else QPainter.Antialiasing, True)
                painter.setRenderHint(QPainter.RenderHint.TextAntialiasing if PYQT_VERSION == 6 else QPainter.TextAntialiasing, True)
                painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform if PYQT_VERSION == 6 else QPainter.SmoothPixmapTransform, True)
            except Exception:
                pass
            editor.scene.render(painter, scene_rect, scene_rect)
            painter.end()
            if frame == preview_frame and job.get('preview_png'):
                image.save(str(job['preview_png']))
            try: encoder.stdin.write(image.bits().asstring(image.sizeInBytes()))
            except BrokenPipeError: break
        encoder.stdin.close()
        error_text = encoder.stderr.read().decode('utf-8', errors='replace')
        return_code = encoder.wait()
        if return_code != 0 or not os.path.isfile(target):
            raise RuntimeError('统一渲染字幕成片失败：' + error_text[-1200:])
    finally:
        if encoder.poll() is None:
            encoder.kill(); encoder.wait()
        editor.close()


class WorkflowGraphScene(QGraphicsScene):
    """Native workflow canvas: restrained, high-contrast, Opal-style light surface."""
    def drawBackground(self, painter, rect):
        painter.fillRect(rect, QColor('#f5f6f8'))
        size = 28.0
        pen = QPen(QColor(40, 50, 65, 22), 0.8)
        painter.setPen(pen)
        x = math.floor(rect.left() / size) * size
        while x <= rect.right() + size:
            # Qt 6 的整数重载不接受 float；网格是像素背景，取整不会影响视觉，
            # 却能避免首次绘制工作流时反复抛异常导致窗口无法稳定显示。
            painter.drawLine(int(round(x)), int(round(rect.top())), int(round(x)), int(round(rect.bottom())))
            x += size
        y = math.floor(rect.top() / size) * size
        while y <= rect.bottom() + size:
            painter.drawLine(int(round(rect.left())), int(round(y)), int(round(rect.right())), int(round(y)))
            y += size


class WorkflowGraphNode(QGraphicsObject):
    """Large, readable workflow card rendered directly by Qt."""
    WIDTH, HEIGHT = 292.0, 166.0

    def __init__(self, node_id, title, subtitle='', status='idle', progress=0, boundary=False, accent=None, parent=None):
        super().__init__(parent)
        self.node_id = str(node_id or '')
        self.title = str(title or '处理节点')
        self.subtitle = str(subtitle or '')
        self.status = str(status or 'idle')
        self.progress = max(0, min(100, int(progress or 0)))
        self.boundary = bool(boundary)
        self.accent = QColor(accent or '#bcd2ff')
        self.on_select = None
        self.on_open = None
        self.on_start_link = None
        self.on_finish_link = None
        self.on_moved = None
        self._hovered = False
        self._link_dragging = False
        flags = QGraphicsItem.GraphicsItemFlag if PYQT_VERSION == 6 else QGraphicsItem
        self.setFlag(flags.ItemIsSelectable, True)
        # Input and output are real graph objects too: users may arrange every
        # card freely.  Their port semantics stay fixed, only position is free.
        self.setFlag(flags.ItemIsMovable, True)
        self.setFlag(flags.ItemSendsGeometryChanges, True)
        self.setAcceptHoverEvents(True)
        self.setAcceptedMouseButtons(_LeftButton)

    def boundingRect(self):
        return QRectF(0, 0, self.WIDTH, self.HEIGHT)

    def _state_color(self):
        return {'running': QColor('#2563eb'), 'completed': QColor('#178a4c'),
                'failed': QColor('#d92d4c'), 'paused': QColor('#b7791f'),
                'stopped': QColor('#64748b')}.get(self.status, QColor('#334155'))

    def paint(self, painter, option, widget=None):
        color = self._state_color()
        rect = self.boundingRect().adjusted(3, 3, -3, -3)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing if PYQT_VERSION == 6 else QPainter.Antialiasing, True)
        shadow = QColor('#64748b'); shadow.setAlpha(38)
        painter.setBrush(QBrush(shadow)); painter.setPen(_NoPen)
        painter.drawRoundedRect(rect.adjusted(4, 5, 4, 5), 13, 13)
        painter.setBrush(QBrush(QColor('#ffffff')))
        painter.setPen(QPen(QColor('#111827'), 2.2 if self.isSelected() else 1.15))
        painter.drawRoundedRect(rect, 13, 13)
        header = QRectF(rect.left(), rect.top(), rect.width(), 43)
        painter.setBrush(QBrush(self.accent)); painter.setPen(_NoPen)
        painter.drawRoundedRect(header, 12, 12)
        painter.fillRect(QRectF(header.left(), header.bottom() - 12, header.width(), 12), self.accent)
        painter.setPen(QColor('#101828'))
        title_font = QFont(); title_font.setBold(True); title_font.setPointSize(11)
        painter.setFont(title_font)
        painter.drawText(QRectF(22, 10, self.WIDTH - 48, 25), _AlignCenter, self.title)
        # The central panel is deliberately state-driven.  Before execution it
        # explains the node.  During execution it becomes a large, unmistakable
        # progress display; completed/failed/paused states stay equally visible.
        body = QRectF(42, 51, self.WIDTH - 84, 88)
        painter.setBrush(QBrush(QColor('#f8fafc'))); painter.setPen(QPen(QColor('#e4e7ec'), 1))
        painter.drawRoundedRect(body, 8, 8)
        state_text = {'running': '运行中', 'completed': '✓ 已完成', 'failed': '✕ 执行失败', 'paused': 'Ⅱ 已暂停', 'stopped': '■ 已停止', 'input': '输入说明', 'output': '输出说明'}.get(self.status, '待执行')
        shown_progress = 100 if self.status == 'completed' else self.progress
        if self.status == 'running':
            painter.setPen(QColor('#344054')); active_font = QFont(); active_font.setBold(True); active_font.setPointSize(9); painter.setFont(active_font)
            painter.drawText(QRectF(body.left(), 59, body.width(), 18), _AlignCenter, '正在处理')
            bar = QRectF(body.left() + 14, 82, body.width() - 28, 17)
            painter.setBrush(QBrush(QColor('#dbeafe'))); painter.setPen(_NoPen); painter.drawRoundedRect(bar, 8, 8)
            fill = QRectF(bar.left(), bar.top(), max(8.0, bar.width() * shown_progress / 100.0), bar.height())
            painter.setBrush(QBrush(color)); painter.drawRoundedRect(fill, 8, 8)
            percent_font = QFont(); percent_font.setBold(True); percent_font.setPointSize(13); painter.setFont(percent_font); painter.setPen(color)
            painter.drawText(QRectF(body.left(), 105, body.width(), 22), _AlignCenter, f'{shown_progress}%')
        elif self.status in ('completed', 'failed', 'paused', 'stopped'):
            state_font = QFont(); state_font.setBold(True); state_font.setPointSize(12); painter.setFont(state_font); painter.setPen(color)
            painter.drawText(QRectF(body.left(), 68, body.width(), 26), _AlignCenter, state_text)
            hint_font = QFont(); hint_font.setPointSize(8); painter.setFont(hint_font); painter.setPen(QColor('#475467'))
            painter.drawText(QRectF(body.left(), 101, body.width(), 18), _AlignCenter, '100%' if self.status == 'completed' else f'当前进度 {shown_progress}%')
        else:
            painter.setPen(QColor('#344054')); sub_font = QFont(); sub_font.setPointSize(9); painter.setFont(sub_font)
            metrics = QFontMetrics(sub_font)
            subtitle = metrics.elidedText(self.subtitle, Qt.TextElideMode.ElideRight if PYQT_VERSION == 6 else Qt.ElideRight, int(body.width() - 12))
            painter.drawText(QRectF(body.left() + 6, 66, body.width() - 12, 22), _AlignCenter, subtitle)
            idle_font = QFont(); idle_font.setBold(True); idle_font.setPointSize(10); painter.setFont(idle_font); painter.setPen(QColor('#667085'))
            painter.drawText(QRectF(body.left(), 101, body.width(), 19), _AlignCenter, state_text)
        # Ports deliberately stay large and labelled: they are the primary
        # interaction surface for building a free-form workflow graph.
        port_y = 70.0
        for x, label, text_rect in (
            (16.0, 'IN', QRectF(28, 59, 38, 22)),
            (self.WIDTH - 16.0, 'OUT', QRectF(self.WIDTH - 66, 59, 38, 22)),
        ):
            painter.setBrush(QBrush(QColor('#101828')))
            painter.setPen(QPen(QColor('#ffffff'), 1.6))
            painter.drawEllipse(QRectF(x - 11, port_y - 11, 22, 22))
            painter.setBrush(QBrush(self.accent))
            painter.setPen(_NoPen)
            painter.drawEllipse(QRectF(x - 5, port_y - 5, 10, 10))
            port_font = QFont(); port_font.setBold(True); port_font.setPointSize(7)
            painter.setFont(port_font); painter.setPen(QColor('#344054'))
            painter.drawText(text_rect, _AlignCenter, label)
        painter.setPen(QColor('#667085'))
        small = QFont(); small.setPointSize(6); painter.setFont(small)
        painter.drawText(QRectF(17, self.HEIGHT - 18, self.WIDTH - 34, 12), _AlignCenter, '双击打开完整设置' if not self.boundary else '')

    def set_live_progress(self, status=None, progress=None):
        if status is not None:
            self.status = str(status)
        if progress is not None:
            self.progress = max(0, min(100, int(progress or 0)))
        self.update()

    def hoverEnterEvent(self, event):
        self._hovered = True; self.update(); super().hoverEnterEvent(event)

    def hoverLeaveEvent(self, event):
        self._hovered = False; self.update(); super().hoverLeaveEvent(event)

    def mousePressEvent(self, event):
        pos = event.pos()
        if pos.x() >= self.WIDTH - 44 and (not self.boundary or str(self.node_id).startswith('__workflow_input')):
            self._link_dragging = True
            if callable(self.on_start_link): self.on_start_link(self.node_id)
            event.accept(); return
        if pos.x() <= 44 and (not self.boundary or str(self.node_id).startswith('__workflow_output')):
            if callable(self.on_finish_link): self.on_finish_link(self.node_id)
            event.accept(); return
        if callable(self.on_select): self.on_select(self.node_id)
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        if not self.boundary and callable(self.on_open): self.on_open(self.node_id)
        event.accept()

    def mouseMoveEvent(self, event):
        # Keep the card still while its OUT port is being dragged.  Qt retains
        # the source item as the mouse grabber until release, so the release
        # position is used below to discover the target IN card.
        if self._link_dragging:
            event.accept(); return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._link_dragging:
            self._link_dragging = False
            target = None
            try:
                scene = self.scene()
                target = scene.itemAt(event.scenePos(), QTransform()) if scene is not None else None
            except Exception:
                target = None
            if isinstance(target, WorkflowGraphNode) and target is not self and callable(self.on_finish_link):
                self.on_finish_link(target.node_id)
            event.accept(); return
        super().mouseReleaseEvent(event)
        if callable(self.on_moved):
            pos = self.pos(); self.on_moved(self.node_id, float(pos.x()), float(pos.y()))


class WorkflowGraphView(QGraphicsView):
    """Zoomable canvas; Ctrl + wheel zooms while ordinary wheel scrolls."""
    def wheelEvent(self, event):
        if event.modifiers() & _ControlModifier:
            factor = 1.16 if event.angleDelta().y() > 0 else (1 / 1.16)
            self.setTransformationAnchor(QGraphicsView.ViewportAnchor.AnchorUnderMouse if PYQT_VERSION == 6 else QGraphicsView.AnchorUnderMouse)
            self.scale(factor, factor)
            event.accept(); return
        super().wheelEvent(event)

    def keyPressEvent(self, event):
        delete_key = Qt.Key.Key_Delete if PYQT_VERSION == 6 else Qt.Key_Delete
        if event.key() == delete_key and callable(getattr(self, 'on_delete_selection', None)):
            self.on_delete_selection(); event.accept(); return
        super().keyPressEvent(event)


class WorkflowLibraryTree(QTreeWidget):
    """基于稳定 ID 的库树：视图从不直接承担数据移动。"""
    def __init__(self, moved_callback, parent=None):
        super().__init__(parent)
        self._moved_callback = moved_callback
        self.setDragEnabled(True)
        self.setAcceptDrops(True)
        self.viewport().setAcceptDrops(True)
        self.setDropIndicatorShown(True)
        # 不能用 InternalMove：Qt 会在事件链的某个时刻尝试更改自身 model，和
        # 工作流库的持久化 model 竞争。DragDrop 模式只提供鼠标拖放，不拥有数据。
        mode = QAbstractItemView.DragDropMode.DragDrop if PYQT_VERSION == 6 else QAbstractItemView.DragDrop
        self.setDragDropMode(mode)
        action = Qt.DropAction.MoveAction if PYQT_VERSION == 6 else Qt.MoveAction
        self.setDefaultDropAction(action)
        self._dragged_raw_ids = []

    @staticmethod
    def _item_raw(item):
        try:
            return str(item.data(0, _UserRole) or '') if item is not None else ''
        except RuntimeError:
            return ''

    def startDrag(self, supported_actions):
        # 在 Qt 开始内部拖放前记下稳定 ID；不能在 dropEvent 再从临时 item 取来源。
        selected = [self._item_raw(item) for item in self.selectedItems()]
        selected = [raw for raw in selected if raw]
        current_raw = self._item_raw(self.currentItem())
        # 多选模式下父分类可能仍处于 Qt 的旧选择集合内。拖一个工作流绝不能顺带
        # 移动其父文件夹；反过来拖分类时也不能把里面被选中的工作流一并带走。
        if current_raw.startswith('template:'):
            selected = [raw for raw in selected if raw.startswith('template:')]
        elif current_raw.startswith('category:'):
            selected = [raw for raw in selected if raw.startswith('category:')]
        self._dragged_raw_ids = selected or ([current_raw] if current_raw else [])
        try:
            super().startDrag(supported_actions)
        finally:
            self._dragged_raw_ids = []

    def _drop_destination_raw(self, event):
        try:
            position = event.position().toPoint() if PYQT_VERSION == 6 else event.pos()
            target = self.itemAt(position)
        except Exception:
            return ''
        target_raw = self._item_raw(target)
        # 用实际行中间 56% 判定“放入文件夹”，而不是读取 Qt 的
        # dropIndicatorPosition：后者在嵌套 QTreeWidget 中会偶发把 OnItem 判为
        # Above/Below，正是深层分类随机丢失的来源。
        row = self.visualItemRect(target) if target is not None else QRect()
        in_center = bool(row.isValid() and position.y() >= row.top() + row.height() * 0.22 and position.y() <= row.bottom() - row.height() * 0.22)
        if in_center:
            if target_raw.startswith('category:'):
                return target_raw
            if target_raw.startswith('template:') and target is not None:
                return self._item_raw(target.parent())
            return ''
        # 行边缘只表示同级区域。当前不重排同级排序，故仅落入已有父分类；顶层行的
        # 边缘不执行移动，避免用户拖偏一点就从树中“消失”。
        if target is not None and target.parent() is not None:
            return self._item_raw(target.parent())
        return ''

    def dragEnterEvent(self, event):
        action = Qt.DropAction.MoveAction if PYQT_VERSION == 6 else Qt.MoveAction
        event.setDropAction(action)
        event.accept()

    def dragMoveEvent(self, event):
        action = Qt.DropAction.MoveAction if PYQT_VERSION == 6 else Qt.MoveAction
        event.setDropAction(action)
        event.accept()

    def dropEvent(self, event):
        # 不调用基类 InternalMove。应用层先校验、写盘，成功后再由模型重建视图。
        dragged = list(self._dragged_raw_ids) or [self._item_raw(self.currentItem())]
        destination_raw = self._drop_destination_raw(event)
        if callable(self._moved_callback):
            self._moved_callback(destination_raw, dragged)
        action = Qt.DropAction.MoveAction if PYQT_VERSION == 6 else Qt.MoveAction
        event.setDropAction(action)
        event.accept()


