        self.auto_task_table.setHorizontalHeaderLabels(["执行", "项目代码", "目标窗口 (留空用全局)", "图片路径", "文案内容", "状态"])
        self.auto_task_table.horizontalHeader().setStretchLastSection(True)
        self.auto_task_table.setAlternatingRowColors(False)
