        self.main_navigation.currentRowChanged.connect(self._on_main_navigation_selected)
        self.apply_navigation_layout(self.navigation_layout)
        
        # GPU 监测状态栏
        self.gpu_status_bar = QWidget(); self.gpu_status_bar.setObjectName("gpu_status_bar")
        gpu_bar = QHBoxLayout(self.gpu_status_bar); gpu_bar.setContentsMargins(9, 3, 9, 3); gpu_bar.setSpacing(8)
        self.gpu_vram_bar = QProgressBar()
        self.gpu_vram_bar.setObjectName("gpu_vram_bar")
