        # ── 运行日志（可隐藏） ──
        self.log_container = QWidget()
        # 防止 QVBoxLayout 把多余高度都分配给最后一个 widget，导致“运行日志”标题和日志框之间出现大片空白
        try:
            self.log_container.setSizePolicy(_Preferred, _Fixed)
        except Exception:
            pass
        _log_layout = QVBoxLayout(self.log_container)
        _log_layout.setContentsMargins(0, 0, 0, 0)
        _log_layout.setSpacing(2)
        self.log_title_label = QLabel("运行日志（含 Debug / 终端输出）")
        self.log_title_label.setObjectName("log_title_label")
        _log_layout.addWidget(self.log_title_label)
        self.log_display = QTextEdit()
        self.log_display.setReadOnly(True)
        # 保留足够长的本次会话明细，同时避免连续媒体/终端输出无限占用内存。
        self.log_display.document().setMaximumBlockCount(5000)
        # 默认高度稍微收紧一点，让主界面更“松”
        self.log_display.setFixedHeight(90)
        self.log_display.setObjectName("main_log_display")
        _log_layout.addWidget(self.log_display)
