        tip = QLabel('可点击打开，或直接从文件夹拖入 CSV、TSV、XLSX 表格；加载后可直接编辑。只有点击“保存到原文件”或“另存为”才会写入磁盘。')
        tip.setObjectName('workspace_tip'); tip.setWordWrap(True); layout.addWidget(tip)
        actions = QHBoxLayout()
        open_button = QPushButton('📄 打开表格文件'); open_button.clicked.connect(self.open_workstation_table); actions.addWidget(open_button)
        save_button = QPushButton('保存到原文件'); save_button.clicked.connect(lambda: self.save_workstation_table(False)); actions.addWidget(save_button)
        save_as = QPushButton('另存为'); save_as.clicked.connect(lambda: self.save_workstation_table(True)); actions.addWidget(save_as)
        fit = QPushButton('适应列宽'); fit.clicked.connect(lambda: self.table_viewer_table.resizeColumnsToContents()); actions.addWidget(fit)
        actions.addStretch(); layout.addLayout(actions)
