        reload_sources = QPushButton('↻ 重载'); reload_sources.setObjectName('action_btn'); reload_sources.setToolTip('重新扫描输入来源，刷新素材表。'); reload_sources.clicked.connect(self._video_editor_load_sources); actions.addWidget(reload_sources)
        clear_input = QPushButton('🧹 清空输入'); clear_input.setObjectName('action_btn'); clear_input.clicked.connect(self.video_editor_source_input.clear); actions.addWidget(clear_input)
