        clear_table = QPushButton('清空列表'); clear_table.clicked.connect(lambda: self.video_editor_table.setRowCount(0)); actions.addWidget(clear_table)
        self.video_editor_open_btn = QPushButton('✂️ 打开视频编辑工作台'); self.video_editor_open_btn.setObjectName('action_btn'); self.video_editor_open_btn.setToolTip('使用已勾选的视频打开逐帧视频编辑工作台；多条素材可连续审核，但仍逐条独立输出。'); self.video_editor_open_btn.clicked.connect(self._video_editor_open_workbench); actions.addWidget(self.video_editor_open_btn)
        self.video_editor_subtitle_btn = QPushButton('💬 动态字幕与渲染'); self.video_editor_subtitle_btn.setObjectName('action_btn'); self.video_editor_subtitle_btn.setToolTip('将已勾选视频带入动态字幕编辑页；可调字体、颜色、描边、阴影与位置，最后渲染为新的成片。'); self.video_editor_subtitle_btn.clicked.connect(self._video_editor_open_dynamic_subtitles); actions.addWidget(self.video_editor_subtitle_btn)
