        self.subtitle_studio_text_input.setPlaceholderText('可选：拖入 txt / srt / vtt / ass / lrc 文案文件或文件夹；同名 TXT 会自动配对。')
        source_form.addWidget(QLabel('文案文件:'), 3, 0); source_form.addWidget(self.subtitle_studio_text_input, 3, 1)
        text_browse = QPushButton('浏览'); text_browse.clicked.connect(lambda: self.video_concat_tab.browse_files_or_dir(self.subtitle_studio_text_input)); source_form.addWidget(text_browse, 3, 2)
        self.subtitle_studio_manual_text = QTextEdit(); self.subtitle_studio_manual_text.setFixedHeight(72)
