        btn_load_material_images.clicked.connect(
            lambda _checked=False, owner=project_widget, fallback=name: self._load_heygen_material_images(
                self._get_heygen_project_name_by_widget(owner) or fallback
            )
        )
        btn_layout.addWidget(btn_load_material_images)
