        self.manual_audit_table.setSelectionBehavior(QAbstractItemView.SelectionBehavior.SelectRows if PYQT_VERSION == 6 else QAbstractItemView.SelectRows)
        self.manual_audit_table.setSelectionMode(_ExtendedSelection)
        self.manual_audit_table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers if PYQT_VERSION == 6 else QAbstractItemView.NoEditTriggers)
        self.manual_audit_table.verticalHeader().setDefaultSectionSize(86)
        self.manual_audit_table.verticalHeader().setVisible(False)
        header = self.manual_audit_table.horizontalHeader()
        header.setSectionResizeMode(0, QHeaderView.ResizeMode.Fixed if PYQT_VERSION == 6 else QHeaderView.Fixed); header.resizeSection(0, 130)
        header.setSectionResizeMode(1, _Interactive); header.resizeSection(1, 300)
        for column in (2, 3, 4, 5, 6, 7):
            header.setSectionResizeMode(column, _Interactive)
        header.resizeSection(2, 300); header.resizeSection(3, 300); header.resizeSection(4, 84); header.resizeSection(5, 112); header.resizeSection(6, 112); header.resizeSection(7, 120)
        self.manual_audit_table.setToolTip('加载后显示首帧、中外文剧本、时长和左右声道峰值；双击单条或右键多选后“审核”可打开时间线审核窗口。')
        # 鼠标双击事件结束后再创建独立的原生播放器窗口；不能在 Qt 的双击分发
        # 栈内直接创建/绑定 VLC HWND，否则部分 Windows 环境会原生崩溃。
        self.manual_audit_table.cellDoubleClicked.connect(
            lambda row, _column: QTimer.singleShot(0, lambda selected_row=int(row): self._open_manual_audit_timeline_review([selected_row]))
        )
