        self.manual_audit_script_toggle.setText('▸ 展开当前审核文案对照')
        self.manual_audit_script_toggle.setCheckable(True)
        self.manual_audit_script_toggle.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextOnly if PYQT_VERSION == 6 else Qt.ToolButtonTextOnly)
        layout.addWidget(self.manual_audit_script_toggle)
