        route_projection = QLabel(); route_projection.setWordWrap(True); route.addRow('预输出：', route_projection)
        def route_refresh(*_):
            custom_input.setEnabled(source_combo.currentData() == 'custom_input')
            output_dir.setEnabled(output_mode.currentData() == 'unified')
            temporary = self._workflow_clone(node)
            selected_source = source_combo.currentData()
            temporary['input_source'] = self._workflow_source_from_picker(flow, selected_source, custom_input.toPlainText())
            temporary['name'] = node_name.text().strip(); temporary['name_auto'] = False
            temporary['output'] = {'mode': str(output_mode.currentData() or 'workflow'), 'directory': output_dir.text().strip(), 'suffix': self._workflow_node_output_suffix(kind), 'stage_label': stage_label.text().strip()}
            index = next((i for i, item in enumerate(flow.get('nodes') or []) if item is node), 0)
            projected_path = self._workflow_node_output_path(flow, temporary, index)
            route_projection.setText(projected_path or '请填写工作流输入或自定义输入。')
