    def setup_heygen_tab(self):
        layout = QVBoxLayout(self.heygen_tab)
        layout.setContentsMargins(8, 8, 8, 7)
        layout.setSpacing(6)
        layout.setProperty("compact_table_priority", True)
        page_header = QWidget(); page_header.setObjectName("heygen_page_header")
