        page_header_layout.addWidget(page_title); page_header_layout.addWidget(page_subtitle); page_header_layout.addStretch()
        layout.addWidget(page_header)
        
        # --- 批量自动化流水线控制区 ---
        # main 3.py 的紧凑布局：常用操作始终可见，路径与参数作为可展开配置区。
        self.btn_toggle_pipeline = QPushButton("▶ 配置（点击展开）")
        self.btn_toggle_pipeline.setCheckable(True)
        self.btn_toggle_pipeline.setChecked(False)
        self.btn_toggle_pipeline.setToolTip("展开后显示总素材根目录、全局存放位置和 AI 配置；再次点击可收起。常用操作按钮始终显示。")
        layout.addWidget(self.btn_toggle_pipeline)
        auto_group = QGroupBox("🤖 批量自动化流水线配置")
        auto_group.setObjectName("heygen_pipeline_group")
        auto_group.setVisible(False)
        auto_layout = QVBoxLayout(auto_group)
        auto_layout.setContentsMargins(8, 3, 8, 5)
        auto_layout.setSpacing(5)
        
        path_row = QHBoxLayout()
